	["Mana"] = "Mana",
	["This power's colour on MelloUI's player, target and focus frames, party and raid frames and the Personal Display."] = "La couleur de cette ressource sur les cadres de joueur, de cible et de focalisation de MelloUI, les cadres de groupe et de raid et l'affichage personnel.",
