	["Unfriendly"] = "Inamical",
	["Neutral"] = "Neutre",
	["Friendly"] = "Amical",
	-- UIModifications
	["UI Modifications"] = "Réglages de l’interface",
	["The painted reskin and most of MelloUI's interface changes: fonts, Dark Mode, chat, tooltips, buffs, bar textures and more."] = "L'habillage peint et la plupart des modifications de l'interface de MelloUI : polices, mode sombre, discussion, encadrés d'aide, améliorations, textures de barres et plus.",
	["The painted reskin, area by area, and the quality-of-life tweaks on nameplates, tooltips, chat and unit frames. Start here."] = "L'habillage peint, zone par zone, et les améliorations de confort des barres d'info, des encadrés d'aide, de la discussion et des cadres d'unité. Commencez ici.",
	["Skin"] = "Habillage",
	["How MelloUI looks. Default: the game's own borders, buttons and fonts. Modern: MelloUI's own art. Oldschool: the painted art on the game's windows and HUD (it switches UI Modifications on). Only the look changes; nothing moves."] = "L'apparence de MelloUI. Par défaut : bordures, boutons et polices du jeu. Moderne : les graphismes de MelloUI. Oldschool : les graphismes peints sur les fenêtres et l'interface du jeu, ce qui active les réglages UI. Seule l'apparence change ; rien ne bouge.",
	["Default (the game's own look)"] = "Par défaut (l'apparence du jeu)",
	["Modern (MelloUI's own look)"] = "Moderne (l'apparence de MelloUI)",
	["Oldschool (the painted look)"] = "Oldschool (l'apparence peinte)",
	["Painted Kit Reskin"] = "Habillage graphique de MelloUI",
	["Dresses the game's windows and HUD in the painted art. Off: the game's own art; every feature keeps working. Turning it on also turns on Custom Sounds and, the first time, sets up the Edit Mode layout it is made for."] = "Habille les fenêtres et l'interface du jeu avec les graphismes peints. Désactivé : les graphismes du jeu ; chaque fonction continue de fonctionner. L'activer active aussi les sons personnalisés et, la première fois, met en place la disposition du mode Édition prévue pour lui.",
	["Preload Artwork"] = "Précharger les graphismes",
	["Loads the reskin's art during the loading screen, so windows show it at once. Uses about 13 MB of memory. Off: the art loads the first time a window needs it."] = "Charge les graphismes de l'habillage pendant l'écran de chargement, pour que les fenêtres l'affichent immédiatement. Utilise environ 13 Mo de mémoire. Désactivé : ils se chargent la première fois qu'une fenêtre en a besoin.",
	["Switch every area on"] = "Activer toutes les zones",
	["Turns every reskinned area back on, with every UI Modifications feature that is on by default."] = "Réactive toutes les zones habillées, avec toutes les fonctions des réglages UI activées par défaut.",
	["when nothing is reskinned any more"] = "lorsque plus rien n'est habillé",
	["Switch on"] = "Activer",
	["Palette"] = "Palette",
	["The painted reskin's colours, also worn by MelloUI's windows while the reskin is on. Without it, MelloUI uses Gilded Slate."] = "Les couleurs de l'habillage peint, portées aussi par les fenêtres de MelloUI tant qu'il est actif. Sans lui, MelloUI utilise la palette d'origine Gilded Slate.",
	["Ember"] = "Ember",
