	["Obsidian"] = "Obsidian",
	["Neutral black glass and pewter, cold white text, one crimson accent. The calmest, highest-contrast base."] = "Verre noir neutre et étain, texte blanc froid, un accent cramoisi. La base la plus calme et la plus contrastée.",
	["Obsidian Vibrant"] = "Obsidienne vive",
	["Black glass, deeper and crisper: blued-steel trim, silver titles, ice-white text, a jewel crimson for the selection."] = "Verre noir, plus profond et plus net : liserés d'acier bleui, titres argentés, texte blanc glacé, un cramoisi de joyau pour la sélection.",
	["Royal Azure"] = "Royal Azure",
