	["The hunter's pet stable in the kit."] = "L'écurie des familiers du chasseur dans l'interface MelloUI.",
	["PvP windows"] = "Fenêtres JcJ",
	["The battleground and arena windows and the scoreboard in the kit."] = "Les fenêtres de champ de bataille et d'arène et le tableau des scores dans l'interface MelloUI.",
	["Battlefield map"] = "Carte du champ de bataille",
	["The battlefield minimap's frame in the kit (the map itself untouched)."] = "Le cadre de la minicarte du champ de bataille dans l'interface MelloUI (la carte elle-même intacte).",
	["Ready checks"] = "Vérifications de préparation",
	["The ready check and the dungeon / battleground ready popups in the kit."] = "La vérification de préparation et les fenêtres « prêt » des donjons et champs de bataille dans l’interface MelloUI.",
	["Split stack"] = "Partager une pile",
	["The split-stack box in the kit."] = "La fenêtre de séparation des piles dans l'interface MelloUI.",
	["Colour picker"] = "Sélecteur de couleur",
	["The colour picker in the kit."] = "Le sélecteur de couleur dans l'interface MelloUI.",
	["Calendar"] = "Calendrier",
	["The calendar and its event windows in the kit."] = "Le calendrier et ses fenêtres d'évènement dans l'interface MelloUI.",
	["Clock and stopwatch"] = "Horloge et chronomètre",
	["The clock settings and the stopwatch in the kit."] = "Les réglages de l'horloge et le chronomètre dans l'interface MelloUI.",
	["Chat channels"] = "Canaux de discussion",
	["The chat channels window in the kit."] = "La fenêtre des canaux de discussion dans l'interface MelloUI.",
	["Help window"] = "Fenêtre d'aide",
	["The help / customer support window in the kit."] = "La fenêtre d'aide / d'assistance clientèle dans l'interface MelloUI.",
	["Unit frames"] = "Cadres d’unité",
	["The player, target, focus, pet and party frames in the painted art."] = "Les cadres du joueur, de la cible, de la focalisation, du familier et du groupe dans les graphismes peints.",
	["Cast bars"] = "Barres d'incantation",
	["The cast bars in the painted art."] = "Les barres d'incantation dans les graphismes peints.",
	["Raid frames"] = "Cadres de raid",
	["The raid frames, group borders and totems in the painted art."] = "Les fenêtres de raid, bordures de groupe et totems dans les graphismes peints.",
	["Action bars"] = "Barres d'actions",
	["The action, stance and pet bars, micro menu, bag bar and experience bars in the painted art."] = "Les barres d'actions, de posture et de familier, le micro-menu, la barre de sacs et les barres d'expérience dans les graphismes peints.",
	["Minimap"] = "Minicarte",
	["The minimap's ring, zone band and buttons in the painted art."] = "L'anneau de la minicarte, sa bande de zone et ses boutons dans les graphismes peints.",
	["Objective tracker"] = "Suivi des objectifs",
	["The game's objective tracker's headers and background in the painted art."] = "Les en-têtes et le fond du suivi des objectifs du jeu dans les graphismes peints.",
	["Chat windows"] = "Fenêtres de discussion",
	["The chat windows, tabs and input line in the painted art."] = "Les fenêtres de discussion, onglets et ligne de saisie dans les graphismes peints.",
	["Damage meter"] = "Compteur de dégâts",
	["The damage meter and its breakdown window in the painted art."] = "Le compteur de dégâts et sa fenêtre de détail dans les graphismes peints.",
	["Tooltips"] = "Encadrés d'aide",
	["Tooltips on the stone box with the single rail."] = "Les encadrés d'aide sur la boîte de pierre avec le rail simple.",
	["Nameplates"] = "Barres d'info",
	["The nameplates' bars in the painted art."] = "Les barres des barres d'info dans les graphismes peints.",
	["Error Messages"] = "Messages d'erreur",
	["Hides the red error messages you pick below from the middle of the screen."] = "Masque au centre de l'écran les messages d'erreur rouges que vous choisissez ci-dessous.",
	["MelloUI on the nameplates: the large CC icon, quest markers, the threat line, combo points, name shading, your debuffs, cooldown timers, impact effects, the swing badge and party markers. Off: the game's own plates, untouched."] = "MelloUI sur les barres d’info : grande icône de contrôle, marqueurs de quête, ligne de menace, points de combo, ombrage du nom, vos affaiblissements, minuteurs de recharge, effets d’impact, insigne d’attaque et marqueurs de groupe. Désactivé : les barres du jeu restent intactes.",
	["Unit Frames"] = "Cadres d’unité",
	["MelloUI on the unit frames: yours, your target's, focus's and pet's, with everything on them (values, portraits, buffs, incoming heals, effects). Off: the game's own frames, untouched."] = "MelloUI sur les cadres d'unité : le vôtre, ceux de votre cible, de votre focalisation et de votre familier, avec tout ce qu'ils affichent (valeurs, portraits, améliorations, soins entrants, effets). Désactivé : les cadres du jeu, intacts.",
	["Bar Textures"] = "Textures des barres",
	["MelloUI's bar textures and health bar colours."] = "Les textures de barres et couleurs de vie de MelloUI.",
	["Chat Tweaks"] = "Réglages de la discussion",
	["MelloUI's chat changes: short channel tags, class-coloured names, the whisper popup, chat buttons and smooth scrolling."] = "Les modifications apportées par MelloUI à la discussion : étiquettes de canal courtes, noms colorés par classe, fenêtre de chuchotement, boutons et défilement doux.",
	["Tooltip Tweaks"] = "Réglages des encadrés d'aide",
	["MelloUI's tooltip changes: colours, the health bar and placement."] = "Les modifications apportées par MelloUI aux encadrés d'aide : couleurs, barre de vie et position.",
	["Custom Fonts"] = "Polices personnalisées",
	["MelloUI's fonts and text sizes for the whole interface. Off: the game's own fonts."] = "Les polices et tailles de texte de MelloUI pour toute l'interface. Désactivé : les polices du jeu.",
	["Dark Mode"] = "Mode sombre",
	["Dims the whole interface. Icons, text and parchment keep their colours."] = "Assombrit toute l'interface. Icônes, texte et parchemin gardent leurs couleurs.",
	["Vendor Automation"] = "Automatisation marchand",
	["Repairs your gear and sells junk at merchants."] = "Répare votre équipement et vend le camelote chez les marchands.",
	["FPS / Latency"] = "IPS / Latence",
	["A small FPS and latency readout in the bottom right corner."] = "Un petit affichage des IPS et de la latence en bas à droite.",
	-- OwnBars
	["Own Bars"] = "Barres propres",
	["The experience and reputation bars and the bag bar as MelloUI's own: placed by Edit Layout and the profiles."] = "Les barres d'expérience, de réputation et de sacs dans le style de MelloUI : placées par Modifier la disposition et les profils.",
	["Vertical Bag Bar"] = "Barre des sacs verticale",
	["The bag bar stands upright instead of lying flat."] = "La barre des sacs se tient debout au lieu d'être couchée.",
	["Bags On The Other Side"] = "Sacs de l'autre côté",
	["The bag slots line up on the other side of the backpack (right instead of left, or down instead of up)."] = "Les emplacements de sacs s'alignent de l'autre côté du sac à dos (à droite au lieu de gauche, ou en bas au lieu d'en haut).",
	["Experience Bar Width"] = "Largeur de la barre d'expérience",
	["The experience bar's width in px, from 20 up to the whole width of your screen. Changes at once."] = "La largeur de la barre d'expérience en pixels, de 20 jusqu'à toute la largeur de l'écran. Prend effet immédiatement.",
	["Reputation Bar Width"] = "Largeur de la barre de réputation",
	["The second bar's width in px (a watched reputation while you level), from 20 up to the whole width of your screen. Changes at once."] = "La largeur de la seconde barre en pixels (la réputation suivie pendant la montée de niveau), de 20 jusqu'à toute la largeur de l'écran. Prend effet immédiatement.",
	["Orientation"] = "Orientation",
	["Whether the bar's buttons lie in a row or stand in a column."] = "Si les boutons de la barre forment une rangée ou une colonne.",
	["Horizontal"] = "Horizontale",
	["Vertical"] = "Verticale",
	["# of Rows"] = "Nombre de rangées",
	["How many rows (or columns, upright) the bar's buttons stand in."] = "Le nombre de rangées (ou de colonnes, à la verticale) des boutons de la barre.",
	["# of Icons"] = "Nombre d'icônes",
	["How many of the bar's buttons show."] = "Combien de boutons de la barre s'affichent.",
	["Icon Size"] = "Taille des icônes",
	["The size of the bar's buttons. 100% is the game's size."] = "La taille des boutons de la barre. 100 % correspond à la taille du jeu.",
	["Icon Padding"] = "Espacement des icônes",
	["The space between the bar's buttons."] = "L'espace entre les boutons de la barre.",
	["Bar Visible"] = "Barre visible",
	["When the bar shows: always, only in a fight, only out of one, never, or while the pointer is over it."] = "Quand la barre s'affiche : toujours, seulement en combat, seulement hors combat, jamais, ou au survol du pointeur.",
	["Always"] = "Toujours",
	["In Combat"] = "En combat",
	["Out of Combat"] = "Hors combat",
	["Hidden"] = "Masquée",
	["On Mouseover"] = "Au survol",
	["Always Show Buttons"] = "Toujours afficher les boutons",
	["Empty buttons show their slot too."] = "Les boutons vides montrent aussi leur emplacement.",
	-- DarkMode
	["Dims the whole interface: MelloUI's windows and frames, the game's own art and the painted reskin. Icons, text and parchment keep their colours."] = "Assombrit toute l'interface : fenêtres et cadres de MelloUI, graphismes du jeu et habillage peint. Icônes, texte et parchemin gardent leurs couleurs.",
	["Dim the gold and the glare. The interface steps back, the world steps forward."] = "Atténuez l'or et l'éclat. L'interface recule, le monde avance.",
	["Appearance"] = "Apparence",
	["Brightness"] = "Luminosité",
	["How bright the interface is with Dark Mode on. Lower is darker."] = "La luminosité de l'interface avec le mode sombre. Plus bas, plus sombre.",
	["Desaturate"] = "Désaturer",
	["Turns the gold and bronze art grey before dimming it."] = "Rend gris les graphismes dorés et bronze avant de les assombrir.",
	["Components"] = "Composants",
	["Dark Mode on the unit frames: player, target, focus, pet, boss, target of target, and the party and raid frames."] = "Mode sombre sur les cadres d'unité : joueur, cible, focalisation, familier, boss, cible de la cible, et les cadres de groupe et de raid.",
	["Cast Bars"] = "Barres d'incantation",
	["Dark Mode on the cast bars."] = "Mode sombre sur les barres d'incantation.",
	["Action Bars"] = "Barres d'actions",
	["Dark Mode on the action buttons and the stance, pet, possess and extra action bars."] = "Mode sombre sur les boutons d'action et les barres de posture, de familier, de possession et d'action supplémentaire.",
	["Action Bar End Caps"] = "Embouts des barres d'actions",
	["Dark Mode on the main bar's end caps and art."] = "Mode sombre sur les embouts et les graphismes de la barre principale.",
	["Dark Mode on the nameplates' bars and cast bars."] = "Mode sombre sur les barres d’info et leurs barres d’incantation.",
	["Personal Display"] = "Affichage personnel",
	["Dark Mode on the Personal Display's bars."] = "Mode sombre sur les barres de l'Affichage personnel.",
	["Experience & Reputation Bars"] = "Barres d'expérience et de réputation",
	["Dark Mode on the experience, reputation and honor bars."] = "Mode sombre sur les barres d'expérience, de réputation et d'honneur.",
	["Cooldown Manager"] = "Gestionnaire de temps de recharge",
	["Dark Mode on the Cooldown Manager's icons and bars."] = "Mode sombre sur les icônes et barres du Gestionnaire de temps de recharge.",
	["Micro Menu & Bag Bar"] = "Micro-menu et barre de sacs",
	["Dark Mode on the micro menu's and bag bar's frames. Their icons stay as they are."] = "Mode sombre sur les cadres du micro-menu et de la barre de sacs. Leurs icônes restent telles quelles.",
	["Dark Mode on the minimap's ring, header and buttons."] = "Mode sombre sur l'anneau, l'en-tête et les boutons de la minicarte.",
	["Chat Frame"] = "Cadre de discussion",
	["Chat tabs, the chat input box and the chat buttons. Window background colours stay as configured in the chat settings."] = "Les onglets de discussion, la zone de saisie et les boutons de discussion. Les couleurs de fond des fenêtres restent celles réglées dans les options de discussion.",
	["Windows"] = "Fenêtres",
	["Dark Mode on MelloUI's windows and panels: the bags, the map, the Quest Tracker, the configurator and the rest."] = "Mode sombre sur les fenêtres et panneaux de MelloUI : les sacs, la carte, le suivi des quêtes, le configurateur et le reste.",
	["Buffs & Debuffs"] = "Améliorations et affaiblissements",
	["Dark Mode on the game's buff and debuff icons."] = "Mode sombre sur les icônes d'améliorations et d'affaiblissements du jeu.",
	["Keep Dispel Colours"] = "Garder les couleurs de dissipation",
	["Dark Mode leaves the coloured debuff borders (magic, curse, poison, disease) alone."] = "Le mode sombre laisse intactes les bordures colorées des affaiblissements (magie, malédiction, poison, maladie).",
	-- Fonts
	["Fonts"] = "Polices",
	["One font per role: interface text, chat and numbers, titles, damage numbers; plus size and outline."] = "Une police pour chaque rôle : texte de l'interface, texte de discussion et chiffres, titres et chiffres de dégâts, avec la taille et le contour.",
	["One font for all of Azeroth. Pick it, scale it, outline it."] = "Une police pour tout Azeroth. Choisissez-la, redimensionnez-la et ajoutez-lui un contour.",
	["Font Style"] = "Style de police",
	["A preset that sets every font and text size at once. Change any font afterwards and the style shows Custom.\nFredoka: MelloUI's own round letters, made to fit its icons. The default.\nScriptorium: Carved capitals over a warm book face.\nChronicle: Small capitals over the most readable book face.\nOld Tome: Aged print, like an old book.\nWarband: Bold blackletter: the boldest look.\nClarity: Plain letters: the easiest to read at small sizes.\nGothic: Gothic titles over a book face."] = "Un préréglage qui règle toutes les polices et tailles de texte d'un coup. Changez une police ensuite et le style affiche Personnalisé.\nFredoka : les lettres rondes de MelloUI, faites pour ses icônes. Par défaut.\nScriptorium : des capitales gravées sur une police de livre chaleureuse.\nChronicle : des petites capitales sur la police de livre la plus lisible.\nOld Tome : une impression vieillie, comme un vieux livre.\nWarband : une gothique épaisse : l'aspect le plus marqué.\nClarity : des lettres simples : les plus lisibles en petite taille.\nGothic : des titres gothiques sur une police de livre.",
	["preset: changes every font at once"] = "préréglage : change toutes les polices d'un coup",
	["Custom"] = "Personnalisé",
	["Fredoka"] = "Fredoka",
	["Scriptorium"] = "Scriptorium",
	["Chronicle"] = "Chronicle",
	["Old Tome"] = "Old Tome",
	["Warband"] = "Warband",
	["Clarity"] = "Clarity",
	["Gothic"] = "Gothic",
	["Interface text (Friz Quadrata)"] = "Texte de l'interface (Friz Quadrata)",
	["The font of window text, buttons, tooltips and names. Names over characters change after a /reload."] = "La police du texte des fenêtres, boutons, encadrés d'aide et noms. Les noms au-dessus des personnages changent après un /reload.",
	["Keep the game's"] = "Garder celle du jeu",
	["Friz Quadrata (default)"] = "Friz Quadrata (par défaut)",
	["Chat & numbers (Arial Narrow)"] = "Discussion et chiffres (Arial Narrow)",
	["The font of numbers: cooldowns, stacks and counts."] = "La police des nombres : temps de recharge, piles et compteurs.",
	["Titles & headers (Morpheus)"] = "Titres et en-têtes (Morpheus)",
	["The font of window titles, dialog headings, mail and books."] = "La police des titres de fenêtres, des en-têtes de dialogue, du courrier et des livres.",
	["Game Numbers Font (Skurri)"] = "Police des chiffres du jeu (Skurri)",
	["The font of damage numbers over enemies and hit numbers on portraits. The game's own numbers change after a /reload."] = "La police des nombres de dégâts au-dessus des ennemis et des nombres de coups sur les portraits. Les nombres du jeu changent après un /reload.",
	["Chat text"] = "Texte de discussion",
	["The font of chat messages, the chat's input line and whisper windows."] = "La police des messages, de la ligne de saisie et des fenêtres de chuchotement.",
	["Same as Interface text"] = "Comme le Texte de l'interface",
	["Chat on parchment"] = "Discussion sur parchemin",
	["The font of chat and whispers on parchment. A heavier cut reads better on paper."] = "La police de la discussion et des chuchotements sur parchemin. Une graisse plus forte se lit mieux sur papier.",
	["Chat text, semibold"] = "Texte de discussion, demi-gras",
	["Size and outline"] = "Taille et contour",
	["Interface text size"] = "Taille du texte de l'interface",
	["The size of the interface text. Text with its own size (Quest Tracker, Combat Text, chat, timers) keeps it."] = "La taille du texte de l'interface. Le texte qui utilise sa propre taille (suivi des quêtes, texte de combat, discussion, minuteurs) la garde.",
	["Chat & numbers size"] = "Taille du texte de discussion et des chiffres",
	["The size of the chat text and of numbers."] = "La taille du texte de discussion et des nombres.",
	["Titles & headers size"] = "Taille des titres et en-têtes",
	["The size of titles and headers. The Quest Tracker and Combat Text keep their own sizes."] = "La taille des titres et en-têtes. Le suivi des quêtes et le texte de combat conservent leur propre taille.",
	["Chat on parchment size"] = "Taille de la discussion sur parchemin",
	["The size of chat and whisper text on parchment, relative to the chat's size."] = "La taille du texte de discussion et de chuchotement sur parchemin, relative à celle de la discussion.",
	["Outline"] = "Contour",
	["An outline on light text. Dark text on parchment keeps its look."] = "Ajoute un contour au texte clair. Le texte sombre sur parchemin garde son aspect.",
	["Keep original"] = "Garder l'original",
	["Thin outline"] = "Contour fin",
	["Thick outline"] = "Contour épais",
	-- ClassIcons
	["Class Icons"] = "Icônes de classe",
	["High resolution painted class medallions in place of the default class icons, and on player portraits."] = "Des médaillons de classe peints en haute résolution à la place des icônes de classe par défaut, et sur les portraits des joueurs.",
	["Painted medallions for every class, on the character sheet and on every portrait."] = "Des médaillons peints pour chaque classe, sur la fiche de personnage et sur chaque portrait.",
	["The painted class medallions in place of the game's class icons and on player portraits."] = "Les médaillons de classe peints à la place des icônes de classe du jeu et sur les portraits des joueurs.",
	["Player Portraits"] = "Portraits des joueurs",
	["Players' portraits show their class emblem instead of their face. NPCs keep theirs."] = "Les portraits des joueurs montrent leur emblème de classe au lieu de leur visage. Les PNJ gardent le leur.",
	-- BarTextures
	["Change the fill texture of health, power, nameplate, experience, reputation, honor and cast bars."] = "Change la texture de remplissage des barres de vie, de ressource, des barres d'info, d'expérience, de réputation, d'honneur et d'incantation.",
	["Health and mana bars in the finish you like: flat, smooth, glossy or minimalist."] = "Des barres de vie et de mana dans la finition qui vous plaît : plate, lisse, brillante ou minimaliste.",
	["Texture"] = "Texture",
	["Bar Texture"] = "Texture des barres",
	["The texture of every bar set to Shared. Each kind of bar can pick its own below."] = "La texture de chaque barre réglée sur Partagée. Chaque type de barre peut choisir la sienne ci-dessous.",
	["Default (Blizzard)"] = "Par défaut (Blizzard)",
	["Flat"] = "Plate",
	["Smooth"] = "Lisse",
	["Gloss"] = "Brillante",
	["Minimalist"] = "Minimaliste",
	["Blizzard Classic"] = "Blizzard Classic",
	["Blizzard Raid"] = "Blizzard Raid",
	["Health Bar Colour"] = "Couleur des barres de vie",
	["How health bars are coloured on unit frames, nameplates and group frames. By health fades from your full to your low colour. NPC nameplates keep the game's colours, except with By health."] = "Comment les barres de vie sont colorées sur les cadres d'unité, barres d'info et cadres de groupe. Selon la vie : passe de votre couleur de vie pleine à votre couleur de vie basse. Les barres d'info des PNJ gardent les couleurs du jeu, sauf avec Selon la vie.",
	["Green (Blizzard)"] = "Vert (Blizzard)",
	["Class colour for players"] = "Couleur de classe pour les joueurs",
	["Class (players) / reaction (NPCs)"] = "Classe / réaction (PNJ)",
	["By health (your three colours)"] = "Selon la vie (vos trois couleurs)",
	["My Colour"] = "Ma couleur",
	["My Health Colour"] = "Ma couleur de vie",
	["The health bar colour with My Colour."] = "La couleur de la barre de vie avec Ma couleur.",
	["Full Health Colour"] = "Couleur pleine vie",
	["By health: the colour at full health."] = "Selon la vie : la couleur à pleine vie.",
	["Half Health Colour"] = "Couleur mi-vie",
	["By health: the colour at half health."] = "Selon la vie : la couleur à mi-vie.",
	["Low Health Colour"] = "Couleur vie basse",
	["By health: the colour near death."] = "Selon la vie : la couleur près de la mort.",
	["Colour Overrides Threat"] = "La couleur prime sur la menace",
	["Your health bar colour wins over the game's threat colours. Off: threat colours show."] = "Votre couleur de barre de vie l'emporte sur les couleurs de menace du jeu. Désactivé : les couleurs de menace s'affichent.",
	["Execute Range"] = "Zone d'exécution",
	["An enemy's health bar turns purple below the Execute Below health, on frames and nameplates."] = "La barre de vie d'un ennemi devient violette sous le seuil d'Exécution, sur les cadres et les barres d'info.",
	["Execute Below"] = "Exécution sous",
	["The health percentage below which an enemy's bar turns purple."] = "Le pourcentage de vie sous lequel la barre d'un ennemi devient violette.",
	["Apply To"] = "Appliquer à",
	["The texture of the unit frames' health and power bars."] = "La texture des barres de vie et de ressource des cadres d'unité.",
	["Same as Every Bar"] = "Partagée (Apparence)",
	["The game's"] = "Celle du jeu",
	["Raid Frames"] = "Cadres de raid",
	["The texture of the party and raid frames' bars."] = "La texture des barres des cadres de groupe et de raid.",
	["Plain"] = "Unie",
	["The texture of nameplate health and cast bars."] = "La texture des barres de vie et d’incantation des barres d’info.",
	["The texture of the Personal Display's bars."] = "La texture des barres de l'Affichage personnel.",
	["The texture of the experience, reputation and honor bars, and the damage meter's bars."] = "La texture des barres d'expérience, de réputation et d'honneur, et des barres du compteur de dégâts.",
	["The texture of cast bars and the swing badge."] = "La texture des barres d'incantation et du badge d'attaque.",
	["Cooldown Manager Bars"] = "Barres du gestionnaire de temps de recharge",
	["The texture of the Cooldown Manager's bars."] = "La texture des barres du Gestionnaire de temps de recharge.",
	["Tooltip Health Bar"] = "Barre de vie de l'encadré d'aide",
	["The texture of the health bar under unit tooltips."] = "La texture de la barre de vie sous les encadrés d'aide d'unité.",
	-- BarText
	["Bar Text"] = "Texte des barres",
	["Always show health and power values on the player, target and focus frames."] = "Affiche toujours les valeurs de vie et de ressource sur les portraits du joueur, de la cible et de la focalisation.",
	["Numbers where they belong. Health and power values, always in view."] = "Les chiffres là où il faut. Vie et ressource, toujours en vue.",
	["Bar Values"] = "Valeurs des barres",
	["Health and power values always shown on the player, target and focus frames."] = "Valeurs de vie et de ressource toujours affichées sur les portraits du joueur, de la cible et de la focalisation.",
