	["Percent (82%)"] = "Pourcentage (82%)",
	["Short + Percent (8.2k | 82%)"] = "Court + pourcentage (8.2k | 82%)",
	["Short / Max (8.2k / 10k)"] = "Court / max (8.2k / 10k)",
	["Full / Max (8,234 / 10,000)"] = "Complet / max (8,234 / 10,000)",
	["Short / Max + Percent (8.2k / 10k | 82%)"] = "Court / max + pourcentage (8.2k / 10k | 82%)",
	["Position"] = "Position",
	["Where the values sit on the bar."] = "Où les valeurs se placent sur la barre.",
	["Center"] = "Centre",
	["Left"] = "Gauche",
	["Right"] = "Droite",
	["Horizontal Offset"] = "Décalage horizontal",
	["Moves the values left or right."] = "Déplace les valeurs à gauche ou à droite.",
	["Vertical Offset"] = "Décalage vertical",
	["Moves the values down or up."] = "Déplace les valeurs vers le bas ou le haut.",
	["Font Size"] = "Taille de la police",
	["The size of health and power values. Default: the game's size."] = "La taille des valeurs de vie et de ressource. Par défaut : la taille du jeu.",
	["Values Font"] = "Police des valeurs",
	["The font of health and power values on the player, target and focus frames. Shared: the interface font."] = "La police des valeurs de vie et de ressource sur les cadres du joueur, de la cible et de la focalisation. Partagée : la police de l'interface.",
	["Shared"] = "Partagée",
	-- CooldownText
	["Cooldown Timers"] = "Minuteurs de recharge",
	["Large countdown numbers on action bar cooldowns and nameplate auras, coloured by time left."] = "De grands chiffres de compte à rebours sur les temps de recharge des barres d'actions et les auras des barres d'info, colorés selon le temps restant.",
	["Countdowns on every cooldown, coloured by how long you still have to wait."] = "Un compte à rebours sur chaque temps de recharge, coloré selon le temps qu'il vous reste à attendre.",
	["Countdown numbers on action bar cooldowns and nameplate auras, coloured by the time left."] = "Des chiffres de compte à rebours sur les temps de recharge des barres d'actions et les auras des barres d'info, colorés selon le temps restant.",
	["Show On"] = "Afficher sur",
	["Timers on action, pet and stance buttons."] = "Minuteurs sur les boutons d'action, de familier et de posture.",
	["Nameplate Auras"] = "Auras des barres d'info",
	["Timers on the game's nameplate auras."] = "Minuteurs sur les auras des barres d'info du jeu.",
	["Timer"] = "Minuteur",
	["Minimum Duration"] = "Durée minimale",
	["Cooldowns shorter than this show no timer. 2 seconds skips the global cooldown."] = "Les temps de recharge inférieurs à cette valeur n'affichent pas de minuteur. À 2 secondes, le temps de recharge global est ignoré.",
	["Text Size"] = "Taille du texte",
	["Timer text size, relative to the icon."] = "La taille du texte des minuteurs, relative à l'icône.",
	["Show Tenths Below 5s"] = "Dixièmes sous 5 s",
	["Shows 4.3 instead of 5 in a cooldown's last seconds."] = "Affiche 4,3 au lieu de 5 dans les dernières secondes d'un temps de recharge.",
	["Colour And Size By Time Left"] = "Couleur et taille selon le temps restant",
	["Timers turn red and larger under 5 seconds, yellow under a minute, and smaller for minutes and hours. Off: all white."] = "Les minuteurs deviennent rouges et plus grands sous 5 secondes, jaunes sous une minute, et plus petits pour les durées en minutes et en heures. Désactivé : tout en blanc.",
	-- Tweaks
	["Tweaks"] = "Réglages",
	["Hide the micro menu and bag bar, and scale the floating combat text."] = "Masque le micro-menu et la barre de sacs, et redimensionne le texte de combat flottant.",
	["Small knobs with a big effect. Hide what you never click, scale what you never see."] = "Petits boutons, grand effet. Masquez ce que vous ne cliquez jamais, agrandissez ce que vous ne voyez jamais.",
	["Hide Frames"] = "Masquer des cadres",
	["Hide Micro Menu"] = "Masquer le micro-menu",
	["Hides the micro menu. It shows in Edit Mode."] = "Masque le micro-menu. Il s'affiche en mode Édition.",
	["Hide Bag Bar"] = "Masquer la barre de sacs",
	["Hides the bag bar. Your bag keys still work; it shows in Edit Mode."] = "Masque la barre de sacs. Vos touches de sacs marchent toujours ; elle s'affiche en mode Édition.",
	["Minimap Coordinates"] = "Coordonnées de la minicarte", -- draft
	["Your coordinates under the minimap, and the mouse's while it is over the minimap."] = "Vos coordonnées sous la minicarte, et celles de la souris quand elle survole la minicarte.", -- draft
	["Bag Slots On Bag Window"] = "Emplacements de sac sur la fenêtre des sacs",
	["With the bag bar hidden, the bag slots show under the bag window, so you can still swap bags."] = "Barre de sacs masquée, les emplacements de sacs s'affichent sous la fenêtre des sacs, pour pouvoir changer de sac.",
	["Collapse Arrow"] = "Flèche de repli",
	["An arrow beside the backpack folds the bag slots away."] = "Une flèche près du sac à dos replie les emplacements de sacs.",
	["Chat"] = "Discussion",
	["Chat Notices"] = "Avis dans la discussion",
	["MelloUI's own lines in the chat, like hints and learned entrances. Replies to commands always show."] = "Les lignes de MelloUI dans la discussion, comme les astuces et les entrées apprises. Les réponses aux commandes s'affichent toujours.",
	["Notices"] = "Avis",
	["On-screen Notices"] = "Avis à l'écran",
	["A short line near the top of the screen when MelloUI has news, like a route set or finished. Move it in Edit Layout."] = "Une courte ligne en haut de l'écran quand MelloUI a du nouveau, comme un itinéraire fixé ou terminé. Déplacez-la avec Modifier la disposition.",
	["Send To Chat Instead"] = "Envoyer à la discussion",
	["The notices go to the chat instead of the screen."] = "Les notifications vont dans la discussion au lieu de l'écran.",
	["Notice Sounds"] = "Sons des avis",
	["A short chime with each notice."] = "Un court carillon à chaque notification.",
	["Text Shade"] = "Ombre du texte",
	["A soft dark shadow behind on-screen text (zone names, messages, names on unit frames and nameplates, chat tags on parchment), so it stays readable on bright ground."] = "Une douce ombre sombre derrière le texte à l'écran (noms de zones, messages, noms sur les cadres d'unité et les barres d'info, étiquettes de discussion sur parchemin), pour rester lisible sur fond clair.",
	["Outlined Text"] = "Texte détouré",
	["An outline on MelloUI's on-screen text: notices, Combat Text, Gains and, with Text Shade on, the zone text and the messages in the middle of the screen. Off: soft text on a dark shadow."] = "Un contour sur le texte de MelloUI à l'écran : notifications, texte de combat, gains et, avec l'Ombre du texte, le texte de zone et les messages au milieu de l'écran. Désactivé : texte doux sur une ombre sombre.",
	["Combat Text"] = "Texte de combat",
	["Numbers Over Enemies"] = "Chiffres au-dessus des ennemis",
	["The size of the game's damage numbers over enemies."] = "La taille des dégâts du jeu au-dessus des ennemis.",
	["Bar Layout"] = "Disposition des barres",
	["Which Bar"] = "Quelle barre",
	["The bar the rows below set: its rows, icons, icon size and padding. MelloUI's own action bars change at once; the stance and pet bars (and the game's bars with UI Modifications off) are saved into your active Edit Mode layout once you let a slider go, and show after a /reload."] = "La barre que règlent les lignes ci-dessous : ses rangées, icônes, taille et espacement. Les barres d'action de MelloUI changent aussitôt ; les barres de posture et de familier (et celles du jeu sans Modifications de l'interface) sont enregistrées dans votre disposition du mode Édition active quand vous relâchez un curseur, et s'affichent après un /reload.",
	["Action Bar 1"] = "Barre d'actions 1",
	["Action Bar 2"] = "Barre d'actions 2",
	["Action Bar 3"] = "Barre d'actions 3",
	["Action Bar 4"] = "Barre d'actions 4",
	["Action Bar 5"] = "Barre d'actions 5",
	["Action Bar 6"] = "Barre d'actions 6",
	["Action Bar 7"] = "Barre d'actions 7",
	["Action Bar 8"] = "Barre d'actions 8",
	["Stance Bar"] = "Barre de posture",
	["Pet Bar"] = "Barre du familier",
	["Rows"] = "Rangées",
	["How many rows the bar's buttons stand in."] = "Sur combien de rangées se placent les boutons de la barre.",
	["Icons"] = "Icônes",
	["Padding"] = "Espacement",
	["The Bar's Shape"] = "La forme de la barre",
	["A preview of the bar's layout."] = "Un aperçu de la disposition de la barre.",
	["Buff Layout"] = "Disposition des améliorations",
	["The size of your buff and debuff icons. The game's own bar changes after a /reload."] = "La taille de vos icônes d'améliorations et d'affaiblissements. La barre du jeu change après un /reload.",
	["Spacing"] = "Espacement",
	["The space between your buff and debuff icons."] = "L'espace entre vos icônes d'améliorations et d'affaiblissements.",
	["Per Row"] = "Par rangée",
	["How many buffs fit in a row before a new row starts."] = "Combien d'améliorations tiennent sur une rangée avant d'en commencer une autre.",
	["Grow"] = "Croissance",
	["Which way a row of buffs grows."] = "Dans quel sens grandit une rangée d'améliorations.",
	["New Rows"] = "Nouvelles rangées",
	["Whether new rows of buffs go below or above."] = "Si les nouvelles rangées d'améliorations vont en dessous ou au-dessus.",
	["Down"] = "Bas",
	["Up"] = "Haut",
	["Split Stack"] = "Partager une pile",
	["Mouse Wheel Amount"] = "Quantité à la molette",
	["In the split box (Shift-click a stack), the mouse wheel changes the amount; hold Shift for steps of ten."] = "Dans la boîte de division (Maj-clic sur une pile), la molette change la quantité ; maintenez Maj pour des pas de dix.",
	["Half Button"] = "Bouton moitié",
	["A ½ button in the split box that sets half the stack."] = "Un bouton ½ dans la boîte de division qui choisit la moitié de la pile.",
	["Item Slots"] = "Emplacements d'objets",
	["Quality Gems"] = "Gemmes de qualité",
	["A small gem on each item in your bags and bank, in the item's quality colour."] = "Une petite gemme sur chaque objet de vos sacs et de la banque, dans la couleur de sa qualité.",
	["Grey Out Junk"] = "Griser la camelote",
	["Junk items show grey in your bags and bank."] = "La camelote s'affiche en gris dans vos sacs et la banque.",
	["Level Up"] = "Montée de niveau",
	["A level up fills the bar with light and announces your new level."] = "Une prise de niveau remplit la barre de lumière et annonce votre nouveau niveau.",
	["Level Up Card"] = "Carte de niveau",
	["A level up shows a small window with the stats you gained and the spells now at your class trainer."] = "Un gain de niveau affiche une petite fenêtre avec les caractéristiques gagnées et les sorts qui vous attendent chez votre maître de classe.",
	["XP Gain"] = "Gain d'expérience",
	["The part of the experience bar you just gained lights up."] = "La partie de la barre d'expérience que vous venez de gagner s'illumine.",
	["Reputation Gain"] = "Gain de réputation",
	["The part of the reputation bar you just gained lights up; a new standing is announced."] = "La partie de la barre de réputation que vous venez de gagner s'illumine ; un nouveau rang est annoncé.",
	-- Stats
	["Small coloured FPS and latency readout in the bottom right corner."] = "Petit affichage coloré des IPS et de la latence dans le coin inférieur droit.",
	["Frames per second and latency in the corner. Blame the server with confidence."] = "Images par seconde et latence dans le coin. Accusez le serveur en toute confiance.",
	["Values"] = "Valeurs",
	["Show FPS"] = "Afficher les IPS",
	["Shows your frames per second."] = "Affiche vos images par seconde.",
	["Show Latency"] = "Afficher la latence",
	["Shows your latency in milliseconds."] = "Affiche votre latence en millisecondes.",
	["Show World Latency Too"] = "Afficher aussi la latence monde",
	["Also shows the world server's latency."] = "Affiche aussi la latence du serveur de monde.",
	["Look"] = "Apparence",
	["The size of the FPS and latency text."] = "La taille du texte des IPS et de la latence.",
	["The distance from the right edge of the screen."] = "La distance au bord droit de l'écran.",
	["The distance from the bottom edge of the screen."] = "La distance au bord bas de l'écran.",
	["Update Interval"] = "Intervalle de mise à jour",
	["How often the numbers update."] = "La fréquence de mise à jour des nombres.",
	-- Vendor
	["Vendor"] = "Marchand",
	["Automatically repair your gear and sell junk items when visiting a merchant."] = "Répare automatiquement votre équipement et vend la camelote en visitant un marchand.",
	["Sell the grey, mend the steel. Every merchant visit handled before the window opens."] = "Vendez le gris, réparez l'acier. Chaque visite chez le marchand réglée avant que la fenêtre s'ouvre.",
	["Repair"] = "Réparations",
	["Auto Repair"] = "Réparation auto",
	["Repairs everything at a merchant who can repair."] = "Répare tout chez un marchand qui sait réparer.",
	["Use Guild Funds"] = "Utiliser les fonds de guilde",
	["Pays repairs from the guild bank when allowed."] = "Paie les réparations avec la banque de guilde quand c'est permis.",
	["Selling"] = "Vente",
	["Auto Sell Junk"] = "Vente auto de la camelote",
	["Sells grey items at a merchant."] = "Vend les objets gris chez un marchand.",
	["Report In Chat"] = "Rapport dans la discussion",
	["Writes the repair cost and the gold from junk in the chat."] = "Écrit dans la discussion le coût des réparations et l'or tiré de la camelote.",
	-- Services
	["Services"] = "Services",
	["Buttons under the minimap that route you to the nearest repair, mailbox, inn, flight master, bank or trainer."] = "Des boutons sous la minicarte qui vous guident vers la réparation, la boîte aux lettres, l'auberge, le maître de vol, la banque ou le maître de classe le plus proche.",
	["Repair, mailbox, innkeeper, bank... the nearest one is a click under the minimap."] = "Réparation, boîte aux lettres, aubergiste, banque... le plus proche est à un clic sous la minicarte.",
	["Icon Bar Under The Minimap"] = "Barre d'icônes sous la minicarte",
	["Buttons for nearby services (repair, trainers, flights...) under the minimap. Click one to get a route there; right-click stops it."] = "Des boutons pour les services proches (réparation, maîtres, vols...) sous la minicarte. Un clic trace un itinéraire ; un clic droit l'arrête.",
	["Button Layout"] = "Disposition des boutons",
	["Groups: one row of group buttons, each opening a list of services with distances. All Buttons: two rows, one icon per service."] = "Groupes : une rangée de boutons de groupe, chacun ouvrant une liste de services avec la distance de chacun. Tous les boutons : deux rangées, une icône par service.",
	["Groups"] = "Groupes",
	["All Buttons"] = "Tous les boutons",
	["AddOns Group"] = "Groupe Add-ons",
	["Gathers other addons' minimap buttons into an AddOns group on the Services bar. Off: they go back on the minimap."] = "Regroupe les boutons de minicarte des autres add-ons dans un groupe AddOns de la barre Services. Désactivé : ils retournent sur la minicarte.",
	["Bar Distance From The Minimap"] = "Distance de la barre sous la minicarte",
	["How far below the minimap the Services bar sits."] = "La distance à laquelle la barre Services se trouve sous la minicarte.",
	["Round Icons"] = "Icônes rondes",
	["Service icons as round medallions instead of squares."] = "Icônes de service en médaillons ronds au lieu de carrés.",
	["Trays Slide Out"] = "Les plateaux glissent",
	["A group's list slides out like a drawer."] = "La liste d'un groupe glisse comme un tiroir.",
	["Minimap Button"] = "Bouton de minicarte",
	["A round button on the minimap's edge that opens the list of the nearest services. /services does the same."] = "Un bouton rond au bord de la minicarte qui ouvre la liste des services les plus proches. /services fait de même.",
	-- Reminders
	["Reminders"] = "Rappels",
	["A round button by your portrait for errands: restock, mail, repairs and trainers. Click it for a route there."] = "Un bouton rond près de votre portrait pour les tâches courantes : réapprovisionnement, courrier, réparations et maîtres. Un clic trace un itinéraire.",
	["Supplies, mail, repairs and training: a gentle nudge beside your portrait, never a nag."] = "Provisions, courrier, réparations et entraînement : un petit coup de coude près de votre portrait, jamais une rengaine.",
	["New Mail"] = "Nouveau courrier",
	["Reminds you when mail is waiting."] = "Vous rappelle qu'un courrier vous attend.",
	["Repair Gear"] = "Réparer l'équipement",
	["Reminds you when your gear is wearing out."] = "Vous rappelle que votre équipement s'use.",
	["Remind At"] = "Rappeler à",
	["Reminds you when your most worn item is down to this durability."] = "Vous rappelle quand votre objet le plus usé atteint cette durabilité.",
	["Trainer"] = "Maître",
	["Reminds you when a trainer has something new for you."] = "Vous rappelle qu'un maître a du nouveau pour vous.",
	["Class Spells"] = "Sorts de classe",
	["New class spells to learn."] = "De nouveaux sorts de classe à apprendre.",
	["Profession Ranks"] = "Rangs de métier",
	["A new profession rank to learn."] = "Un nouveau rang de métier à apprendre.",
	["Stay Up In Rest Areas"] = "Rester affiché en zone de repos",
	["In inns, cities and towns, reminders stay until done or until you leave."] = "Dans les auberges, villes et bourgs, les rappels restent jusqu'à ce qu'ils soient faits ou que vous partiez.",
	["Widget"] = "Widget",
	["Place"] = "Place",
	["Which side of your portrait the reminder button sits on. Detached or without a player frame, you move it in Edit Layout, and this is the side its line opens to."] = "De quel côté de votre portrait se place le bouton de rappel. Détaché ou sans cadre du joueur, déplacez-le avec Modifier la disposition ; c'est le côté vers lequel sa liste s'ouvre.",
	["Left of the portrait"] = "À gauche du portrait",
	["Above the portrait"] = "Au-dessus du portrait",
	["Right of the portrait"] = "À droite du portrait",
	["Detach From Portrait"] = "Détacher du portrait",
	["Gives the reminder button a place of its own, so it no longer follows your player frame. Move it in Edit Layout."] = "Donne au bouton de rappel sa propre place : il ne suit plus votre cadre du joueur. Déplacez-le avec Modifier la disposition.",
	["Glow"] = "Halo",
	["The soft glow around the reminder button: steady, or none."] = "La douce lueur autour du bouton de rappel : fixe ou aucune.",
	["Steady"] = "Fixe",
	["Show For"] = "Afficher pendant",
	["How long a new reminder stays before tucking itself away."] = "Combien de temps un nouveau rappel reste avant de se replier.",
	["Lock The Widgets"] = "Verrouiller les widgets",
	["Locks the widget column in place, also in Edit Layout."] = "Verrouille la colonne de widgets, même dans Modifier la disposition.",
	["Most Widgets Shown"] = "Widgets affichés au maximum",
	["How many widgets show at once; the rest wait in a \"+ more\" row. Loot rolls, summons and ready checks always show."] = "Nombre de widgets affichés à la fois ; les autres attendent dans une ligne « + autres ». Les jets de butin, les invocations et les vérifications de préparation restent toujours visibles.",
	-- Restock
	["Restock"] = "Réapprovisionner",
	["Keeps food, drink, ammo and reagents stocked: a reminder when low, and a shopping list at merchants."] = "Garde la nourriture, les boissons, les munitions et les composants en stock : un rappel quand il en manque, et une liste d'achats chez les marchands.",
	["Water, bread and arrows, topped up before they run out."] = "Eau, pain et flèches, complétés avant d'en manquer.",
	["Remind Below"] = "Rappeler sous",
	["Reminds you when an item drops below this share of its amount."] = "Vous rappelle quand un objet tombe sous cette part de sa quantité.",
	["Shopping List At The Shop"] = "Liste de courses chez le marchand",
	["At a merchant, a shopping list of what you are low on. Nothing is bought until you click Buy."] = "Chez un marchand, une liste de ce qui vous manque. Rien n'est acheté avant un clic sur Acheter.",
	["Restock List"] = "Liste de réapprovisionnement",
	["What to keep in your bags, and how many. Each character has its own list. /restock opens it too."] = "Ce qu'il faut garder dans vos sacs, et en quelle quantité. Chaque personnage a sa liste. /restock l'ouvre aussi.",
	["Edit"] = "Modifier",
	-- Widgets
	["Widgets"] = "Widgets",
	["Small live widgets in one column (loot rolls, summons, ready checks, whispers and more), and reminders by your portrait."] = "Petits widgets mis à jour en direct dans une colonne (jets de butin, invocations, vérifications de préparation, chuchotements, etc.) et rappels près de votre portrait.",
	["What needs you now, in one small column."] = "Tout ce qui nécessite votre attention, dans une petite colonne.",
	["In The Column"] = "Dans la colonne",
	["Loot Rolls"] = "Jets de butin",
	["Group loot rolls, with Need, Greed and Pass."] = "Jets de butin en groupe, avec Besoin, Cupidité et Passer.",
	["Corpse Run"] = "Retour au corps",
	["As a ghost: how far your body is. Click for the way there."] = "En fantôme : indique la distance jusqu'à votre corps. Un clic montre le chemin.",
	["Timed Quests"] = "Quêtes à durée limitée",
	["Timed quests and the time left."] = "Les quêtes chronométrées et le temps restant.",
	["Summons"] = "Invocations",
	["Summons, with Accept and Decline."] = "Les invocations, avec Accepter et Refuser.",
	["Resurrect Offers"] = "Offres de résurrection",
	["Resurrect offers, with Accept and Decline."] = "Les offres de résurrection, avec Accepter et Refuser.",
	["Ready Checks"] = "Vérifications de préparation",
	["Ready checks, with Ready and Not Ready."] = "Vérifications de préparation, avec les options « Prêt » et « Pas prêt ».",
	["Threat"] = "Menace",
	["In group fights, a warning when you are close to pulling or have aggro."] = "En combat de groupe, une alerte vous prévient lorsque vous êtes sur le point d’attirer la menace ou que vous l’avez déjà.",
	["Whispers"] = "Chuchotements",
	["New whispers. Reply opens the whisper window. Needs the Whisper Popup Window."] = "Nouveaux chuchotements. Répondre ouvre la fenêtre de chuchotement. Demande la fenêtre de chuchotement.",
	["Hunter Pet"] = "Familier de chasseur",
	["Your hunter pet is unhappy, with Feed Pet."] = "Votre familier de chasseur est mécontent ; l’option Nourrir le familier est disponible.",
	["Auction House"] = "Hôtel des ventes",
	["Outbid, sold, won and expired auctions."] = "Enchères sur lesquelles vous avez été surenchéri, vendues, remportées ou expirées.",
	["Crafting"] = "Artisanat",
	["Crafting progress, with Stop."] = "La progression de l'artisanat, avec Arrêter.",
	["Profession Cooldowns"] = "Temps de recharge de métier",
	["A profession cooldown is ready again."] = "Le temps de recharge d'un métier est terminé.",
	["Quest Items"] = "Objets de quête",
	["In a quest's area, the quest's item. Click to use it."] = "Dans la zone d’une quête, l’objet associé à cette quête. Cliquez dessus pour l’utiliser.",
	["Healer Drinking"] = "Soigneur qui boit",
	["When you tank: a healer is drinking, so wait before the next pull."] = "Quand vous tankez, un soigneur boit : attendez avant d’engager le combat suivant.",
	["Rare Alert"] = "Alerte rare",
	["A rare nearby, with its distance. Click to target it."] = "Un rare proche, avec la distance qui vous en sépare. Un clic le cible.",
	["Rare Alert Sound"] = "Son d'alerte rare",
	["A sound when a rare is spotted."] = "Un son quand un rare est repéré.",
	["By The Portrait"] = "Près du portrait",
	["Bags Almost Full"] = "Sacs presque pleins",
	["Your bags are almost full. Click for the way to the nearest vendor."] = "Vos sacs sont presque pleins. Cliquez pour afficher l’itinéraire vers le marchand le plus proche.",
	["Free Slots"] = "Emplacements libres",
	["Reminds you when this many free bag slots or fewer are left."] = "Vous rappelle quand il reste ce nombre d'emplacements libres ou moins.",
	["Talent Points"] = "Points de talent",
	["You have talent points to spend."] = "Vous avez des points de talent à dépenser.",
	["Well Fed Ending"] = "Fin de Bien nourri",
	["Well Fed has two minutes left."] = "Il reste deux minutes à l'effet Bien nourri.",
	["Weapon Poisons & Oils"] = "Poisons et huiles d'arme",
	["A poison, oil or sharpening stone on your weapon has run out or is ending. Click to put it back on."] = "Un poison, une huile ou une pierre à aiguiser sur votre arme a expiré ou va expirer. Un clic le remet.",
	["Your Buffs"] = "Vos améliorations",
	["One of your own buffs is missing on you. Click to cast it."] = "Il vous manque un de vos effets bénéfiques. Cliquez pour le lancer.",
	["Your Buffs On The Group"] = "Vos améliorations sur le groupe",
	["Group members are missing a buff you can cast. Click to cast it on them."] = "Des membres du groupe n'ont pas une amélioration que vous pouvez lancer. Un clic la leur lance.",
	["Which Buffs"] = "Quelles améliorations",
	["Your class's buffs, each with a switch for its reminder on you and one for the group. All on at first."] = "Les améliorations de votre classe, chacune avec un interrupteur pour son rappel sur vous et un pour le groupe. Toutes activées au départ.",
	-- Discard
	["Discard"] = "Jeter",
	["A button on the bag and loot windows that throws away your cheapest grey or white junk to free a slot (sells it at a vendor)."] = "Un bouton sur les fenêtres de sac et de butin qui jette votre camelote grise ou blanche la moins chère pour libérer un emplacement (la vend chez un vendeur).",
	["Full bags? The cheapest junk makes room, never anything worth keeping."] = "Sacs pleins ? La camelote la moins chère fait de la place, jamais rien qui vaille la peine d'être gardé.",
	["Discard Button"] = "Bouton Jeter",
	["A button on the bag window that throws away your cheapest junk item (sells it at a vendor). Never consumables, materials, quest items or your Restock list. A white item asks first."] = "Un bouton sur la fenêtre des sacs qui jette votre camelote la moins chère (la vend chez un marchand). Jamais les consommables, matériaux, objets de quête ou votre liste de réapprovisionnement. Un objet blanc demande d'abord.",
	["Discard Button On Loot"] = "Bouton Jeter sur le butin",
	["The same button on the loot window. It only throws something away for loot worth more."] = "Le même bouton sur la fenêtre de butin. Il ne jette que pour un butin qui vaut plus.",
	["Never Throw Away Items Worth"] = "Ne jamais jeter les objets valant",
	["Stacks worth this many silver or more are never thrown away (they can still be sold)."] = "Les piles valant au moins cette somme ne sont jamais jetées (elles peuvent toujours être vendues).",
	-- Gains
	["Gains"] = "Gains",
	["Short lines beside your character for what you just gained: skill ups, items and money. Move them in Edit Layout."] = "De courtes lignes près de votre personnage pour ce que vous venez de gagner : compétences, objets et argent. Déplacez-les avec Modifier la disposition.",
	["Every skill point and every new item, told softly beside your character, then gone."] = "Chaque nouvelle compétence et chaque nouvel objet sont signalés brièvement près de votre personnage, puis disparaissent.",
	["Show"] = "Afficher",
	["Skill Ups"] = "Gains de compétence",
	["A line when a skill goes up: weapons, Defense, professions and languages."] = "Une ligne quand une compétence monte : armes, Défense, métiers et langues.",
	["Show Skill Values"] = "Afficher les valeurs de compétence",
	["The skill's new value and its cap, such as 57 / 80."] = "La nouvelle valeur de la compétence et son maximum, comme 57 / 80.",
	["Looted & Received Items"] = "Objets ramassés et reçus",
	["A line for each item you get: loot, quest rewards, crafts, mail and trades."] = "Une ligne pour chaque objet obtenu : butin, récompenses de quête, artisanat, courrier et échanges.",
	["Bought Items"] = "Objets achetés",
	["A line for what you buy from a merchant."] = "Une ligne pour ce que vous achetez chez un marchand.",
	["Junk Items"] = "Camelote",
	["Also shows junk items."] = "Affiche aussi la camelote.",
	["Money"] = "Argent",
	["A line when you gain money. Gains in a row add up on one line."] = "Une ligne quand vous gagnez de l'argent. Les gains d'affilée s'additionnent sur une ligne.",
	["Currencies"] = "Monnaies",
	["A line for other currencies you gain: honor, tokens and marks."] = "Une ligne pour les autres monnaies gagnées : honneur, insignes et marques.",
	["Item Names In Quality Colour"] = "Noms d'objets dans la couleur de qualité",
	["Item names in their quality colour. Off: in the text colour, easier to read on bright ground."] = "Les noms d'objets dans leur couleur de qualité. Désactivé : dans la couleur du texte, pour une meilleure lisibilité sur fond clair.",
	["Lines"] = "Lignes",
	["How long each line stays before it fades."] = "Combien de temps chaque ligne reste avant de s'effacer.",
	-- Meter
	["Damage Meter"] = "Compteur de dégâts",
	["MelloUI's damage meter: numbers on your frames, a race bar in fights, a summary after, and a fight history. Replaces the game's meter."] = "Le compteur de dégâts de MelloUI : des nombres sur vos cadres, une barre de performance en combat, un résumé après et un historique des combats. Remplace le compteur du jeu.",
	["How the fight went, where you already look."] = "Le déroulement du combat, affiché là où vous regardez déjà.",
	["Your Values"] = "Vos valeurs",
	["Your damage per second, run total and healing per second beside your player frame."] = "Vos dégâts par seconde, le total de la session et vos soins par seconde à côté de votre cadre de joueur.",
	["Party Values"] = "Valeurs du groupe",
	["The same numbers beside each party frame, and beside your own when it shows in your party."] = "Les mêmes valeurs à côté de chaque cadre de groupe, y compris le vôtre lorsqu'il apparaît dans le groupe.",
	["On Raid-Style Frames"] = "Sur les cadres style raid",
	["A damage or healing number on each raid-style frame. Point at a frame for all three."] = "Un nombre de dégâts ou de soins sur chaque cadre de style raid. Survolez un cadre pour voir les trois valeurs.",
	["Race Bar"] = "Barre de performance",
	["In a fight, a race bar of your group's damage, with you highlighted. Point at it for everyone's numbers."] = "En combat, une barre de performance des dégâts de votre groupe, avec votre score mis en évidence. Survolez-la pour voir les valeurs de chaque joueur.",
	["Race Bar Shows"] = "La barre de performance montre",
	["What the race bar compares. Auto: healing as a healer, damage otherwise."] = "Ce que compare la barre de performance. Auto : les soins en soigneur, sinon les dégâts.",
	["Auto"] = "Auto",
	["Damage"] = "Dégâts",
	["Healing"] = "Soins",
	["Race Bar Pins"] = "Repères de la barre de performance",
	["How many players the race bar shows. You are always on it."] = "Nombre de joueurs affichés par la barre de performance. Vous y êtes toujours.",
	["Race Bar Width"] = "Largeur de la barre de performance",
	["How wide the race bar is."] = "Largeur de la barre de performance.",
	["Race Bar Thickness"] = "Épaisseur de la barre de performance",
	["How thick the race bar's line is."] = "Épaisseur de la ligne de la barre de performance.",
	["Fight Summary"] = "Résumé du combat",
	["After a fight, a short summary in the widget column: your damage, DPS and rank. Click it for the full fight."] = "Après un combat, un court résumé dans la colonne de widgets : vos dégâts, DPS et rang. Un clic montre le combat entier.",
	["Fight History"] = "Historique des combats",
	["A window with every fight of this session: damage, healing and your spells. Opens from the chat's buttons."] = "Une fenêtre avec chaque combat de cette session : dégâts, soins et vos sorts. S'ouvre depuis les boutons de la discussion.",
	["Fights Kept"] = "Combats conservés",
	["How many fights the history keeps. It starts empty at each login."] = "Nombre de combats conservés dans l'historique. Il est vide à chaque connexion.",
	-- SwingTimers
	["Swing Timers"] = "Minuteurs d'attaque",
	["Your swing timer as a badge on your target's nameplate. Replaces the game's swing timers."] = "Votre minuteur d'attaque en badge sur la barre d'info de votre cible. Remplace les minuteurs d'attaque du jeu.",
	["Every swing and shot at a glance."] = "Chaque coup et chaque tir d'un coup d'œil.",
	["Shots"] = "Tirs",
	["Your Auto Shot on the swing badge: reload, then aim."] = "Votre Tir automatique sur le badge d'attaque : rechargez, puis visez.",
	["Melee Swings"] = "Coups de mêlée",
	["Your main hand's swings on the swing badge. Wand shots too."] = "Les coups de votre main droite sur le badge d'attaque. Les tirs de baguette aussi.",
	["Off Hand"] = "Main gauche",
	["Your off hand's swings on a smaller badge."] = "Les coups de votre main gauche sur un badge plus petit.",
	["Swing Ring Width"] = "Largeur de l'anneau d'attaque", -- draft
	["How wide the ring round the swing badge is, the one that fills as your next swing nears. The Personal Display's badge wears it too."] = "La largeur de l'anneau autour du badge d'attaque, celui qui se remplit à l'approche de votre prochaine attaque. Le badge de l'affichage personnel le porte aussi.", -- draft
	["Thin"] = "Fin", -- draft
	["Medium"] = "Moyen", -- draft
	["Thick"] = "Épais", -- draft
	["Swing Ring Colour"] = "Couleur de l'anneau d'attaque", -- draft
	["The colour of the ring that fills as your next swing nears; the palette's gold until you pick one. The Personal Display's badge wears it too."] = "La couleur de l'anneau qui se remplit à l'approche de votre prochaine attaque ; l'or de la palette tant que vous n'en choisissez pas. Le badge de l'affichage personnel le porte aussi.", -- draft
	-- PartyMarkers
	["Party Markers"] = "Marqueurs de groupe",
	["A class medallion over your party members' nameplates, ringed in their role's colour. Open world only."] = "Un médaillon de classe au-dessus des barres d'info des membres du groupe, cerclé de la couleur de leur rôle. Uniquement en monde ouvert.",
	["A class medallion over every party member's head, ringed in their role's colour: the healer, found at a glance."] = "Un médaillon de classe au-dessus de la tête de chaque membre du groupe, cerclé de la couleur de son rôle : le soigneur, repéré d'un coup d'œil.",
	["Markers"] = "Marqueurs",
	["Mark"] = "Marquer",
	["Whose nameplate gets a class medallion."] = "Quelle barre d'info reçoit un médaillon de classe.",
	["Party and raid members"] = "Membres du groupe et du raid",
	["Every friendly player"] = "Tous les joueurs alliés",
	["Marker Size"] = "Taille du marqueur",
	["The medallion's size."] = "La taille du médaillon.",
	["Height Above The Name"] = "Hauteur au-dessus du nom",
	["The space between the name and the medallion."] = "L'espace entre le nom et le médaillon.",
	["Role Ring"] = "Anneau de rôle",
	["A ring in the member's role colour around the medallion: green healer, blue tank, red damage."] = "Un anneau à la couleur du rôle autour du médaillon : vert soigneur, bleu tank, rouge dégâts.",
	["Open world only: inside instances the game keeps friendly nameplates to itself"] = "Uniquement en monde ouvert : dans les instances, le jeu gère lui-même les barres d'info alliées.",
	-- Sparkles
	["Loot Sparkles"] = "Étincelles de butin",
	["Keeps the sparkle on lootable quest items, and adds glints over nearby ore and herbs."] = "Garde l'éclat sur les objets de quête à ramasser, et ajoute des reflets sur le minerai et les herbes proches.",
	["What you can loot, at a glance."] = "Ce que vous pouvez ramasser, d'un coup d'œil.",
	["Quest Item Sparkles"] = "Étincelles des objets de quête",
	["Keeps the game's sparkle on lootable quest items. Turning it off takes effect after a game restart."] = "Garde l'éclat du jeu sur les objets de quête à ramasser. La désactivation prend effet après un redémarrage du jeu.",
	["Ore Veins"] = "Filons de minerai",
	["Golden glints over the nearest ore vein: bright when you can mine it, grey when your skill is too low."] = "Des reflets dorés sur le filon le plus proche : vifs si vous pouvez miner, gris si votre compétence est trop basse.",
	["Herbs"] = "Herbes",
	["The same glints over the nearest herb."] = "Les mêmes reflets sur l'herbe la plus proche.",
	["Quest Objects"] = "Objets de quête",
	["The same glints over the nearest quest object."] = "Les mêmes reflets sur l'objet de quête le plus proche.",
	-- CustomSounds
	["Custom Sounds"] = "Sons personnalisés",
	["Replaces the interface's sounds with MelloUI's own, in the set of your skin: clicks, windows, bags, gear, vendors and more. The Default skin keeps the game's own sounds."] = "Remplace les sons de l'interface par ceux de MelloUI, dans le style de votre habillage : clics, fenêtres, sacs, équipement, marchands et plus. L'habillage Par défaut garde les sons du jeu.",
	["Every click, page, pouch and latch of the interface, re-recorded: light and clean for Modern, iron and leather for Oldschool."] = "Chaque clic, page, bourse et loquet de l'interface, réenregistré : léger et net pour Moderne, fer et cuir pour Oldschool.",
	["Sounds"] = "Sons",
	["Clicks"] = "Clics",
	["Clicks on buttons, checkboxes and tabs."] = "Clics sur les boutons, cases à cocher et onglets.",
	["Page turns and latches when windows open and close."] = "Pages tournées et loquets à l'ouverture et la fermeture des fenêtres.",
	["Inventory"] = "Inventaire",
	["Picking up, moving and looting items. Needed for the Equipment and Vendor sounds."] = "Ramasser, déplacer et piller des objets. Nécessaire aux sons Équipement et Vendeur.",
	["Equipment"] = "Équipement",
	["Buckles, steel and jewellery when you put gear on or take it off."] = "Boucles, acier et bijoux quand vous mettez ou retirez de l'équipement.",
	["Coins when you buy and sell."] = "Des pièces à l'achat et à la vente.",
	["Social"] = "Social",
	["A note for a whisper, two knocks for a group invite."] = "Un billet pour un chuchotement, deux coups pour une invitation de groupe.",
	["Group Finder"] = "Recherche de groupe",
	["Joining and leaving a queue, and a bell when your group is ready."] = "Entrer et sortir d'une file, et une cloche quand votre groupe est prêt.",
	["A workbench sound when you craft."] = "Un son d'établi lorsque vous fabriquez.",
	["Quests"] = "Quêtes",
	["A sound when you turn in a quest."] = "Un son lorsque vous rendez une quête.",
	["Errors"] = "Erreurs",
	["A muted knock for the game's red error messages."] = "Un coup étouffé pour les messages d'erreur rouges du jeu.",
	["Targets"] = "Cibles",
	["A click when you pick or lose a target."] = "Un clic lorsque vous sélectionnez ou perdez une cible.",
	["A jingle when you level up."] = "Un carillon lorsque vous gagnez un niveau.",
	["Loot Coins"] = "Pièces du butin",
	["Coins when you loot money."] = "Des pièces quand vous ramassez de l'argent.",
	["Spell Icons"] = "Icônes de sort",
	["Sounds when you drag and place spells."] = "Des sons quand vous glissez et placez des sorts.",
	["Map Ping"] = "Signal sur la carte",
	["A clear sound for a minimap ping."] = "Un son clair pour un signal sur la minicarte.",
	["Scroll Wheel"] = "Molette",
