	-- Nameplates
	["Large crowd-control icon above the name and a quest marker on enemy nameplates."] = "Une grande icône de contrôle au-dessus du nom et un marqueur de quête sur les barres d'info ennemies.",
	["Know who is stunned, who is your quest target, and who is about to be a problem."] = "Sachez qui est étourdi, qui est votre cible de quête, et qui va poser problème.",
	["Own Plate Size"] = "Taille de barre personnelle",
	["The enemy plates take the width and height set here instead of the game's."] = "Les barres ennemies prennent la largeur et la hauteur réglées ici au lieu de celles du jeu.",
	["Plate Width"] = "Largeur de barre",
	["The whole plate's width: the health bar and the level badge's room beside it."] = "La largeur de toute la barre : la barre de vie et la place de l'insigne de niveau à côté.",
	["Plate Height"] = "Hauteur de barre",
	["The health bar's height."] = "La hauteur de la barre de vie.",
	["Crowd Control"] = "Contrôle des foules",
	["Large CC Icon Above Name"] = "Grande icône de contrôle au-dessus du nom",
	["A large crowd-control icon above the name. Needs the game's Crowd Control nameplate option on."] = "Une grande icône de contrôle au-dessus du nom. Activez l'option de contrôle des foules des barres d'info du jeu.",
	["CC Icon Size"] = "Taille de l'icône de contrôle",
	["The size of the crowd-control icon."] = "La taille de l'icône de contrôle.",
	["Gap Above Name"] = "Écart au-dessus du nom",
	["The space between the name and the crowd-control icon."] = "L'espace entre le nom et l'icône de contrôle.",
	["Mouseover Highlight"] = "Surbrillance au survol",
	["A crisp outline on the plate under your mouse."] = "Un contour net sur la barre d'info sous votre souris.",
	["Quest Icon"] = "Icône de quête",
	["A quest marker on enemies you still need for a quest."] = "Un marqueur de quête sur les ennemis qu'il vous reste à vaincre pour une quête.",
	["Quest Icon Size"] = "Taille de l'icône de quête",
	["The size of the quest marker."] = "La taille du marqueur de quête.",
	["Threat Line"] = "Ligne de menace",
	["In group fights, a thin line on an enemy's bar showing how close it is to turning on you. For tanks, it turns red when you lose a mob."] = "En combat de groupe, une fine ligne sur la barre d'un ennemi indique s'il est sur le point de vous attaquer. Pour les tanks, elle devient rouge lorsque vous perdez la menace d'un ennemi.",
	["Combo Points"] = "Points de combo",
	["Rogues and cat druids: your combo points on your target's nameplate."] = "Voleurs et druides en forme de félin : vos points de combo sur la barre d’info de votre cible.",
	["Combo Point Size"] = "Taille des points de combo",
	["The size of each combo point."] = "La taille de chaque point de combo.",
	["Moves the combo points left or right on the nameplate."] = "Déplace les points de combo vers la gauche ou la droite sur la barre d'info.",
	["Moves the combo points up or down on the nameplate. The name moves out of their way."] = "Déplace les points de combo vers le haut ou le bas sur la barre d'info. Le nom s'écarte pour leur laisser la place.",
	["Swing Badge"] = "Badge d'attaque",
	["Swing Badge Size"] = "Taille de l'insigne de frappe",
	["The size of your swing timer's weapon badge on your target's nameplate, or over the Personal Display."] = "La taille de l'insigne d'arme de votre minuteur de frappe sur la barre d'info de votre cible ou au-dessus de l'affichage personnel.",
	-- PlateImpact
	["Impact Effects"] = "Effets d'impact",
	["Your target's nameplate reacts to the fight: hits flash, crits glow, interrupted casts shatter."] = "La barre d'info de votre cible réagit au combat : les coups clignotent, les critiques brillent et les incantations interrompues volent en éclats.",
	["Every hit lands on the plate, not only in a number."] = "Chaque coup frappe la barre, pas seulement un chiffre.",
	["Hit Flash"] = "Flash de coup",
	["Your target's bar flashes when it is hit; gold for a critical hit."] = "La barre de votre cible clignote lorsqu'elle est touchée ; elle devient dorée en cas de coup critique.",
	["Damage Chunk"] = "Morceau de dégâts",
	["The part of the bar a hit took stays lit for a moment before it drains, so you see each hit's size."] = "La portion de la barre correspondant aux dégâts d'un coup reste éclairée un instant avant de se vider, afin d'en voir l'importance.",
	["Crit Glow"] = "Lueur critique",
	["A gold glow bursts around your target's bar on a critical hit."] = "Une lueur dorée éclate autour de la barre de votre cible sur un critique.",
	["Kill Flash"] = "Flash fatal",
	["A killing blow flashes the bar out instead of the plate just vanishing."] = "Un coup fatal fait clignoter la barre au lieu de faire simplement disparaître la barre d'info.",
	["Dodge And Miss"] = "Esquive et raté",
	["Dodge, parry and miss words flick off the side of your target's plate."] = "Les mots « esquive », « parade » et « raté » s'envolent du bord de la barre d'info de votre cible.",
	["Cast Warning"] = "Alerte d'incantation",
	["Your target's cast bar glows hotter near the end, and shatters when interrupted."] = "La barre d'incantation de votre cible chauffe vers la fin et vole en éclats si elle est interrompue.",
	["On Your Target Frame"] = "Sur le cadre de la cible",
	["Your target frame's health bar shows the same hit effects."] = "La barre de vie de votre cadre de cible montre les mêmes effets de coup.",
	-- Tooltip
	["Tooltip"] = "Encadrés d’aide",
	["Dark flat tooltips with class coloured names and borders, plus placement options."] = "Des encadrés d'aide sombres et plats avec noms et bordures aux couleurs de classe, plus des options de placement.",
	["Dark, flat and out of the way, with names in the colour of their class."] = "Sombres, plats et discrets, avec les noms dans la couleur de leur classe.",
	["Background"] = "Fond",
	["The tooltips' background: Dark, the game's own, or (with Oldschool) Painted or Parchment."] = "Le fond des encadrés d'aide : Sombre, celui du jeu ou (avec Oldschool) Peint ou Parchemin.",
	["Painted"] = "Peint",
	["Parchment"] = "Parchemin",
	["Dark"] = "Sombre",
	["Game"] = "Jeu",
	["Backdrop Opacity"] = "Opacité du fond",
	["How solid the Dark background is."] = "L'opacité du fond Sombre.",
	["Border"] = "Bordure",
	["The border round the Dark background: a dark line in your palette's colour, the game's own, none, or one shared by a SharedMedia addon."] = "La bordure autour du fond sombre : une ligne foncée de la couleur de votre palette, celle du jeu, aucune bordure ou une bordure fournie par un addon SharedMedia.",
	["Class / Reaction Border"] = "Bordure classe / réaction",
	["Colours a unit tooltip's border by class (players) or reaction (NPCs)."] = "Colore la bordure d'un encadré d'aide d'unité selon la classe (joueurs) ou la réaction (PNJ).",
	["Units"] = "Unités",
	["Class / Reaction Health Colour"] = "Couleur de vie classe / réaction",
	["The tooltip's health bar in the class or reaction colour instead of green."] = "La barre de vie de l'encadré d'aide adopte la couleur de classe ou de réaction au lieu du vert.",
	["Hide Health Bar"] = "Masquer la barre de vie",
	["Hides the health bar under unit tooltips."] = "Masque la barre de vie sous les encadrés d'aide d'unité.",
	["Hide Issue Report Line"] = "Masquer la ligne de signalement",
	["Hides the beta's \"Press F6 to submit an issue\" line in tooltips."] = "Masque la ligne de la bêta « Appuyez sur F6 pour signaler un problème » dans les encadrés d'aide.",
	["Coloured Lines"] = "Lignes colorées",
	["Colours tooltip lines: guild, faction, level difficulty and quest progress."] = "Colore les lignes des encadrés d'aide : guilde, faction, difficulté de niveau et progression de quête.",
	["Hide Unit Tooltips In Combat"] = "Masquer les encadrés d'unités en combat",
	["No unit tooltips in combat."] = "Aucun encadré d'aide d'unité en combat.",
	["Fade Delay"] = "Délai de disparition",
	["How long a tooltip stays after your mouse leaves."] = "La durée pendant laquelle un encadré d'aide reste affiché après le départ de la souris.",
	["Placement"] = "Placement",
	["Anchor"] = "Ancrage",
	["Where tooltips appear."] = "Où apparaissent les encadrés d'aide.",
	["Default (Edit Mode position)"] = "Par défaut (mode Édition)",
	["At the cursor"] = "Au curseur",
	["Right of the cursor"] = "À droite du curseur",
	["Scale"] = "Échelle",
	["The size of tooltips."] = "La taille des encadrés d'aide.",
	-- UnitFrames
	["Centred names, a clear name band and no combat flash for player, target and focus; the party's levels and the names' soft bands."] = "Noms centrés, bandeau de nom net et absence de flash de combat pour le joueur, la cible et la focalisation ; niveaux du groupe et bandeaux doux autour des noms.",
	["Player, target and focus, centred and calm."] = "Joueur, cible et focalisation, centrés et calmes.",
	["MelloUI Frames"] = "Cadres MelloUI",
	["The unit frames in MelloUI's look: a gold portrait ring, a level badge and gold-lined borders. Off: the game's own art."] = "Les cadres d'unité dans le style de MelloUI : anneau de portrait doré, badge de niveau et bordures à filet doré. Désactivé : les graphismes du jeu.",
	["Target of Target"] = "Cible de la cible",
	["Shows who your target is targeting, under the target frame, and who your focus is targeting, under the focus frame. This is the game's own Target of Target setting. A change here takes effect after a /reload."] = "Affiche la cible de votre cible sous le cadre de cible, et celle de votre focalisation sous le cadre de focalisation. C'est le réglage « Cible de la cible » du jeu. Un changement ici s'applique après un /reload.",
	["Flip Horizontally"] = "Retourner horizontalement",
	["Mirrors the party frames for a party on the right of the screen: portraits on the right."] = "Inverse les cadres de groupe pour un groupe à droite de l'écran : portraits à droite.",
	["Names"] = "Noms",
	["Name Font"] = "Police des noms",
	["The font of names on the unit frames and party portraits. Shared: the interface font."] = "La police des noms sur les cadres d'unité et portraits de groupe. Partagée : la police de l'interface.",
	["Glows"] = "Halos",
	["Hide Combat Flash"] = "Masquer le flash de combat",
	["Hides the threat glow on the unit frames. Off: a soft halo round each frame's own shape while it has threat, amber when close to pulling, red while holding the enemy."] = "Masque la lueur de menace sur les cadres d’unité. Désactivé : un halo discret épouse la forme de chaque cadre lorsque l’unité attire la menace ; il devient ambre quand elle est sur le point de l’attirer et rouge lorsqu’elle détient la menace.",
	["Hide Status Glow"] = "Masquer le halo d'état",
	["Hides the resting and combat glow around your portrait, and your pet's attack glow."] = "Masque la lueur de repos et de combat autour de votre portrait, et la lueur d'attaque de votre familier.",
	["Hide PvP Badge"] = "Masquer l'insigne JcJ",
	["Hides the PvP badge beside the portraits."] = "Masque le badge JcJ à côté des portraits.",
	["Hide Heal Numbers"] = "Masquer les nombres de soins",
	["Your portrait no longer shows the green numbers of the heals you take. Damage, misses and mana gains still show."] = "Votre portrait n'affiche plus les nombres verts des soins que vous recevez. Les dégâts, les échecs et les gains de mana s'affichent toujours.",
	["Frame Art"] = "Art des cadres",
	-- Fader
	["Fader"] = "Fondu",
	["Fades parts of the interface while you don't need them: out of combat, or until you point at them."] = "Estompe des parties de l'interface quand vous n'en avez pas besoin : hors combat, ou jusqu'à ce que vous les survoliez.",
	["Your interface, only when you need it."] = "Votre interface, seulement quand vous en avez besoin.",
	["Fade Everything"] = "Tout estomper",
	["Sets every part below to In Combat: the interface fades out of combat and comes back in a fight."] = "Met chaque partie ci-dessous sur En combat : l'interface s'estompe hors combat et revient en combat.",
	["Fade"] = "Estomper",
	["Fade Nothing"] = "Rien estomper",
	["Sets every part below to Always: nothing fades."] = "Met chaque partie ci-dessous sur Toujours : rien ne s'estompe.",
	["Reset"] = "Réinitialiser",
	["Faded Opacity"] = "Opacité estompée",
	["How visible a faded part stays. 0%: hidden until needed."] = "La visibilité d'une partie estompée. 0 % : cachée jusqu'à ce qu'elle soit nécessaire.",
	["Fade After"] = "Estomper après",
	["How long a part waits before fading, after a fight or after your mouse leaves."] = "Combien de temps une partie attend avant de s'estomper, après un combat ou lorsque la souris l'a quittée.",
	["Fade Speed"] = "Vitesse du fondu",
	["How long the fade takes. Coming back is always quick."] = "La durée du fondu. Le retour est toujours rapide.",
	["Show With A Target"] = "Afficher avec une cible",
	["In Combat parts also come back while you have a target."] = "Les éléments configurés sur « En combat » reviennent aussi tant que vous avez une cible.",
	["Also Show On Mouseover"] = "Afficher aussi au survol",
	["In Combat parts also come back while your mouse is over them."] = "Les éléments configurés sur « En combat » reviennent aussi tant que la souris les survole.",
	["Your own frame. In Combat, it also returns while you are hurt, low on mana or dead. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Votre propre cadre. En combat, il revient aussi tant que vous êtes blessé, à court de mana ou mort. Toujours : jamais estompé. En combat : estompé hors combat. Au survol : estompé jusqu'à ce que vous le survoliez.",
	["Pet Frame Too"] = "Cadre du familier aussi",
	["Your pet's frame fades with the player frame and returns while your pet is hurt."] = "Le cadre de votre familier s'estompe avec celui du joueur et revient tant que votre familier est blessé.",
	["Your target's frame and its target. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Le cadre de votre cible et sa cible. Toujours : jamais estompé. En combat : estompé hors combat. Au survol : estompé jusqu'à ce que vous le survoliez.",
	["Your focus's frame. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Le cadre de votre focalisation. Toujours : jamais estompé. En combat : estompé hors combat. Au survol : estompé jusqu'à ce que vous le survoliez.",
	["Party Frames"] = "Cadres de groupe",
	["The party frames. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Les cadres de groupe. Toujours : jamais estompés. En combat : estompés hors combat. Au survol : estompés jusqu'à ce que vous les survoliez.",
	["The raid frames. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Les fenêtres de raid. Toujours : jamais estompées. En combat : estompées hors combat. Au survol : estompées jusqu'à ce que vous les survoliez.",
	["Your buffs and debuffs. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Vos améliorations et affaiblissements. Toujours : jamais estompés. En combat : estompés hors combat. Au survol : estompés jusqu'à ce que vous les survoliez.",
	["The reminder buttons beside your portrait. A new reminder doesn't bring them back. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Les boutons de rappel près de votre portrait. Un nouveau rappel ne les ramène pas. Toujours : jamais estompés. En combat : estompés hors combat. Au survol : estompés jusqu'à ce que vous les survoliez.",
	["The Personal Display's bars. In Combat, they also return while you cast. Always: never faded. In Combat: faded out of combat."] = "Les barres de l'Affichage personnel. En combat, elles reviennent aussi pendant vos incantations. Toujours : jamais estompées. En combat : estompées hors combat.",
	["Main Action Bar"] = "Barre d'actions principale",
	["The main action bar. Its keys still work while faded. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "La barre d'actions principale. Ses touches marchent même estompée. Toujours : jamais estompée. En combat : estompée hors combat. Au survol : estompée jusqu'à ce que vous la survoliez.",
	["Its keys still work while faded. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Ses touches marchent même estompée. Toujours : jamais estompée. En combat : estompée hors combat. Au survol : estompée jusqu'à ce que vous la survoliez.",
	["Stance & Pet Bar"] = "Barre de posture et de familier",
	["The stance, form and pet bars. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Les barres de posture, de forme et de familier. Toujours : jamais estompées. En combat : estompées hors combat. Au survol : estompées jusqu'à ce que vous les survoliez.",
	["Micro Menu"] = "Micro-menu",
	["The micro menu. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Le micro-menu. Toujours : jamais estompé. En combat : estompé hors combat. Au survol : estompé jusqu'à ce que vous le survoliez.",
	["Bag Bar"] = "Barre de sacs",
	["The bag bar. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "La barre de sacs. Toujours : jamais estompée. En combat : estompée hors combat. Au survol : estompée jusqu'à ce que vous la survoliez.",
	["The experience and reputation bars. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Les barres d'expérience et de réputation. Toujours : jamais estompées. En combat : estompées hors combat. Au survol : estompées jusqu'à ce que vous les survoliez.",
	["The chat windows, tabs and buttons. They return while you type. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Les fenêtres de discussion, onglets et boutons. Ils reviennent pendant que vous tapez. Toujours : jamais estompés. En combat : estompés hors combat. Au survol : estompés jusqu'à ce que vous les survoliez.",
	["The minimap and the Services bar. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "La minicarte et la barre Services. Toujours : jamais estompées. En combat : estompées hors combat. Au survol : estompées jusqu'à ce que vous les survoliez.",
	["Quest Tracker"] = "Suivi des quêtes",
	["MelloUI's Quest Tracker. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Le suivi des quêtes de MelloUI. Toujours : jamais estompé. En combat : estompé hors combat. Au survol : estompé jusqu'à ce que vous le survoliez.",
	["Objective Tracker"] = "Suivi des objectifs",
	["The game's objective tracker. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Le suivi des objectifs du jeu. Toujours : jamais estompé. En combat : estompé hors combat. Au survol : estompé jusqu'à ce que vous le survoliez.",
	["Widget Column"] = "Colonne de widgets",
	["The widget column. A new widget doesn't bring it back. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "La colonne de widgets. Un nouveau widget ne la ramène pas. Toujours : jamais estompée. En combat : estompée hors combat. Au survol : estompée jusqu'à ce que vous la survoliez.",
	["World Marker"] = "Marqueur du monde",
	["Route's World Marker. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "Le marqueur du monde de Route. Toujours : jamais estompé. En combat : estompé hors combat. Au survol : estompé jusqu'à ce que vous le survoliez.",
	["The FPS and latency readout. Always: never faded. In Combat: faded out of combat. On Mouseover: faded until you point at it."] = "L'affichage des IPS et de la latence. Toujours : jamais estompé. En combat : estompé hors combat. Au survol : estompé jusqu'à ce que vous le survoliez.",
	-- QuestAuto
	["Auto Accept & Hand In"] = "Acceptation et remise automatiques",
	["Accepts quests and hands them in as you talk to their givers, off until you switch it on."] = "Accepte les quêtes et les remet lorsque vous parlez à leurs donneurs ; la fonction reste désactivée tant que vous ne l'activez pas.",
	["Talk, and the quest is yours. Hold Shift to read it first."] = "Parlez, et la quête est à vous. Maintenez Maj pour la lire d'abord.",
	["Auto Accept Quests"] = "Accepter les quêtes automatiquement",
	["Accepts quests as soon as a giver offers them. Repeatable, daily and shared quests are left to you."] = "Accepte les quêtes dès qu'un donneur les propose. Les quêtes répétables, journalières et partagées restent à votre charge.",
	["Auto Hand In"] = "Rendu automatique",
	["Hands in finished quests as soon as you talk to the NPC. A choice of rewards waits for you."] = "Rend les quêtes terminées dès que vous parlez au PNJ. Un choix de récompenses vous attend.",
	["Take The Upgrade"] = "Prendre l'amélioration",
	["With a choice of rewards, takes the best upgrade you can use, or the one that sells for the most."] = "Avec un choix de récompenses, prend la meilleure amélioration utilisable, ou celle qui se vend le plus cher.",
	["Skip Key"] = "Touche pour passer",
	["Hold this key while talking to an NPC to stop the automatic accept and hand-in."] = "Maintenez cette touche en parlant à un PNJ pour arrêter l'acceptation et la remise automatiques.",
	["Shift"] = "Maj",
	["Ctrl"] = "Ctrl",
	["Alt"] = "Alt",
	-- HealerFrames
	["Healer Frames"] = "Cadres de soigneur",
	["Incoming heals on the unit frames, and a glow in a debuff's colour round any frame whose unit has a debuff to remove."] = "Les soins entrants sur les cadres d’unité, et un halo de la couleur d'un affaiblissement autour de chaque cadre dont l'unité a un affaiblissement dissipable.",
	["See the heals coming in, and who needs a cleanse."] = "Voyez les soins arriver, et qui a besoin d'une purification.",
	["Incoming Heals"] = "Soins entrants",
	["Incoming heals and shields shown on the player, target and focus health bars."] = "Soins et boucliers à venir sur les barres de vie du joueur, de la cible et de la focalisation.",
	["Debuff Glow"] = "Halo d'affaiblissement",
	["A glow in the debuff's colour around a friend's frame while they have a debuff that can be removed."] = "Une lueur à la couleur de l'affaiblissement autour du cadre d'un allié qui a un affaiblissement dissipable.",
	["Debuff Glow Shows"] = "Le halo d'affaiblissement montre",
	["Which debuffs light a frame: any that can be removed, the ones your group can remove, or only yours."] = "Quels affaiblissements allument un cadre : tout dissipable, ceux que votre groupe peut dissiper, ou seulement les vôtres.",
	["Every Dispellable Debuff"] = "Tout affaiblissement dissipable",
	["Ones The Group Can Dispel"] = "Ceux que le groupe peut dissiper",
	["Ones I Can Dispel"] = "Ceux que je peux dissiper",
	-- ActionBars
	["MelloUI on the bars: its own action, stance, pet and possess bars, micro menu, bag bar and experience bars, with their backdrops, button frames, colours and timers. Off: the game's own bars, untouched."] = "MelloUI sur les barres : ses propres barres d'action, de posture, de familier et de possession, le micro-menu, la barre de sacs et les barres d'expérience, avec leurs fonds, cadres de boutons, couleurs et minuteurs. Désactivé : les barres du jeu, intactes.",
	["The experience and reputation bars in MelloUI's look. Off: the game's own frame."] = "Les barres d'expérience et de réputation dans le style de MelloUI. Désactivé : le cadre du jeu.",
	["Hide Page Arrows"] = "Masquer les flèches de page",
	["Hides the main bar's page number and arrows. Paging keys still work."] = "Masque le numéro de page et les flèches de la barre principale. Les touches de page marchent toujours.",
	["Hide Bar Art"] = "Masquer l'art de la barre",
	["Hides the main bar's art, like the other bars. With UI Modifications off: only on your own Edit Mode layouts, after a /reload."] = "Masque le décor de la barre principale, comme pour les autres barres. Sans Modifications de l'interface : seulement sur vos propres dispositions du mode Édition, après un /reload.",
	["A backdrop around Action Bar 1. Neighbours with a backdrop share one."] = "Un fond autour de la barre d'actions 1. Les éléments voisins qui ont un fond en partagent un.",
	["A backdrop around Action Bar 2. Neighbours with a backdrop share one."] = "Un fond autour de la barre d'actions 2. Les éléments voisins qui ont un fond en partagent un.",
	["A backdrop around Action Bar 3. Neighbours with a backdrop share one."] = "Un fond autour de la barre d'actions 3. Les éléments voisins qui ont un fond en partagent un.",
	["A backdrop around Action Bar 4. Neighbours with a backdrop share one."] = "Un fond autour de la barre d'actions 4. Les éléments voisins qui ont un fond en partagent un.",
	["A backdrop around Action Bar 5. Neighbours with a backdrop share one."] = "Un fond autour de la barre d'actions 5. Les éléments voisins qui ont un fond en partagent un.",
	["A backdrop around Action Bar 6. Neighbours with a backdrop share one."] = "Un fond autour de la barre d'actions 6. Les éléments voisins qui ont un fond en partagent un.",
	["A backdrop around Action Bar 7. Neighbours with a backdrop share one."] = "Un fond autour de la barre d'actions 7. Les éléments voisins qui ont un fond en partagent un.",
	["A backdrop around Action Bar 8. Neighbours with a backdrop share one."] = "Un fond autour de la barre d'actions 8. Les éléments voisins qui ont un fond en partagent un.",
	["A backdrop around the stance bar. Neighbours with a backdrop share one."] = "Un fond autour de la barre de posture. Les éléments voisins qui ont un fond en partagent un.",
	["A backdrop around the pet bar. Neighbours with a backdrop share one."] = "Un fond autour de la barre de familier. Les éléments voisins qui ont un fond en partagent un.",
	["Possess Bar"] = "Barre de possession",
	["A backdrop around the possess bar. Neighbours with a backdrop share one."] = "Un fond autour de la barre de possession. Les éléments voisins qui ont un fond en partagent un.",
	["Totem Bar"] = "Barre de totems",
	["A backdrop around the totem bar. Neighbours with a backdrop share one."] = "Un fond autour de la barre de totems. Les éléments voisins qui ont un fond en partagent un.",
	["A backdrop around the micro menu. Neighbours with a backdrop share one."] = "Un fond autour du micro-menu. Les éléments voisins qui ont un fond en partagent un.",
	["A backdrop around the bag bar. Neighbours with a backdrop share one."] = "Un fond autour de la barre de sacs. Les éléments voisins qui ont un fond en partagent un.",
	["Experience Bar"] = "Barre d'expérience",
	["A backdrop around the experience bar (the reputation bar in its place at the top level). Neighbours with a backdrop share one."] = "Un fond autour de la barre d'expérience (la barre de réputation à sa place au niveau maximum). Les éléments voisins qui ont un fond en partagent un.",
	["Reputation Bar"] = "Barre de réputation",
	["A backdrop around the second status bar (a watched reputation while you level). Neighbours with a backdrop share one."] = "Un fond autour de la seconde barre d'état (la réputation suivie pendant la montée de niveau). Les éléments voisins qui ont un fond en partagent un.",
	-- ActionButtons
	["Action Buttons"] = "Boutons d'action",
	["Lights an action button while its key is held, and colours its icon by range and resources."] = "Allume un bouton d'action tant que sa touche est enfoncée, et colore son icône selon la portée et les ressources.",
	["See which button you press, and which spell cannot reach its target."] = "Voyez quel bouton vous pressez, et quel sort ne peut pas atteindre sa cible.",
	["Action buttons in MelloUI's frame: gold when active, red out of range. Off: the game's own frames."] = "Boutons d'action dans le cadre de MelloUI : dorés quand actifs, rouges hors de portée. Désactivé : les cadres du jeu.",
	["Cooldown Ready Flash"] = "Flash de recharge prête",
	["A gold light runs around a button when its cooldown ends."] = "Une lumière dorée fait le tour d'un bouton quand son temps de recharge finit.",
	["Light While Pressed"] = "Lumière à l'appui",
	["A button lights up while you press it."] = "Un bouton s'allume pendant que vous l'appuyez.",
	["Range And Resource Colours"] = "Couleurs de portée et de ressource",
	["Icons turn red out of range, blue without enough mana, and grey when unusable."] = "Les icônes deviennent rouges hors de portée, bleues sans assez de mana, et grises quand inutilisables.",
	-- CooldownTweaks
	["Cooldown Manager Tweaks"] = "Réglages du gestionnaire de temps de recharge",
	["Centred rows, key bindings, a light while pressed and the count size on the game's Cooldown Manager."] = "Rangées centrées, raccourcis, une lumière à l'appui et la taille des nombres sur le gestionnaire de temps de recharge du jeu.",
	["Your cooldowns, in the middle, with their keys on them."] = "Vos temps de recharge, au milieu, avec leurs touches dessus.",
	["Centre Rows"] = "Centrer les rangées",
	["A shorter row of cooldown icons sits centred under the others."] = "Une rangée plus courte d'icônes de temps de recharge se centre sous les autres.",
	["Key Bindings"] = "Raccourcis",
	["The key bound to a cooldown's spell, on the icon's corner."] = "La touche liée au sort d'un temps de recharge, au coin de l'icône.",
	["A cooldown's icon lights up while you press its action button."] = "L'icône d'un temps de recharge s'allume pendant que vous appuyez sur son bouton d'action.",
	["Count Size"] = "Taille des nombres",
	["The size of the charges and stacks numbers on the icons."] = "La taille des nombres de charges et de cumuls sur les icônes.",
	-- BagWindow
	["Bags by Kind"] = "Sacs par type",
	["Your bags in one window, sorted by kind: new items, gear, quest items, consumables, junk and more."] = "Vos sacs dans une seule fenêtre, triés par type : nouveaux objets, équipement, objets de quête, consommables, camelote et plus.",
	["A place for everything, and everything under its heading."] = "Une place pour chaque chose, et chaque chose sous son en-tête.",
	["Kinds"] = "Types",
	["The kinds your bag window sorts items into, top first. Drag to reorder, untick to hide, Add kind to make your own; double-click a name to rename it, its cog opens its settings."] = "Les types selon lesquels votre fenêtre de sacs trie les objets, le premier en haut. Glissez pour réordonner, décochez pour masquer, Ajouter un type pour les vôtres ; double-clic sur un nom pour le renommer, sa roue ouvre ses réglages.",
	["Items You Placed"] = "Objets que vous avez placés",
	["While you hold an item, drop it on a kind's + to always sort it there. Forget puts every placed item back."] = "En tenant un objet, déposez-le sur le + d'un type pour toujours l'y ranger. Oublier remet en place chaque objet placé.",
	["Forget"] = "Oublier",
	["Bank by Kind"] = "Banque par type",
	["Your bank sorted by the same kinds as your bags. Off: the game's grid."] = "Votre banque triée selon les mêmes types que vos sacs. Désactivé : la grille du jeu.",
	["Recent Lasts"] = "Durée de Récent",
	["How long new items stay under Recent: until you close your bags, until you point at them, or 5 minutes."] = "Durée d’affichage des nouveaux objets dans Récents : jusqu’à la fermeture des sacs, jusqu’à ce que vous les survoliez ou pendant 5 minutes.",
	["Until The Bags Close"] = "Jusqu'à la fermeture des sacs",
	["Until Hovered"] = "Jusqu'au survol",
	["For 5 Minutes"] = "Pendant 5 minutes",
	["Columns"] = "Colonnes",
	["How many slots wide the bag window is."] = "Combien d'emplacements de large fait la fenêtre des sacs.",
	["Item Size"] = "Taille des objets",
	["The size of the item slots. 37 is the game's size."] = "La taille des emplacements. 37 est la taille du jeu.",
	["Fold Empty Slots"] = "Replier les emplacements vides",
	["All empty slots shown as one, with their count."] = "Tous les emplacements vides affichés en un seul, avec leur nombre.",
	["Reagent Bag With The Bags"] = "Sac de composants avec les sacs", -- draft
	["The Reagent Bag's items among your bags' kinds in one view, its slots in its own colour and its free slots in an Empty slot of their own, instead of on its own side tab."] = "Les objets du sac de composants parmi les types de vos sacs dans une seule vue, ses emplacements dans sa propre couleur et ses emplacements libres dans un emplacement Vide à part, au lieu de son propre onglet latéral.", -- draft
	["Special Bags"] = "Sacs spéciaux",
	["Items in a special bag (a mining bag, an herb bag, an ammo pouch, a quiver ...) wear that bag's colour, and the window's foot lists those bags with how full they are."] = "Les objets d'un sac spécial (sac de mineur, sac d'herbes, giberne, carquois...) prennent la couleur de ce sac, et le bas de la fenêtre liste ces sacs avec leur remplissage.",
	["Sort Items By"] = "Trier les objets par",
	["How items are ordered inside each kind."] = "L'ordre des objets dans chaque type.",
	["Quality"] = "Qualité",
	["Name"] = "Nom",
	["Newest First"] = "Plus récents d'abord",
	["Item Level"] = "Niveau d'objet",
	["Loot Flight"] = "Vol du butin",
	["Looted items fly into your bag window; the rarer the item, the bigger the effect."] = "Les objets ramassés volent dans votre fenêtre de sacs ; plus ils sont rares, plus l'effet est grand.",
	["Items Glide"] = "Les objets glissent",
	["Items glide to their new slots instead of jumping."] = "Les objets glissent vers leurs nouveaux emplacements au lieu de sauter.",
	["Rolling Money"] = "Argent qui défile",
	["Your money counts up or down to its new amount."] = "Votre argent monte ou descend jusqu'à son nouveau montant.",
	["Bags Full Warning"] = "Alerte sacs pleins",
	["The bag window shakes and flashes red when your bags are full."] = "La fenêtre des sacs tremble et flashe en rouge quand vos sacs sont pleins.",
	-- MinimapPanel
	["MelloUI's minimap: its size, square shape and the Services bar under it. Off: the game's own minimap."] = "La minicarte de MelloUI : sa taille, sa forme carrée et la barre Services en dessous. Désactivé : la minicarte du jeu.",
	["Shape"] = "Forme",
	["The painted minimap's shape: round in its ring, or square in the Square Border."] = "La forme de la minicarte peinte : ronde dans son anneau, ou carrée dans la bordure carrée.",
	["Round"] = "Ronde",
	["Square"] = "Carrée",
	["Square Border"] = "Bordure carrée",
	["The border around the square minimap. Painted borders need Oldschool's painted Minimap."] = "La bordure de la minicarte carrée. Les bordures peintes demandent la minicarte peinte d'Oldschool.",
	["Window frame"] = "Cadre de fenêtre",
	["Chat panel"] = "Panneau de discussion",
	["Heavy, red gems"] = "Lourd, gemmes rouges",
	["Heavy, iron gems"] = "Lourd, gemmes de fer",
	["Merge With Services"] = "Fusionner avec les services",
	["The square minimap, its zone name and the Services bar share one frame."] = "La minicarte carrée, son nom de zone et la barre Services partagent un même cadre.",
	["Width"] = "Largeur",
	["How wide the minimap is. The Quest Tracker under it follows its width."] = "La largeur de la minicarte. Le suivi des quêtes en dessous suit sa largeur.",
	["Height"] = "Hauteur",
	["How tall the square minimap is."] = "La hauteur de la minicarte carrée.",
	-- QuestTracker
	["MelloUI's quest tracker in the game's tracker's place. It scrolls, so every quest fits."] = "Le suivi des quêtes de MelloUI à la place de celui du jeu. Il défile, pour que chaque quête tienne.",
	["Every watched quest within reach: the tracker scrolls when the list runs long."] = "Toutes les quêtes suivies à portée sont affichées ; le suivi défile lorsque la liste devient trop longue.",
	["Tracker"] = "Suivi",
	["How tall the tracker grows before it scrolls. You can also drag its corner."] = "La hauteur maximale du suivi avant qu'il ne commence à défiler. Vous pouvez aussi redimensionner le suivi en faisant glisser son coin.",
	["Match The Minimap's Width"] = "Même largeur que la minicarte",
	["The tracker is as wide as the minimap and sits right under it, following it. Off: use Width below."] = "Le suivi a la même largeur que la minicarte et se place juste en dessous, en suivant ses dimensions. Désactivé : utilisez Largeur ci-dessous.",
	["How wide the tracker is when it doesn't match the minimap. You can also drag its corner."] = "La largeur du suivi lorsqu'il n'est pas aligné sur la minicarte. Vous pouvez aussi redimensionner le suivi en faisant glisser son coin.",
	["The size of quest titles and section headers. Objectives are one size smaller."] = "La taille des titres de quête et des en-têtes de section. Les objectifs s’affichent dans une taille inférieure.",
	["Header Text Size"] = "Taille du texte d'en-tête",
	["The size of the tracker's title."] = "La taille du titre du suivi.",
	["Background Opacity"] = "Opacité du fond",
	["How solid the tracker's background is. At 0% its lines stand on the world, as the game's tracker's do."] = "L’opacité du fond du suivi. À 0 %, ses lignes se superposent directement au monde, comme celles du suivi du jeu.",
	["Scroll Step"] = "Pas de défilement",
	["How far one turn of the mouse wheel scrolls."] = "La distance parcourue à chaque cran de molette.",
	["A quest's usable item beside it. Click to use it out of combat."] = "L'objet utilisable d'une quête à côté d'elle. Un clic l'utilise hors combat.",
	["Progress Motion"] = "Animation de progression",
	["Counts roll to their new number, finished objectives get a tick, and a finished quest lights up."] = "Les compteurs défilent vers leur nouveau nombre, les objectifs faits reçoivent une coche et une quête terminée s'illumine.",
	["Nearest First"] = "Le plus proche d'abord",
	["Nearest Quest First"] = "Quête la plus proche d'abord",
	["The nearest quest on top, after the one you follow. Needs Route."] = "La quête suivie apparaît en premier, puis la plus proche. Nécessite Itinéraire.",
	["Distances"] = "Distances",
	["How far each quest is, beside its name. Needs Route."] = "La distance de chaque quête, affichée à côté de son nom. Nécessite Route.",
	["Quest XP"] = "XP des quêtes", -- draft
	["The XP each quest gives at your level, beside its name (the game's own figure; none at the top level)."] = "L'XP que chaque quête rapporte à votre niveau, à côté de son nom (la valeur du jeu ; aucune au niveau maximum).", -- draft
	["Turn-in Line"] = "Ligne de remise de quête",
	["A finished quest says who takes it and where."] = "Une quête terminée dit qui la reprend et où.",
	["Reset Position"] = "Position par défaut",
	["Puts the tracker back in its starting place."] = "Remet le suivi à sa place de départ.",
	["back under the minimap (or on the game's tracker's place)"] = "de retour sous la minicarte (ou à la place du suivi du jeu)",
	-- ErrorFilter
	["Hide the red error messages you choose, such as \"Not enough energy\" or \"Spell is not ready yet\", from the middle of the screen."] = "Masque au centre de l'écran les messages d'erreur rouges que vous choisissez, comme « Pas assez d'énergie » ou « Le sort n'est pas encore utilisable ».",
	["Quiet, please. The red shouts in the middle of the screen, a kind at a time."] = "Silence, s'il vous plaît. Les cris rouges au milieu de l'écran, un type à la fois.",
	["Hide"] = "Masquer",
	["Not Enough Resources"] = "Ressources insuffisantes",
	["Not enough energy, rage, mana or combo points."] = "Pas assez d'énergie, de rage, de mana ou de points de combo.",
	["Not Ready Yet"] = "Pas encore prêt",
	["An ability, spell or item is not ready yet."] = "Une technique, un sort ou un objet n'est pas encore prêt.",
	["Out Of Range"] = "Hors de portée",
	["Out of range, too far or too close."] = "Hors de portée, trop loin ou trop près.",
	["Facing And Target"] = "Orientation et cible",
	["Wrong facing, no target, invalid target or out of sight."] = "Mauvaise orientation, pas de cible, cible invalide ou hors de vue.",
	["Busy Or Moving"] = "Occupé ou en mouvement",
	["Busy, moving, stunned or mounted."] = "Occupé, en mouvement, étourdi ou monté.",
	-- Auras
	["Your own buff and debuff rows on the target frame, enemy nameplates and at your buffs, drawn by the game so they keep working in combat."] = "Vos propres rangées d’améliorations et d’affaiblissements sur le cadre de la cible, les barres d’info ennemies et près de vos améliorations. Elles sont dessinées par le jeu pour rester visibles en combat.",
	["Buffs and debuffs in rows of your own, drawn by the game itself, so they never go dark in a fight."] = "Améliorations et affaiblissements dans vos propres rangées, dessinées par le jeu lui-même, pour qu'ils ne s'éteignent jamais en combat.",
	["MelloUI's own rows of buffs and debuffs: yours in place of the game's buff bar, the target's under its frame, your debuffs on enemy nameplates."] = "Les rangées d'améliorations et d'affaiblissements de MelloUI : les vôtres à la place de la barre d'améliorations du jeu, celles de la cible sous son cadre, vos affaiblissements sur les barres d'info ennemies.",
	["Your Buffs And Debuffs"] = "Vos améliorations et affaiblissements",
	["MelloUI's own rows for your buffs and debuffs, in place of the game's. Right-click a buff to cancel it."] = "Remplace les rangées d'améliorations et d'affaiblissements du jeu par celles de MelloUI. Faites un clic droit sur une amélioration pour l'annuler.",
	["Where your buffs and debuffs stand. Minimap: beside the minimap, moving with it. Unit Frame: under your player frame. Free: anywhere, moved in Edit Layout."] = "Position de vos améliorations et affaiblissements. Minicarte : à côté de la minicarte, ils la suivent. Cadre d'unité : sous votre cadre de joueur. Libre : à l'emplacement de votre choix, à déplacer dans Modifier la disposition.",
	["Unit Frame"] = "Cadre d'unité",
	["Free"] = "Libre",
	["Move Them"] = "Les déplacer",
	["Opens Edit Layout, with your buffs and debuffs shown so you can drag them where you want."] = "Ouvre Modifier la disposition et affiche vos améliorations et affaiblissements pour que vous puissiez les faire glisser à l'emplacement voulu.",
	["drag your buffs and debuffs"] = "faire glisser vos améliorations et affaiblissements",
	["Edit Layout"] = "Modifier la disposition",
	["Direction"] = "Direction",
	["Which way your icons run under the player frame."] = "Dans quelle direction vos icônes s'alignent sous le cadre du joueur.",
	["Left To Right"] = "De gauche à droite",
	["Right To Left"] = "De droite à gauche",
	["Icon Size On The Frame"] = "Taille des icônes sur le cadre",
	["The size of your buff and debuff icons under the player frame."] = "La taille de vos icônes d'améliorations et d'affaiblissements sous le cadre du joueur.",
	["Debuff Icon Size"] = "Taille des icônes d'affaiblissement",
	["The size of your debuff icons."] = "La taille de vos icônes d'affaiblissement.",
	["Debuff Spacing"] = "Espacement des affaiblissements",
	["The space between your debuff icons."] = "L'espace entre vos icônes d'affaiblissement.",
	["Debuffs Per Row"] = "Affaiblissements par rangée",
	["How many debuffs fit in a row before a new row starts."] = "Combien d'affaiblissements tiennent sur une rangée avant d'en commencer une nouvelle.",
	["Debuff Grow"] = "Sens des affaiblissements",
	["Which way a row of debuffs grows."] = "Dans quel sens s'étend une rangée d'affaiblissements.",
	["Debuff New Rows"] = "Nouvelles rangées d'affaiblissements",
	["Which way new rows of debuffs go."] = "Dans quel sens vont les nouvelles rangées d'affaiblissements.",
	["Target"] = "Cible",
	["Your target's debuffs and buffs under the target frame, in MelloUI's look."] = "Les affaiblissements et améliorations de votre cible sous son cadre, dans le style de MelloUI.",
	["The size of your target's buff and debuff icons."] = "La taille des icônes d'améliorations et d'affaiblissements de votre cible.",
	["Only My Debuffs"] = "Seulement mes affaiblissements",
	["Only the debuffs you put on your target."] = "Seulement les affaiblissements que vous avez posés sur votre cible.",
	["Enemy Nameplates"] = "Barres d'info ennemies",
	["Your debuffs on enemy nameplates, in MelloUI's look."] = "Vos affaiblissements sur les barres d'info ennemies, dans le style de MelloUI.",
	["The size of your debuff icons on nameplates."] = "La taille de vos icônes d'affaiblissement sur les barres d'info.",
	["Only the debuffs you put on enemies. Off: every debuff the game shows on their nameplates."] = "Seulement les affaiblissements que vous lancez sur les ennemis. Désactivé : tous ceux que le jeu affiche sur leurs barres d'info.",
	["Buff Numbers Font"] = "Police des chiffres d'auras",
	["The font of timers and stacks on MelloUI's buffs and debuffs. Shared: the numbers font."] = "La police des minuteurs et des piles sur les améliorations et affaiblissements de MelloUI. Partagée : la police des nombres.",
	-- Map
	["Map"] = "Carte",
	["One seamless map of the whole world. Zoom with the mouse wheel, drag to look around."] = "Une carte continue du monde entier. Zoomez avec la molette et faites glisser la carte pour explorer.",
	["The whole world on one sheet, from the continents down to a village."] = "Le monde entier sur une feuille, des continents jusqu'au village.",
	["Open The Map"] = "Ouvrir la carte",
	["Opens MelloUI's map. Your map key (M) and /mellomap open it too."] = "Ouvre la carte de MelloUI. Votre touche de carte (M) et /mellomap l'ouvrent aussi.",
	["Open"] = "Ouvrir",
	["Dungeon Maps"] = "Cartes des donjons",
	["Inside a dungeon or raid the map opens on its own map (Blizzard's drawings for the classic ones), Dungeon Info's bosses and loot beside it. From outside, a click on its door or on its row in Dungeon Info shows it."] = "Dans un donjon ou un raid, la carte s'ouvre sur sa propre carte (les dessins de Blizzard pour les classiques), avec les boss et le butin d'Infos des donjons à côté. De l'extérieur, un clic sur son entrée ou sur sa ligne dans Infos des donjons l'affiche.",
	["Map Coordinates"] = "Coordonnées de la carte", -- draft
	["Your coordinates in the line under the map, and the mouse's while it is over the map."] = "Vos coordonnées sur la ligne sous la carte, et celles de la souris quand elle survole la carte.", -- draft
	["Fog Of War"] = "Brouillard de guerre", -- draft
	["Places you haven't explored stay hidden on the map, as on the game's own world map, until you walk there. Off: they show faintly."] = "Les lieux que vous n'avez pas explorés restent cachés sur la carte, comme sur la carte du monde du jeu, jusqu'à ce que vous y alliez. Désactivé : ils s'affichent en transparence.", -- draft
	-- CharacterPanel
	["Character Panel"] = "Panneau du personnage",
	["The character window dressed in the painted kit: stone frame, slot rims, framed panes and stats, all on the game's own layout."] = "La fenêtre du personnage dans l'habillage graphique de MelloUI : cadre de pierre, bords d'emplacements, volets encadrés et caractéristiques, le tout sur la disposition du jeu.",
	["Stone, iron and a window on the world. Your character, framed the way it deserves."] = "Pierre, fer et une fenêtre sur le monde. Votre personnage, encadré comme il le mérite.",
	["Window Background"] = "Fond de fenêtre",
	["The character window's background."] = "Le fond de la fenêtre du personnage.",
	["Window stone"] = "Pierre de la fenêtre",
