	["The quest log and its window dressed in the painted kit on the game's own layout."] = "Le journal des quêtes et sa fenêtre dans l'habillage graphique de MelloUI sur la disposition du jeu.",
	-- GuildPanel
	["Guild Panel"] = "Panneau de guilde",
	["The guild and communities window dressed in the painted kit on the game's own layout."] = "La fenêtre de guilde et des communautés dans l'habillage graphique de MelloUI sur la disposition du jeu.",
	-- GroupFinderPanel
	["Group Finder Panel"] = "Panneau de recherche de groupe",
	["The looking-for-group window dressed in the painted kit on the game's own layout."] = "La fenêtre de recherche de groupe dans l'habillage graphique de MelloUI sur la disposition du jeu.",
	-- CollectionsPanel
	["Collections Panel"] = "Panneau des collections",
	["The collections window dressed in the painted kit on the game's own layout."] = "La fenêtre des collections dans l'habillage graphique de MelloUI sur la disposition du jeu.",
	-- UnitFramePanel
	["Unit Frames Kit"] = "Interface MelloUI : cadres d’unité",
	["The player, target, focus and pet frames dressed in the painted kit on the game's own layout."] = "Les cadres du joueur, de la cible, de la focalisation et du familier dans l'habillage graphique de MelloUI sur la disposition du jeu.",
	["Elite and Rare Marks"] = "Marques d'élite et de rare",
	["The target's and focus's ring and level in gold for elites, silver for rares and bronze for bosses, with a small crest."] = "L'anneau et le niveau de la cible et de la focalisation en or pour les élites, en argent pour les rares et en bronze pour les boss, avec un petit blason.",
	["Bar Background"] = "Fond des barres",
	["What shows behind the empty part of the unit frames' bars."] = "Ce qui s'affiche derrière la partie vide des barres des cadres d'unité.",
	["Painted Trough"] = "Bac peint",
	["Bar Texture, Dark"] = "Texture des barres, sombre",
	["Bar Background Opacity"] = "Opacité du fond des barres",
	["How solid the bars' background is. Lower lets the world show through."] = "L'opacité du fond des barres. Plus bas laisse voir le monde.",
	["Frame Backdrop"] = "Fond des cadres",
	["A stone backdrop behind the player, target and focus frames, with a border of your choice."] = "Un fond de pierre derrière les cadres du joueur, de la cible et de la focalisation, avec la bordure de votre choix.",
	["Red gems"] = "Gemmes rouges",
	["Iron gems"] = "Gemmes de fer",
	["Frame Backdrop Background"] = "Matière du fond des cadres",
	["What shows inside the unit frames' backdrop."] = "Ce qui s'affiche dans le fond des cadres d'unité.",
	-- CastBarPanel
	["Cast Bars Kit"] = "Interface des barres d'incantation",
	["The cast bars dressed in the painted kit on the game's own layout."] = "Les barres d'incantation dans l'habillage graphique de MelloUI sur la disposition du jeu.",
	-- RaidFramePanel
	["Raid Frames Kit"] = "Interface des cadres de raid",
	["The compact raid and party frames and the totem bar dressed in the painted kit on the game's own layout."] = "Les cadres compacts de raid et de groupe, ainsi que la barre de totems dans l'habillage graphique de MelloUI sur la disposition du jeu.",
	-- ActionBarPanel
	["Action Bars Kit"] = "Interface des barres d'actions",
	["The action bars, micro menu, bag bar and experience bars dressed in the painted kit on the game's own layout."] = "Les barres d'actions, le micro-menu, la barre de sacs et les barres d'expérience dans l'habillage graphique de MelloUI sur la disposition du jeu.",
	["The border of the action bars' backdrop: red or iron gems, or a border style. Turn the backdrop on in Bars."] = "La bordure du fond des barres d'actions : gemmes rouges ou de fer, ou un style de bordure. Activez le fond dans Barres.",
	["Backdrop Background"] = "Matière du fond",
	["What shows behind the buttons inside the backdrop."] = "Ce qui s'affiche derrière les boutons dans le fond.",
	["Button Background"] = "Fond des boutons",
	["What an empty button shows."] = "Ce qu'affiche un bouton vide.",
	["The border of the micro menu's backdrop: red or iron gems, or a border style. Turn the backdrop on in Bars."] = "La bordure du fond du micro-menu : gemmes rouges ou de fer, ou un style de bordure. Activez le fond dans Barres.",
	["The border of the bag bar's backdrop: red or iron gems, or a border style. Turn the backdrop on in Bars."] = "La bordure du fond de la barre de sacs : gemmes rouges ou de fer, ou un style de bordure. Activez le fond dans Barres.",
	-- BackpackPanel
	["Backpack Kit"] = "Interface du sac à dos",
	["The bag windows dressed in the painted kit on the game's own layout."] = "Les fenêtres de sac dans l'habillage graphique de MelloUI sur la disposition du jeu.",
	["The background behind your bag and bank items."] = "Le fond derrière vos objets de sacs et de banque.",
	["Item Background"] = "Fond des objets",
	["What an empty bag slot shows."] = "Ce qu'affiche un emplacement de sac vide.",
	-- MinimapKit
	["Minimap Kit"] = "Interface de la minicarte",
	["The minimap dressed in the painted kit: the ring round the map (or the square map's painted border), the zone plate, the tracking button's rim and the zoom buttons."] = "La minicarte dans l'habillage graphique de MelloUI : l'anneau autour de la carte (ou la bordure peinte de la carte carrée), la plaque de zone, le bord du bouton de pistage et les boutons de zoom.",
	-- TrackerPanel
	["Objective Tracker Kit"] = "Interface du suivi des objectifs",
	["The objective tracker dressed in the painted kit on the game's own layout."] = "Le suivi des objectifs dans l'habillage graphique de MelloUI sur la disposition du jeu.",
	-- SocialPanel
	["Social Panel Kit"] = "Interface du panneau social",
	["The social window (contacts, raid, quick join) dressed in the painted kit on the game's own layout."] = "La fenêtre sociale (contacts, raid, rejoindre) dans l'habillage graphique de MelloUI sur la disposition du jeu.",
	-- ChatPanel
	["Chat Panel Kit"] = "Interface du panneau de discussion",
	["The chat windows (frame, tabs, edit box, buttons) dressed in the painted kit on the game's own layout."] = "Les fenêtres de discussion (cadre, onglets, zone de saisie, boutons) dans l'habillage graphique de MelloUI sur la disposition du jeu.",
	-- DamageMeterPanel
	["Damage Meter Kit"] = "Interface MelloUI : compteur de dégâts",
	["The game's damage meter (window, header, entry bars, breakdown windows) dressed in the painted kit on its own layout."] = "Le compteur de dégâts du jeu (fenêtre, en-tête, barres d'entrée, fenêtres de détail) dans l'habillage graphique de MelloUI sur sa propre disposition.",
	-- TooltipPanel
	["Tooltip Kit"] = "Interface des encadrés d'aide",
	["Tooltips dressed in the painted kit: the stone box with the single rail, the unit health bar in the bracket."] = "Les encadrés d'aide dans l'habillage graphique de MelloUI : la boîte de pierre avec le rail simple, la barre de vie d'unité dans le support.",
	-- NameplatePanel
	["Nameplate Kit"] = "Interface des barres d'info",
	["Nameplates dressed in the painted kit: the health bar in the bracket, the cast bar on the single rail, the level circle on the orb."] = "Les barres d'info dans l'habillage graphique de MelloUI : la barre de vie dans le support, la barre d'incantation sur le rail simple, le cercle de niveau sur l'orbe.",
	["Whole Plate Shade"] = "Ombre de toute la plaque",
	["The UI Shade follows the painted plate's whole shape."] = "L'ombre de l'interface suit toute la forme de la barre d'info peinte.",
	["Elites, rares and bosses get a metal crest over their name."] = "Élites, rares et boss reçoivent un blason de métal au-dessus de leur nom.",
	-- QuestList
	["Quest List"] = "Liste des quêtes",
	["A quest log page listing a zone's quests, your progress and where each one starts, with quest givers on the map."] = "Une page du journal de quêtes qui liste les quêtes d'une zone, votre progression et où chacune commence, avec les donneurs sur la carte.",
	["Every quest of the zone in the map's quest log: who gives it, where, and what is left to do."] = "Chaque quête de la zone dans le journal des quêtes de la carte : qui la donne, où, et ce qu'il reste à faire.",
	["List"] = "Liste",
	["Show Quests For"] = "Afficher les quêtes de",
	["Which quests the list shows. The dropdown on the list does the same."] = "Quelles quêtes la liste affiche. Le menu déroulant de la liste fait de même.",
	["All"] = "Tout",
	["Current continent"] = "Continent actuel",
	["Current zone"] = "Zone actuelle",
	["Class quests"] = "Quêtes de classe",
	["Dungeons"] = "Donjons",
	["Raids"] = "Raids",
	["Attunements"] = "Accès",
	["Events"] = "Évènements",
	["Hide Completed"] = "Masquer les terminées",
	["Leaves out quests you have completed instead of greying them."] = "Omet les quêtes terminées au lieu de les griser.",
	["Show Hidden Quests"] = "Afficher les quêtes masquées",
	["Lists the quests you hid, dimmed, so you can Alt-click them back."] = "Liste les quêtes masquées, estompées ; faites un Alt-clic pour les réafficher.",
	["Quests From A Quest Giver"] = "Quêtes d'un donneur de quête",
	["Quests from a quest giver or an object. Also on the map."] = "Les quêtes d'un donneur ou d'un objet. Aussi sur la carte.",
	["Quests From a Mob Drop"] = "Quêtes provenant d'un butin de créature",
	["Quests that start from an item a creature drops."] = "Les quêtes qui commencent par un objet lâché par une créature.",
	["Quests From an Item Picked Up"] = "Quêtes d'un objet ramassé",
	["Quests that start from an item on the ground or in a chest."] = "Les quêtes qui commencent par un objet au sol ou dans un coffre.",
	["Quests Starting Somewhere Unknown"] = "Quêtes au départ inconnu",
	["Quests whose start is not known yet."] = "Les quêtes dont le début n'est pas encore connu.",
	["Show Other Faction's Quests"] = "Afficher les quêtes de l'autre faction",
	["Also lists the other faction's quests."] = "Liste aussi les quêtes de l'autre faction.",
	["Show Other Classes' Quests"] = "Afficher les quêtes des autres classes",
	["Also lists other classes' quests."] = "Liste aussi les quêtes des autres classes.",
	["Most Levels Above Me"] = "Niveaux au-dessus de moi au plus",
	["Leaves out quests more than this many levels above you."] = "Omet les quêtes de plus de ce nombre de niveaux au-dessus de vous.",
	["Quest Givers On Zone Maps"] = "Donneurs de quêtes sur les cartes de zone",
	["Marks quest givers on the zone map with a ! or ?. Point at one for its quests; click to track it."] = "Marque les donneurs de quêtes sur la carte de zone d'un ! ou ?. Survolez-en un pour ses quêtes ; un clic le suit.",
	["Include Givers You Are Done With"] = "Inclure les donneurs terminés",
	["Also marks givers whose quests you have all done, with a grey tick."] = "Marque aussi les donneurs dont vous avez fait toutes les quêtes, d'une coche grise.",
	["Hide Grey Quests"] = "Masquer les quêtes grises",
	["Leaves quests far below your level off the map."] = "Retire de la carte les quêtes bien en dessous de votre niveau.",
	["Zone Progress On Continent Maps"] = "Progression des zones sur les cartes de continent",
	["A done / total badge on each zone of the continent map."] = "Un badge terminées / total sur chaque zone de la carte du continent.",
	["Zone Progress On Zone Maps"] = "Progression de la zone sur les cartes de zone",
	["The zone's quest progress in the zone map's corner."] = "La progression des quêtes de la zone dans le coin de la carte de zone.",
	["Dungeon And Raid Entrances"] = "Entrées de donjons et de raids",
	["Marks dungeon and raid entrances on zone maps. Click one to list its quests."] = "Marque les entrées de donjons et de raids sur les cartes de zone. Un clic affiche leurs quêtes.",
	["Boats And Zeppelins"] = "Bateaux et zeppelins",
	["Marks boats and zeppelins with their destination. Click to route there."] = "Marque les bateaux et les zeppelins avec leur destination. Un clic trace un itinéraire vers celle-ci.",
	["Objective Marks"] = "Marques d'objectif",
	["Marks where your quests' objectives are on the zone map, with their progress. Click a mark for a waypoint."] = "Marque sur la carte de zone où sont les objectifs de vos quêtes, avec leur progression. Un clic sur une marque pose un point de passage.",
	["Only The Tracked Quests"] = "Seulement les quêtes suivies",
	["Marks only the quests you track."] = "Marque seulement les quêtes suivies.",
	["Hide The Game's Quest Areas"] = "Masquer les zones de quête du jeu",
	["Hides the game's blue quest areas while MelloUI's marks are on."] = "Masque les zones de quête bleues du jeu tant que les marques de MelloUI sont actives.",
	["On The Minimap"] = "Sur la minicarte",
	["The same marks on the minimap, with an arrow for nearby ones off its edge. Needs Route."] = "Les mêmes marques sur la minicarte, avec une flèche pour celles qui sont proches mais sortent de son bord. Nécessite Route.",
	["Quest Check When Entering An Instance"] = "Vérification de quêtes en entrant en instance",
	["Entering a dungeon or raid lists in the chat its quests you have not picked up."] = "En entrant dans un donjon ou un raid, la discussion liste ses quêtes que vous n'avez pas prises.",
	["Quest Progress On Items"] = "Progression de quête sur les objets",
	["Item tooltips show the quest that needs the item and your progress."] = "Les encadrés d'aide d'objet montrent la quête qui en a besoin et votre progression.",
	["Turn-In NPCs"] = "PNJ auprès desquels rendre les quêtes",
	["NPC tooltips show where you can turn in a quest."] = "Les encadrés d'aide des PNJ montrent où rendre une quête.",
	["Your Other Characters On Quests"] = "Vos autres personnages sur les quêtes",
	["Quest tooltips list your other characters who have done or hold the quest."] = "Les encadrés d'aide de quête listent vos autres personnages qui l'ont terminée ou qui l'ont en cours.",
	-- Route
	["Route"] = "Itinéraire",
	["Draws the way to your waypoint on the world map and the minimap, along real roads."] = "Trace le chemin vers votre point de passage sur la carte du monde et la minicarte, le long de vraies routes.",
	["A trail of gems from here to there, along the roads you have walked before."] = "Une traînée de gemmes d'ici à là-bas, le long des routes déjà parcourues.",
	["Drawing"] = "Tracé",
	["Route On The World Map"] = "Itinéraire sur la carte du monde",
	["Draws the route and its destination flag on the world map."] = "Trace l'itinéraire et son drapeau de destination sur la carte du monde.",
	["Route On The Minimap"] = "Itinéraire sur la minicarte",
	["Draws the nearby part of the route on the minimap."] = "Trace la partie proche de l'itinéraire sur la minicarte.",
	["Trail Look"] = "Apparence de la traînée",
	["How the route is drawn: red beads, a gold line, or gold dashes."] = "Comment l'itinéraire est tracé : perles rouges, ligne dorée ou tirets dorés.",
	["Red Beads"] = "Perles rouges",
	["Gilded Line"] = "Ligne dorée",
	["Waymarks"] = "Balises",
	["Trail Size"] = "Taille de la traînée",
	["How big the route's trail is."] = "La taille de la traînée de l'itinéraire.",
	["Route To The Tracked Quest"] = "Itinéraire vers la quête suivie",
	["Without a map pin, routes to the quest you track: its next objective, then its turn-in."] = "Sans épingle sur la carte, l'itinéraire mène vers la quête suivie : son prochain objectif, puis le lieu où la rendre.",
	["Fall Back To The First Tracked Quest"] = "Se rabattre sur la première quête suivie",
	["When no quest is followed, routes to the first quest on the game's watch list."] = "Lorsqu'aucune quête n'est suivie, l'itinéraire est calculé vers la première quête de la liste de suivi du jeu.",
	["Follow Guide Addons"] = "Suivre les addons de guides",
	["Shows the current steps of RestedXP and other guide addons in the Quest Tracker and routes to them, hiding the guide's own arrow and window. Off, the guide keeps its own."] = "Affiche les étapes en cours de RestedXP et d'autres addons de guides dans le Suivi des quêtes et y trace l'itinéraire, en masquant la flèche et la fenêtre du guide. Désactivé, le guide garde les siennes.",
	["Distance Under The Minimap"] = "Distance sous la minicarte",
	["The distance left and the destination under the minimap."] = "La distance restante et la destination sous la minicarte.",
	["Travel Time"] = "Temps de trajet",
	["About how long the rest of the way takes, beside the distance."] = "La durée approximative restante du trajet, affichée à côté de la distance.",
	["A mark over the destination in the world with its distance; an arrow points the way when it is off screen."] = "Un marqueur au-dessus de la destination dans le monde avec sa distance ; une flèche indique la direction quand elle est hors écran.",
	["Light Beam"] = "Rayon de lumière",
	["A slim beam of light over the destination, seen from far away."] = "Un fin rayon de lumière au-dessus de la destination, visible de loin.",
	["Wisp"] = "Feu follet",
	["A small light flies from you to a new destination and lights it."] = "Une petite lumière vole depuis vous jusqu'à une nouvelle destination et l'illumine.",
	["Firefly"] = "Luciole",
	["Embers"] = "Braises",
	["Route Draws In"] = "Tracé progressif",
	["A new route grows from you to the destination instead of appearing all at once."] = "Un nouvel itinéraire se trace depuis vous jusqu'à la destination au lieu d'apparaître d'un coup.",
	["Arrival Light"] = "Lumière d'arrivée",
	["The mark sinks into a ring of light when you arrive."] = "À votre arrivée, la marque s'enfonce dans un anneau de lumière.",
	["Marker Sounds"] = "Sons du marqueur",
	["A soft sound when the World Marker appears or changes."] = "Un son discret lorsque le marqueur du monde apparaît ou change.",
	["Arrival"] = "Arrivée",
	["Arrived Within (yards)"] = "Arrivée à moins de (mètres)",
	["How close you must get for the route to end."] = "La distance à atteindre pour terminer l'itinéraire.",
	["Flights"] = "Vols",
	["Flight Map Help"] = "Aide de la carte de vol",
	["At a flight master, shows where your route flies to and how long the flight takes."] = "Chez un maître de vol, indique la destination de votre itinéraire et la durée du vol.",
	["Learning"] = "Apprentissage",
	["Learn Paths While Playing"] = "Apprendre les chemins en jouant",
	["Remembers where you walk and fly, so routes follow real roads."] = "Retient où vous marchez et volez, pour que les itinéraires suivent de vraies routes.",
	-- Chat
	["Clean chat: hidden background and input art, short coloured channel tags, class coloured names."] = "Une discussion épurée : fond et décor de la zone de saisie masqués, étiquettes de canal courtes et colorées, noms aux couleurs de classe.",
	["Less frame, more talk. Short channel tags and class colours keep the log readable."] = "Moins de cadre, plus de conversation. Des étiquettes de canal courtes et les couleurs de classe gardent le journal lisible.",
	["Chat View"] = "Vue de la discussion",
	["How the chat looks. Game Windows: the game's windows and tabs. Minimal: one panel with round tabs, each message under its sender, and buttons to pick a channel."] = "L'aspect de la discussion. Fenêtres du jeu : les fenêtres et onglets du jeu. Minimaliste : un panneau aux onglets ronds, chaque message sous son auteur, et des boutons pour choisir un canal.",
	["Game Windows"] = "Fenêtres du jeu",
	["Minimal"] = "Minimale",
	["Channel List As Icons"] = "Liste des canaux en icônes", -- draft
	["The Minimal Chat View's channel list shows only its icons, leaving more room for the messages. Point at an icon for its name. The small handle on the list's edge does the same."] = "La liste des canaux de la vue de chat minimale n'affiche que ses icônes, pour laisser plus de place aux messages. Survolez une icône pour voir son nom. La petite poignée sur le bord de la liste fait de même.", -- draft
	["The chat's background: Dark, the game's own, none, or one shared by a SharedMedia addon."] = "Fond de la discussion : sombre, celui du jeu, aucun ou un fond partagé par un addon SharedMedia.",
	["Set The Background Opacity"] = "Régler l'opacité du fond",
	["Every chat window uses the same background opacity. Off: each keeps its own."] = "Chaque fenêtre de discussion utilise la même opacité de fond. Désactivé : chacune garde la sienne.",
	["How solid the chat windows' background is."] = "L'opacité du fond des fenêtres de discussion.",
	["Border Opacity"] = "Opacité de la bordure",
	["How solid the painted border around the chat is."] = "L'opacité de la bordure peinte autour de la discussion.",
	["Hide Input Box Art"] = "Masquer le décor de la zone de saisie",
	["Hides the border and background of the chat's input line."] = "Masque la bordure et le fond de la ligne de saisie de la discussion.",
	["Hide Tab Background"] = "Masquer le fond des onglets",
	["Hides the background behind the chat tabs. Their names stay."] = "Masque le fond derrière les onglets de discussion. Leurs noms restent.",
	["Tabs Only On Mouseover"] = "Onglets seulement au survol",
	["The chat tab names show only while your mouse is over the chat. Flashing tabs stay visible."] = "Les noms des onglets de discussion n'apparaissent que quand la souris survole la discussion. Les onglets qui clignotent restent visibles.",
	["Input Box On Top"] = "Zone de saisie en haut",
	["The input line sits above the chat instead of below it."] = "La ligne de saisie se place au-dessus de la discussion au lieu d'en dessous.",
	["Input Box Only While Typing"] = "Zone de saisie seulement en écrivant",
	["The input line shows only while you type."] = "La ligne de saisie ne s'affiche que pendant que vous tapez.",
	["Chat Buttons"] = "Boutons de discussion",
	["The column of chat buttons beside the chat: Friends, Channels and the chat menu."] = "La colonne de boutons près de la discussion : Contacts, Canaux et le menu de discussion.",
	["Smooth Scrolling"] = "Défilement fluide",
	["The mouse wheel scrolls the chat smoothly instead of a line at a time."] = "La molette fait défiler la discussion en douceur au lieu de ligne par ligne.",
	["Copy Chat Button"] = "Bouton Copier la discussion",
	["While your mouse is on the chat, a small button at its top right corner puts the tab's lines in a window to copy, each with its time."] = "Tant que votre souris est sur la discussion, un petit bouton dans son coin supérieur droit met les lignes de l'onglet dans une fenêtre à copier, chacune avec son heure.",
	["Channels"] = "Canaux",
	["Short Channel Tags"] = "Étiquettes de canal courtes",
	["Short coloured tags instead of [Guild], [Party], [1. General] and so on."] = "Des étiquettes courtes colorées au lieu de [Guilde], [Groupe], [1. Général] et ainsi de suite.",
	["Hide Brackets"] = "Masquer les crochets",
	["Removes the brackets around the short tags."] = "Retire les crochets autour des étiquettes courtes.",
	["Chat Timestamps"] = "Horodatage de la discussion", -- draft
	["The time before each chat line, or None for no time. It is the game's own Chat Timestamps setting, and both chat views follow it."] = "L'heure devant chaque ligne de discussion, ou Aucun pour aucune heure. C'est le réglage Horodatage de la discussion du jeu, et les deux vues de discussion le suivent.", -- draft
	["Whisper Popup Window"] = "Fenêtre de chuchotement",
	["Each whisper opens a small window for that person, with a box to answer in. Whispers still show in the chat."] = "Chaque chuchotement ouvre une petite fenêtre pour cette personne, avec une case pour répondre. Les chuchotements restent dans la discussion.",
	-- CombatText
	["The text around your character in a fight (damage taken, heals, procs) in MelloUI's look, or the game's own."] = "Le texte autour de votre personnage en combat (dégâts subis, soins, effets) dans le style de MelloUI, ou celui du jeu.",
	["Your hits taken, heals and procs in MelloUI's soft look, or the game's own text."] = "Vos dégâts subis, vos soins et vos effets déclenchés dans l'aspect doux de MelloUI, ou le texte du jeu.",
	["Combat Text Style"] = "Style du texte de combat",
	["How the text around your character is shown. Game: the game's own. Lanes: damage taken left, healing right. Feed: one column over your portrait. Classic: one stream over your head."] = "Comment s'affiche le texte autour de votre personnage. Jeu : celui du jeu. Couloirs : dégâts subis à gauche, soins à droite. Fil : une colonne au-dessus de votre portrait. Classique : un flot au-dessus de votre tête.",
	["Game (Blizzard)"] = "Jeu (Blizzard)",
	["Lanes: round your character"] = "Couloirs : autour de votre personnage",
	["Feed: over your portrait"] = "Fil : au-dessus de votre portrait",
	["Classic: one stream, restyled"] = "Classique : un flux, restylé",
	["Your Damage"] = "Vos dégâts",
	["How your damage numbers over enemies look. Game: the game's own. Rise, Beside, Fan or Stack: MelloUI's, shown solo; in a group the game's show."] = "L’apparence des nombres de dégâts au-dessus des ennemis. Jeu : affichage du jeu. Montée, À côté, Éventail ou Colonne : affichage de MelloUI, en solo ; en groupe, celui du jeu.",
	["Rise: up from the enemy"] = "Montée : depuis l'ennemi",
	["Beside: up from the plate's side"] = "À côté : depuis le flanc de la barre",
	["Fan: up, left and right"] = "Éventail : haut, gauche et droite",
	["Stack: a column beside the enemy"] = "Pile : une colonne à côté de l'ennemi",
	["Your Damage Size"] = "Taille des nombres de dégâts",
	["The size of your damage numbers over enemies."] = "La taille de vos dégâts au-dessus des ennemis.",
	["Plays sample lines in the chosen style."] = "Lit des exemples de lignes dans le style choisi.",
	["a short burst in the chosen style"] = "une courte salve dans le style choisi",
	["Text Around You"] = "Texte autour de vous",
	["The size of the text around your character. Crits are a third bigger."] = "La taille du texte autour de votre personnage. Les nombres critiques sont un tiers plus grands.",
	["Notices In Title Font"] = "Avis en police de titre",
	["Procs and auras in the title font. Off: the text font."] = "Effets et auras dans la police des titres. Désactivé : la police du texte.",
	["Shade Size"] = "Taille de l'ombre",
	["The size of the soft shadow behind combat text. 0: none."] = "La taille de l'ombre douce derrière le texte de combat. 0 : aucune.",
	["Lane Spread"] = "Écart des couloirs",
	["How far left and right of your character the damage and healing lanes run."] = "Distance vers la gauche et la droite de votre personnage sur laquelle s'étendent les couloirs de dégâts et de soins.",
	["Most Lines"] = "Nombre de lignes",
	["The most lines shown at once. The oldest goes first."] = "Le plus de lignes à la fois. La plus ancienne part la première.",
	["Damage Taken"] = "Dégâts subis",
	["Damage you take."] = "Les dégâts subis.",
	["Healing and shields you get."] = "Les soins et boucliers reçus.",
	["Procs & Auras"] = "Déclenchements et auras",
	["Procs, auras gained or lost, interrupts and dispels."] = "Effets, auras gagnées ou perdues, interruptions et dissipations.",
	["Dodge, Parry & Block"] = "Esquive, Parade et Blocage",
	["Attacks that miss you: dodge, parry, block, absorb, resist and immune."] = "Les attaques qui vous ratent : esquive, parade, blocage, absorption, résistance et immunité.",
	["Resources Gained"] = "Ressources gagnées",
	["Mana, rage, energy and focus you gain."] = "Le mana, la rage, l'énergie et la focalisation que vous gagnez.",
	["Entering & Leaving Combat"] = "Entrée et sortie de combat",
	["A short line when a fight starts and ends."] = "Une courte ligne au début et à la fin d'un combat.",
	["Reputation & Honor"] = "Réputation et honneur",
	["Reputation and honor you gain."] = "La réputation et l'honneur que vous gagnez.",
	["Damage Over Enemies"] = "Dégâts au-dessus des ennemis",
	["Your damage numbers over enemies (the game's own)."] = "Vos dégâts au-dessus des ennemis (ceux du jeu).",
	["DoT Ticks Over Enemies"] = "Tics de DoT au-dessus des ennemis",
	["Your damage over time ticks over enemies (the game's own)."] = "Les nombres de vos dégâts périodiques au-dessus des ennemis (affichage du jeu).",
	["Pet Damage Over Enemies"] = "Dégâts du familier au-dessus des ennemis",
	["Your pet's damage over enemies (the game's own)."] = "Les nombres de dégâts de votre familier au-dessus des ennemis (affichage du jeu).",
	["Healing Over Friends"] = "Soins au-dessus des alliés",
	["Your healing numbers over friends (the game's own)."] = "Vos soins au-dessus des alliés (ceux du jeu).",
	-- DungeonInfo
	["Dungeon Info"] = "Infos des donjons",
	["Every dungeon and raid: its bosses, what they drop, and your own list of items to watch for."] = "Chaque donjon et raid : ses boss, les objets qu'ils laissent tomber, et votre liste d'objets à surveiller.",
	["Every dungeon's bosses and their loot beside the map; star the items you want and a loot roll tells you when one drops."] = "Les boss de chaque donjon et leur butin près de la carte ; marquez d'une étoile les objets voulus et un jet de butin vous prévient quand l'un tombe.",
	["Open Dungeon Info"] = "Ouvrir les infos des donjons",
	["Opens Dungeon Info beside the map. /dungeoninfo opens it too."] = "Ouvre les infos des donjons près de la carte. /dungeoninfo les ouvre aussi.",
	["At A Dungeon's Door"] = "À la porte d'un donjon",
	["At a dungeon's door, a row in the widget column with its bosses, your drops there and its quests."] = "À l’entrée d’un donjon, une ligne de la colonne de widgets présente ses boss, le butin que vous y avez obtenu et ses quêtes.",
	-- HealFlight
	["Heal Effects"] = "Effets de soin",
	["Your heals shown as light flying from your cast bar to the frame of the one you heal."] = "Vos soins apparaissent sous forme de lumière qui part de votre barre d’incantation et rejoint le cadre de la personne soignée.",
	["Your heals fly from your cast bar to the frame of the one you heal."] = "Vos soins volent de votre barre d'incantation jusqu'au cadre de celui que vous soignez.",
	["How your heals look. By Class: Holy for priests and paladins, Nature for druids, Water for shamans. Quiet: a subtle thread of light."] = "L’apparence de vos soins. Selon la classe : Sacré pour les prêtres et paladins, Nature pour les druides, Eau pour les chamans. Discret : un fin filet de lumière.",
	["By Class: Holy, Nature or Water"] = "Selon la classe : Sacré, Nature ou Eau",
	["Holy: a gold comet"] = "Sacré : une comète d'or",
	["Nature: ribbons and leaves"] = "Nature : rubans et feuilles",
	["Water: a stream and a splash"] = "Eau : un ruisseau et une éclaboussure",
	["Quiet: a thread of light"] = "Discret : un fil de lumière",
	["Flying Light"] = "Lumière volante",
	["A light flies from your cast bar to the healed frame. Off: the heal lands at once; the other effects stay."] = "Une lumière vole de votre barre d'incantation vers le cadre soigné. Désactivé : le soin arrive aussitôt ; les autres effets restent.",
	["Heal Over Time Ticks"] = "Tics des soins sur la durée",
	["Each tick of your heals over time plays a small pulse on the frame."] = "Chaque tic de vos soins sur la durée affiche une petite pulsation sur le cadre.",
	["Buff Landings"] = "Arrivées d'améliorations",
	["A buff landing on your group or your target plays a spiral of light on the frame, in its school's colour (Fortitude, Mark of the Wild, Arcane Intellect, the blessings ...), whoever cast it. A group buff runs out from the caster's frame; in a raid, a small glint. Buffs you can only cast on yourself play nothing."] = "Lorsqu'une amélioration arrive sur votre groupe ou votre cible, une spirale de lumière s'affiche sur le cadre, dans la couleur de son école (Robustesse, Marque du fauve, Intelligence des Arcanes, les bénédictions ...), quel que soit le lanceur. Une amélioration de groupe part du cadre du lanceur ; en raid, un petit scintillement. Les améliorations que vous ne pouvez lancer que sur vous ne déclenchent aucun effet.",
	["Plays the chosen heal look once on your own frame."] = "Affiche une fois l'aspect de soin choisi sur votre propre cadre.",
	["a made-up heal on you"] = "un soin inventé sur vous",
	["Every Kind"] = "Chaque type",
	["Plays each kind of heal landing on your frame: heal over time, shield, protection, full heal, resurrection, a buff."] = "Chaque type d'arrivée de soin s'affiche sur votre cadre : soin sur la durée, bouclier, protection, soin complet, résurrection, une amélioration.",
	["each kind's landing on your frame"] = "l'atterrissage de chaque type sur votre cadre",
	-- FrameEffects
	["Cooldown Effects"] = "Effets de temps de recharge",
	["Your group's frames show their big moments: taunts, Shield Wall, immunities, evasion and more."] = "Les cadres de votre groupe mettent en valeur leurs actions importantes : provocations, Mur protecteur, immunités, Évasion et autres effets.",
	["Shield Wall, Last Stand, a roar: your group's frames show their big moments."] = "Mur protecteur, Dernier rempart, un cri : les cadres de votre groupe montrent leurs grands moments.",
	["Every Effect"] = "Chaque effet",
	["Plays each kind of big moment on your own frame."] = "Chaque type de grand moment s'affiche sur votre propre cadre.",
	["each kind on your own frame"] = "chaque type sur votre propre cadre",
	["Whose"] = "Lesquels",
	["Whose big moments (Shield Wall, Divine Shield, Evasion...) play on the frames: yours, your group's, or both."] = "De qui les grands moments (Mur protecteur, Bouclier divin, Évasion...) s'affichent sur les cadres : les vôtres, ceux du groupe, ou les deux.",
	["Yours And Your Group's"] = "Les vôtres et ceux du groupe",
	["Yours"] = "Les vôtres",
	["Your Group's"] = "Ceux du groupe",
	-- GroupFrames
	["Group Frames"] = "Cadres de groupe",
	["MelloUI's own party and raid frames: their size, layout, colours, texts and your aura indicators."] = "Les cadres de groupe et de raid de MelloUI : leur taille, disposition, couleurs, textes et vos indicateurs d'aura.",
	["Your party and raid as you want them: colours, bars, texts, and your HoTs and shields at a glance."] = "Votre groupe et votre raid comme vous les voulez : couleurs, barres, textes, et vos soins sur la durée et boucliers d'un coup d'œil.",
	["In A Party"] = "En groupe",
	["In a party: the raid frames (their look is set on Raid), or the party frames with portraits. In a raid, the raid frames always show."] = "En groupe : les cadres de raid (leur apparence se règle dans Raid) ou les cadres de groupe avec portraits. En raid, les cadres de raid s’affichent toujours.",
	["Party Frames (Portraits)"] = "Cadres de groupe (portraits)",
	["Raid Frames' Look"] = "Apparence des cadres de raid",
	["Your party wears the raid frames' look: set it on Raid."] = "Votre groupe porte l'apparence des cadres de raid : réglez-la dans Raid.",
	["Raid"] = "Raid",
	["Show Yourself In Your Party"] = "Vous afficher dans votre groupe",
	["Your own frame among your party's."] = "Votre propre cadre parmi ceux de votre groupe.",
	["Show Yourself While Solo"] = "Vous afficher en solo",
	["Your own frame shows while you are not in a group. Move it in Edit Layout."] = "Votre propre cadre s'affiche quand vous n'êtes pas en groupe. Déplacez-le avec Modifier la disposition.",
	["Frame Width"] = "Largeur du cadre",
	["The width of each frame."] = "La largeur de chaque cadre.",
	["Frame Height"] = "Hauteur du cadre",
	["The height of each frame."] = "La hauteur de chaque cadre.",
	["Party Spacing"] = "Espacement du groupe",
	["The space between the party's frames."] = "L'espace entre les cadres du groupe.",
	["Vertical Spacing"] = "Espacement vertical",
	["The space between the party frames with portraits."] = "L'espace entre les cadres de groupe avec portraits.",
	["Party Grows"] = "Croissance du groupe",
	["Which way the party's frames line up."] = "Dans quel sens s'alignent les cadres du groupe.",
	["Party Order"] = "Ordre du groupe",
	["The order of the party's frames: by role, the game's order, or by name."] = "L'ordre des cadres du groupe : par rôle, l'ordre du jeu, ou par nom.",
	["By Role (Tanks, Healers, Damage)"] = "Par rôle (tanks, soigneurs, dégâts)",
	["Group Order"] = "Ordre du groupe",
	["By Name"] = "Par nom",
	["Raid Grouping"] = "Regroupement du raid",
	["How the raid is grouped: by group, role, class, or one list."] = "Comment le raid est regroupé : par groupe, rôle, classe, ou une seule liste.",
	["By Group"] = "Par groupe",
	["By Role"] = "Par rôle",
	["By Class"] = "Par classe",
	["One List"] = "Une liste",
	["Raid Fills"] = "Remplissage du raid",
	["Fill down columns, or across rows."] = "Remplir en colonnes vers le bas, ou en rangées en travers.",
	["Down, Then Across"] = "Vers le bas, puis en travers",
	["Across, Then Down"] = "En travers, puis vers le bas",
	["Frames Per Column / Row"] = "Cadres par colonne / rangée",
	["How many frames per column or row. 5 lines the raid up by group."] = "Combien de cadres par colonne ou rangée. 5 aligne le raid par groupe.",
	["Raid Spacing"] = "Espacement du raid",
	["The space between the raid's frames."] = "L'espace entre les cadres du raid.",
	["Gap Between Columns / Rows"] = "Écart entre colonnes / rangées",
	["The space between the raid's columns or rows."] = "L'espace entre les colonnes ou rangées du raid.",
	["Out Of Range Opacity"] = "Opacité hors de portée",
	["How much a member out of your range fades. 100%: no fade."] = "À quel point un membre hors de portée s'estompe. 100 % : pas d'estompage.",
	["Health Bar Opacity"] = "Opacité de la barre de vie",
	["How solid the health bar is."] = "L’opacité de la barre de vie.",
	["Fill Direction"] = "Sens de remplissage",
	["Which way the health and power bars fill."] = "Dans quel sens se remplissent les barres de vie et de ressource.",
	["Bottom To Top"] = "De bas en haut",
	["Top To Bottom"] = "De haut en bas",
	["Smooth Bars"] = "Barres fluides",
	["Bars glide to new values instead of jumping."] = "Les barres glissent vers les nouvelles valeurs au lieu de sauter.",
	["A glow and an outline on the frame under your mouse."] = "Une lueur et un contour sur le cadre sous votre souris.",
	["What shows behind the health bar: a flat colour, a texture, or nothing."] = "Ce qui s'affiche derrière la barre de vie : une couleur unie, une texture ou rien.",
	["Flat colour"] = "Couleur unie",
	["Background Colour"] = "Couleur de fond",
	["The colour behind the health bar: yours, or the member's class colour."] = "La couleur derrière la barre de vie : la vôtre, ou la couleur de classe du membre.",
	["Class Colour"] = "Couleur de classe",
	["My Background Colour"] = "Ma couleur de fond",
	["The background colour with My Colour."] = "La couleur de fond avec Ma couleur.",
	["How solid the background is."] = "L’opacité du fond.",
	["Missing Health"] = "Vie manquante",
	["Colours the lost part of the health bar: your colour, the class colour, or by health."] = "Colore la partie perdue de la barre de vie : votre couleur, la couleur de classe ou selon la vie.",
	["By Health"] = "Selon la vie",
	["My Missing Health Colour"] = "Ma couleur de vie manquante",
	["The missing health's colour with My Colour."] = "La couleur de la vie manquante avec Ma couleur.",
	["Missing Health Opacity"] = "Opacité de la vie manquante",
	["How solid the missing health is."] = "La densité de la vie manquante.",
	["Power Bar"] = "Barre de ressource",
	["Who shows a power bar under their health."] = "Qui affiche une barre de ressource sous sa vie.",
	["Healers"] = "Soigneurs",
	["Everyone"] = "Tout le monde",
	["Your Power Bar While Solo"] = "Votre barre de ressource en solo",
	["Your own power bar while you play solo."] = "Votre propre barre de ressource quand vous jouez seul.",
	["Power Bar Height"] = "Hauteur de la barre de ressource",
	["How tall the power bar is."] = "La hauteur de la barre de ressource.",
	["Power Colour"] = "Couleur de la ressource",
	["The power bar's colour: the power's own, the class colour, or yours."] = "La couleur de la barre de ressource : celle de la ressource, la couleur de classe ou la vôtre.",
	["Power Type"] = "Type de ressource",
	["My Power Colour"] = "Ma couleur de ressource",
	["The power colour with My Colour."] = "La couleur de ressource avec Ma couleur.",
	["Name Colour"] = "Couleur du nom",
	["The name's colour: white, the class colour, or yours."] = "La couleur du nom : blanc, la couleur de classe ou la vôtre.",
	["White"] = "Blanc",
	["My Name Colour"] = "Ma couleur de nom",
	["The name colour with My Colour."] = "La couleur du nom avec Ma couleur.",
	["Name Length"] = "Longueur du nom",
	["The most letters of a name shown."] = "Le nombre maximal de caractères affichés pour un nom.",
	["Health Text"] = "Texte de vie",
	["The health text: percent, current health, or missing health."] = "Le texte de vie : pourcentage, points de vie actuels ou points de vie manquants.",
	["Percent"] = "Pourcentage",
	["Current"] = "Actuelle",
	["Missing"] = "Manquante",
	["Dead / Offline Text"] = "Texte Mort / Hors ligne",
	["Dead, Ghost or Offline on a member's frame."] = "Mort, Fantôme ou Hors ligne sur le cadre d'un membre.",
	["The font of names on the party and raid frames. Shared: the interface font."] = "La police des noms sur les cadres de groupe et de raid. Partagée : la police de l'interface.",
	["Health Text Font"] = "Police du texte de vie",
	["The font of health text and status words on the party and raid frames. Shared: the interface font."] = "La police du texte de vie et des mots d'état sur les cadres de groupe et de raid. Partagée : la police de l'interface.",
	["Indicator Numbers Font"] = "Police des chiffres d'indicateurs",
	["The font of the indicators' timers and stacks. Shared: the numbers font."] = "La police des minuteurs et des piles des indicateurs. Partagée : la police des nombres.",
	["Indicators On The Frames"] = "Indicateurs sur les cadres",
	["Your aura indicators on the frames."] = "Vos indicateurs d'aura sur les cadres.",
	["Your Indicators"] = "Vos indicateurs",
	["Your spell groups for this spec: drag a group onto the frame, pick its spells, then its look, place, size and colour."] = "Vos groupes de sorts pour cette spécialisation : glissez un groupe sur le cadre, choisissez ses sorts, puis son aspect, sa place, sa taille et sa couleur.",
	-- PersonalDisplay
	["Your health, power and cast bars under your character, with a shield bar beside them. Place it in Edit Layout. Replaces the game's personal resource display."] = "Vos barres de vie, de ressource et d'incantation sous votre personnage, avec une barre de bouclier à côté. Placez-les avec Modifier la disposition. Remplace l'affichage des ressources personnelles du jeu.",
	["Health, power, casts and shields, right by your character."] = "Vie, ressource, incantations et boucliers, juste à côté de votre personnage.",
	["Shield Column"] = "Colonne de bouclier",
	["A bar beside your character for all your shields, each in its school's colour. It drains as they take hits."] = "Une barre près de votre personnage pour tous vos boucliers, chacun à la couleur de son école. Elle se vide quand ils encaissent.",
	["Hide The Game's Cast Bar"] = "Masquer la barre d'incantation du jeu",
	["Hides the game's cast bar; your casts show on the display."] = "Masque la barre d'incantation du jeu ; vos incantations s'affichent sur l'affichage personnel.",
	["Heal Light From Your Character"] = "Lumière de soin depuis votre personnage",
	["Your heals' light starts from your character instead of the cast bar."] = "La lumière de vos soins part de votre personnage au lieu de la barre d'incantation.",
	["Your swing timer as a small badge on your target's nameplate."] = "Votre minuteur d'attaque en petit badge sur la barre d'info de votre cible.",
	["Over The Personal Display"] = "Au-dessus de l'affichage personnel",
	["The swing badge stands centred above the display instead of on your target's nameplate."] = "L'insigne de frappe se place au centre au-dessus de l'affichage au lieu de se trouver au-dessus de la barre d'info de votre cible.",
	["Big Cooldowns"] = "Grands temps de recharge",
	["Your big defensive cooldowns (Shield Wall, Evasion, Ice Block...) as icons above the health bar."] = "Vos grands temps de recharge défensifs (Mur protecteur, Évasion, Bloc de glace...) en icônes au-dessus de la barre de vie.",
	["Tracked Spells"] = "Sorts suivis",
	["Tick your class's spells to see them in a row under the bars while they last on you, each with its seconds. Nothing is ticked at first."] = "Cochez des sorts de votre classe pour les voir dans une rangée sous les barres tant qu'ils durent sur vous, chacun avec ses secondes. Rien n'est coché au départ.",
	["Track By Name"] = "Suivre par nom",
	["Type a buff or debuff's name (or its spell ID) to see it in the Tracked Spells row while it lasts on you, like a talent's proc. In a fight the game tells only some spells; those it keeps hidden show out of a fight."] = "Saisissez le nom (ou l'ID de sort) d'une amélioration ou d'un affaiblissement pour le voir dans la rangée des sorts suivis tant qu'il dure sur vous, comme l'effet d'un talent. En combat, le jeu n'indique que certains sorts ; ceux qu'il cache s'affichent hors combat.",
	["Percent And Spell Text"] = "Pourcentage et texte de sort",
	["Health and power percent, spell names and times."] = "Pourcentage de vie et de ressource, nom et durée des sorts.",
	["Text Font"] = "Police du texte",
	["The font of the display's text. Shared: the interface font."] = "La police du texte de l'affichage. Partagée : la police de l'interface.",
	["Class Colours"] = "Couleurs de classe",
	["The health bar in your class colour instead of green."] = "La barre de vie dans votre couleur de classe au lieu du vert.",
	["How wide the bars are."] = "La largeur des barres.",
	["How tall the health bar is; the others follow."] = "La hauteur de la barre de vie ; les autres suivent.",
	["Big Cooldown Size"] = "Taille des grands temps de recharge",
	["The size of the Big Cooldowns' icons."] = "La taille des icônes des grands temps de recharge.",
	["Follow Camera Zoom"] = "Suivre le zoom de la caméra",
	["The display stays by your character as you zoom the camera."] = "L'affichage reste près de votre personnage quand vous zoomez la caméra.",
	["Cast Motion"] = "Mouvement d'incantation",
	["The cast bar opens, flashes on a landed cast and drops when interrupted."] = "La barre d'incantation s'ouvre, clignote quand l'incantation réussit et descend lorsqu'elle est interrompue.",
	["The health a hit took stays lit for a moment before it drains."] = "La vie qu'un coup a prise reste éclairée un instant avant de se vider.",
	["Heal Lead"] = "Avance du soin",
	["A heal lights the health it gives at once; the bar then fills into it."] = "Un soin éclaire aussitôt la vie qu'il rend ; la barre se remplit ensuite jusque-là.",
	["Heavy Hit"] = "Coup lourd",
	["A critical or crushing blow on you flashes the bars red."] = "Un coup critique ou écrasant sur vous fait flasher les barres en rouge.",
	["Power Spent"] = "Ressource dépensée",
	["The power an ability costs stays lit for a moment, so you see the cost."] = "La ressource que coûte une technique reste éclairée un instant, pour voir le coût.",
	["Power Gained"] = "Ressource gagnée",
	["New power lights up ahead of the bar before it fills."] = "La nouvelle ressource s'éclaire devant la barre avant qu'elle se remplisse.",
	["Dodge, Parry, Block"] = "Esquive, Parade, Blocage",
	["Your dodge, parry or block flicks its word off the health bar."] = "Votre esquive, parade ou blocage s'envole de la barre de vie.",
	["Low Health"] = "Vie basse",
	["The health bar turns ember under 35% health."] = "La barre de vie prend une teinte braise lorsque les points de vie passent sous 35 %.",
	["Loss Of Control"] = "Perte de contrôle",
	["While you are stunned, feared or silenced, the bars turn red and a line counts down its time. Replaces the game's own banner."] = "Quand vous êtes étourdi, apeuré ou réduit au silence, les barres rougissent et une ligne décompte le temps. Remplace la bannière du jeu.",
	["Combat Settle"] = "Posture de combat",
	["The bars rise into place when a fight starts and settle lower and slimmer after it. (To fade them out of combat: the Fader.)"] = "Les barres montent en place au début d'un combat et se posent plus bas et plus fines après. (Pour les estomper hors combat : le Fondu.)",
	["Plays a short sample fight on the display."] = "Lance un court combat d'exemple sur l'affichage.",
	["a shield going up, hit, low and broken, casts, and the bars in the fight"] = "un bouclier levé, frappé, bas et brisé, des incantations, et les barres en combat",
	-- VoiceOver
	["Voice Over"] = "Voix",
	["Reads NPC dialog, quests and books aloud: recorded voices from the voice pack, or text-to-speech."] = "Lit à voix haute les dialogues des PNJ, les quêtes et les livres : voix enregistrées du pack de voix, ou synthèse vocale.",
	["Every quest giver speaks. Recorded voices with the pack, text-to-speech without it."] = "Chaque donneur de quête parle : voix enregistrées avec le pack, synthèse vocale sans le pack.",
	["Read Aloud"] = "Lecture à voix haute",
	["NPC Greetings"] = "Salutations des PNJ",
	["What an NPC says when you talk to them."] = "Ce que dit un PNJ quand vous lui parlez.",
	["Quest Offers"] = "Offres de quête",
	["The quest's description when it is offered."] = "La description de la quête quand elle est proposée.",
	["Quest Objectives"] = "Objectifs de quête",
	["The quest's objectives after its description, when the voice pack has them recorded."] = "Les objectifs de la quête après sa description, quand le pack de voix les a enregistrés.",
	["Quest Progress"] = "Progression de quête",
	["What the NPC says when you return with an unfinished quest."] = "Ce que dit le PNJ quand vous revenez avec une quête inachevée.",
	["Quest Turn-In"] = "Rendu de quête",
	["What the NPC says when you hand in a quest."] = "Ce que dit le PNJ quand vous rendez une quête.",
	["Read Books And Letters Aloud"] = "Lire les livres et lettres à voix haute",
	["Books, letters, notes and signs read aloud when you open them."] = "Livres, lettres, notes et panneaux lus à voix haute à l'ouverture.",
	["Text-to-Speech"] = "Synthèse vocale",
	["Male NPCs"] = "PNJ masculins",
	["The text-to-speech voice for male NPCs. Add voices in Windows' speech settings."] = "La voix de synthèse pour les PNJ masculins. Ajoutez des voix dans les paramètres vocaux de Windows.",
	["Automatic (by gender)"] = "Automatique (selon le genre)",
	["Female NPCs"] = "PNJ féminins",
	["The text-to-speech voice for female NPCs."] = "La voix de synthèse pour les PNJ féminins.",
	["Speed"] = "Vitesse",
	["How fast text-to-speech reads. 0: the voice's normal pace."] = "La vitesse de lecture de la synthèse vocale. 0 : le rythme normal de la voix.",
	["Volume"] = "Volume",
	["How loud text-to-speech reads. Recorded lines follow the game's Sound Channel volume."] = "Le volume de la synthèse vocale. Les lignes enregistrées suivent le volume du canal sonore du jeu.",
	["Voice Per Race (optional)"] = "Voix selon la race (facultatif)",
	["Humans"] = "Humains",
	["The text-to-speech voice for humans of either gender; recorded lines keep their own voice. Automatic uses the male / female voices above."] = "La voix de synthèse pour les humains des deux sexes ; les lignes enregistrées gardent leur voix. Le mode Automatique utilise les voix masculine / féminine ci-dessus.",
	["Elves"] = "Elfes",
	["The text-to-speech voice for elves of either gender; recorded lines keep their own voice. Automatic uses the male / female voices above."] = "La voix de synthèse pour les elfes des deux sexes ; les lignes enregistrées gardent leur voix. Le mode Automatique utilise les voix masculine / féminine ci-dessus.",
	["Dwarves"] = "Nains",
	["The text-to-speech voice for dwarves of either gender; recorded lines keep their own voice. Automatic uses the male / female voices above."] = "La voix de synthèse pour les nains des deux sexes ; les lignes enregistrées gardent leur voix. Le mode Automatique utilise les voix masculine / féminine ci-dessus.",
	["Gnomes"] = "Gnomes",
	["The text-to-speech voice for gnomes of either gender; recorded lines keep their own voice. Automatic uses the male / female voices above."] = "La voix de synthèse pour les gnomes des deux sexes ; les lignes enregistrées gardent leur voix. Le mode Automatique utilise les voix masculine / féminine ci-dessus.",
	["Orcs"] = "Orcs",
	["The text-to-speech voice for orcs of either gender; recorded lines keep their own voice. Automatic uses the male / female voices above."] = "La voix de synthèse pour les orcs des deux sexes ; les lignes enregistrées gardent leur voix. Le mode Automatique utilise les voix masculine / féminine ci-dessus.",
	["Trolls"] = "Trolls",
	["The text-to-speech voice for trolls of either gender; recorded lines keep their own voice. Automatic uses the male / female voices above."] = "La voix de synthèse pour les trolls des deux sexes ; les lignes enregistrées gardent leur voix. Le mode Automatique utilise les voix masculine / féminine ci-dessus.",
	["Tauren"] = "Taurens",
	["The text-to-speech voice for tauren of either gender; recorded lines keep their own voice. Automatic uses the male / female voices above."] = "La voix de synthèse pour les taurens des deux sexes ; les lignes enregistrées gardent leur voix. Le mode Automatique utilise les voix masculine / féminine ci-dessus.",
	["Undead"] = "Morts-vivants",
	["The text-to-speech voice for undead of either gender; recorded lines keep their own voice. Automatic uses the male / female voices above."] = "La voix de synthèse pour les morts-vivants des deux sexes ; les lignes enregistrées gardent leur voix. Le mode Automatique utilise les voix masculine / féminine ci-dessus.",
	["Goblins"] = "Gobelins",
	["The text-to-speech voice for goblins of either gender; recorded lines keep their own voice. Automatic uses the male / female voices above."] = "La voix de synthèse pour les gobelins des deux sexes ; les lignes enregistrées gardent leur voix. Le mode Automatique utilise les voix masculine / féminine ci-dessus.",
	["Ogres & Giants"] = "Ogres et géants",
	["The text-to-speech voice for ogres & giants of either gender; recorded lines keep their own voice. Automatic uses the male / female voices above."] = "La voix de synthèse pour les ogres et géants des deux sexes ; les lignes enregistrées gardent leur voix. Le mode Automatique utilise les voix masculine / féminine ci-dessus.",
	["Monsters & Beasts"] = "Monstres et bêtes",
	["The text-to-speech voice for monsters & beasts of either gender; recorded lines keep their own voice. Automatic uses the male / female voices above."] = "La voix de synthèse pour les monstres et bêtes des deux sexes ; les lignes enregistrées gardent leur voix. Le mode Automatique utilise les voix masculine / féminine ci-dessus.",
	["Sound Packs"] = "Packs sonores",
	["Use Voice Packs"] = "Utiliser les packs de voix",
	["Plays recorded lines from the voice pack (MelloUI_VoicePack, a separate download) where it has them."] = "Lit les lignes enregistrées du pack de voix (MelloUI_VoicePack, un téléchargement séparé) lorsqu'elles existent.",
	["Read Unvoiced Lines"] = "Lire les lignes sans enregistrement",
	["Lines the voice pack doesn't have are read with text-to-speech. Off: they stay silent."] = "Les lignes absentes du pack de voix sont lues en synthèse vocale. Désactivé : elles restent silencieuses.",
	["Prefer Recordings"] = "Préférer les enregistrements",
	["Plays an NPC's recorded greeting even when the game changed its text. The words may not match."] = "Lit l'accueil enregistré d'un PNJ même si le jeu a changé son texte. Les mots peuvent ne pas correspondre.",
	["The game volume slider recorded lines follow."] = "Les lignes enregistrées suivent le curseur de volume du jeu.",
	["Ambience"] = "Ambiance",
	["Record Dialog Lines"] = "Enregistrer les lignes de dialogue",
	["For making new voice lines: keep the greetings and quest lines Voice Over picks up (read aloud or left silent), with the NPC and whether a recording existed, so the lines this client added or changed can be voiced for the pack. Lines of a kind switched off, repeats and greetings passed over behind a quest line are not kept. Saved and kept from one session to the next. Off by default."] = "Pour créer de nouvelles lignes de voix : garde les salutations et lignes de quête que Voice Over capte (lues ou laissées muettes), avec le PNJ et l'existence d'un enregistrement, pour que les lignes ajoutées ou modifiées par ce client puissent être doublées pour le pack. Les lignes d'un type désactivé, les répétitions et les salutations passées derrière une ligne de quête ne sont pas gardées. Enregistré et gardé d'une session à l'autre. Désactivé par défaut.",
	["Playback"] = "Lecture",
	["Queue Lines"] = "Mettre les lignes en file",
	["Lines are read one after another. Off: a new dialog interrupts the last one."] = "Les lignes sont lues l'une après l'autre. Désactivé : un nouveau dialogue interrompt le précédent.",
	["Stop When Window Closes"] = "Arrêter à la fermeture de la fenêtre",
	["Stops reading when you close the dialog."] = "Arrête la lecture quand vous fermez le dialogue.",
	["Read Button In The Quest Log"] = "Bouton Lire dans le journal des quêtes",
	["A Read button in the quest log that reads the quest aloud. /vo read does the same."] = "Un bouton Lire dans le journal de quêtes qui lit la quête à voix haute. /vo read fait de même.",
	["Stop When Target Changes"] = "Arrêter au changement de cible",
	["Stops reading when you change target."] = "Arrête la lecture quand vous changez de cible.",
	["Show The Widget"] = "Afficher le widget",
	["Shows the speaker in the widget column while a line is read, with Pause, Skip and Stop."] = "Affiche l'orateur dans la colonne de widgets pendant la lecture, avec Pause, Passer et Arrêter.",
	["3D Portrait"] = "Portrait 3D",
	["The speaker's animated face in the widget. Off: a book."] = "Le visage animé de l'orateur dans le widget. Désactivé : un livre.",
	["Subtitles"] = "Sous-titres",
	["Also shows the text being read."] = "Affiche aussi le texte lu.",
	["Compact In Combat"] = "Compact en combat",
	["In a fight, the widget shrinks to the speaker's face."] = "En combat, le widget se réduit au visage de l'orateur.",
