	["Your bars: pick one, click a part of it, change it."] = "Vos barres : choisissez-en une, cliquez sur une de ses parties et modifiez-la.",
	["Animations"] = "Animations",
	["Every animation MelloUI plays, in one place. Press Play beside one to see it before you choose."] = "Toutes les animations de MelloUI, au même endroit. Appuyez sur Jouer à côté de l'une d'elles pour la voir avant de choisir.",
	["The damage meter."] = "Le compteur de dégâts.",
	["Your buffs and debuffs: switch on MelloUI's own, pick where they stand, then move them in Edit Layout."] = "Vos améliorations et affaiblissements : activez ceux de MelloUI, choisissez leur position, puis déplacez-les dans Modifier la disposition.",
	["The chat windows, the lines in them and the whisper popup."] = "Les fenêtres de discussion, leurs lignes et la fenêtre de chuchotement.",
	["Fade parts of the interface while you don't need them: pick when each one shows."] = "Estompe des parties de l'interface quand vous n'en avez pas besoin : choisissez quand chacune s'affiche.",
	["Home"] = "Accueil",
	["The painted reskin and MelloUI's interface features: Vendor, Error Messages, Nameplates, Unit Frames, Chat, Tooltip, Fonts, Dark Mode, Bar Textures and FPS / Latency, and hiding the micro menu, bag bar and minimap coordinates. Off: all of them stop, and Edit Layout lets go of the game's windows; the palette, the UI Shade, Reduce Motion and the notices keep working."] = "La refonte peinte et les fonctions de l’interface MelloUI : marchand, messages d’erreur, barres d’info, cadres d’unité, discussion, encadrés d’aide, polices, mode sombre, textures des barres et IPS / latence, ainsi que le masquage du micro-menu, de la barre de sacs et des coordonnées de la minicarte. Désactivé : ces fonctions s’arrêtent et Modifier la disposition libère les fenêtres du jeu ; la palette, l’ombre de l’interface, Réduire les animations et les avis restent actifs.",
	["The look of the whole interface: its skin, the soft shade, every font and texture, the colours, icons and Dark Mode. The painted reskin and its palettes are on the Oldschool page."] = "L'apparence de toute l'interface : son habillage, l'ombre douce, chaque police et texture, les couleurs, icônes et le mode sombre. L'habillage peint et ses palettes sont sur la page Oldschool.",
	["The minimap and the Services bar under it: pick one, click a part, change it."] = "La minicarte et la barre Services dessous : choisissez-en une, cliquez une partie, modifiez-la.",
