	-- Language
	["The language of the configurator and the installer. A line not translated yet shows in English."] = "La langue du configurateur et de l'installateur. Une ligne pas encore traduite s'affiche en anglais.",
	["Type /reload to finish switching the language."] = "Tapez /reload pour finir de changer de langue.",
	["Language"] = "Langue",
	-- Core/Config.lua
	["Module based interface tweaks for World of Warcraft: Forever."] = "Des réglages d'interface par modules pour World of Warcraft: Forever.",
	["Your whole setup under one name. Save it, load it, or make it the default for a fresh install."] = "Toute votre configuration sous un nom. Enregistrez-la, chargez-la, ou faites-en la configuration par défaut d'une nouvelle installation.",
	["Supporters"] = "Soutiens",
	["The people who help keep MelloUI going."] = "Les personnes qui font vivre MelloUI.",
	["Map: with RareScanner installed, its rares, treasures and events show on MelloUI's map as MelloUI's icons on a plate; the rim shows if you just saw one, haven't found it yet or are done."] = "Carte : avec RareScanner installé, ses rares, trésors et événements apparaissent sur la carte de MelloUI sous forme d'icônes MelloUI sur une plaque ; le contour indique si vous venez d'en voir un, si vous ne l'avez pas encore trouvé ou si c'est fait.", -- draft
	["Minimap: RareScanner's icons on the minimap wear the same look."] = "Minicarte : les icônes de RareScanner sur la minicarte prennent le même style.", -- draft
	["Rare Alert: a rare RareScanner finds comes up in MelloUI's Rare Alert with its place; RareScanner's own alert button is switched off once, switch it on in RareScanner to keep it."] = "Alerte rare : un rare trouvé par RareScanner apparaît dans l'Alerte rare de MelloUI avec son emplacement ; le bouton d'alerte de RareScanner est désactivé une fois, réactivez-le dans RareScanner pour le garder.", -- draft
	["Map: with Questie installed, its objective icons (swords, sacks ...) no longer show over MelloUI's quest areas and marks; MelloUI now knows Questie's icons by their kind, not their picture."] = "Carte : avec Questie installé, ses icônes d'objectif (épées, sacs ...) ne s'affichent plus par-dessus les zones et marques de quête de MelloUI ; MelloUI reconnaît désormais les icônes de Questie à leur type, et non à leur image.", -- draft
	["Map: Questie's flight master icons stay hidden while the map's Flight masters layer shows MelloUI's own."] = "Carte : les icônes de maître de vol de Questie restent cachées tant que le calque Maîtres de vol de la carte affiche ceux de MelloUI.", -- draft
	["Map: quest areas that touch now show one outline instead of a stack of rings; each objective keeps its marks where it is done, and hovering a mark shows its own area inside."] = "Carte : les zones de quête qui se touchent affichent désormais un seul contour au lieu d'une pile d'anneaux ; chaque objectif garde ses marques là où il se fait, et survoler une marque montre sa propre zone à l'intérieur.", -- draft
	["Minimap: quest areas that touch show one outline there too, and hovering a quest mark lifts it and shows its own area, as on the map."] = "Minicarte : les zones de quête qui se touchent y affichent aussi un seul contour, et survoler une marque de quête la soulève et montre sa propre zone, comme sur la carte.", -- draft
	["Map: a Fog Of War option keeps the places you haven't explored hidden on the map, as on the game's own world map, until you walk there."] = "Carte : une option Brouillard de guerre garde cachés sur la carte les lieux que vous n'avez pas explorés, comme sur la carte du monde du jeu, jusqu'à ce que vous y alliez.", -- draft
	["Chat: the whisper window now stays on top of other windows, like the map and the bags, while it is open."] = "Chat : la fenêtre des chuchotements reste désormais au-dessus des autres fenêtres, comme la carte et les sacs, tant qu'elle est ouverte.", -- draft
	["Chat: right-click a person in the whisper window to remove that conversation, or all of them; they are gone from the saved history too."] = "Chat : faites un clic droit sur une personne dans la fenêtre des chuchotements pour retirer cette conversation, ou toutes ; elles disparaissent aussi de l'historique enregistré.", -- draft
	["Chat: the whisper window lists every conversation the first time it opens after logging in, not only the first two."] = "Chat : la fenêtre des chuchotements affiche toutes les conversations dès sa première ouverture après la connexion, et plus seulement les deux premières.", -- draft
	["Swing timer: Swing Ring Width (Thin, Medium, Thick) and Swing Ring Colour options for the ring that fills round the swing badge; the part still to fill is now a dark track, easier to see."] = "Délai d'attaque : options Largeur de l'anneau d'attaque (Fin, Moyen, Épais) et Couleur de l'anneau d'attaque pour l'anneau qui se remplit autour du badge ; la partie encore à remplir est désormais une piste sombre, plus visible.", -- draft
	["Edit Layout: the game's own swing timers no longer show there while MelloUI's swing badge takes their place."] = "Modifier la disposition : les délais d'attaque du jeu n'y apparaissent plus tant que le badge d'attaque de MelloUI prend leur place.", -- draft
	["Dark Mode: an action button's gold frame for an active stance or a queued spell stays bright, as do its pressed, hover and out-of-range frames; only the plain frames darken."] = "Mode sombre : le cadre doré d'un bouton d'action pour une posture active ou un sort en file reste lumineux, tout comme ses cadres enfoncé, survolé et hors de portée ; seuls les cadres simples s'assombrissent.", -- draft
	["Map: a Map Coordinates option shows your coordinates in the line under the map, and the mouse's while it is over the map."] = "Carte : une option Coordonnées de la carte affiche vos coordonnées sur la ligne sous la carte, et celles de la souris quand elle survole la carte.", -- draft
	["Minimap: a Minimap Coordinates option shows your coordinates under the minimap, and the mouse's in gold while it is over the minimap. It takes the place of Hide Minimap Coordinates."] = "Minicarte : une option Coordonnées de la minicarte affiche vos coordonnées sous la minicarte, et celles de la souris en doré quand elle survole la minicarte. Elle remplace Masquer les coordonnées de la minicarte.", -- draft
	["Dark Mode: gold words no longer darken with it, like the MelloUI button in the Game Menu, the chat's headers and the map's quest counts; only the frames and backgrounds darken."] = "Mode sombre : les textes dorés ne s'assombrissent plus avec lui, comme le bouton MelloUI du menu du jeu, les en-têtes du chat et les compteurs de quêtes de la carte ; seuls les cadres et les fonds s'assombrissent.", -- draft
	["Bags: the new Reagent Bag With The Bags option shows the Reagent Bag's items in your bags' one view, its slots in lime and its free slots counted in an Empty slot of their own."] = "Sacs : la nouvelle option Sac de composants avec les sacs montre les objets du sac de composants dans la vue unique de vos sacs, ses emplacements en vert citron et ses emplacements libres comptés dans un emplacement Vide à part.", -- draft
	["Chat: the short channel tags (G, P, R ...) wear the game's own chat colours, and with Short Channel Tags on the Minimal Chat View's headers show only the tag."] = "Discussion : les abréviations courtes des canaux (G, P, R ...) prennent les couleurs de discussion du jeu, et avec Abréviations courtes des canaux les en-têtes de la vue de discussion minimale n'affichent que l'abréviation.", -- draft
	["Chat: a Chat Timestamps option on the Chat page sets the game's own chat timestamps, None hides them; the Minimal Chat View follows it."] = "Discussion : une option Horodatage de la discussion sur la page Discussion règle l'horodatage du jeu, Aucun le masque ; la vue de discussion minimale le suit.", -- draft
	["Chat: a Copy button on the whisper windows puts the whole conversation in a window to copy, links and long messages included."] = "Discussion : un bouton Copier dans les fenêtres de chuchotement met toute la conversation dans une fenêtre à copier, liens et longs messages compris.", -- draft
	["Map: the first time you open the map after logging in, it shows your current zone (a city's own map in a city) instead of the whole world."] = "Carte : la première fois que vous ouvrez la carte après la connexion, elle montre votre zone actuelle (la carte d'une ville dans une ville) au lieu du monde entier.", -- draft
	["Map: Krol'dok Stronghold's entrance (levels 40-45) shows in the Riverglades, at the cave west of the fortress, and Route takes you there."] = "Carte : l'entrée du Bastion Krol’dok (niveaux 40-45) apparaît aux Rives Claires, à la grotte à l'ouest de la forteresse, et Route vous y emmène.", -- draft
	["Quests: with Questie installed, the Quest List, its map pins, the objective marks and Route use Questie's quest database for the newest quest data; MelloUI's own fills any gaps."] = "Quêtes : avec Questie installé, la liste des quêtes, ses repères sur la carte, les marques d'objectifs et l'itinéraire utilisent la base de quêtes de Questie pour les données les plus récentes ; celle de MelloUI comble les manques.", -- draft
	["Quest List: with Questie installed, a quest you cannot take yet (an earlier quest, a breadcrumb, a spell or a profession first) waits in the list, no longer shown as ready."] = "Liste des quêtes : avec Questie installé, une quête que vous ne pouvez pas encore prendre (une quête précédente, une quête d'introduction, un sort ou un métier d'abord) attend dans la liste et n'apparaît plus comme disponible.", -- draft
	["Map: with Questie installed, MelloUI's quest givers, objective marks and quest areas stay and Questie's icons of the same kind hide, no more double icons; its others wear MelloUI's pictures."] = "Carte : avec Questie installé, les donneurs de quêtes, marques d'objectifs et zones de quête de MelloUI restent et les icônes de Questie du même type sont masquées, plus d'icônes en double ; ses autres icônes prennent les images de MelloUI.", -- draft
	["Map: an Icons slider in the map's title row sizes every icon on the map, from 50 to 200 %, Questie's too."] = "Carte : un curseur Icônes dans la barre de titre de la carte règle la taille de toutes ses icônes, de 50 à 200 %, celles de Questie aussi.", -- draft
	["Map: with Questie installed, hovering one of Questie's icons no longer lists the quests MelloUI's own marks already show nearby (a dungeon's quests at its entrance)."] = "Carte : avec Questie, survoler une icône de Questie n'affiche plus les quêtes que les marques de MelloUI montrent déjà à côté (les quêtes d'un donjon à son entrée).", -- draft
	["Map: more colour in the quest tooltips: a mob's name red, an NPC's green, levels in their difficulty colour, and an objective's count red until done, green once done."] = "Carte : plus de couleur dans les infobulles de quête : le nom d'un monstre en rouge, celui d'un PNJ en vert, les niveaux dans leur couleur de difficulté, et le compteur d'un objectif rouge jusqu'à ce qu'il soit fait, puis vert.", -- draft
	["Quest Tracker: each quest's XP beside its name (Quest XP)."] = "Suivi des quêtes : l'XP de chaque quête à côté de son nom (XP des quêtes).", -- draft
	["Quest Tracker: with Questie's tracker on, MelloUI's steps aside and Questie's wears MelloUI's look, never both at once; its quests stay open in dungeons."] = "Suivi des quêtes : avec le suivi de Questie actif, celui de MelloUI s'efface et celui de Questie prend l'apparence de MelloUI, jamais les deux ; ses quêtes restent ouvertes en donjon.", -- draft
	["Quest Tracker: with Questie's tracker on, a leveling guide's steps (RestedXP, Follow The Arrow, APR), and tracked recipes where Questie lists none, dock under it in MelloUI's look."] = "Suivi des quêtes : avec le suivi de Questie activé, les étapes d'un guide de montée en niveau (RestedXP, Follow The Arrow, APR), et les recettes suivies quand Questie n'en affiche pas, s'ancrent en dessous avec l'apparence de MelloUI.", -- draft
	["Quest Tracker: each quest in Questie's tracker carries MelloUI's quest mark, on any Questie version: a click follows it with Route, a right-click opens Questie's menu."] = "Suivi des quêtes : chaque quête du suivi de Questie porte la marque de quête de MelloUI, avec toute version de Questie : un clic la suit avec Route, un clic droit ouvre le menu de Questie.", -- draft
	["Quest Tracker: with MelloUI's map on, a click on a quest in Questie's tracker opens it in MelloUI's map and its quest log, and Questie's Show on Map opens MelloUI's map."] = "Suivi des quêtes : avec la carte de MelloUI activée, un clic sur une quête dans le suivi de Questie l'ouvre dans la carte de MelloUI et son journal de quêtes, et « Afficher sur la carte » de Questie ouvre la carte de MelloUI.", -- draft
	["Nameplates: with Questie installed, its own quest icons over the plates are switched off once for MelloUI's Quest Icon; switch them on in Questie to keep them."] = "Barres de nom : avec Questie installé, ses propres icônes de quête au-dessus des barres sont désactivées une fois au profit de l'icône de quête de MelloUI ; réactivez-les dans Questie pour les garder.", -- draft
