	["the last recording's report again, to copy"] = "le rapport du dernier enregistrement à nouveau, à copier",
	["how long each part took to load, and its memory"] = "le temps de chargement de chaque partie, et sa mémoire",
	["MelloUI's recent messages in a window to copy"] = "les messages récents de MelloUI dans une fenêtre à copier",
	["Custom Sounds: its state and the slowest sounds"] = "Sons personnalisés : leur état et les sons les plus lents",
	["hear one custom sound (/sfx list names them)"] = "écouter un son personnalisé (/sfx list les nomme)",
	["stop, pause or skip the voice that is reading"] = "arrêter, mettre en pause ou passer la voix qui lit",
	["read the quest selected in the quest log aloud"] = "lire à voix haute la quête choisie dans le journal des quêtes",
	["a test line in the targeted NPC's voice"] = "une ligne d'essai avec la voix du PNJ ciblé",
	["which voice packs are installed"] = "quels packs de voix sont installés",
	["the Voice Over window back to its place"] = "la fenêtre Voice Over remise à sa place",
	["the route, its road data and your flight points"] = "l'itinéraire, ses données de routes et vos points de vol",
	["stop the route"] = "arrêter l'itinéraire",
	["the list of the nearest services"] = "la liste des services les plus proches",
	["route to the nearest one, e.g. /services repair"] = "itinéraire vers le plus proche, p. ex. /services repair",
	["your Restock List: what to keep in your bags"] = "votre Liste de réapprovisionnement : quoi garder dans vos sacs",
	["How big it is: Edit Layout's Size, the same value."] = "Sa taille : la Taille de Modifier la disposition, la même valeur.",
	["MelloUI was updated: restart the game once to finish (/reload does not load the new files)."] = "MelloUI a été mis à jour : redémarrez le jeu une fois pour finir (/reload ne charge pas les nouveaux fichiers).",
	["Keybind Mode"] = "Mode raccourcis",
	["Enabled"] = "Activé",
	["Reset this page"] = "Réinitialiser cette page",
	["Every setting on this page back to its default: every tab, and on a page with a picker the one picked (and what every pick shares). Switches of whole modules and what belongs to your character stay as they are. It asks first."] = "Chaque réglage de cette page remis par défaut : chaque onglet, et sur une page avec un sélecteur celui choisi (et ce que partagent tous les choix). Les interrupteurs de modules entiers et ce qui appartient à votre personnage restent tels quels. Une confirmation est demandée.",
	["%s: %s reset to default."] = "%s : %s remis par défaut.",
	["%s: every setting on this page is at its default already."] = "%s : chaque réglage de cette page est déjà par défaut.",
	["Reset every setting on the %s page to its default? It changes %s."] = "Remettre par défaut chaque réglage de la page %s ? Cela change %s.",
	["Reset every setting on the %s page for %s to its default? It changes %s."] = "Remettre par défaut chaque réglage de la page %s pour %s ? Cela change %s.",
	["%s (%d shared with other %ss)"] = "%s (%d partagés avec les autres éléments : %s)",
	["Copy from…"] = "Copier depuis…",
	["Every setting this page keeps per %s, copied from the %s you choose to the one shown. What they share is one setting already. It asks first."] = "Chaque réglage que cette page garde par %s, copié depuis l'élément %s choisi vers celui affiché. Ce qu'ils partagent est déjà un seul réglage. Une confirmation est demandée.",
	["%s: %s copied from %s to %s."] = "%s : %s copié de %s vers %s.",
	["%s is not loaded"] = "%s n'est pas chargé",
	["Tick %s in the game's AddOns list, then reload."] = "Cochez %s dans la liste des add-ons du jeu, puis rechargez.",
	["%s: %s has the settings of %s already."] = "%s : %s a déjà les réglages de %s.",
	["Copy the %s settings to %s? It changes %s."] = "Copier les réglages de %s vers %s ? Cela change %s.",
	["Copy"] = "Copier",
	["Set this for every %s that has it: %s."] = "Régler ceci pour chaque élément (%s) qui l'a : %s.",
	["%s: %s set for every %s."] = "%s : %s réglé pour chaque élément (%s).",
	["One setting for %s%s."] = "Un seul réglage pour %s%s.",
	[" (%s too)"] = " (%s aussi)",
	["Not for %s"] = "Pas pour %s",
	["Switch on \"%s\" first."] = "Requiert « %s ».",
	["Switch on \"%s\" first (%s)."] = "Requiert « %s » (%s).",
	["Pick \"%s\" in \"%s\" first."] = "Choisissez d'abord « %s » dans « %s ».",
	["Pick \"%s\" in \"%s\" first (%s)."] = "Choisissez d'abord « %s » dans « %s » (%s).",
	["Go to \"%s\""] = "Aller à « %s »",
	["On %s"] = "Sur %s",
	["Back to %s"] = "Retour à %s",
	["Click to open its settings."] = "Cliquez pour ouvrir ses réglages.",
	["%s tab"] = "Onglet %s",
	["The %s this page's settings are for. Rows it has no setting for are dimmed."] = "L'élément (%s) auquel s'appliquent les réglages de cette page. Les lignes sans réglage pour lui sont atténuées.",
	["Nothing to set here yet."] = "Rien à régler ici pour l'instant.",
	["Edit Layout is open: size it there."] = "Modifier la disposition est ouvert : dimensionnez-le là.",
	["Parts:"] = "Parties :",
	["Nothing to pick on it: its options are below."] = "Rien à choisir dessus : ses options sont ci-dessous.",
	["Reset part"] = "Réinitialiser la partie",
	["This part's settings back to their defaults, and its place on the frame. Switches of whole modules and what belongs to your character stay as they are. It asks first."] = "Les réglages de cette partie remis par défaut, et sa place sur le cadre. Les interrupteurs de modules entiers et ce qui appartient à votre personnage restent tels quels. Une confirmation est demandée.",
	["Reset %s"] = "Réinitialiser %s",
	["Every setting of %s back to its default%s. Switches of whole modules and what belongs to your character stay as they are. It asks first."] = "Chaque réglage de %s remis par défaut%s. Les interrupteurs de modules entiers et ce qui appartient à votre personnage restent tels quels. Une confirmation est demandée.",
	[": its own and its parts' (not All frames', not the places on the frame)"] = ": les siens et ceux de ses parties (pas ceux de Tous les cadres, ni les places sur le cadre)",
	["Put every setting of %s back to its default? It changes %s."] = "Remettre par défaut chaque réglage de %s ? Cela change %s.",
	["its place on the frame"] = "sa place sur le cadre",
	["%s: %s is at its default already."] = "%s : %s est déjà par défaut.",
	["Every setting %s keeps for itself, copied from the one you choose; what they share is one setting already. It asks first."] = "Chaque réglage que %s garde pour lui, copié depuis celui que vous choisissez ; ce qu'ils partagent est déjà un seul réglage. Une confirmation est demandée.",
	["Not in combat: this would switch painted skins."] = "Pas en combat : cela changerait les habillages peints.",
	["1 setting"] = "1 réglage",
	["%d settings"] = "%d réglages",
	["%s and %s"] = "%s et %s",
	["IMPORTANT"] = "IMPORTANT",
	["also %s"] = "aussi %s",
	["Run"] = "Lancer",
	["%s: %s"] = "%s : %s",
	["The game keeps your settings; /mello status shows where they came from. The voice pack, MelloUI_VoicePack, replaces the old pack: a separate download in two parts from the 0.15.0 release (the Voice pack link above). Unzip both into the AddOns folder, where they make one MelloUI_VoicePack folder."] = "Le jeu garde vos réglages ; /mello status montre d'où ils viennent. Le pack de voix, MelloUI_VoicePack, remplace l'ancien pack : un téléchargement à part en deux parties depuis la version 0.15.0 (le lien Pack de voix ci-dessus). Décompressez les deux dans le dossier AddOns, où ils forment un seul dossier MelloUI_VoicePack.",
	["installed"] = "installé",
	["old pack: the new one is under Help"] = "ancien pack : le nouveau est sous Aide",
	["not installed (the link is under Help)"] = "non installé (le lien est sous Aide)",
	["Fit to this screen"] = "Ajuster à cet écran",
	["Not now"] = "Pas maintenant",
	["Profile '%s' loaded."] = "Profil « %s » chargé.",
	["Load"] = "Charger",
	["Go back to how MelloUI was before the installer ran ('Before install')? Your settings return to what they were then, and Edit Mode's layouts too if the installer changed them."] = "Revenir à MelloUI tel qu'il était avant l'installateur (« Before install ») ? Vos réglages reviennent à ce qu'ils étaient alors, et les dispositions du mode Édition aussi si l'installateur les a changées.",
	["Go back"] = "Revenir",
	["None loaded"] = "Aucun chargé",
	["Look for this tag on the side list, the tabs and the options: it marks everything this update added."] = "Cherchez cette étiquette dans la liste latérale, les onglets et les options : elle marque tout ce que cette mise à jour a ajouté.",
	["Version %s"] = "Version %s",
	["Help"] = "Aide",
	["Slash commands"] = "Commandes slash",
	["Links (select the text and copy it)"] = "Liens (sélectionnez le texte et copiez-le)",
	["Loading…"] = "Chargement…",
	["What's new"] = "Nouveautés",
	["Earlier versions"] = "Versions précédentes",
	["Profile"] = "Profil",
	["Screen"] = "Écran",
	["Installer"] = "Installateur",
	["Your setup"] = "Votre configuration",
	["Change…"] = "Changer…",
	["Install again"] = "Réinstaller",
	["Revert…"] = "Revenir…",
	["Palette: %s"] = "Palette : %s",
	["%s, %d of %d modules on"] = "%s, %d modules actifs sur %d",
	["Tutorial"] = "Tutoriel",
	["Revert"] = "Revenir",
	["Delete"] = "Supprimer",
	["share string of '%s' (%d characters)"] = "chaîne de partage de « %s » (%d caractères)",
	["Could not share '%s': %s."] = "Impossible de partager « %s » : %s.",
	["Share"] = "Partager",
	["Active: %s      Default on a fresh install: %s"] = "Actif : %s      Par défaut à une nouvelle installation : %s",
	["Set default"] = "Définir par défaut",
	["built in"] = "intégré",
	["A profile is a copy of every setting of every module. It leaves out your Dark Mode and what belongs to your characters: the flight points they know, game settings MelloUI borrowed, and steps done once; loading a profile never touches those. The one marked default is applied when MelloUI starts with no settings at all, such as on a fresh install. Load asks before it replaces your settings. Profiles you save here are kept with your settings; Share gives a string to pass one on, and Import as brings one in. The profiles that come with MelloUI are always here."] = "Un profil est une copie de chaque réglage de chaque module. Il laisse de côté votre mode sombre et ce qui appartient à vos personnages : les points de vol qu'ils connaissent, les réglages du jeu empruntés par MelloUI, et les étapes faites une fois ; charger un profil n'y touche jamais. Celui marqué par défaut s'applique quand MelloUI démarre sans aucun réglage, comme à une nouvelle installation. Charger demande avant de remplacer vos réglages. Les profils enregistrés ici sont gardés avec vos réglages ; Partager donne une chaîne pour en transmettre un, et Importer sous en fait entrer un. Les profils fournis avec MelloUI sont toujours là.",
	["Save current as"] = "Enregistrer l'actuel sous",
	["Profile '%s' saved."] = "Profil « %s » enregistré.",
	["Import as"] = "Importer sous",
	["Type a name for the imported profile first, then click Import as."] = "Tapez d'abord un nom pour le profil importé, puis cliquez Importer sous.",
	["paste a MelloUI profile string for '%s'"] = "collez une chaîne de profil MelloUI pour « %s »",
	["Not imported: %s."] = "Non importé : %s.",
	["Profile '%s' imported (%d settings). Load it from the list to use it."] = "Profil « %s » importé (%d réglages). Chargez-le depuis la liste pour l'utiliser.",
	["No profiles yet. Type a name above and save the current settings."] = "Aucun profil pour l'instant. Tapez un nom ci-dessus et enregistrez les réglages actuels.",
	["Search options"] = "Rechercher des options",
	["Nothing found. Try another word."] = "Rien trouvé. Essayez un autre mot.",
	["%d more. Type more letters to narrow it down."] = "%d de plus. Tapez plus de lettres pour affiner.",
	["Top bar"] = "Barre du haut",
	["unlock windows snap snapping auto position positions reset"] = "déverrouiller fenêtres aimanter aimantation position auto positions réinitialiser",
	["preview simulate simulation test demo try fight combat behave behaviour"] = "aperçu simuler simulation test démo essayer combat comportement",
	["Move and size MelloUI's windows and bars on the screen itself. Closes the configurator while you edit."] = "Déplacez et dimensionnez les fenêtres et barres de MelloUI à même l'écran. Ferme le configurateur pendant la modification.",
	["See how your interface behaves in a fight, with made-up numbers: resting, the fight, after it. A fight alone or in a group, or one part at a time (the fades, the reminders, the widget column, party frames, the meter, Combat Text, Gains). Out of combat only; Stop ends it."] = "Voyez comment votre interface se comporte en combat, avec des chiffres inventés : au repos, le combat, après. Un combat seul ou en groupe, ou une partie à la fois (les fondus, les rappels, la colonne de widgets, les cadres de groupe, le compteur, le Texte de combat, les Gains). Hors combat seulement ; Arrêter le termine.",
	["Install…"] = "Installer…",
	["The installer: a setup for the whole interface in a few steps, fitted to this screen. Closes the configurator while it runs."] = "L'installateur : une configuration de toute l'interface en quelques étapes, ajustée à cet écran. Ferme le configurateur pendant son exécution.",
	-- Core/Installer.lua
	["MelloUI setup"] = "Installation de MelloUI",
	["Mello's layout and the window places fitted to this screen. Your other settings stay."] = "La disposition de Mello et les places des fenêtres ajustées à cet écran. Vos autres réglages restent.",
	["MelloUI's settings are still loading; try again in a moment."] = "Les réglages de MelloUI se chargent encore ; réessayez dans un instant.",
	["Install waits until you are out of combat."] = "L'installation attend que vous soyez hors combat.",
	["Close Edit Mode first."] = "Fermez d'abord le mode Édition.",
	["Your screen is still being fitted."] = "Votre écran est encore en cours d'ajustement.",
	["Your screen changed; it is being fitted again."] = "Votre écran a changé ; il est de nouveau ajusté.",
	["Edit Mode already keeps %d account layouts, the most it can. Delete one in Edit Mode, or keep your own layout."] = "Le mode Édition garde déjà %d dispositions de compte, le maximum. Supprimez-en une en mode Édition, ou gardez votre propre disposition.",
	["Keep or revert the setup you just installed first."] = "Gardez ou annulez d'abord la configuration que vous venez d'installer.",
	["There is no setup to go back to."] = "Il n'y a pas de configuration à laquelle revenir.",
	["Paused while you are in combat."] = "En pause pendant le combat.",
	["Revert waits until you are out of combat; try again then."] = "Revenir attend que vous soyez hors combat ; réessayez alors.",
	["Paused while Edit Mode is open."] = "En pause tant que le mode Édition est ouvert.",
	["%s installed. Keep it, or MelloUI goes back to 'Before install' when the timer runs out."] = "%s installé. Gardez-le, ou MelloUI revient à « Before install » à la fin du minuteur.",
	["Your layout was fitted to this screen. Keep it, or MelloUI goes back to 'Before install' when the timer runs out."] = "Votre disposition a été ajustée à cet écran. Gardez-la, ou MelloUI revient à « Before install » à la fin du minuteur.",
	["MelloUI's Edit Mode layout did not go in (%s). Your own layout stays; /mello layout check shows why."] = "La disposition du mode Édition de MelloUI n'a pas été appliquée (%s). Votre disposition reste ; /mello layout check indique pourquoi.",
	["the screen was not fitted"] = "l'écran n'a pas été ajusté",
	["Back to 'Before install'."] = "Retour à « Before install ».",
	["Something went wrong while installing, so MelloUI went back to 'Before install'."] = "Un problème est survenu pendant l'installation, MelloUI est donc revenu à « Before install ».",
	["Something went wrong while installing. Use Revert to go back to 'Before install'."] = "Un problème est survenu pendant l'installation. Utilisez Revenir pour retourner à « Before install ».",
	["Something went wrong while preparing the setup. Nothing was changed."] = "Un problème est survenu pendant la préparation de la configuration. Rien n'a été changé.",
	["MelloUI could not go all the way back to 'Before install'. Type /reload to try again."] = "MelloUI n'a pas pu revenir entièrement à « Before install ». Tapez /reload pour réessayer.",
	["This setup did not install fully, so it cannot be kept. Revert goes back to 'Before install'."] = "Cette configuration ne s'est pas installée entièrement, elle ne peut donc pas être gardée. Revenir retourne à « Before install ».",
	["MelloUI was only partly put back, so this setup cannot be kept. Revert tries again to go back to 'Before install'."] = "MelloUI n'a été remis qu'en partie, cette configuration ne peut donc pas être gardée. Revenir tente de nouveau de retourner à « Before install ».",
	["%s: %.1f ms in one frame."] = "%s : %.1f ms en une image.",
	["The installer opens when combat ends."] = "L'installateur s'ouvre à la fin du combat.",
	["Close Edit Mode first, then open the installer again."] = "Fermez d'abord le mode Édition, puis rouvrez l'installateur.",
	["Version %s. /mello shows what's new; Install... there sets MelloUI up again."] = "Version %s. /mello montre les nouveautés ; Installer... y configure de nouveau MelloUI.",
	["Use MelloUI's Edit Mode layout on this character too?\n\nYour own layouts stay in Edit Mode's list. Later: /mello layout apply."] = "Utiliser aussi la disposition du mode Édition de MelloUI sur ce personnage ?\n\nVos propres dispositions restent dans la liste du mode Édition. Plus tard : /mello layout apply.",
	["Use it"] = "L'utiliser",
	["MelloUI's Edit Mode layout is not active on this character: pick it in Edit Mode's layout list, or log in without the Gamepad UI to be asked."] = "La disposition du mode Édition de MelloUI n'est pas active sur ce personnage : choisissez-la dans la liste des dispositions du mode Édition, ou connectez-vous sans l'interface manette pour qu'on vous le demande.",
	-- Core/InstallerWindow.lua
	["Screen: %s"] = "Écran : %s",
	["Detected screen: %s"] = "Écran détecté : %s",
	["Fitting to your screen..."] = "Ajustement à votre écran...",
	["Mello's layout could not be fitted on this client; your own Edit Mode layout stays."] = "La disposition de Mello n'a pas pu être ajustée sur ce client ; votre propre disposition du mode Édition reste.",
	["Aspect ratio"] = "Format d'image",
	["Mello's layout, as made"] = "La disposition de Mello, telle quelle",
	["Mello's layout, fitted to your screen"] = "La disposition de Mello, ajustée à votre écran",
	["Being fitted to your screen"] = "En cours d'ajustement à votre écran",
	["Your own Edit Mode layout stays"] = "Votre disposition reste",
	["UI scale: yours stays as it is"] = "Échelle de l'interface : inchangée",
	["MelloUI never changes it"] = "MelloUI ne la change jamais",
	["Add the '%s' Edit Mode layout (your own layouts stay)"] = "Ajouter la disposition « %s » (les vôtres restent)",
	["Mello's layout, fitted to this screen, as an account layout of its own, made active. Your own layouts stay in the list, and Revert puts the one you use now back."] = "La disposition de Mello, ajustée à cet écran, comme disposition de compte à part, rendue active. Vos propres dispositions restent dans la liste, et Revenir remet celle que vous utilisez maintenant.",
	["Pieces at an edge keep their distance to it; the centre group tightens to fit; then everything is checked for overlaps."] = "Les éléments près d'un bord gardent leur distance à celui-ci ; le groupe du centre se resserre pour tenir ; puis tout est vérifié pour les chevauchements.",
	["Worth a look in the game once it is in:"] = "À regarder dans le jeu une fois en place :",
	["... and %d more"] = "... et %d de plus",
	["Your own Edit Mode layout suits this screen better."] = "Votre propre disposition du mode Édition convient mieux à cet écran.",
	["Install Without The Layout"] = "Installer sans la disposition",
	["Delete '%s'"] = "Supprimer « %s »",
	["Delete the Edit Mode layout '%s'?\n\nIt is an older MelloUI layout, made for another screen. Your own layouts stay, and Edit Mode then has room for this screen's."] = "Supprimer la disposition du mode Édition « %s » ?\n\nC'est une ancienne disposition MelloUI, faite pour un autre écran. Vos propres dispositions restent, et le mode Édition a alors de la place pour celle de cet écran.",
	["Delete it"] = "La supprimer",
	["The Edit Mode layout '%s' was not deleted: %s."] = "La disposition du mode Édition « %s » n'a pas été supprimée : %s.",
	["%s: this is what changes."] = "%s : voici ce qui change.",
	["Edit Mode layout '%s', fitted to %s"] = "Disposition du mode Édition « %s », ajustée à %s",
	["The Edit Mode layout, once your screen is fitted"] = "La disposition du mode Édition, une fois votre écran ajusté",
	["No Edit Mode change: your own layout stays"] = "Aucun changement du mode Édition : votre propre disposition reste",
	["Your UI scale stays as it is"] = "Votre échelle d'interface reste telle quelle",
	["Your current setup is saved as the profile 'Before install' first, so you can go back to it later from the Profiles page. After Install you have 15 seconds to keep the new setup; Keep then reloads the UI."] = "Votre configuration actuelle est d'abord enregistrée comme profil 'Before install', pour y revenir plus tard depuis la page Profils. Après Installer, vous avez 15 secondes pour garder la nouvelle configuration ; Garder recharge alors l'interface.",
	["Keep this setup?"] = "Garder cette configuration ?",
	["If you don't answer, MelloUI goes back to 'Before install' when the timer runs out."] = "Sans réponse, MelloUI revient à « Before install » à la fin du minuteur.",
	["Keep reloads the UI, so everything takes the new setup."] = "Garder recharge l'interface, pour que tout prenne la nouvelle configuration.",
	["Type /reload so everything takes the new setup."] = "Tapez /reload pour que tout prenne la nouvelle configuration.",
	["Type /reload to finish: the names above characters still use the installed font."] = "Tapez /reload pour finir : les noms au-dessus des personnages utilisent encore la police installée.",
	["Back as before"] = "Comme avant",
	["Install... in /mello (or /mello install) sets MelloUI up any time."] = "Installer... dans /mello (ou /mello install) configure MelloUI à tout moment.",
	["Continue keeps Mello's own choice for this step."] = "Continuer garde le choix de Mello pour cette étape.",
	["Continue"] = "Continuer",
	["Back"] = "Retour",
	["Install"] = "Installer",
	["Keep"] = "Garder",
	["Choose again"] = "Choisir de nouveau",
	["Close"] = "Fermer",
	["How everything looks: the game's frames and MelloUI's own windows and features alike. Every step after this one shows its pictures in this skin."] = "L'aspect de tout : les fenêtres du jeu comme celles et les fonctions de MelloUI. Chaque étape suivante montre ses images dans cet habillage.",
	["Recommended"] = "Recommandé",
	["Not installed"] = "Non installé",
	["Switched off"] = "Désactivé",
	["MelloUI Oldschool is an addon of its own. Get it from CurseForge, then restart the game: this card turns on."] = "MelloUI Oldschool est un add-on à part. Téléchargez-le sur CurseForge, puis redémarrez le jeu : cette carte s'activera.",
	["MelloUI Oldschool is installed but switched off: switch it on in the game's AddOn list, then type /reload."] = "MelloUI Oldschool est installé mais désactivé : activez-le dans la liste des add-ons du jeu, puis tapez /reload.",
	["The game can't open web pages: the link is selected in the box, Ctrl+C copies it."] = "Le jeu ne peut pas ouvrir de pages web : le lien est sélectionné dans la case, Ctrl+C le copie.",
	["Where everything stands on your %s screen."] = "Où tout se place sur votre écran %s.",
	["Your own Edit Mode layout stays as it is."] = "Votre propre disposition du mode Édition reste telle quelle.",
	["Keep My Layout"] = "Garder ma disposition",
	["Pick what you want. Each one comes with Mello's settings for it; change them any time in /mello."] = "Choisissez ce que vous voulez. Chacun vient avec les réglages de Mello ; changez-les quand vous voulez dans /mello.",
	["Skin: %s"] = "Habillage : %s",
	["Colours: the game's own"] = "Couleurs : celles du jeu",
	["Default"] = "Par défaut",
	["The game's own look for everything, MelloUI's windows and features too."] = "L'apparence du jeu pour tout, fenêtres et fonctions de MelloUI comprises.",
	["Modern"] = "Moderne",
	["MelloUI's own look for everything: slate panels, gold trim, one clean font."] = "L'apparence de MelloUI pour tout : panneaux d'ardoise, liserés dorés, une police nette.",
	["The painted RPG look for everything: parchment, iron and stone."] = "L’apparence inspirée des jeux de rôle, avec parchemin, fer et pierre.",
	["Mello's Layout"] = "La disposition de Mello",
	["Bars, frames, chat and the map column fitted to your screen; your own layouts stay in Edit Mode's list."] = "Barres, cadres, discussion et colonne de carte ajustés à votre écran ; vos propres dispositions restent dans la liste du mode Édition.",
	["Your Edit Mode layout stays exactly as it is; MelloUI only dresses it."] = "Votre disposition du mode Édition reste exactement telle quelle ; MelloUI ne fait que l'habiller.",
	["MelloUI's own party and raid frames, the heal and cooldown effects across them."] = "Les cadres de groupe et de raid de MelloUI, avec les effets de soin et de temps de recharge.",
	["Portraits"] = "Portraits",
	["The game's party frames with their portraits, in your skin."] = "Les cadres de groupe du jeu avec leurs portraits, dans votre habillage.",
	["Your own frame on top of the group."] = "Votre propre cadre en haut du groupe.",
	["Portraits on the right: for a party on the right side of the screen."] = "Portraits à droite : pour un groupe à droite de l'écran.",
	["Your friends' class medallions over their heads, to find them in a crowd."] = "Les médaillons de classe de vos amis au-dessus de leurs têtes, pour les trouver dans la foule.",
	["Your quests by zone, in your skin."] = "Vos quêtes par zone, dans votre habillage.",
	["Every quest near you, on the map and in a list."] = "Chaque quête près de vous, sur la carte et dans une liste.",
	["The way to your next quest, over the real ground."] = "Le chemin vers votre prochaine quête, sur le vrai terrain.",
	["One seamless world map with your quests."] = "Une carte du monde sans couture avec vos quêtes.",
	["Quest givers speak their text."] = "Les donneurs de quêtes disent leur texte.",
	["Repair, innkeeper, flight master: one click routes there."] = "Réparations, aubergiste, maître de vol : un clic y trace l'itinéraire.",
	["Every dungeon and raid on the map: its bosses, their loot, your wish list."] = "Chaque donjon et raid sur la carte : ses boss, leur butin, votre liste de souhaits.",
	["Enemy plates: names, debuffs, crowd control, threat."] = "Barres d'info ennemies : noms, affaiblissements, contrôle, menace.",
	["Your hits and heals, easy to read."] = "Vos coups et soins, faciles à lire.",
	["Damage and healing, for you and your group."] = "Dégâts et soins, pour vous et votre groupe.",
	["Heal And Cooldown Effects"] = "Effets de soin et de temps de recharge",
	["Heals fly to the frame and land on it; cooldowns show on it."] = "Les soins volent jusqu'au cadre et s'y posent ; les temps de recharge s'y affichent.",
	["Your health, power and cooldowns under your character."] = "Votre vie, ressource et temps de recharge sous votre personnage.",
	["Channel tabs, readable lines, a whisper window."] = "Onglets de canal, lignes lisibles, une fenêtre de chuchotement.",
	["The Plain Chat"] = "La discussion simple",
	["The chat windows as the game has them."] = "Les fenêtres de discussion telles que le jeu les a.",
	["Map Column"] = "Colonne de carte",
	["The minimap as wide as the tracker, its buttons in groups."] = "La minicarte aussi large que le suivi, ses boutons en groupes.",
	["A buff or food running out: a quiet card."] = "Une amélioration ou nourriture qui expire : une carte discrète.",
	["Small cards: your quest's step, a timer, a count."] = "De petites cartes : l'étape de votre quête, un minuteur, un compteur.",
	["Bags By Kind"] = "Sacs par type",
	["One window, sorted by kind, with search."] = "Une fenêtre, triée par type, avec recherche.",
	["Separate Bags"] = "Sacs séparés",
	["One window a bag, as the game has them."] = "Une fenêtre par sac, comme le jeu les a.",
	["Short lines beside you: what you loot, receive and buy."] = "De courtes lignes près de vous : ce que vous ramassez, recevez et achetez.",
	["Drink, food, ammunition and reagents: a list to buy at the shop, bought on a click."] = "Boisson, nourriture, munitions et composants : une liste à acheter chez le marchand, achetée d'un clic.",
	["A button that sells or throws away your cheapest junk to free a slot."] = "Un bouton qui vend ou jette votre camelote la moins chère pour libérer un emplacement.",
	["MelloUI Sounds"] = "Sons de MelloUI",
	["The sounds of your skin: soft clicks, a chime for a waypoint, a quest done."] = "Les sons de votre habillage : des clics doux, un carillon pour un point de passage, une quête terminée.",
	["The Game's Sounds"] = "Les sons du jeu",
	["The game's own interface sounds. The Default skin always uses them."] = "Les sons d'interface du jeu. L'habillage Par défaut les utilise toujours.",
	["Which frames show your group, in your skin. Both can be clicked to heal."] = "Quels cadres montrent votre groupe, dans votre habillage. Les deux se cliquent pour soigner.",
	["Your chat window, in your skin."] = "Votre fenêtre de discussion, dans votre habillage.",
	["Your bags, in your skin."] = "Vos sacs, dans votre habillage.",
	["The interface's sounds."] = "Les sons de l'interface.",
	["Window places fitted to this screen"] = "Position des fenêtres adaptée à cet écran",
	["Your other settings stay as they are"] = "Vos autres réglages restent tels quels",
	["Welcome to MelloUI"] = "Bienvenue dans MelloUI",
	["Party and raid"] = "Groupe et raid",
	["Combat"] = "Combat",
	["Minimap and widgets"] = "Minicarte et widgets",
	["Fit to your screen"] = "Ajuster à votre écran",
	["Your screen"] = "Votre écran",
	["Review and install"] = "Vérifier et installer",
	["Review"] = "Vérifier",
