	["How MelloUI looks. Modern: MelloUI's own art. Default: the game's own borders, buttons and fonts in the same places. Only the look changes; nothing moves."] = "L'apparence de MelloUI. Moderne : les graphismes de MelloUI. Par défaut : les bordures, boutons et polices du jeu aux mêmes endroits. Seule l'apparence change ; rien ne bouge.",
	["Whisper Popup"] = "Fenêtre de chuchotement",
