-- stale: ["A backdrop round the experience bar (the reputation bar in its place at the top level), merged into one with the other switched-on elements placed next to it (this bar then takes their width, within a limit). Off: no backdrop, and it joins none."] = "Un fond autour de la barre d'expérience (la barre de réputation à sa place au niveau maximum), fusionné en un seul avec les autres éléments activés placés à côté (cette barre prend alors leur largeur, dans une limite). Désactivé : pas de fond, et elle n'en rejoint aucun.", -- draft
