-- stale: ["A backdrop round the pet bar, merged into one with the other switched-on elements placed next to it. Off: no backdrop, and it joins none."] = "Un fond autour de la barre du familier, fusionné en un seul avec les autres éléments activés placés à côté. Désactivé : pas de fond, et elle n'en rejoint aucun.", -- draft
-- stale: ["A backdrop round the player, target and focus frames: stone behind the portrait, the name and the bars, framed by the red or iron gems of the action bars' backdrops or by one of the border styles of Look > Borders (its inner corners mitred)."] = "Un fond autour des cadres du joueur, de la cible et de la focalisation : de la pierre derrière le portrait, le nom et les barres, encadrée par les gemmes rouges ou de fer des fonds des barres d'actions ou par l'un des styles de bordure d'Apparence > Bordures (ses coins intérieurs biseautés).", -- draft
-- stale: ["A backdrop round the possess bar, merged into one with the other switched-on elements placed next to it. Off: no backdrop, and it joins none."] = "Un fond autour de la barre de possession, fusionné en un seul avec les autres éléments activés placés à côté. Désactivé : pas de fond, et elle n'en rejoint aucun.", -- draft
-- stale: ["A backdrop round the second status bar (a watched reputation while you level), merged into one with the other switched-on elements placed next to it (this bar then takes their width, within a limit). Off: no backdrop, and it joins none."] = "Un fond autour de la deuxième barre d'état (une réputation suivie pendant la montée de niveau), fusionné en un seul avec les autres éléments activés placés à côté (cette barre prend alors leur largeur, dans une limite). Désactivé : pas de fond, et elle n'en rejoint aucun.", -- draft
-- stale: ["A backdrop round the stance bar, merged into one with the other switched-on elements placed next to it. Off: no backdrop, and it joins none."] = "Un fond autour de la barre de posture, fusionné en un seul avec les autres éléments activés placés à côté. Désactivé : pas de fond, et elle n'en rejoint aucun.", -- draft
-- stale: ["A backdrop round the totem bar, merged into one with the other switched-on elements placed next to it. Off: no backdrop, and it joins none."] = "Un fond autour de la barre de totems, fusionné en un seul avec les autres éléments activés placés à côté. Désactivé : pas de fond, et elle n'en rejoint aucun.", -- draft
-- stale: ["A batch you craft: which one of how many, a ring for each item, and Stop on hover."] = "Une série que vous fabriquez : lequel sur combien, un anneau par objet, et Arrêter au survol.", -- draft
-- stale: ["A button on the bag window that frees a slot: it throws away the grey or white junk item worth least (at a vendor it sells it). Never food, drink, potions, scrolls, conjured items, crafting materials, quest items, reagents, ammunition, keys, white gear or anything on your Restock list. A white item asks first."] = "Un bouton sur la fenêtre de sac qui libère un emplacement : il jette l'objet de camelote gris ou blanc qui vaut le moins (chez un vendeur, il le vend). Jamais nourriture, boisson, potions, parchemins, objets invoqués, matériaux d'artisanat, objets de quête, composants, munitions, clés, équipement blanc ni rien de votre liste Réapprovisionner. Un objet blanc demande d'abord.", -- draft
-- stale: ["A class medallion above every party member's friendly nameplate, with a ring in their role's colour. In the open world; inside instances the game keeps friendly nameplates to itself."] = "Un médaillon de classe au-dessus de la barre d'info amicale de chaque membre du groupe, avec un anneau à la couleur de son rôle. En monde ouvert ; dans les instances, le jeu garde les barres d'info amicales pour lui.", -- draft
-- stale: ["A coloured ring around the medallion for the member's assigned role: green healer, blue tank, red damage. Only when the group has roles set (the group finder sets them; a party can set them by hand)."] = "Un anneau coloré autour du médaillon pour le rôle attribué au membre : vert soigneur, bleu tank, rouge dégâts. Seulement quand le groupe a des rôles définis (la recherche de groupe les définit ; un groupe peut les définir à la main).", -- draft
-- stale: ["A cooldown's icon lights up while you press the action button with its spell, as the button does (Action Buttons)."] = "L'icône d'un temps de recharge s'allume quand vous pressez le bouton d'action avec son sort, comme le bouton (Boutons d'action).", -- draft
-- stale: ["A count going up rolls over to its new number as a soft light runs along its line; a finished objective gets a tick drawn in its dash's place; a finished quest's last count rolls first, then a light runs over its title, its mark turns over to the hand-in ? and its turn-in line comes in. Off: the lines change at once, with their dashes. Not with Reduce Motion."] = "Un compteur qui monte passe à son nouveau chiffre pendant qu'une lumière douce parcourt sa ligne ; un objectif terminé reçoit une coche à la place de son tiret ; le dernier compteur d'une quête terminée défile d'abord, puis une lumière passe sur son titre, sa marque se retourne en ? de rendu et sa ligne de rendu arrive. Désactivé : les lignes changent aussitôt, avec leurs tirets. Pas avec Réduire les animations.", -- draft
-- stale: ["A critical or crushing blow on you flashes the bars' rim red and dips them a hair, once."] = "Un coup critique ou écrasant sur vous fait flasher en rouge le bord des barres et les abaisse d'un cheveu, une fois.", -- draft
-- stale: ["A font style is a preset: it changes every font at once. Each card shows its title face and its reading face."] = "Un style de police est un préréglage : il change toutes les polices d'un coup. Chaque carte montre sa police de titre et sa police de lecture.", -- draft
-- stale: ["A fresh Mello layout for wide screens, fitted to every other (on 32:9 in the corners); Keep My Layout keeps your places; profiles keep every bar's place and offer Fit to this screen."] = "Une nouvelle disposition Mello pour les écrans larges, ajustée à tous les autres (en 32:9 dans les coins) ; Garder ma disposition garde vos emplacements ; les profils gardent la place de chaque barre et proposent Ajuster à cet écran.", -- draft
-- stale: ["A fresh Mello layout for wide screens, fitted to every other; Keep My Layout keeps your own places; profiles offer Fit to this screen."] = "Une nouvelle disposition Mello pour écrans larges, adaptée à tous les autres ; Garder ma disposition garde vos emplacements ; les profils proposent Adapter à cet écran.", -- draft
-- stale: ["A group's list slides out from the minimap column like a drawer when you click its button, its rows one after another, and slides back in as it closes. Not with Reduce Motion: then it shows at once."] = "La liste d'un groupe glisse hors de la colonne de la minicarte comme un tiroir quand vous cliquez son bouton, ses lignes l'une après l'autre, et se rentre en se fermant. Pas avec Réduire les animations : elle apparaît alors aussitôt.", -- draft
-- stale: ["A heal bursts, a heal over time seals onto the portrait, a shield closes round the frame, a resurrection unfolds wings, a group heal runs through the group."] = "Un soin éclate, un soin sur la durée se scelle sur le portrait, un bouclier se referme autour du cadre, une résurrection déploie des ailes, un soin de groupe traverse le groupe.", -- draft
-- stale: ["A heal lights the health it gives at once; the bar then grows into it."] = "Un soin allume aussitôt la vie qu'il rend ; la barre grandit ensuite jusqu'à elle.", -- draft
-- stale: ["A line for each item that comes into your bags: loot, quest rewards, crafted items, mail and trades. Moving items between your bags, the bank and your gear never counts."] = "Une ligne pour chaque objet qui entre dans vos sacs : butin, récompenses de quête, objets fabriqués, courrier et échanges. Déplacer des objets entre vos sacs, la banque et votre équipement ne compte jamais.", -- draft
-- stale: ["A line for the other currencies you gain (honor, tokens, marks), with the currency's own icon."] = "Une ligne pour les autres monnaies que vous gagnez (honneur, insignes, marques), avec l'icône de la monnaie.", -- draft
-- stale: ["A line for what you buy from a merchant, buybacks too, marked as bought."] = "Une ligne pour ce que vous achetez à un marchand, rachats compris, marqué comme acheté.", -- draft
-- stale: ["A line not translated yet shows in English. Corrections are welcome on MelloUI's CurseForge translation page."] = "Une ligne pas encore traduite s'affiche en anglais. Les corrections sont les bienvenues sur la page de traduction CurseForge de MelloUI.", -- draft
-- stale: ["A line when one of your skills goes up: weapon skills, Defense, professions, secondary skills and languages."] = "Une ligne quand l'une de vos compétences monte : compétences d'arme, Défense, métiers, compétences secondaires et langues.", -- draft
-- stale: ["A line when your money goes up: loot, quest rewards, sales, mail and trades, with the game's coins. Several gains in a row add up on one line. Spending makes no line."] = "Une ligne quand votre argent augmente : butin, récompenses de quête, ventes, courrier et échanges, avec les pièces du jeu. Plusieurs gains d'affilée s'additionnent sur une ligne. Dépenser ne fait aucune ligne.", -- draft
-- stale: ["A muted knock for the game's red error messages (\"You can't do that yet\"), at most one every half second; none for a message Error Messages hides."] = "Un coup sourd pour les messages d'erreur rouges du jeu (« Vous ne pouvez pas encore faire cela »), au plus un par demi-seconde ; aucun pour un message que Messages d'erreur masque.", -- draft
-- stale: ["A new icon set, sharp at every size, map pins glowing and marks shaded; MelloUI Frames on buttons, XP bars and unit frames; Heal Flight and Frame Effects in soft light."] = "Un nouveau jeu d'icônes, net à toutes les tailles, épingles de carte lumineuses et marques ombrées ; Cadres MelloUI sur les boutons, barres d'XP et portraits d'unités ; Effets de soin et Effets de cadre en lumière douce.", -- draft
-- stale: ["A new installer: skin first, then each part; one setup for every skin, fitted to your screen, reloaded on Keep; moved frames keep their screen edges. Preview: Solo, Party, Raid Fight."] = "Un nouvel installateur : l'habillage d'abord, puis chaque partie ; une configuration pour chaque habillage, ajustée à votre écran, rechargée en la gardant ; les cadres déplacés gardent leurs bords d'écran. Aperçu : solo, groupe, raid.", -- draft
-- stale: ["A new installer: your skin first, then each part of the UI step by step, with a picture of every choice."] = "Un nouvel installateur : votre habillage d'abord, puis chaque partie de l'interface pas à pas, avec une image de chaque choix.", -- draft
-- stale: ["A new installer: your skin first, then each part; one setup for every skin, fitted to your screen's shape, reloaded when you keep it. Preview: Solo, Party and Raid Fight."] = "Un nouvel installateur : d'abord votre habillage, puis chaque partie ; une configuration pour chaque habillage, ajustée à la forme de votre écran, rechargée quand vous la gardez. Aperçu : combat en solo, en groupe et en raid.", -- draft
-- stale: ["A new installer: your skin first, then each part; one setup for every skin, reloaded when you keep it. Preview: Solo, Party and Raid Fight."] = "Un nouvel installateur : d'abord votre habillage, puis chaque partie ; une configuration pour chaque habillage, rechargée quand vous la gardez. Aperçu : combat en solo, en groupe et en raid.", -- draft
-- stale: ["A new route grows from you to the destination in about a second instead of appearing whole, on the world map and the minimap at once: the beads pop in one after another, the line and the dashes are drawn with a small light at their head, and the destination's flag pops in as the trail reaches it. A re-plan of the same route (you strayed off it) swaps at once. Not with Reduce Motion."] = "Un nouvel itinéraire pousse de vous jusqu'à la destination en une seconde environ au lieu d'apparaître d'un coup, sur la carte du monde et la minicarte à la fois : les perles apparaissent l'une après l'autre, la ligne et les tirets se dessinent avec une petite lumière en tête, et le drapeau de la destination apparaît quand la traînée l'atteint. Un recalcul du même itinéraire (vous vous en êtes écarté) change aussitôt. Pas avec Réduire les animations.", -- draft
-- stale: ["A new whisper: the sender in their class colour, the last line and how many are unread. Reply opens their whisper window. Needs Chat's Whisper Popup Window."] = "Un nouveau chuchotement : l'expéditeur dans sa couleur de classe, la dernière ligne et combien sont non lus. Répondre ouvre sa fenêtre de chuchotement. Nécessite la Fenêtre de chuchotement de la discussion.", -- draft
-- stale: ["A note under the door for a whisper, two knocks for a group invite."] = "Un mot glissé sous la porte pour un chuchotement, deux coups pour une invitation de groupe.", -- draft
-- stale: ["A page in the world map's quest log listing the quests of a zone, how many you have completed, and where each one is picked up."] = "Une page dans le journal des quêtes de la carte du monde listant les quêtes d'une zone, combien vous en avez terminé, et où chacune se prend.", -- draft
-- stale: ["A page lifting when a spell, macro or ability is dragged, the slot latching when it is placed."] = "Une page qui se soulève quand un sort, une macro ou une technique est glissé, l'emplacement qui s'enclenche quand il est posé.", -- draft
-- stale: ["A page turn when the character sheet, spell book, quest log or main menu opens, a latch when they close; the spell book's page turns; a quest giver's list and Decline; the bags as a leather pouch opening and closing."] = "Une page qui tourne à l'ouverture de la fiche de personnage, du grimoire, du journal des quêtes ou du menu principal, un loquet à leur fermeture ; les pages du grimoire ; la liste d'un donneur de quête et Refuser ; les sacs comme une bourse de cuir qui s'ouvre et se ferme.", -- draft
-- stale: ["A pin into parchment for a minimap ping."] = "Une épingle dans le parchemin pour un signal sur la minicarte.", -- draft
-- stale: ["A preset: choosing a style changes every font at once -- the titles, the interface text, the chat and numbers, the chat text and the chat on parchment, the sizes back to 100% (each face brings its own size correction) -- each pairing themed with readability first. Fine-tune any of them afterwards (the style then shows Custom). The damage numbers keep their own choice, but for Fredoka's: one face for everything.\nFredoka: MelloUI's own face: Fredoka's round letters for the titles, the text and the damage numbers, to fit MelloUI's icons. The default.\nScriptorium: Cinzel's carved capitals over Alegreya, a warm book face.\nChronicle: Alegreya SC's small capitals over Source Serif 4, the most readable serif.\nOld Tome: IM Fell English's aged print over Spectral.\nWarband: Pirata One's blackletter over Crimson Pro SemiBold: the boldest look.\nClarity: Cinzel titles, Noto Sans everywhere else: the easiest to read at small sizes.\nGothic: Enchanted Land's gothic titles kept, over Alegreya."] = "Un préréglage : choisir un style change toutes les polices d'un coup -- les titres, le texte de l'interface, la discussion et les chiffres, le texte de discussion et la discussion sur parchemin, les tailles remises à 100% (chaque police apporte sa propre correction de taille) -- chaque association pensée d'abord pour la lisibilité. Ajustez-les ensuite (le style affiche alors Personnalisé). Les chiffres de dégâts gardent leur propre choix, sauf pour Fredoka : une seule police pour tout.\nFredoka : la police de MelloUI : les lettres rondes de Fredoka pour les titres, le texte et les chiffres de dégâts, en accord avec les icônes de MelloUI. Par défaut.\nScriptorium : les capitales gravées de Cinzel sur Alegreya, une chaude police de livre.\nChronicle : les petites capitales d'Alegreya SC sur Source Serif 4, l'empattement le plus lisible.\nOld Tome : l'impression vieillie d'IM Fell English sur Spectral.\nWarband : la gothique de Pirata One sur Crimson Pro SemiBold : l'aspect le plus marqué.\nClarity : titres en Cinzel, Noto Sans partout ailleurs : le plus facile à lire en petite taille.\nGothic : les titres gothiques d'Enchanted Land conservés, sur Alegreya.", -- draft
-- stale: ["A preview of the bar's layout. Changes show after a /reload."] = "Un aperçu de la disposition de la barre. Les changements s'affichent après un /reload.", -- draft
-- stale: ["A profession cooldown ready again (a transmute, mooncloth, the salt shaker). MelloUI learns it when you open that profession."] = "Un temps de recharge de métier de nouveau prêt (une transmutation, l'étoffe lunaire, la salière). MelloUI l'apprend quand vous ouvrez ce métier.", -- draft
-- stale: ["A quest ready to turn in says who takes it and where, for example: Turn in: Gryan Stoutmantle, Sentinel Hill."] = "Une quête prête à être rendue indique qui la prend et où, par exemple : Rendre : Gryan Fortmantel, Colline des Sentinelles.", -- draft
-- stale: ["A quest tracker in the game's tracker's place that scrolls with the mouse wheel, so every watched quest can be reached."] = "Un suivi des quêtes à la place de celui du jeu qui défile à la molette, pour atteindre chaque quête suivie.", -- draft
-- stale: ["A quest with a time limit: a ring for its whole time and the time left."] = "Une quête avec une limite de temps : un anneau pour toute sa durée et le temps restant.", -- draft
-- stale: ["A rare or rare elite nearby, seen on the minimap, as a nameplate, as your target or under the mouse: its face, its name and how far it is, glowing as it comes up. Click its face to target it (out of combat); Lead Me There shows the way to where the minimap has it."] = "Un rare ou un élite rare à proximité, vu sur la minicarte, comme barre d'info, comme cible ou sous la souris : sa tête, son nom et sa distance, brillant à son arrivée. Cliquez sa tête pour le cibler (hors combat) ; Guidez-moi montre le chemin vers l'endroit où la minicarte l'indique.", -- draft
-- stale: ["A roll in a group: the item in its quality colour, a ring for the time left, and Need, Greed and Pass on hover. The count is the rolls waiting. The game's own roll window stays out of sight meanwhile (with the Gamepad UI it stays)."] = "Un jet en groupe : l'objet dans la couleur de sa qualité, un anneau pour le temps restant, et Besoin, Cupidité et Passer au survol. Le nombre est celui des jets en attente. La fenêtre de jet du jeu reste cachée pendant ce temps (avec l'interface manette, elle reste).", -- draft
-- stale: ["A round button by your portrait for errands: supplies low (Restock), new mail, gear to repair, a trainer with something new. Click it to route there. Off, none of the four shows; the Widgets' portrait reminders keep their own switches."] = "Un bouton rond près de votre portrait pour les courses : provisions basses (Réapprovisionner), nouveau courrier, équipement à réparer, un maître avec du nouveau. Cliquez-le pour un itinéraire. Désactivé, aucun des quatre ne s'affiche ; les rappels de portrait des Widgets gardent leurs propres interrupteurs.", -- draft
-- stale: ["A row with fewer icons than the others sits centred under them, so the icons grow from the middle. The essential and utility cooldowns and the buff icons."] = "Une rangée avec moins d'icônes que les autres se centre sous elles, pour que les icônes poussent depuis le milieu. Les temps de recharge essentiels et utilitaires et les icônes d'améliorations.", -- draft
-- stale: ["A seal stamped when you level up."] = "Un sceau frappé quand vous montez de niveau.", -- draft
-- stale: ["A seal struck into the record when you level."] = "Un sceau frappé dans le registre quand vous montez de niveau.", -- draft
-- stale: ["A seamless world map of MelloUI's own (M): zoom from Azeroth to a village, ground and caves up close; your party, Route, flights, dungeons, quests and objectives on it."] = "Une carte du monde continue propre à MelloUI (M) : zoomez d'Azeroth jusqu'à un village, sol et grottes de près ; votre groupe, l'Itinéraire, les vols, donjons, quêtes et objectifs dessus.", -- draft
-- stale: ["A short chime with each notice: the map's tracking sound for a new destination (left out while the World Marker's own sound plays for it), a softer one when you arrive."] = "Un court carillon avec chaque avis : le son de suivi de la carte pour une nouvelle destination (omis quand le Marqueur du monde joue son propre son), un plus doux à l'arrivée.", -- draft
-- stale: ["A short line when a fight starts and when it ends."] = "Une courte ligne au début et à la fin d'un combat.", -- draft
-- stale: ["A shot bar and a melee bar in MelloUI's look in place of the game's swing timers: each swing and shot counted down beside your weapon's icon, the off hand under the main hand, a wand's shots on the melee bar. The game's own swing timers are switched off while this is on, and come back as you had them when it is off. While the Personal Display shows your swing on its rails (Swing On The Rails), these bars step aside."] = "Une barre de tir et une barre de mêlée à l'apparence de MelloUI à la place des minuteurs d'attaque du jeu : chaque coup et tir décompté à côté de l'icône de votre arme, la main gauche sous la main droite, les tirs de baguette sur la barre de mêlée. Les minuteurs du jeu sont désactivés tant que ceci est actif, et reviennent comme vous les aviez quand c'est désactivé. Tant que l'Affichage personnel montre vos coups sur ses rails (Coups sur les rails), ces barres s'effacent.", -- draft
-- stale: ["A slim beam of light rising from the destination, so the place can be seen from far away, with a small glow on the ground at its foot, red with Red Beads and gold with the other Trail Looks. It fades as you come near and is gone once the marker rises above the place, and hides while the place is off screen. Part of the World Marker."] = "Un fin rayon de lumière qui s'élève de la destination, pour voir le lieu de loin, avec une petite lueur au sol à son pied, rouge avec Perles rouges et dorée avec les autres apparences de traînée. Il s'estompe en approchant et disparaît dès que le marqueur s'élève au-dessus du lieu, et se cache quand le lieu est hors de l'écran. Fait partie du Marqueur du monde.", -- draft
-- stale: ["A small DPS or healing number on the right of each raid-style or raid frame, beside the health. In a fight, players MelloUI cannot tell apart stay empty until it ends. Point at a frame for all three numbers."] = "Un petit chiffre de DPS ou de soins à droite de chaque cadre style raid ou de raid, à côté de la vie. En combat, les joueurs que MelloUI ne peut pas distinguer restent vides jusqu'à la fin. Survolez un cadre pour les trois chiffres.", -- draft
-- stale: ["A small coloured FPS and latency readout in the bottom right corner."] = "Un petit affichage coloré des IPS et de la latence dans le coin inférieur droit.", -- draft
-- stale: ["A small flag mark over the destination itself, with the distance and the travel time, that stays on it as you move the camera. Far away it is a beacon, smaller the farther the place, faint while it stands in the middle of the screen; within 100 yards it rises above the place, the distance and the name over it and a gold chevron pointing down to it, so it never covers what you are looking for. Inside a quest's objective area it hides, and comes back when you leave. When the place is off screen, an arrow beside your character points the way to turn. Takes the place of the game's own destination marker while it is on."] = "Une petite marque en drapeau au-dessus de la destination elle-même, avec la distance et le temps de trajet, qui y reste quand vous bougez la caméra. De loin c'est une balise, plus petite à mesure que le lieu est loin, pâle quand elle est au milieu de l'écran ; à moins de 100 mètres elle s'élève au-dessus du lieu, la distance et le nom au-dessus et un chevron doré pointant vers lui, pour ne jamais couvrir ce que vous cherchez. Dans la zone d'objectif d'une quête elle se cache, et revient quand vous en sortez. Quand le lieu est hors de l'écran, une flèche à côté de votre personnage indique où tourner. Remplace le marqueur de destination du jeu tant que c'est actif.", -- draft
-- stale: ["A small gem in the top-left corner of every item in your bags, the bank and the guild bank, in the colour of the item's quality: grey for junk, white for common, then green, blue, purple and orange. Junk and better items stand out at a glance. While the game shows its own mark in that corner (the junk coin at a merchant, the upgrade arrow, the exclamation mark on an item that starts a quest, the quality badge on a crafting reagent), the gem moves to the top-right corner. One switch for all three windows."] = "Une petite gemme dans le coin supérieur gauche de chaque objet de vos sacs, de la banque et de la banque de guilde, à la couleur de la qualité de l'objet : gris pour la camelote, blanc pour le commun, puis vert, bleu, violet et orange. La camelote et les meilleurs objets se repèrent d'un coup d'œil. Quand le jeu affiche sa propre marque dans ce coin (la pièce de camelote chez un marchand, la flèche d'amélioration, le point d'exclamation d'un objet qui commence une quête, l'insigne de qualité d'un composant d'artisanat), la gemme passe dans le coin supérieur droit. Un interrupteur pour les trois fenêtres.", -- draft
-- stale: ["A soft breath of air as the World Marker changes: when it comes up for a new destination, as it rises above the place you are near, and as it turns back into the beacon when you walk away. For a new destination it is the one sound: the tracking notice leaves its chime out then. Plays on the Sound Effects channel. Part of the World Marker."] = "Un doux souffle d'air quand le Marqueur du monde change : quand il apparaît pour une nouvelle destination, quand il s'élève au-dessus du lieu dont vous êtes proche, et quand il redevient balise en vous éloignant. Pour une nouvelle destination c'est le seul son : l'avis de suivi omet alors son carillon. Joué sur le canal Effets sonores. Fait partie du Marqueur du monde.", -- draft
-- stale: ["A soft dark shade behind the text MelloUI shows on the world, so it reads on bright ground: the zone name when you enter a new area (with its subzone and PvP lines), the game's messages in the middle of the screen (red errors, yellow quest progress, raid warnings and boss emotes), the Route's World Marker, the names on the unit frames (yours, your pet's, your targets' targets' and the party's) and on the nameplates, and the channel tags and links on the chat's parchment. No outline on the zone name and the messages (Outlined Text adds it back); the game's colours stay. Off: the game's own look, and no shade behind any of them."] = "Une ombre douce et sombre derrière le texte que MelloUI affiche sur le monde, pour qu'il se lise sur un fond clair : le nom de zone en entrant dans une nouvelle zone (avec ses lignes de sous-zone et JcJ), les messages du jeu au centre de l'écran (erreurs rouges, progression de quête jaune, avertissements de raid et emotes de boss), le Marqueur du monde de l'Itinéraire, les noms sur les portraits d'unités (le vôtre, celui de votre familier, des cibles de vos cibles et du groupe) et sur les barres d'info, et les étiquettes de canal et liens sur le parchemin de la discussion. Pas de contour sur le nom de zone et les messages (Texte détouré le remet) ; les couleurs du jeu restent. Désactivé : l'aspect du jeu, et aucune ombre derrière tout cela.", -- draft
-- stale: ["A soft dark shade round the kit's outlines, so windows, bars and frames stand out from the world. Each area has its own switch under it."] = "Une ombre sombre et douce autour des contours du kit, pour que fenêtres, barres et cadres se détachent du monde. Chaque zone a son propre interrupteur dessous.", -- draft
-- stale: ["A soft glow in the debuff's colour (Magic blue, Curse purple, Disease brown, Poison green) round a friend's frame while they have a debuff that can be removed. On the raid frames the border takes the colour too."] = "Un halo doux à la couleur de l'affaiblissement (Magie bleu, Malédiction violet, Maladie brun, Poison vert) autour du cadre d'un allié tant qu'il a un affaiblissement qui peut être retiré. Sur les cadres de raid, la bordure prend aussi la couleur.", -- draft
-- stale: ["A soft gold glow bursts round your target's bar on a critical hit."] = "Une douce lueur dorée jaillit autour de la barre de votre cible sur un coup critique.", -- draft
-- stale: ["A tab waiting on a switch has a button to it; the other skin's settings and turned-off action bars stay out of sight."] = "Un onglet qui attend un interrupteur a un bouton pour y aller ; les réglages de l'autre skin et les barres d'action éteintes restent cachés.", -- draft
-- stale: ["A thinner bar under the melee bar for your off-hand weapon's swings, while you carry one."] = "Une barre plus fine sous la barre de mêlée pour les coups de votre arme en main gauche, tant que vous en portez une.", -- draft
-- stale: ["A tiny tick when the mouse reaches a button. The game has no hover sound; this is an addition."] = "Un tout petit tic quand la souris atteint un bouton. Le jeu n'a pas de son de survol ; c'est un ajout.", -- draft
-- stale: ["A unit's tooltip in colours that tell you at a glance: the guild green, Alliance blue and Horde red, the level line in the colour of how hard the unit is for you, a quest's title gold and its objectives cream while still to do, green once done."] = "L'encadré d'aide d'une unité dans des couleurs qui parlent d'un coup d'œil : la guilde en vert, l'Alliance en bleu et la Horde en rouge, la ligne de niveau dans la couleur de la difficulté de l'unité pour vous, le titre d'une quête en or et ses objectifs en crème tant qu'ils sont à faire, en vert une fois faits.", -- draft
-- stale: ["A whisper opens a small window of its own, one per person, with the conversation and a box to answer in, instead of a new chat tab. Whispers still show in the main chat. Switching it off puts the game's own whisper setting back."] = "Un chuchotement ouvre une petite fenêtre à lui, une par personne, avec la conversation et une zone pour répondre, au lieu d'un nouvel onglet de discussion. Les chuchotements s'affichent toujours dans la discussion principale. Le désactiver remet le réglage de chuchotement du jeu.", -- draft
-- stale: ["A ½ button at the left end of the split box's amount: click it and the amount is half the stack (191 makes 95). Buying in bundles at a merchant, it rounds down to whole bundles."] = "Un bouton ½ à gauche de la quantité de la boîte de partage : cliquez-le et la quantité devient la moitié de la pile (191 donne 95). En achetant par lots chez un marchand, il arrondit au lot entier inférieur.", -- draft
-- stale: ["Abilities that light up (Overpower!), auras you gain or lose, interrupts and dispels."] = "Les techniques qui s'allument (Fulgurance !), les auras que vous gagnez ou perdez, les interruptions et les dissipations.", -- draft
-- stale: ["Ability, spell or item is not ready yet."] = "La technique, le sort ou l'objet n'est pas encore prêt.", -- draft
-- stale: ["About how long the rest of the way takes, beside the distance on the World Marker, from how fast you are moving (on foot or mounted). The tracking notice says it too, and arriving says how long the way took."] = "Environ combien de temps prend le reste du chemin, à côté de la distance sur le Marqueur du monde, d'après votre vitesse (à pied ou sur une monture). L'avis de suivi le dit aussi, et l'arrivée dit combien de temps a pris le trajet.", -- draft
-- stale: ["Accept a quest as soon as its giver shows it, and open a giver's only quest from its list. Grey, repeatable, daily and ignored quests are left to you, and so is an escort's or a shared quest's question."] = "Accepte une quête dès que son donneur la montre, et ouvre la seule quête d'un donneur depuis sa liste. Les quêtes grises, répétables, journalières et ignorées vous sont laissées, ainsi que la question d'une escorte ou d'une quête partagée.", -- draft
-- stale: ["Action Bar 1 without the game's bar art (its frame, dividers and the art of empty slots), like the other bars: MelloUI ticks Edit Mode's own Hide Bar Art for it. Only on your own Edit Mode layouts: a preset such as Modern can't be changed. Shows after a /reload. Off: the art back on the layouts MelloUI changed (or set it yourself in Edit Mode)."] = "La barre d'actions 1 sans l'art de barre du jeu (son cadre, ses séparateurs et l'art des emplacements vides), comme les autres barres : MelloUI coche pour elle le Masquer l'art de la barre du mode Édition. Seulement sur vos propres dispositions du mode Édition : un préréglage comme Moderne ne peut pas être modifié. S'affiche après un /reload. Désactivé : l'art revient sur les dispositions modifiées par MelloUI (ou réglez-le vous-même dans le mode Édition).", -- draft
-- stale: ["Action Bar 1. Its keys work while it is faded. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "La barre d'actions 1. Ses touches fonctionnent tant qu'elle est estompée. Toujours : jamais estompé. En combat : estompé hors combat, de retour en combat. Au survol : estompé en permanence, affiché quand vous la survolez.", -- draft
-- stale: ["Action Bars: class flyouts such as the hunter's Aspects, the warrior's stances and the druid's forms open on MelloUI's action bars, and their spells cast."] = "Barres d'action : les menus déroulants de classe, comme les aspects du chasseur, les postures du guerrier et les formes du druide, s'ouvrent sur les barres d'action de MelloUI, et leurs sorts se lancent.", -- draft
-- stale: ["Action Bars: the game's hidden stance, pet and possess bars no longer take clicks where they stood once MelloUI's bars are moved (thanks, Baine)."] = "Barres d'action : les barres cachées de posture, de familier et de possession du jeu ne prennent plus les clics à leur ancienne place une fois les barres de MelloUI déplacées (merci, Baine).", -- draft
-- stale: ["Action bars and minimap: backdrops and MelloUI's square minimap for everyone, no painted skin needed; the round painted map is Oldschool's."] = "Barres d'actions et minicarte : fonds et minicarte carrée de MelloUI pour tous, sans habillage peint ; la carte peinte ronde est celle d'Oldschool.", -- draft
-- stale: ["Action bars, stance and pet bars, micro menu, bag bar, experience and reputation bars in the kit."] = "Les barres d'actions, de posture et de familier, le micro-menu, la barre de sacs, les barres d'expérience et de réputation dans le kit.", -- draft
-- stale: ["Action, pet, stance and flyout buttons."] = "Boutons d'action, de familier, de posture et de menu déroulant.", -- draft
-- stale: ["After a fight, for a few seconds in the widget column (longer while you point at it): won or lost and its length, your damage, DPS and rank, the ring your share of the group. The pointer on it shows the top five; a click opens the fight in the Fight History."] = "Après un combat, quelques secondes dans la colonne de widgets (plus longtemps si vous le survolez) : gagné ou perdu et sa durée, vos dégâts, DPS et rang, l'anneau votre part du groupe. Le pointeur dessus montre les cinq meilleurs ; un clic ouvre le combat dans l'Historique des combats.", -- draft
-- stale: ["After a quest offer, and after the description the quest log's Read button reads, play the quest's objectives when the voice pack (MelloUI_VoicePack) has them recorded: the Forever Narrator reads them. Text-to-speech never reads the objectives or their counts."] = "Après une offre de quête, et après la description que lit le bouton Lire du journal des quêtes, joue les objectifs de la quête quand le pack de voix (MelloUI_VoicePack) les a enregistrés : le Forever Narrator les lit. La synthèse vocale ne lit jamais les objectifs ni leurs compteurs.", -- draft
-- stale: ["All action bar buttons, the stance bar, pet bar, possess bar and extra action button."] = "Tous les boutons des barres d'actions, la barre de posture, la barre de familier, la barre de possession et le bouton d'action supplémentaire.", -- draft
-- stale: ["All features"] = "Toutes les fonctions", -- draft
-- stale: ["All set"] = "Tout est prêt", -- draft
-- stale: ["All your empty slots as one slot with their count (drop an item on it to put it in a free slot). Off: every empty slot shows."] = "Tous vos emplacements vides en un seul avec leur nombre (déposez un objet dessus pour le mettre dans un emplacement libre). Désactivé : chaque emplacement vide s'affiche.", -- draft
-- stale: ["Also darken the gryphons / end caps and border art of the main action bar."] = "Assombrit aussi les griffons / embouts et l'art de bordure de la barre d'actions principale.", -- draft
-- stale: ["Also list quests only the other faction can take."] = "Liste aussi les quêtes que seule l'autre faction peut prendre.", -- draft
-- stale: ["Also list quests restricted to classes other than yours."] = "Liste aussi les quêtes réservées à d'autres classes que la vôtre.", -- draft
-- stale: ["Also mark givers whose quests you have all completed, with a grey tick."] = "Marque aussi les donneurs dont vous avez terminé toutes les quêtes, d'une coche grise.", -- draft
-- stale: ["Also remove the square brackets around the short channel tags."] = "Retire aussi les crochets autour des étiquettes de canal courtes.", -- draft
-- stale: ["Also show a round button on the minimap's edge that opens the list of the nearest services; drag it to move it, right-click it to stop the route. /services opens the same list."] = "Affiche aussi un bouton rond au bord de la minicarte qui ouvre la liste des services les plus proches ; faites-le glisser pour le déplacer, clic droit pour arrêter l'itinéraire. /services ouvre la même liste.", -- draft
-- stale: ["Also show junk (grey) items. Off: they are left out."] = "Affiche aussi la camelote (grise). Désactivé : elle est omise.", -- draft
-- stale: ["Also show the text being read under the line, page by page as the voice goes on."] = "Affiche aussi le texte lu sous la ligne, page par page au fil de la voix.", -- draft
-- stale: ["Also show the world server latency next to the home latency."] = "Affiche aussi la latence du serveur de monde à côté de la latence domicile.", -- draft
-- stale: ["An action's icon turns red while your target is out of its range, deep blue while you lack the mana (or other resource) for it, and grey while it cannot be used. Its key already turns red out of range."] = "L'icône d'une action devient rouge tant que votre cible est hors de portée, bleu profond tant qu'il vous manque le mana (ou une autre ressource), et grise tant qu'elle ne peut pas être utilisée. Sa touche devient déjà rouge hors de portée.", -- draft
-- stale: ["An arrow beside the backpack folds the bag slots away so only the backpack shows; click it again to bring them back. While you hold an item they come out by themselves, so a new bag can be dropped into a slot. The game remembers which way you left it."] = "Une flèche à côté du sac à dos replie les emplacements de sac pour ne montrer que le sac à dos ; cliquez à nouveau pour les faire revenir. Quand vous tenez un objet, ils sortent d'eux-mêmes pour qu'un nouveau sac puisse être posé dans un emplacement. Le jeu se souvient de la position laissée.", -- draft
-- stale: ["An enemy's health bar turns purple once its health is below the percentage set here, on the target, focus, target-of-target and boss frames and on nameplates, so you see when finishing moves can be used. Works in combat, when the game hides the exact health, and with every health bar colour."] = "La barre de vie d'un ennemi devient violette dès que sa vie passe sous le pourcentage réglé ici, sur les portraits de la cible, de la focalisation, de la cible de la cible et des boss et sur les barres d'info, pour voir quand les coups de grâce sont utilisables. Fonctionne en combat, quand le jeu masque la vie exacte, et avec chaque couleur de barre de vie.", -- draft
-- stale: ["An iron pin into the parchment for a minimap ping."] = "Une épingle de fer dans le parchemin pour un signal sur la minicarte.", -- draft
-- stale: ["An iron sight catching when a target is selected, a latch releasing when it is lost."] = "Une mire de fer qui s'enclenche quand une cible est choisie, un loquet qui se relâche quand elle est perdue.", -- draft
-- stale: ["An item picked up, moved between slots, put down or looted; a rare or better item has its own sound. Silences the game's own pick-up and put-down sounds (the Equipment and Vendor sounds rely on that, and play only while this is on)."] = "Un objet ramassé, déplacé entre emplacements, posé ou récupéré en butin ; un objet rare ou mieux a son propre son. Coupe les sons de prise et de dépose du jeu (les sons Équipement et Marchand en dépendent, et ne jouent que tant que ceci est actif).", -- draft
-- stale: ["An item you loot flies from where you picked it up into its slot in your bag window (with the bags closed, onto the bag button) and lands with a light across it. The rarer it is, the more it does: green leaves a streak, blue bursts into rays and lands in a ring, purple throws sparks and a shockwave, and a legendary rises in a pillar of light, flashes your bag window's border and says its name on the screen. Turning in a quest, its reward item flies the same way, and its money flies as coins into the bag window's money, which counts up as they land; coins you loot fly in the same way while the bag window is open. Only loot and quest rewards, never what you buy, craft or take from the mail. Not with Reduce Motion."] = "Un objet ramassé vole de l'endroit où vous l'avez pris jusqu'à son emplacement dans votre fenêtre de sacs (sacs fermés, sur le bouton de sac) et atterrit avec une lumière qui le traverse. Plus il est rare, plus il en fait : le vert laisse une traînée, le bleu éclate en rayons et atterrit dans un anneau, le violet lance des étincelles et une onde de choc, et un légendaire s'élève dans une colonne de lumière, fait flasher la bordure de votre fenêtre de sacs et annonce son nom à l'écran. En rendant une quête, son objet de récompense vole de la même façon, et son argent vole en pièces dans l'argent de la fenêtre de sacs, qui s'additionne à leur arrivée ; les pièces ramassées volent de même tant que la fenêtre de sacs est ouverte. Seulement le butin et les récompenses de quête, jamais ce que vous achetez, fabriquez ou retirez du courrier. Pas avec Réduire les animations.", -- draft
-- stale: ["An upright bar beside your character for every shield on you added up, as the game counts them: spells (Power Word: Shield, Ice Barrier, Mana Shield, the wards), talents and items, the ones against one kind of damage too. Each shield is its own part, in its school's colour (Power Word: Shield gold, Ice Barrier frost, Mana Shield arcane, a Fire Protection Potion fire), stacked in the order they went up, its icon beside the column. It fills when one goes up, drains as it takes the hits, turns amber when low and breaks when the last one is gone; one ending while another holds only takes its part away. Edit Layout places it."] = "Une barre verticale à côté de votre personnage pour tous vos boucliers additionnés, comme le jeu les compte : sorts (Mot de pouvoir : Bouclier, Barrière de glace, Bouclier de mana, les protections), talents et objets, ceux contre un seul type de dégâts aussi. Chaque bouclier est sa propre part, dans la couleur de son école (Mot de pouvoir : Bouclier or, Barrière de glace givre, Bouclier de mana arcanes, une potion de protection contre le Feu feu), empilés dans l'ordre où ils se sont levés, leur icône à côté de la colonne. Elle se remplit quand l'un se lève, se vide à mesure qu'il encaisse, devient ambre quand elle est basse et se brise quand le dernier disparaît ; un qui finit tandis qu'un autre tient ne retire que sa part. Modifier la disposition la place.", -- draft
-- stale: ["Animations: a new Animations page (The look) holds every animation MelloUI plays, with Reduce Motion on top and a tab for each place they play: frames, nameplates, bars and windows, travel."] = "Animations : une nouvelle page Animations (L'apparence) réunit toutes les animations de MelloUI, avec Réduire les animations en haut et un onglet pour chaque endroit où elles se jouent : cadres, barres d'info, barres et fenêtres, voyage.", -- draft
-- stale: ["Animations: press Play beside an animation to see it once before you choose."] = "Animations : appuyez sur Jouer à côté d'une animation pour la voir une fois avant de choisir.", -- draft
-- stale: ["Another action is in progress, can't do that while moving, while stunned or while mounted."] = "Une autre action est en cours, impossible en mouvement, étourdi ou sur une monture.", -- draft
