-- stale: ["Edit Layout opened from the configurator brings you back to your page when you leave it."] = "Edit Layout ouvert depuis le configurateur vous ramène à votre page en le quittant.", -- draft
-- stale: ["Edit Layout, bags and groups: more windows move without the reskin; quality gems and junk on every slot; party and raid frames keep their own places and indicators."] = "Modifier la disposition, sacs et groupes : plus de fenêtres se déplacent sans l'habillage ; gemmes de qualité et camelote sur chaque emplacement ; les cadres de groupe et de raid gardent leurs propres places et indicateurs.", -- draft
-- stale: ["Edit Layout, the map, Dungeon Info and the installer bring you back to your settings page; Dark Mode leaves it alone."] = "Modifier la disposition, la carte, Infos des donjons et l'installateur vous ramènent à votre page de réglages ; le Mode sombre la laisse tranquille.", -- draft
-- stale: ["Edit Layout: Grid, Snap, Dim and Coordinates in one View menu, with the grid spacing and snapping gap as sliders."] = "Edit Layout : grille, aimantation, assombrissement et coordonnées dans un menu Affichage, avec l'espacement de la grille et l'écart d'aimantation en curseurs.", -- draft
-- stale: ["Edit Layout: Revert and Default place for each element; switch, make, copy, rename, delete and share Edit Mode layouts from the bar."] = "Modifier la disposition : Revenir et Place par défaut pour chaque élément ; changer, créer, copier, renommer, supprimer et partager les dispositions du mode Édition depuis la barre.", -- draft
-- stale: ["Edit Layout: a dock at the top, the Elements list to show, hide, lock or single out any part, and the game's Edit Mode settings in each part's box."] = "Modifier la disposition : un dock en haut, la liste des éléments pour afficher, masquer, verrouiller ou isoler chaque partie, et les réglages du mode Édition du jeu dans la boîte de chaque partie.", -- draft
-- stale: ["Edit Layout: a top dock; every part of Edit Mode, hidden ones too, to show, hide, lock or move; the game's settings and switches in each box (bars: On Mouseover); one gold highlight."] = "Modifier la disposition : une barre en haut ; chaque partie du mode Édition, même cachée, à afficher, masquer, verrouiller ou déplacer ; les réglages et interrupteurs du jeu dans chaque boîte (barres : Au survol) ; une surbrillance dorée.", -- draft
-- stale: ["Edit Layout: an element the game hides (the Tooltip, the loot window ...) shows with one click on its eye in the Elements list, and with Show all; it took a double-click before."] = "Edit Layout : un élément que le jeu masque (l'infobulle, la fenêtre de butin ...) s'affiche d'un clic sur son œil dans la liste des éléments, et avec Tout afficher ; il fallait un double-clic avant.", -- draft
-- stale: ["Edit Layout: attach elements as in Edit Mode; your other characters are asked again to use MelloUI's layout."] = "Modifier la disposition : attachez les éléments comme dans le mode Édition ; vos autres personnages sont de nouveau invités à utiliser la disposition de MelloUI.", -- draft
-- stale: ["Edit Layout: attach the game's elements to each other, as in Edit Mode."] = "Modifier la disposition : attachez les éléments du jeu les uns aux autres, comme dans le mode Édition.", -- draft
-- stale: ["Edit Layout: the damage meter's size shows as you change it; the player box takes in the meter tab."] = "Modifier la disposition : la taille du compteur DPS se voit pendant que vous la changez ; le cadre du joueur englobe l'onglet du compteur.", -- draft
-- stale: ["Edit Mode already keeps %d account layouts, the most it can. Delete one in Edit Mode, or switch the layout off on the Screen step."] = "Le mode Édition garde déjà %d dispositions de compte, le maximum. Supprimez-en une dans le mode Édition, ou désactivez la disposition à l'étape Écran.", -- draft
-- stale: ["Effects: bolder heals and cooldowns across the whole frame; Buff Landings in each school's colour; a threat halo (untick Hide Combat Flash)."] = "Effets : soins et temps de recharge plus marqués sur tout le cadre ; arrivées d'améliorations dans la couleur de leur école ; un halo de menace (décochez Masquer le flash de combat).", -- draft
-- stale: ["Elites, rares, rare elites and bosses stand out: a metal line over the name with a crest on it. Gold with a crown and wings for an elite, silver with a star for a rare, silver with a gold star and wings for a rare elite, and red-bronze scrollwork with a skull, winged at both ends, for a boss. The plate itself keeps its look."] = "Les élites, rares, élites rares et boss se distinguent : une ligne de métal au-dessus du nom avec un blason. Or avec une couronne et des ailes pour un élite, argent avec une étoile pour un rare, argent avec une étoile d'or et des ailes pour un élite rare, et des volutes de bronze rouge avec un crâne, ailées aux deux bouts, pour un boss. La plaque elle-même garde son apparence.", -- draft
-- stale: ["Escape goes one step at a time; Settings Window Scale on Look sizes this window; helper texts are full size."] = "Échap va pas à pas ; Échelle de la fenêtre des réglages (Apparence) règle sa taille ; les textes d'aide sont en taille normale.", -- draft
-- stale: ["Escape in the configurator goes one step at a time: an open list or panel, a picked part, the search, then the window."] = "Échap dans le configurateur va pas à pas : une liste ou un panneau ouvert, une partie choisie, la recherche, puis la fenêtre.", -- draft
-- stale: ["Escape in the configurator goes one step at a time; its side list starts with Home and has a thin scroll bar."] = "Échap dans le configurateur va pas à pas ; sa liste latérale commence par Accueil et a une fine barre de défilement.", -- draft
-- stale: ["Every MelloUI animation ends at once: windows open without fading, the whisper popup appears in place, the quest tracker's lines do not flash, the configurator jumps instead of gliding. For anyone who finds moving interface parts distracting. Works with UI Modifications switched off as well."] = "Chaque animation de MelloUI se termine immédiatement : les fenêtres s'ouvrent sans fondu, la fenêtre de chuchotement apparaît sur place, les lignes du suivi des quêtes ne clignotent pas, le configurateur saute au lieu de glisser. Pour ceux que les éléments mobiles de l'interface dérangent. Fonctionne aussi avec les Réglages UI désactivés.", -- draft
-- stale: ["Every action button in MelloUI's frame: a dark iron rim with a gold line, brighter under the pointer, bright gold while its aura or stance is on, red out of range, a dark slot when the button is empty. Off: the game's own frames. The painted skin's bars keep their own (Oldschool)."] = "Chaque bouton d'action dans le cadre de MelloUI : un bord de fer sombre avec une ligne dorée, plus clair sous le pointeur, or vif tant que son aura ou sa posture est active, rouge hors de portée, un emplacement sombre quand le bouton est vide. Désactivé : les cadres du jeu. Les barres de l'habillage peint gardent le leur (Oldschool).", -- draft
-- stale: ["Every element on the Frames, Bars and Chat & Map tabs on Always: nothing fades."] = "Chaque élément des onglets Cadres, Barres et Discussion et carte sur Toujours : rien ne s'estompe.", -- draft
-- stale: ["Every element on the Frames, Bars and Chat & Map tabs on In Combat: the whole interface fades away out of combat and comes back in a fight."] = "Chaque élément des onglets Cadres, Barres et Discussion et carte sur En combat : toute l'interface s'estompe hors combat et revient en combat.", -- draft
-- stale: ["Every feature below on or off at once."] = "Chaque fonction ci-dessous activée ou désactivée d'un coup.", -- draft
-- stale: ["Every font drawn with the interface face, relative to its normal size; a Font Style puts it back to 100% (its faces bring their own correction). Not the text with a size of its own: the Quest Tracker, Combat Text, the chat (Chat & numbers size), FPS / Latency, Cooldown Timers, and the bar values while their size is set."] = "Chaque police dessinée avec la police de l'interface, par rapport à sa taille normale ; un style de police la remet à 100% (ses polices apportent leur propre correction). Pas le texte qui a sa propre taille : le suivi des quêtes, le Texte de combat, la discussion (taille Discussion et chiffres), IPS / Latence, les minuteurs de recharge et les valeurs des barres tant que leur taille est réglée.", -- draft
-- stale: ["Every frame: the heal light, the big moments, the debuff glow"] = "Chaque cadre : la lumière des soins, les grands moments, le halo d'affaiblissement", -- draft
-- stale: ["Every setting lives in /mello, and in the MelloUI button of the game menu."] = "Chaque réglage se trouve dans /mello, et dans le bouton MelloUI du menu du jeu.", -- draft
-- stale: ["Every window and HUD area of the reskin back on, and every feature of UI Modifications that is on by default."] = "Réactive chaque zone de fenêtre et d'ATH de l'habillage, ainsi que chaque fonction des Réglages UI activée par défaut.", -- draft
-- stale: ["Every window fades in over a fifth of a second when it opens, instead of appearing at once: the character window, talents and spells, professions, the bags, social, guild, group finder, collections, the map, the game menu and the rest. Works with the reskin on or off. Reduce Motion: at once."] = "Chaque fenêtre apparaît en fondu en un cinquième de seconde à l'ouverture, au lieu d'apparaître d'un coup : la fenêtre du personnage, talents et sorts, métiers, sacs, social, guilde, recherche de groupe, collections, carte, menu de jeu et le reste. Fonctionne avec l'habillage activé ou non. Réduire les animations : immédiat.", -- draft
-- stale: ["Everything off. Set it up step by step."] = "Tout désactivé. Configurez pas à pas.", -- draft
-- stale: ["Facing the wrong way, target needs to be in front of you, no target, invalid target, target not in line of sight."] = "Mal orienté, la cible doit être devant vous, pas de cible, cible incorrecte, cible hors de vue.", -- draft
-- stale: ["Fade parts of the interface away while you do not need them: out of combat, or until you point at them. Pick for each frame, bar, the chat, the minimap and the trackers."] = "Estompe des parties de l'interface quand vous n'en avez pas besoin : hors combat, ou jusqu'à ce que vous les survoliez. À choisir pour chaque cadre, barre, la discussion, la minicarte et les suivis.", -- draft
