-- stale: ["Fixed: Russian, Korean and Chinese letters in Combat Text, zone names, headings and titles no longer show as boxes."] = "Corrigé : les lettres russes, coréennes et chinoises du texte de combat, des noms de zone, des en-têtes et des titres ne s'affichent plus en carrés.", -- draft
-- stale: ["Fixed: Silithus and six other zones are no longer cut out of the map; Edit Layout's Chat box covers the whole minimal chat."] = "Corrigé : Silithus et six autres zones ne sont plus coupées de la carte ; la boîte Discussion de Modifier la disposition couvre toute la discussion minimaliste.", -- draft
-- stale: ["Fixed: Voice Over now speaks when a levelling addon accepts or hands in a quest the moment its window opens."] = "Corrigé : la voix se fait entendre lorsqu'un addon de progression accepte ou rend une quête dès l'ouverture de sa fenêtre.", -- draft
-- stale: ["Fixed: Zygor Guides could not start with MelloUI 2.1.9. It starts again."] = "Corrigé : Zygor Guides ne pouvait pas démarrer avec MelloUI 2.1.9. Il démarre de nouveau.", -- draft
-- stale: ["Fixed: a kind's settings low in the Bags by Kind list are no longer cut off: the list grows with them."] = "Corrigé : les réglages d'un type en bas de la liste de Sacs par type ne sont plus coupés : la liste s'agrandit avec eux.", -- draft
-- stale: ["Fixed: after a level-up the micro menu no longer leaves the place you gave it."] = "Corrigé : après une montée de niveau, le micro-menu ne quitte plus la place que vous lui avez donnée.", -- draft
-- stale: ["Fixed: after learning a new stance or form, a fight could drop to a few frames a second until a restart."] = "Corrigé : après avoir appris une nouvelle posture ou forme, un combat pouvait tomber à quelques images par seconde jusqu'au redémarrage.", -- draft
-- stale: ["Fixed: an error in fights from the Personal Display's Big Cooldowns."] = "Corrigé : une erreur en combat venant des grands temps de recharge de l'Affichage personnel.", -- draft
-- stale: ["Fixed: asking a guard for directions now puts its marker on MelloUI's map."] = "Corrigé : demander son chemin à un garde place désormais son repère sur la carte de MelloUI.", -- draft
-- stale: ["Fixed: clicks on Stealth, stance, form and pet buttons; the Chat font in the Minimal Chat View; Default's whole ticks; labels by sliders."] = "Corrigé : les clics sur Camouflage, les postures, les formes et les boutons du familier ; la police de discussion dans la Vue Minimale ; les coches entières de Par défaut ; les libellés près des curseurs.", -- draft
-- stale: ["Fixed: dead players and ghosts no longer keep a debuff or threat glow around their frames."] = "Corrigé : les joueurs morts et les fantômes ne gardent plus de lueur d'affaiblissement ou de menace autour de leurs cadres.", -- draft
-- stale: ["Fixed: in dungeons, the target of target and other unit frames no longer keep showing an old name."] = "Corrigé : dans les donjons, la cible de la cible et les autres cadres d'unité n'affichent plus un ancien nom.", -- draft
-- stale: ["Fixed: inside a battleground, MelloUI's map opens on the battleground's own map, with you and your group on it."] = "Corrigé : dans un champ de bataille, la carte de MelloUI s'ouvre sur la carte du champ de bataille, avec vous et votre groupe dessus.", -- draft
-- stale: ["Fixed: keys bound in Keybind Mode in place of a default key, such as those of action bar 1, now stay after logging in again."] = "Corrigé : les touches attribuées dans le Mode raccourcis à la place d'une touche par défaut, comme celles de la barre d'action 1, sont désormais conservées après une nouvelle connexion.", -- draft
-- stale: ["Fixed: on Chinese, Korean and Russian clients, floating combat text and names above characters no longer show as squares."] = "Corrigé : sur les clients chinois, coréens et russes, le texte de combat flottant et les noms au-dessus des personnages ne s'affichent plus en carrés.", -- draft
-- stale: ["Fixed: on Oldschool's frames the power bar keeps a small gap under the health bar, and the target's lines up with it."] = "Corrigé : sur les cadres d'Oldschool, la barre de ressource garde un petit écart sous la barre de vie, et celle de la cible s'aligne sur elle.", -- draft
-- stale: ["Fixed: party, raid and other unit frames now show empty health and power bars for dead players and ghosts."] = "Corrigé : les cadres de groupe, de raid et les autres cadres d'unité affichent désormais des barres de vie et de puissance vides pour les joueurs morts et les fantômes.", -- draft
-- stale: ["Fixed: quest givers' marks on MelloUI's map no longer show as stretched yellow blobs."] = "Corrigé : les marques des donneurs de quêtes sur la carte de MelloUI ne s'affichent plus comme des taches jaunes étirées.", -- draft
-- stale: ["Fixed: the Backpack's and the Reagent Bag's tabs beside the bag window show their icons again."] = "Corrigé : les onglets du sac à dos et du sac de composants à côté de la fenêtre des sacs affichent de nouveau leurs icônes.", -- draft
-- stale: ["Fixed: the Names setting now works in the Minimal chat view and the whisper window."] = "Corrigé : le réglage Noms fonctionne dans la vue de discussion minimale et la fenêtre de chuchotements.", -- draft
-- stale: ["Fixed: the World Marker on a guide's step beside you; the Quest List's class quests; Dungeon Info's item quality and repeated bosses."] = "Corrigé : le Marqueur du monde sur une étape de guide à côté de vous ; les quêtes de classe de la Liste des quêtes ; la qualité des objets et les boss répétés d'Infos des donjons.", -- draft
-- stale: ["Fixed: the installer no longer calls your screen too small when it is some of your own settings that do not fit."] = "Corrigé : l'installateur ne dit plus votre écran trop petit quand ce sont certains de vos propres réglages qui ne tiennent pas.", -- draft
-- stale: ["Fixed: the reminder button's line and extra buttons no longer run off the screen: they open on the side with room."] = "Corrigé : la ligne et les boutons supplémentaires du bouton de rappel ne sortent plus de l'écran : ils s'ouvrent du côté où il y a de la place.", -- draft
-- stale: ["Fixed: the target of target's and focus target's health and power bars no longer look dark when a bar texture is chosen."] = "Corrigé : les barres de vie et de puissance de la cible de la cible et de la cible de la focalisation ne sont plus sombres lorsqu'une texture de barre est choisie.", -- draft
-- stale: ["Fixed: the text in MelloUI's search and input boxes starts at the left again instead of the middle."] = "Corrigé : le texte des champs de recherche et de saisie de MelloUI recommence à gauche au lieu du milieu.", -- draft
-- stale: ["Fixed: with MelloUI's buff icons off, the game's Buffs bar can be moved in Edit Layout again."] = "Corrigé : avec les icônes d'amélioration de MelloUI désactivées, la barre d'améliorations du jeu peut de nouveau être déplacée dans l'éditeur de disposition.", -- draft
-- stale: ["Fixed: with the Default skin, the whisper window opens without a Lua error and has the game's look again."] = "Corrigé : avec l'habillage Par défaut, la fenêtre de chuchotement s'ouvre sans erreur Lua et retrouve l'apparence du jeu.", -- draft
-- stale: ["For a rogue, and a druid in Cat Form: your five combo points in a row on the top edge of your target's health bar, empty until you build them. The name moves up a little to make room."] = "Pour un voleur, et un druide en forme de félin : vos cinq points de combo en rangée sur le bord supérieur de la barre de vie de votre cible, vides jusqu'à ce que vous les accumuliez. Le nom monte un peu pour faire de la place.", -- draft
-- stale: ["Force an outline on every light-coloured font. Dark text on parchment (quests, spellbook, dialogs) keeps its original look. MelloUI's own text in the world (notices, combat text, Gains lines) takes its outline from Notices: Outlined Text; this sets only how thick it is."] = "Force un contour sur chaque police de couleur claire. Le texte sombre sur parchemin (quêtes, grimoire, dialogues) garde son aspect d'origine. Le texte de MelloUI dans le monde (avis, texte de combat, lignes de gains) prend son contour dans Avis : texte détouré ; ceci n'en règle que l'épaisseur.", -- draft
-- stale: ["Frame previews stand on the left with room around them; the Player preview shows you; pick 5 to 40 for the fake raid."] = "Les aperçus de cadres se placent à gauche avec de l'espace autour ; l'aperçu du joueur vous montre ; de 5 à 40 pour le faux raid.", -- draft
-- stale: ["Frame, background and segment dividers of the experience, reputation and honor bars."] = "Cadre, fond et séparateurs de segments des barres d'expérience, de réputation et d'honneur.", -- draft
-- stale: ["Frames and bars: party levels on the name line, soft name bands, a round-rim swing timer, a slim race bar, a gold flash as cooldowns end, one Health Colour for all."] = "Cadres et barres : niveaux du groupe sur la ligne du nom, bandeaux de nom doux, un minuteur d'attaque à bord rond, une fine barre de course, un flash doré à la fin des recharges, une seule Couleur de vie pour tout.", -- draft
-- stale: ["Frames per second."] = "Images par seconde.", -- draft
-- stale: ["Frames: Hide Heal Numbers on your portrait; party: Flip Horizontally, Mouseover Highlight, raid frames wear Raid's look and stay in place when you switch."] = "Cadres : Masquer les nombres de soins sur votre portrait ; groupe : Retourner horizontalement, Surbrillance au survol, les cadres de raid portent l'apparence de Raid et restent en place au changement.", -- draft
-- stale: ["Frames: Hide Heal Numbers on your portrait; party: Flip Horizontally, Mouseover Highlight, the meter's numbers in a tab on each frame, Raid's look in raid frames."] = "Cadres : Masquer les nombres de soins sur votre portrait ; groupe : Retourner horizontalement, Surbrillance au survol, les nombres du compteur dans un onglet sur chaque cadre, l'apparence de Raid sur les cadres de raid.", -- draft
-- stale: ["Frames: Hide Heal Numbers on your portrait; the meter's numbers in a tab on your frame and each party frame; party: Flip, Mouseover Highlight, Raid's look in raid frames."] = "Cadres : Masquer les nombres de soins sur votre portrait ; les nombres du compteur dans un onglet sur votre cadre et chaque cadre de groupe ; groupe : Retourner, Surbrillance au survol, l'apparence de Raid sur les cadres de raid.", -- draft
