-- stale: ["Hide the red flash around the player, target, focus, pet and party frames while in combat or when a target attacks."] = "Masque le flash rouge autour des cadres du joueur, de la cible, de la focalisation, du familier et du groupe en combat ou quand une cible attaque.", -- draft
-- stale: ["Hide the row of menu buttons (character, spellbook, talents, ...). Still shown while Edit Mode is open."] = "Masque la rangée de boutons de menu (personnage, grimoire, talents, ...). Toujours visible tant que le mode Édition est ouvert.", -- draft
-- stale: ["Hides the coordinates under the minimap."] = "Masque les coordonnées sous la minicarte.",
-- stale: ["Hides the main bar's art, like the other bars. Only on your own Edit Mode layouts, not the presets; shows after a /reload."] = "Masque les graphismes de la barre principale, comme les autres barres. Seulement sur vos dispositions du mode Édition, pas les préréglages ; s'affiche après un /reload.", -- draft
-- stale: ["Hides the red error messages you choose (not enough energy, not ready yet, out of range...) from the middle of the screen."] = "Masque au centre de l'écran les messages d'erreur rouges que vous choisissez (pas assez d'énergie, pas encore prêt, hors de portée...).", -- draft
-- stale: ["Hides the red flash around unit frames in combat."] = "Masque le flash rouge autour des cadres d'unité en combat.", -- draft
-- stale: ["Hold it as you talk to a giver to see its dialog as usual: nothing is accepted or handed in there."] = "Maintenez-la en parlant à un donneur pour voir son dialogue comme d'habitude : rien n'y est accepté ni rendu.", -- draft
-- stale: ["Home latency in milliseconds."] = "Latence domicile en millisecondes.", -- draft
-- stale: ["How a character's name is written, everywhere at once: the player, target, focus, pet, party and raid frames, the nameplates, the chat and whisper windows, and the name over your own head (the game's own setting for it: only First name leaves out the surname there). A character with no surname shows the name it has; in the chat the name is still a link to the player. Names over other players' heads without a nameplate are the engine's and have no setting."] = "Comment le nom d'un personnage s'écrit, partout à la fois : cadres du joueur, de la cible, de la focalisation, du familier, de groupe et de raid, barres d'info, fenêtres de discussion et de chuchotement, et le nom au-dessus de votre tête (le réglage du jeu pour cela : seul « Prénom » y omet le nom de famille). Un personnage sans nom de famille montre le nom qu'il a ; dans la discussion, le nom reste un lien vers le joueur. Les noms au-dessus des autres joueurs sans barre d'info relèvent du moteur et n'ont pas de réglage.", -- draft
-- stale: ["How big the Big Cooldowns' icons above the health bar are. Their seconds keep the display's text size."] = "La taille des icônes des Gros temps de recharge au-dessus de la barre de vie. Leurs secondes gardent la taille du texte de l'affichage.", -- draft
-- stale: ["How big the item slots are (37 is the game's own size)."] = "La taille des emplacements d'objet (37 est la taille du jeu).", -- draft
-- stale: ["How big the route's beads, line or dashes are on the world map and the minimap."] = "La taille des perles, de la ligne ou des tirets de l'itinéraire sur la carte du monde et la minicarte.", -- draft
-- stale: ["How bright the game's own artwork is where Dark Mode darkens it (the parts the reskin does not cover, or everything with the reskin off). Lower values are darker. The reskin's own art has Reskin Brightness below."] = "La luminosité de l'art du jeu là où le mode sombre l'assombrit (les parties que l'habillage ne couvre pas, ou tout si l'habillage est désactivé). Plus la valeur est basse, plus c'est sombre. L'art de l'habillage a sa propre Luminosité de l'habillage ci-dessous.", -- draft
-- stale: ["How bright the game's own artwork is where Dark mode darkens it. Lower is darker."] = "La luminosité de l'art du jeu là où le mode sombre l'assombrit. Plus bas, plus sombre.", -- draft
-- stale: ["How bright the painted reskin is while Dark Mode is on: every kit piece (stone, iron, plates, brackets) is darkened by this much; the red gems keep their colour. The default art above is darkened where the reskin is off."] = "La luminosité de l'habillage peint tant que le mode sombre est actif : chaque pièce du kit (pierre, fer, plaques, supports) est assombrie d'autant ; les gemmes rouges gardent leur couleur. L'art par défaut ci-dessus est assombri là où l'habillage est désactivé.", -- draft
-- stale: ["How dark the UI Shade round the kit's outlines is, the nameplates' Whole plate shade too. The bands behind unit frame and nameplate names keep their own."] = "L'intensité de l'ombre de l'interface autour des contours du kit, ainsi que l'ombre « Plaque entière » des barres d'info. Les bandes derrière les noms des portraits d'unités et des barres d'info gardent la leur.", -- draft
-- stale: ["How far a member too far away for your heals fades. 100%: no fade."] = "À quel point s'estompe un membre trop loin pour vos soins. 100% : pas de fondu.", -- draft
-- stale: ["How far each quest is, beside its name: its objectives, or the one who takes it once it is done. The quest you follow shows the way along its route. Needs Route."] = "La distance de chaque quête, à côté de son nom : ses objectifs, ou celui qui la reprend une fois faite. La quête que vous suivez indique le chemin le long de son itinéraire. Nécessite Itinéraire.", -- draft
-- stale: ["How far from your character the damage and healing lanes run, left and right. Move the whole text in Edit Layout."] = "À quelle distance de votre personnage courent les couloirs des dégâts et des soins, à gauche et à droite. Déplacez tout le texte dans Modifier la disposition.", -- draft
-- stale: ["How far under the minimap the buttons sit. Not used while they are merged into the square minimap's frame."] = "À quelle distance sous la minicarte se placent les boutons. Inutilisé tant qu'ils sont fusionnés dans le cadre de la minicarte carrée.", -- draft
-- stale: ["How fast text-to-speech reads; 0 is the voice's normal pace. Recorded lines always play at their own pace."] = "La vitesse de lecture de la synthèse vocale ; 0 est le rythme normal de la voix. Les lignes enregistrées jouent toujours à leur propre rythme.", -- draft
-- stale: ["How long a new reminder stays before it tucks itself away. It stays while your pointer is on it."] = "Combien de temps un nouveau rappel reste avant de se ranger. Il reste tant que votre pointeur est dessus.", -- draft
-- stale: ["How long an element waits before it fades: after a fight ends, after you let go of your target or point away."] = "Combien de temps un élément attend avant de s'estomper : après la fin d'un combat, après avoir lâché votre cible ou détourné le pointeur.", -- draft
-- stale: ["How long an item stays under Recent: until you close your bags, only until you point at it (it moves to its own kind as the pointer leaves it), or for 5 minutes after you got it."] = "Combien de temps un objet reste sous Récent : jusqu'à la fermeture des sacs, seulement jusqu'à ce que vous le survoliez (il rejoint son type quand le pointeur le quitte), ou 5 minutes après l'avoir obtenu.", -- draft
-- stale: ["How long each line stays before it fades. Gaining the same skill or item again adds to its line and starts it over."] = "Combien de temps chaque ligne reste avant de s'effacer. Regagner la même compétence ou le même objet s'ajoute à sa ligne et la relance.", -- draft
-- stale: ["How long the fade itself takes. Coming back is always quick. Reduce Motion: at once."] = "La durée du fondu lui-même. Le retour est toujours rapide. Réduire les animations : aussitôt.", -- draft
-- stale: ["How long the tooltip of a creature or an object stays fully visible after your cursor leaves it, before it fades out (the fade itself takes a quarter of a second)."] = "Combien de temps l'encadré d'aide d'une créature ou d'un objet reste pleinement visible après que votre curseur l'a quitté, avant de s'effacer (l'effacement lui-même prend un quart de seconde).", -- draft
-- stale: ["How loud text-to-speech reads. Recorded lines follow the Sound Channel's volume in the game's sound settings."] = "Le volume de la synthèse vocale. Les lignes enregistrées suivent le volume du Canal sonore dans les réglages audio du jeu.", -- draft
-- stale: ["How many buffs stand in a row before the next row starts. Your debuffs start a row of their own (the game's debuff bar takes at most 16 in a row)."] = "Combien d'améliorations tiennent sur une rangée avant que la suivante commence. Vos affaiblissements commencent leur propre rangée (la barre d'affaiblissements du jeu en prend au plus 16 par rangée).", -- draft
-- stale: ["How many fights the history keeps, the oldest dropped first. Kept over a /reload; a new login starts it empty."] = "Combien de combats l'historique conserve, le plus ancien supprimé d'abord. Conservés après un /reload ; une nouvelle connexion le vide.", -- draft
-- stale: ["How many frames in a column (or a row) before the next one starts. 5 lines the raid up by its groups."] = "Combien de cadres dans une colonne (ou une rangée) avant que la suivante commence. 5 aligne le raid par ses groupes.", -- draft
-- stale: ["How many rows the bar's buttons stand in (columns, on a bar stood upright in Edit Mode)."] = "Sur combien de rangées se tiennent les boutons de la barre (de colonnes, pour une barre mise à la verticale dans le mode Édition).", -- draft
-- stale: ["How many slots across the bag window is: more makes it wider and shorter."] = "Combien d'emplacements en largeur compte la fenêtre de sacs : plus la rend plus large et moins haute.", -- draft
-- stale: ["How many widgets the column shows at once. The rest wait in a slim \"+2 more\" row on top; a click there lists them. Loot rolls, summons, resurrect offers and ready checks always show, and Voice Over keeps the bottom place."] = "Combien de widgets la colonne affiche à la fois. Les autres attendent dans une fine ligne « +2 de plus » en haut ; un clic les liste. Les jets de butin, invocations, offres de résurrection et appels s'affichent toujours, et Voice Over garde la place du bas.", -- draft
-- stale: ["How much of an element stays while it is faded. At 0 % it is gone until it is needed (an On Mouseover bar at 0 % still shows when you point at it)."] = "Ce qui reste d'un élément tant qu'il est estompé. À 0 % il disparaît jusqu'à ce qu'on en ait besoin (une barre Au survol à 0 % s'affiche encore quand vous la survolez).", -- draft
-- stale: ["How names read in chat."] = "Comment les noms se lisent dans la discussion.", -- draft
-- stale: ["How solid the bars' background is: lower lets the world show through the empty part of a bar."] = "La densité du fond des barres : plus bas laisse voir le monde à travers la partie vide d'une barre.", -- draft
-- stale: ["How solid the chat windows' background is. Moving the Background slider in a chat tab's menu changes this too."] = "La densité du fond des fenêtres de discussion. Déplacer le curseur Fond dans le menu d'un onglet de discussion change aussi ceci.", -- draft
-- stale: ["How solid the painted border round the chat windows and their button column is, and its shade (the painted chat: its Painted Skin, the reskin on)."] = "La densité de la bordure peinte autour des fenêtres de discussion et de leur colonne de boutons, et de son ombre (la discussion peinte : son Habillage peint, l'habillage actif).", -- draft
-- stale: ["How tall the bars are; the off hand's is 60 % of it, and the weapon's rim grows with them from 15 on. Also in Edit Layout."] = "La hauteur des barres ; celle de la main gauche en fait 60 %, et l'anneau de l'arme grandit avec elles à partir de 15. Aussi dans Modifier la disposition.", -- draft
-- stale: ["How tall the health bar is; the power and cast bars are a little thinner, in step with it. Their frames grow and shrink with them."] = "La hauteur de la barre de vie ; les barres de ressource et d'incantation sont un peu plus fines, au même rythme. Leurs cadres grandissent et rétrécissent avec elles.", -- draft
-- stale: ["How tall the square map is (the round map takes its Width). The shorter side is at least half the longer one."] = "La hauteur de la carte carrée (la carte ronde prend sa Largeur). Le côté le plus court fait au moins la moitié du plus long.", -- draft
-- stale: ["How tall the tracker may grow before it scrolls (at least 88, room for the title and a few lines). Edit Mode's: the height set for the game's tracker in Edit Mode. The grip in its bottom-left corner sets it by dragging."] = "La hauteur que le suivi peut atteindre avant de défiler (au moins 88, de la place pour le titre et quelques lignes). Celle du mode Édition : la hauteur réglée pour le suivi du jeu dans le mode Édition. La poignée du coin inférieur gauche la règle en glissant.", -- draft
-- stale: ["How the chat is shown. Game Windows: the game's chat windows and tabs. Minimal: one panel with a rail of round tabs on its left (one per chat window, a count of the lines you have not seen; Whispers last), each line under its sender's name, channel and time, and a row of round buttons under the lines: Say, Party, Raid, Instance, Guild, Yell, Whisper and Emote open the line you type in on that chat, then Channels, Friends, the fight history and these settings. A whisper puts a count on the Whispers tab and shows the Whispers widget; either opens one whisper window above the chat with every conversation in it, theirs left and yours right. Parchment (its own switch) puts both on the parchment sheet."] = "Comment la discussion s'affiche. Fenêtres du jeu : les fenêtres et onglets de discussion du jeu. Minimale : un panneau avec un rail d'onglets ronds à gauche (un par fenêtre de discussion, avec le nombre de lignes non vues ; Chuchotements en dernier), chaque ligne sous le nom de son expéditeur, le canal et l'heure, et une rangée de boutons ronds sous les lignes : Dire, Groupe, Raid, Instance, Guilde, Crier, Chuchoter et Emote ouvrent la ligne de saisie sur ce canal, puis Canaux, Contacts, l'historique des combats et ces réglages. Un chuchotement met un compteur sur l'onglet Chuchotements et affiche le widget Chuchotements ; l'un ou l'autre ouvre une fenêtre de chuchotement au-dessus de la discussion avec toutes les conversations, les leurs à gauche et les vôtres à droite. Parchemin (son propre interrupteur) pose les deux sur la feuille de parchemin.", -- draft
-- stale: ["How the parchment looks wherever it shows: the sheets switched on below, and the quest log, quest and spell book pages. Burnt paper: warm paper with burnt edges, big pages with curled corners. Classic vellum: the vellum with painted brush-stroke edges from before 0.20.1."] = "L'aspect du parchemin partout où il apparaît : les feuilles activées ci-dessous, ainsi que les pages du journal des quêtes, des quêtes et du grimoire. Papier brûlé : papier chaud aux bords brûlés, grandes pages aux coins enroulés. Vélin classique : le vélin aux bords peints au pinceau d'avant 0.20.1.", -- draft
-- stale: ["How the raid's frames are grouped: by raid group (1 to 8), by role, by class, or one list."] = "Comment les cadres du raid sont regroupés : par groupe de raid (1 à 8), par rôle, par classe, ou une seule liste.", -- draft
-- stale: ["How the route is drawn on the world map and the minimap: red beads in gold rings, one pale gold line, or short pale gold dashes. The destination is a flag in a gold ring either way."] = "Comment l'itinéraire est tracé sur la carte du monde et la minicarte : des perles rouges dans des anneaux dorés, une ligne d'or pâle, ou de courts tirets d'or pâle. La destination est un drapeau dans un anneau doré dans tous les cas.", -- draft
-- stale: ["How the value is written."] = "Comment la valeur est écrite.", -- draft
-- stale: ["How thick your share is on the race bar's line (its pins and labels keep their size). Also in Edit Layout: right-click the race bar."] = "L'épaisseur de votre part sur la ligne de la barre de course (ses repères et étiquettes gardent leur taille). Aussi dans Modifier la disposition : clic droit sur la barre de course.", -- draft
-- stale: ["How wide the bars are; the weapon's rim hangs left of them and the seconds right of them. Also in Edit Layout (right-click a bar there)."] = "La largeur des barres ; l'anneau de l'arme pend à leur gauche et les secondes à leur droite. Aussi dans Modifier la disposition (clic droit sur une barre).", -- draft
-- stale: ["How wide the health, power and cast bars are. Edit Layout sizes the whole display."] = "La largeur des barres de vie, de ressource et d'incantation. Modifier la disposition dimensionne tout l'affichage.", -- draft
-- stale: ["How wide the map is. The round map is as tall as it is wide, and its painted ring grows and shrinks with it. The square map's border and the zone name keep their size, the Services buttons too (smaller only on a map too narrow for them), and the Quest Tracker under the map follows its width. Edit Mode's minimap Size no longer sizes the map while the Minimap Kit is on."] = "La largeur de la carte. La carte ronde est aussi haute que large, et son anneau peint grandit et rétrécit avec elle. La bordure de la carte carrée et le nom de zone gardent leur taille, les boutons Services aussi (plus petits seulement sur une carte trop étroite pour eux), et le suivi des quêtes sous la carte suit sa largeur. La Taille de minicarte du mode Édition ne dimensionne plus la carte tant que le kit de la minicarte est actif.", -- draft
-- stale: ["How wide the race bar is. Also in Edit Layout: right-click the race bar."] = "La largeur de la barre de course. Aussi dans Modifier la disposition : clic droit sur la barre de course.", -- draft
-- stale: ["How wide the tracker is when it does not match the minimap's width (at least 60). Edit Mode's: as wide as the game's tracker. The grip in its bottom-left corner sets width and height by dragging (only the height while it matches the minimap)."] = "La largeur du suivi quand il ne prend pas la largeur de la minicarte (au moins 60). Celle du mode Édition : aussi large que le suivi du jeu. La poignée du coin inférieur gauche règle largeur et hauteur en glissant (seulement la hauteur tant qu'il suit la minicarte).", -- draft
-- stale: ["How your heals look. By Class: Holy for priests and paladins, Nature for druids, Water for shamans (Holy for anyone else). Water: water circles your cast bar, a winding stream throws off droplets, a splash lands; a shield is a water bubble, a heal to full a geyser. Holy: gold sparks spiral into your spell's icon, a gold comet flies, a white flash and a burst of rays land, rune marks linger round the frame. Nature: green and gold ribbons circle your cast bar, ribbons fly shedding leaves, leaves burst and rise. Quiet: your cast bar's fill glows, a thin thread of light flies, the frame's border flares. Each kind lands its own way in each look: a heal over time sinks in, a shield wraps the frame in a barrier, protection puts a crest over it, a heal to full raises a column of light, a resurrection lights the fallen one's frame."] = "L'apparence de vos soins. Selon la classe : Sacré pour les prêtres et paladins, Nature pour les druides, Eau pour les chamans (Sacré pour les autres). Eau : l'eau entoure votre barre d'incantation, un ruisseau sinueux projette des gouttes, une éclaboussure atterrit ; un bouclier est une bulle d'eau, un soin complet un geyser. Sacré : des étincelles d'or tournoient dans l'icône de votre sort, une comète d'or vole, un flash blanc et une gerbe de rayons atterrissent, des runes s'attardent autour du cadre. Nature : des rubans verts et or entourent votre barre d'incantation, des rubans volent en perdant des feuilles, des feuilles éclatent et montent. Discret : le remplissage de votre barre d'incantation brille, un fin fil de lumière vole, la bordure du cadre s'embrase. Chaque type atterrit à sa façon dans chaque apparence : un soin sur la durée s'infiltre, un bouclier enveloppe le cadre d'une barrière, une protection pose un blason dessus, un soin complet dresse une colonne de lumière, une résurrection illumine le cadre du défunt.", -- draft
-- stale: ["Icon frames and bar backgrounds of the Essential, Utility and Buff cooldown viewers."] = "Les cadres d'icône et les fonds de barre des affichages de temps de recharge essentiels, utilitaires et des améliorations.", -- draft
-- stale: ["Icons stay smooth and sharp at every size and UI scale: each one is drawn from a copy made for its size on your screen."] = "Les icônes restent lisses et nettes à toute taille et échelle : chacune est dessinée depuis une copie faite pour sa taille à l'écran.", -- draft
-- stale: ["Impact Effects: hits flash on your target's nameplate in dungeons too, where the game hides how much a hit did."] = "Effets d'impact : les coups font aussi clignoter la barre de nom de votre cible en donjon, où le jeu cache les dégâts infligés.", -- draft
-- stale: ["In Combat elements come back while you have a target, a friend too."] = "Les éléments En combat reviennent tant que vous avez une cible, même amicale.", -- draft
-- stale: ["In Combat elements come back while you point at them, too. (On Mouseover elements always do.)"] = "Les éléments En combat reviennent aussi quand vous les survolez. (Les éléments Au survol le font toujours.)", -- draft
-- stale: ["In Combat: a bar shows in a fight once it swings or shoots, and fades out when the fight ends (the shot bar also when Auto Shot stops). Always: each bar shows while you carry a weapon for it, at rest between swings."] = "En combat : une barre s'affiche en combat dès qu'elle frappe ou tire, et s'efface à la fin du combat (la barre de tir aussi quand Tir automatique s'arrête). Toujours : chaque barre s'affiche tant que vous portez une arme pour elle, au repos entre les coups.", -- draft
-- stale: ["In a fight"] = "En combat", -- draft
-- stale: ["In a fight the widget shrinks to the speaker's face and its ring, and the reading goes on (a book too). The name and the line come back when the fight is over."] = "En combat, le widget se réduit au visage de l'orateur et à son anneau, et la lecture continue (un livre aussi). Le nom et la ligne reviennent après le combat.", -- draft
-- stale: ["In a fight, one line for the group: the top player at its right end with their value, everyone else a class icon at their share of the top, you the bigger icon with the line filled up to you in your class colour. It fades in when the fight starts and out when it ends. The pointer on it lists everyone. Move it in Edit Layout."] = "En combat, une ligne pour le groupe : le meilleur joueur à son extrémité droite avec sa valeur, chacun des autres une icône de classe à sa part du meilleur, vous la plus grande icône avec la ligne remplie jusqu'à vous dans votre couleur de classe. Elle apparaît au début du combat et s'efface à la fin. Le pointeur dessus liste tout le monde. Déplacez-la dans Modifier la disposition.", -- draft
-- stale: ["In a group fight, a thin bar along the bottom of an enemy's health bar (in the Nameplate Kit's lower rail) fills to the point where it would turn on you: gold while safe, amber when close, red when it is on you. For a tank it turns red when a mob is not on you. Solo it stays away."] = "Dans un combat de groupe, une fine barre au bas de la barre de vie d'un ennemi (dans le rail inférieur du kit des barres d'info) se remplit jusqu'au point où il se tournerait vers vous : doré tant que c'est sûr, ambre quand c'est proche, rouge quand il est sur vous. Pour un tank, elle devient rouge quand un monstre n'est pas sur lui. En solo, elle reste à l'écart.", -- draft
-- stale: ["In a group fight, only when it matters: close to pulling your target (\"Ease off\") or with it on you (\"Aggro\"), and for a tank the mobs not on you. The ring is your threat against the pull; point at it for the group's threat on your target."] = "Dans un combat de groupe, seulement quand ça compte : près d'attirer votre cible (« Calmez-vous ») ou quand elle est sur vous (« Aggro »), et pour un tank les monstres qui ne sont pas sur lui. L'anneau est votre menace face au seuil ; survolez-le pour la menace du groupe sur votre cible.", -- draft
-- stale: ["In a party: these frames, or MelloUI's normal party frames (the game's party frames with their portraits, in the painted look). With the normal ones, you show as one of them while solo too (Show Yourself While Solo), so you can see your heals and indicators on it. In a raid these frames show. The normal party frames show as the game's Edit Mode sets them: with Raid-Style Party Frames on there, the game shows none of its normal ones."] = "En groupe : ces cadres, ou les cadres de groupe normaux de MelloUI (les cadres de groupe du jeu avec leurs portraits, dans l'aspect peint). Avec les normaux, vous apparaissez aussi parmi eux en solo (Vous afficher en solo), pour voir vos soins et indicateurs dessus. En raid, ces cadres s'affichent. Les cadres de groupe normaux s'affichent comme le mode Édition du jeu les règle : avec Cadres de groupe style raid activé là-bas, le jeu n'en montre aucun normal.", -- draft
-- stale: ["In a party: these frames, or the classic party frames with portraits. In a raid, these frames always show."] = "En groupe : ces cadres, ou les cadres de groupe classiques avec portraits. En raid, ces cadres s'affichent toujours.", -- draft
-- stale: ["In a quest's objective area, with the quest's item in your bags: the item, a ring for the objective's progress and how many you carry. Click it to use the item (out of combat: it folds away in a fight)."] = "Dans la zone d'objectif d'une quête, avec l'objet de la quête dans vos sacs : l'objet, un anneau pour la progression de l'objectif et combien vous en portez. Cliquez pour utiliser l'objet (hors combat : il se replie en combat).", -- draft
-- stale: ["In an inn or a city, and in a town like Sentinel Hill, every reminder stays until it is done (a mailbox opened, the spells or the rank learned ...) or you leave; Not now there waits until you next enter one."] = "Dans une auberge ou une ville, et dans un bourg comme Colline des Sentinelles, chaque rappel reste jusqu'à ce qu'il soit fait (une boîte aux lettres ouverte, les sorts ou le rang appris ...) ou que vous partiez ; Pas maintenant y attend votre prochaine entrée.", -- draft
-- stale: ["In silver: a stack worth this or more is never thrown away (selling it at a vendor still is). 100 silver = 1 gold."] = "En argent : une pile qui vaut ceci ou plus n'est jamais jetée (la vendre chez un vendeur, si). 100 argent = 1 or.", -- draft
-- stale: ["In the box that splits a stack (Shift-click a stack), the mouse wheel changes the amount: up adds one, down takes one, ten at a time while you hold Shift."] = "Dans la boîte qui partage une pile (Maj-clic sur une pile), la molette change la quantité : vers le haut ajoute un, vers le bas en retire un, dix à la fois en maintenant Maj.", -- draft
-- stale: ["Indicators for %s"] = "Indicateurs pour %s", -- draft
-- stale: ["Installer: Keep my layout now keeps your own Edit Mode layout; MelloUI's layout went in all the same."] = "Installation : Garder ma disposition garde maintenant votre propre disposition du mode Édition ; celle de MelloUI était appliquée quand même.", -- draft
-- stale: ["Interrupted casts show only on the Personal Display's cast bar, with their word."] = "Les sorts interrompus ne s'affichent que sur la barre d'incantation de l'affichage personnel, avec leur mot.", -- draft
-- stale: ["Into a fight the bars rise into place; a moment after it they settle a little lower, until the next one. (To fade them out of combat: the Fader.)"] = "En entrant en combat, les barres montent en place ; un instant après, elles se posent un peu plus bas, jusqu'au prochain. (Pour les estomper hors combat : le Fondu.)", -- draft
