-- stale: ["MelloUI's damage meter in place of the game's: three numbers by every frame (this fight, this run, healing), a race bar for the group in a fight, a summary after it and a Fight History window. The game's own damage meter is switched off while it is on, and comes back as you had it when it is off."] = "Le compteur de dégâts de MelloUI à la place de celui du jeu : trois chiffres près de chaque cadre (ce combat, cette sortie, soins), une barre de course pour le groupe en combat, un résumé ensuite et une fenêtre Historique des combats. Le compteur du jeu est désactivé tant que celui-ci est actif, et revient comme vous l'aviez quand il est désactivé.", -- draft
