-- stale: ["On a quest's tooltip in the Quest List, name your other characters who have done the quest or have it in their quest log. A character is noted each time it logs out; /mello alts lists them and forgets a deleted one."] = "Sur l'encadré d'aide d'une quête dans la Liste des quêtes, nomme vos autres personnages qui ont fait la quête ou l'ont dans leur journal. Un personnage est noté à chaque déconnexion ; /mello alts les liste et oublie un personnage supprimé.", -- draft
-- stale: ["On the game's nameplates: the large crowd-control icon above the name, the quest marker on enemies you still need, the threat line, the combo points on your target's plate, the names' form (Show Names As) and the soft shade behind the names (Name Shade). Off: all six go. Works with or without the reskin."] = "Sur les barres d'info du jeu : la grande icône de contrôle au-dessus du nom, le marqueur de quête sur les ennemis qu'il vous faut encore, la ligne de menace, les points de combo sur la barre de votre cible, la forme des noms (Afficher les noms) et l'ombre douce derrière les noms (Ombre des noms). Désactivé : les six disparaissent. Fonctionne avec ou sans l'habillage.", -- draft
-- stale: ["On the target, show only the debuffs you put on it."] = "Sur la cible, n'affiche que les affaiblissements que vous lui avez posés.", -- draft
-- stale: ["On the tooltip of an NPC that takes back one of your quests: \"Turn in here\" once the quest is ready, a quieter \"Quest ends here\" while it is still in progress."] = "Sur l'encadré d'aide d'un PNJ qui reprend l'une de vos quêtes : « Rendre ici » une fois la quête prête, un « La quête finit ici » plus discret tant qu'elle est en cours.", -- draft
-- stale: ["On the tooltip of an item one of your quests asks for, name the quest and how many you have, for example \"Quest: Red Linen Goods (4/6)\"."] = "Sur l'encadré d'aide d'un objet demandé par l'une de vos quêtes, nomme la quête et combien vous en avez, par exemple « Quête : Red Linen Goods (4/6) ».", -- draft
-- stale: ["One cog notch per mouse-wheel step on any list, window or the chat. The game has no wheel sound; this is an addition."] = "Un cran de rouage par pas de molette sur toute liste, fenêtre ou la discussion. Le jeu n'a pas de son de molette ; c'est un ajout.", -- draft
-- stale: ["One look: its own look, Gilded Slate colours, the Fredoka font and a new logo, reskin or not; the installer sets up the new layout. The painted reskin is MelloUI Oldschool."] = "Une apparence : son propre aspect, les couleurs Gilded Slate, la police Fredoka et un nouveau logo, habillage ou non ; l'installateur met en place la nouvelle disposition. L'habillage peint, c'est MelloUI Oldschool.", -- draft
-- stale: ["One seamless map of the whole world: zoom from Azeroth down to a zone with the mouse wheel and drag to look around."] = "Une carte continue du monde entier : zoomez d'Azeroth jusqu'à une zone avec la molette et faites glisser pour regarder autour.", -- draft
-- stale: ["One short line in the upper third of the screen when MelloUI has news for you: a route set or finished, a service remembered, a dungeon's quests listed. It fades after a few seconds. Move it in Edit Layout."] = "Une courte ligne dans le tiers supérieur de l'écran quand MelloUI a du nouveau pour vous : un itinéraire défini ou terminé, un service mémorisé, les quêtes d'un donjon listées. Elle s'efface après quelques secondes. Déplacez-la dans Modifier la disposition.", -- draft
