-- stale: ["Options: shorter, plainer descriptions; the Fader lists all that fades (Focus Frame, FPS too); Dark Mode: one Brightness for the whole UI, icons and text untouched."] = "Options : descriptions plus courtes et plus claires ; le Fondu liste tout ce qui s'estompe (cadre du focus, IPS aussi) ; mode sombre : une seule luminosité pour toute l'interface, icônes et texte intacts.", -- draft
-- stale: ["Options: shorter, plainer descriptions; the Fader lists all that fades (Focus Frame, FPS); Dark Mode: one Brightness for all of MelloUI, all switches on its tab, new: Windows."] = "Options : descriptions plus courtes et plus simples ; le Fondu liste tout ce qui s'estompe (Cadre de focalisation, FPS) ; Mode sombre : une seule Luminosité pour tout MelloUI, tous ses interrupteurs sur son onglet, nouveau : Fenêtres.", -- draft
