-- stale: ["Play the recorded lines of the voice pack, MelloUI_VoicePack (a separate download in two parts that replaces the old pack), when it has one for the quest, greeting or page; the rest is read with text-to-speech unless Read Unvoiced Lines is off. Tick the pack in the addon list; it loads when needed."] = "Joue les lignes enregistrées du pack de voix, MelloUI_VoicePack (un téléchargement à part en deux parties qui remplace l'ancien pack), quand il en a une pour la quête, la salutation ou la page ; le reste est lu en synthèse vocale sauf si Lire les lignes non doublées est désactivé. Cochez le pack dans la liste des add-ons ; il se charge quand il le faut.", -- draft
