-- stale: ["Raid Frames: indicators for %s"] = "Cadres de raid : indicateurs pour %s", -- draft
-- stale: ["Read NPC dialog and quest text aloud with the built in text-to-speech voices, picked by the NPC's race and gender."] = "Lit à voix haute les dialogues des PNJ et le texte des quêtes avec les voix de synthèse vocale intégrées, choisies selon la race et le sexe du PNJ.", -- draft
-- stale: ["Read a book, letter, note, plaque or sign aloud when you open it: the whole book, from the page you open to the last, with no page turning, and it goes on when you close it or walk away. Turning a page reads on from that page; Stop ends it. The narrator's recordings come from the voice pack (MelloUI_VoicePack); without it only the page you see is read, with text-to-speech when Read Unvoiced Lines is on."] = "Lit à voix haute un livre, une lettre, une note, une plaque ou un panneau quand vous l'ouvrez : tout le livre, de la page ouverte à la dernière, sans tourner les pages, et continue quand vous le fermez ou vous éloignez. Tourner une page reprend la lecture depuis cette page ; Arrêter la termine. Les enregistrements du narrateur viennent du pack de voix (MelloUI_VoicePack) ; sans lui seule la page affichée est lue, en synthèse vocale si Lire les lignes non doublées est actif.", -- draft
-- stale: ["Read a quest or greeting the voice pack has no recording of with a text-to-speech voice. Off: only recorded lines are heard and the rest stay silent."] = "Lit avec une voix de synthèse une quête ou une salutation que le pack de voix n'a pas enregistrée. Désactivé : seules les lignes enregistrées s'entendent, le reste reste muet.", -- draft
-- stale: ["Read lines one after another: a greeting finishes before the quest offer that follows it. Off makes every new dialog interrupt the previous one."] = "Lit les lignes l'une après l'autre : une salutation se termine avant l'offre de quête qui suit. Désactivé, chaque nouveau dialogue interrompt le précédent.", -- draft
-- stale: ["Red and larger under 5 s (1.3 times the Text Size), yellow under a minute, dim white and smaller for minutes (0.8 times), grey and smaller still for hours (0.75 times). Off: every timer is white at the Text Size."] = "Rouge et plus grand sous 5 s (1,3 fois la Taille du texte), jaune sous une minute, blanc atténué et plus petit pour les minutes (0,8 fois), gris et encore plus petit pour les heures (0,75 fois). Désactivé : chaque minuteur est blanc à la Taille du texte.", -- draft
-- stale: ["Remember where you walk and fly so routes can follow real roads. What it learns is saved and kept from one session to the next. /route shows how much has been learned."] = "Retient où vous marchez et volez pour que les itinéraires suivent de vraies routes. Ce qui est appris est enregistré et gardé d'une session à l'autre. /route montre ce qui a été appris.", -- draft
-- stale: ["Remind you once this many free bag slots or fewer are left."] = "Vous rappelle dès qu'il ne reste que ce nombre d'emplacements libres ou moins.", -- draft
-- stale: ["Remind you once your most worn piece of gear is down to this much durability."] = "Vous rappelle dès que votre pièce d'équipement la plus usée descend à cette durabilité.", -- draft
-- stale: ["Remind you when Well Fed has two minutes left."] = "Vous rappelle quand il reste deux minutes à Bien nourri.", -- draft
-- stale: ["Remind you when a poison, an oil or a sharpening stone has run out on a weapon, or has two minutes left, while you carry one to put it back on. It stays until it is back on, in fights too; click it to put it back on (out of combat)."] = "Vous rappelle quand un poison, une huile ou une pierre à aiguiser est épuisé sur une arme, ou qu'il lui reste deux minutes, tant que vous en portez un pour le remettre. Il reste jusqu'à ce qu'il soit remis, en combat aussi ; cliquez pour le remettre (hors combat).", -- draft
-- stale: ["Remind you when a trainer has something new for you."] = "Vous rappelle qu'un maître a du nouveau pour vous.", -- draft
-- stale: ["Remind you when mail is waiting for you. It goes once you open a mailbox, and comes back only for mail that arrives after."] = "Vous rappelle qu'un courrier vous attend. Il part dès que vous ouvrez une boîte aux lettres, et ne revient que pour le courrier arrivé ensuite.", -- draft
-- stale: ["Remind you when one of your own buffs is missing on you: Arcane Intellect and a mage's armor, Fortitude, Inner Fire and Divine Spirit, Mark of the Wild, a warlock's armor. Only buffs you can cast. It stays until the buff is back, in fights too (the game hides buffs in a fight, so one lost there shows after it); click it to cast (out of combat)."] = "Vous rappelle quand l'une de vos propres améliorations vous manque : Intelligence des Arcanes et l'armure d'un mage, Robustesse, Feu intérieur et Esprit divin, Marque du fauve, l'armure d'un démoniste. Seulement les améliorations que vous pouvez lancer. Il reste jusqu'au retour de l'amélioration, en combat aussi (le jeu cache les améliorations en combat, une perdue là s'affiche après) ; cliquez pour la lancer (hors combat).", -- draft
-- stale: ["Remind you when people in your group are missing a buff you can cast (Arcane Intellect and Divine Spirit only on those who use mana); point at it for their names. It stays until they have it, in fights too; click it to cast it on them, one by one (out of combat)."] = "Vous rappelle quand des membres de votre groupe n'ont pas une amélioration que vous pouvez lancer (Intelligence des Arcanes et Esprit divin seulement sur ceux qui utilisent le mana) ; survolez-le pour leurs noms. Il reste jusqu'à ce qu'ils l'aient, en combat aussi ; cliquez pour la leur lancer, un par un (hors combat).", -- draft
-- stale: ["Remind you when you have talent points to spend."] = "Vous rappelle que vous avez des points de talent à dépenser.", -- draft
-- stale: ["Remind you when your bags are almost full; it stays, in a fight too, until you make room. Click it for the way to the nearest vendor."] = "Vous rappelle que vos sacs sont presque pleins ; il reste, en combat aussi, jusqu'à ce que vous fassiez de la place. Cliquez pour le chemin vers le vendeur le plus proche.", -- draft
