-- stale: ["Route follows Polestar: its step in the tracker and on the map, one arrow and one route; its own features go first. The World Marker and the route agree on item-first quests."] = "L'Itinéraire suit Polestar : son étape dans le suivi et sur la carte, une flèche et un itinéraire ; ses propres fonctions passent d'abord. Le Marqueur du monde et l'itinéraire s'accordent sur les quêtes qui commencent par un objet.", -- draft
-- stale: ["Route takes far less memory while its roads go in and while it finds routes."] = "Route prend bien moins de mémoire pendant le chargement des routes et la recherche d'itinéraires.", -- draft
