-- stale: ["Small live widgets in one column: loot rolls, the way back to your corpse, timed quests, summons, resurrect offers, ready checks, whispers, your pet, the auction house, crafting batches, profession cooldowns, quest items and a healer drinking. And more reminders by your portrait: bags, talents, Well Fed, weapon poisons and oils, your buffs."] = "De petits widgets en direct dans une colonne : jets de butin, le chemin vers votre corps, quêtes à durée limitée, invocations, offres de résurrection, appels, chuchotements, votre familier, l'hôtel des ventes, fabrications en série, temps de recharge de métier, objets de quête et un soigneur qui boit. Et d'autres rappels près de votre portrait : sacs, talents, Bien nourri, poisons et huiles d'arme, vos améliorations.", -- draft
