-- stale: ["The bag window's money rolls to its new sum when it changes (selling, buying, a repair, a quest) instead of jumping there: warm while it goes up, red while it goes down. Not with Reduce Motion."] = "L'argent de la fenêtre de sacs défile jusqu'à sa nouvelle somme quand il change (vente, achat, réparation, quête) au lieu d'y sauter : chaud quand il monte, rouge quand il descend. Pas avec Réduire les animations.", -- draft
-- stale: ["The bar as the rows above lay it out. Saved into your Edit Mode layout when you let a slider go (in a fight, when it ends); the bar itself changes after a reload."] = "La barre telle que les lignes ci-dessus la disposent. Enregistrée dans votre disposition du mode Édition quand vous lâchez un curseur (en combat, à sa fin) ; la barre elle-même change après un rechargement.", -- draft
-- stale: ["The bar the rows below set: its rows, icons, icon size and padding, saved into your active Edit Mode layout as Edit Mode saves them, once you let a slider go (out of combat). The game shows them after a reload: type /reload (MelloUI says so once). One of the game's preset layouts is copied first: you are asked once."] = "La barre que règlent les lignes ci-dessous : ses rangées, icônes, taille d'icône et espacement, enregistrés dans votre disposition active du mode Édition comme celui-ci les enregistre, dès que vous lâchez un curseur (hors combat). Le jeu les affiche après un rechargement : tapez /reload (MelloUI le dit une fois). Une des dispositions prédéfinies du jeu est d'abord copiée : la question est posée une fois.", -- draft
-- stale: ["The bars glide to a new value instead of jumping."] = "Les barres glissent vers une nouvelle valeur au lieu de sauter.", -- draft
-- stale: ["The bars of your experience and the reputation you watch. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "Les barres de votre expérience et de la réputation suivie. Toujours : jamais estompé. En combat : estompé hors combat, de retour en combat. Au survol : estompé en permanence, affiché quand vous le survolez.", -- draft
-- stale: ["The bars under your character and the shield column beside it (Personal Display). In Combat, they also come back while you cast. (No On Mouseover: the pointer passes through them to the world.) Always: never faded. In Combat: faded out of combat, back in a fight."] = "Les barres sous votre personnage et la colonne de bouclier à côté (Affichage personnel). En combat, elles reviennent aussi pendant que vous incantez. (Pas d'Au survol : le pointeur les traverse vers le monde.) Toujours : jamais estompé. En combat : estompé hors combat, de retour en combat.", -- draft
-- stale: ["The border of the backdrop round the action bars (and the experience and reputation bars): the red or iron gems on its corners, or one of the border styles of Oldschool > Borders (drawn heavy, its inner corners mitred). Each element's backdrop is switched on on Bars (its Backdrop); switched-on elements placed together share one backdrop, in the look of the first of them: Action Bar 1, the other bars, the micro menu, the bag bar."] = "La bordure du fond autour des barres d'actions (et des barres d'expérience et de réputation) : les gemmes rouges ou de fer à ses coins, ou l'un des styles de bordure d'Oldschool > Bordures (dessiné épais, ses coins intérieurs biseautés). Le fond de chaque élément s'active dans Barres (son Fond) ; les éléments activés placés ensemble partagent un fond, à l'apparence du premier d'entre eux : barre d'actions 1, les autres barres, le micro-menu, la barre de sacs.", -- draft
-- stale: ["The border of the backdrop round the bag bar: the red or iron gems on its corners, or one of the border styles of Oldschool > Borders (drawn heavy, its inner corners mitred). Each element's backdrop is switched on on Bars (its Backdrop); switched-on elements placed together share one backdrop, in the look of the first of them: Action Bar 1, the other bars, the micro menu, the bag bar."] = "La bordure du fond autour de la barre de sacs : les gemmes rouges ou de fer à ses coins, ou l'un des styles de bordure d'Oldschool > Bordures (dessiné épais, ses coins intérieurs biseautés). Le fond de chaque élément s'active dans Barres (son Fond) ; les éléments activés placés ensemble partagent un fond, à l'apparence du premier d'entre eux : barre d'actions 1, les autres barres, le micro-menu, la barre de sacs.", -- draft
-- stale: ["The border of the backdrop round the micro menu: the red or iron gems on its corners, or one of the border styles of Oldschool > Borders (drawn heavy, its inner corners mitred). Each element's backdrop is switched on on Bars (its Backdrop); switched-on elements placed together share one backdrop, in the look of the first of them: Action Bar 1, the other bars, the micro menu, the bag bar."] = "La bordure du fond autour du micro-menu : les gemmes rouges ou de fer à ses coins, ou l'un des styles de bordure d'Oldschool > Bordures (dessiné épais, ses coins intérieurs biseautés). Le fond de chaque élément s'active dans Barres (son Fond) ; les éléments activés placés ensemble partagent un fond, à l'apparence du premier d'entre eux : barre d'actions 1, les autres barres, le micro-menu, la barre de sacs.", -- draft
-- stale: ["The border on each raid frame and raid-style party frame: the Single rail they wear today, one of the thin rims the buttons wear, or the Backdrop, its corner gems in the colour of the action bars' Backdrop."] = "La bordure de chaque fenêtre de raid et cadre de groupe en style raid : le rail simple qu'ils portent aujourd'hui, l'un des contours fins des boutons, ou le fond, ses gemmes d'angle de la couleur du fond des barres d'actions.", -- draft
-- stale: ["The border round the square map: the windows' frame with its gem corners, a single iron rail, the action bars' heavy frame with red or iron gems, one of the thin rims the buttons wear (drawn heavier, at the map's size), or none. Picked with pictures on the Minimap page, its Border part. The painted borders need the painted Minimap skin (Oldschool); without it the map wears the Chat panel."] = "La bordure autour de la carte carrée : le cadre des fenêtres avec ses coins de gemmes, un rail de fer simple, le cadre lourd des barres d'actions avec des gemmes rouges ou de fer, l'un des fins bords des boutons (dessiné plus épais, à la taille de la carte), ou aucune. Choisie avec des images sur la page Minicarte, sa partie Bordure. Les bordures peintes nécessitent l'habillage peint de la minicarte (Oldschool) ; sans lui, la carte porte le panneau de discussion.", -- draft
-- stale: ["The buffs you give yourself on a cooldown -- Shield Wall, Shield Block, Last Stand, Evasion, Ice Block, Recklessness, a trinket's -- as icons above the health bar, their time sweeping round them and their seconds on them, the most important first: an immunity, then damage taken down, more health, block, evasion, the rest. From the game's own spell data, for every class."] = "Les améliorations que vous vous donnez avec un temps de recharge -- Mur protecteur, Maîtrise du blocage, Dernier rempart, Évasion, Bloc de glace, Témérité, celle d'un bijou -- en icônes au-dessus de la barre de vie, leur temps tournant autour d'elles et leurs secondes dessus, les plus importantes d'abord : une immunité, puis dégâts subis réduits, plus de vie, blocage, évasion, le reste. D'après les données de sorts du jeu, pour chaque classe.", -- draft
-- stale: ["The character window on a parchment sheet, its text in dark ink: Right pane lays it under the right pane (the stats, reputation, skills and the other lists); Whole window over the whole window inside its frame, the window's own stone round its edge. Off: no parchment; the window shows its Window Background (Windows > Character window)."] = "La fenêtre du personnage sur une feuille de parchemin, son texte à l'encre sombre : « Volet droit » la pose sous le volet droit (les caractéristiques, la réputation, les compétences et les autres listes) ; « Fenêtre entière » sur toute la fenêtre dans son cadre, la pierre de la fenêtre autour de son bord. Désactivé : pas de parchemin ; la fenêtre montre son fond (Fenêtres > Fenêtre du personnage).", -- draft
-- stale: ["The chat and whisper windows' text on their parchment sheet, relative to the chat's own size."] = "Le texte des fenêtres de discussion et de chuchotement sur leur feuille de parchemin, par rapport à la taille de la discussion.", -- draft
-- stale: ["The chat input box shows only while you type: Enter (or /) brings it up, and it goes again once you send the line or press Escape. It sets the game's Chat Style to Classic while on, and gives your own back when off. The change shows from the next line you type."] = "La zone de saisie ne s'affiche que pendant que vous écrivez : Entrée (ou /) la fait apparaître, et elle repart une fois la ligne envoyée ou Échap pressé. Règle le Style de discussion du jeu sur Classique tant que c'est actif, et rend le vôtre une fois désactivé. Le changement se voit dès la prochaine ligne écrite.", -- draft
-- stale: ["The chat on a parchment sheet, its text in dark ink: the Minimal Chat View and its whisper window with the reskin on or off; the game's chat windows with the painted chat (its Painted Skin, the reskin on)."] = "La discussion sur une feuille de parchemin, son texte à l'encre sombre : la vue de discussion minimale et sa fenêtre de chuchotements, avec ou sans l'habillage ; les fenêtres de discussion du jeu avec la discussion peinte (son habillage peint, l'habillage activé).", -- draft
-- stale: ["The chat windows (on top of the game's own chat font size) and every number."] = "Les fenêtres de discussion (en plus de la taille de police de discussion du jeu) et chaque chiffre.", -- draft
-- stale: ["The chat windows and whisper windows while they lie on their parchment sheet (Oldschool > Parchment). By default the chat text's face in its semibold cut where it has one, heavier so the dark ink reads on the paper; each Font Style sets that cut of its reading face."] = "Les fenêtres de discussion et de chuchotement tant qu'elles reposent sur leur feuille de parchemin (Oldschool > Parchemin). Par défaut la police du texte de discussion en demi-gras quand elle en a un, plus épaisse pour que l'encre sombre se lise sur le papier ; chaque style de police règle cette graisse de sa police de lecture.", -- draft
-- stale: ["The chat windows with their tabs, buttons, the Friends button and the line you type in. They come back while you type. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "Les fenêtres de discussion avec leurs onglets, boutons, le bouton Contacts et la ligne de saisie. Elles reviennent pendant que vous écrivez. Toujours : jamais estompé. En combat : estompé hors combat, de retour en combat. Au survol : estompé en permanence, affiché quand vous le survolez.", -- draft
-- stale: ["The chat windows' background: a dark panel of the palette behind the window, its tabs and its input box (Dark), the game's own (Game), or none at all (None). Under the painted chat (its Painted Skin, the reskin on) its stone instead. With the Minimal Chat View: None leaves its panel clear, Dark and Game keep its dark panel; Parchment lays the parchment sheet over it."] = "Le fond des fenêtres de discussion : un panneau sombre de la palette derrière la fenêtre, ses onglets et sa zone de saisie (Sombre), celui du jeu (Jeu), ou aucun (Aucun). Sous la discussion peinte (son Habillage peint, l'habillage actif), sa pierre à la place. Avec la Vue Minimale : Aucun laisse son panneau dégagé, Sombre et Jeu gardent son panneau sombre ; Parchemin pose la feuille de parchemin dessus.", -- draft
-- stale: ["The chat windows' messages, the chat's input box and the whisper windows. The same face as the Interface text unless you choose otherwise (the Chat & numbers face while that is the game's), so the chat follows the Font Styles and your own choice of reading face. The size stays the chat's own (Chat & numbers size)."] = "Les messages des fenêtres de discussion, la zone de saisie et les fenêtres de chuchotement. La même police que le Texte de l'interface sauf autre choix (la police Discussion et chiffres tant que celle-ci est celle du jeu), pour que la discussion suive les styles de police et votre propre police de lecture. La taille reste celle de la discussion (taille Discussion et chiffres).", -- draft
-- stale: ["The chat's background: Dark, the game's own, or none."] = "Le fond de la discussion : Sombre, celui du jeu ou aucun.", -- draft
-- stale: ["The chosen health bar colour wins over the game's own recolouring of health bars (the aggro / threat display on nameplates and unit frames): whenever the game sets its colour, yours is put back. Off: the game's threat colours show."] = "La couleur de barre de vie choisie l'emporte sur la recoloration du jeu (l'affichage d'aggro / de menace sur les barres d'info et les portraits d'unités) : chaque fois que le jeu pose sa couleur, la vôtre est remise. Désactivé : les couleurs de menace du jeu s'affichent.", -- draft
-- stale: ["The colour behind the health bar with My Colour."] = "La couleur derrière la barre de vie avec Ma couleur.", -- draft
-- stale: ["The colour behind the health bar: one of yours, or the member's class colour."] = "La couleur derrière la barre de vie : l'une des vôtres, ou la couleur de classe du membre.", -- draft
-- stale: ["The colours of all the painted art (frames, headers, rows, buttons, slots, bars). With the Ember and Ember Vibrant palettes: Warm iron (the metal in warm browns), Bronze (warm browns with gold bevels), or the Original painted grey iron and bright red. With any other palette: that palette's own colours, or the Original. Pictures keep their own colours."] = "Les couleurs de tous les graphismes peints (cadres, en-têtes, rangées, boutons, emplacements, barres). Avec les palettes Ember et Ember Vibrant : Fer chaud (le métal en bruns chauds), Bronze (bruns chauds aux biseaux dorés) ou le fer gris peint d'origine et le rouge vif. Avec toute autre palette : les couleurs de cette palette, ou l'Original. Les images gardent leurs propres couleurs.", -- draft
-- stale: ["The column of widgets: loot rolls, summons, Voice Over, whispers and the rest. A new one does not bring the column back: In Combat keeps a loot roll, a summons or a whisper faded out of combat, On Mouseover until you point at the column. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "La colonne de widgets : jets de butin, invocations, Voice Over, chuchotements et le reste. Un nouveau ne fait pas revenir la colonne : En combat garde un jet de butin, une invocation ou un chuchotement estompé hors combat, Au survol jusqu'à ce que vous survoliez la colonne. Toujours : jamais estompé. En combat : estompé hors combat, de retour en combat. Au survol : estompé en permanence, affiché quand vous le survolez.", -- draft
-- stale: ["The configurator's frame previews stand on the left with room around them; the settings sit beside them."] = "Les aperçus de cadres du configurateur se placent à gauche avec de l'espace autour ; les réglages à côté.", -- draft
-- stale: ["The configurator's side list starts with Home, has a thin scroll bar, and its tooltips no longer cover the page."] = "La liste latérale du configurateur commence par Accueil, a une fine barre de défilement, et ses infobulles ne couvrent plus la page.", -- draft
-- stale: ["The configurator: one painted window per skin that moves a little while open (Oldschool's in ink on parchment); Quality of Life holds Automation, Screen Text, Reminders and Tooltip."] = "Le configurateur : une fenêtre peinte par habillage qui bouge un peu quand elle est ouverte (celle d'Oldschool à l'encre sur parchemin) ; Confort réunit Automatisation, Texte à l'écran, Rappels et Encadré d'aide.", -- draft
