-- stale: ["The display keeps its place by your character as you zoom the camera: closer under your feet when you zoom out, further down when you zoom in, so it never covers your character. Place it in Edit Layout at the zoom you play at; it follows from there. Turning the camera up or down is not followed (the game does not tell)."] = "L'affichage garde sa place près de votre personnage quand vous zoomez : plus près de vos pieds en dézoomant, plus bas en zoomant, pour ne jamais couvrir votre personnage. Placez-le dans Modifier la disposition au zoom où vous jouez ; il suit à partir de là. L'inclinaison de la caméra n'est pas suivie (le jeu ne la donne pas).", -- draft
-- stale: ["The experience and reputation bars in MelloUI's look: a slim iron frame with gold diamond ends, a dark track, the notches between the bar's parts and a soft light on the filling edge. Off: the game's own frame. The painted skin's bars keep their own (Oldschool)."] = "Les barres d'expérience et de réputation à l'apparence de MelloUI : un fin cadre de fer aux extrémités en losange doré, une piste sombre, les encoches entre les parties de la barre et une lumière douce sur le bord qui se remplit. Désactivé : le cadre du jeu. Les barres de l'habillage peint gardent le leur (Oldschool).", -- draft
-- stale: ["The face of every indicator's time and stacks. Shared: the Chat & numbers face (Look > Fonts)."] = "La police du temps et des cumuls de chaque indicateur. Partagée : la police Discussion et chiffres (Apparence > Polices).", -- draft
