-- stale: ["The face of the health and power values on the player, target and focus frames. Shared: the Interface text's face (Look > Fonts)."] = "La police des valeurs de vie et de ressource sur les portraits du joueur, de la cible et de la focalisation. Partagée : la police du Texte de l'interface (Apparence > Polices).", -- draft
