-- stale: ["The face of the names on your party and raid frames. Shared: the Interface text's face (Look > Fonts)."] = "La police des noms sur vos cadres de groupe et de raid. Partagée : la police du Texte de l'interface (Apparence > Polices).", -- draft
-- stale: ["The face of the time and stacks on MelloUI's buffs and debuffs: yours, the target's and the nameplates'. Shared: the Chat & numbers face (Look > Fonts)."] = "La police du temps et des cumuls sur les améliorations et affaiblissements de MelloUI : les vôtres, ceux de la cible et ceux des barres d'info. Partagée : la police Discussion et chiffres (Apparence > Polices).", -- draft
