-- stale: ["The fill of nameplate health and cast bars: Shared (the Look page's Bar Texture), the game's own art, or a picture of their own."] = "Le remplissage des barres de vie et d'incantation des barres d'info : Partagée (la Texture des barres de la page Apparence), l'art du jeu, ou une image à elles.", -- draft
