-- stale: ["The fill of the Personal Display's health, power and shield bars under your character (and the game's own personal resource display while the Personal Display is off): Shared, Plain, or a picture of their own."] = "Le remplissage des barres de vie, de ressource et de bouclier de l'Affichage personnel sous votre personnage (et de l'affichage des ressources personnelles du jeu tant que l'Affichage personnel est désactivé) : Partagée, Unie, ou une image à elles.", -- draft
-- stale: ["The fill of the experience, reputation and honor bars, and the damage meter's race bar and Fight History's bars (Minimalist there on The game's): Shared, the game's own art, or a picture of their own."] = "Le remplissage des barres d'expérience, de réputation et d'honneur, de la barre de course du compteur de dégâts et des barres de l'Historique des combats (Minimaliste pour Celle du jeu) : Partagée, l'art du jeu, ou une image à elles.", -- draft
