-- stale: ["The fill of the health bar under a unit's tooltip (when Tooltip's Hide Health Bar is off): Shared, the game's own art, or a picture of its own."] = "Le remplissage de la barre de vie sous l'encadré d'aide d'une unité (quand Masquer la barre de vie de l'encadré d'aide est désactivé) : Partagée, l'art du jeu, ou une image à elle.", -- draft
-- stale: ["The fill of the player, pet, target, focus and boss cast bars, and MelloUI's swing timers (Minimalist there on The game's): Shared, the game's own art, or a picture of their own."] = "Le remplissage des barres d'incantation du joueur, du familier, de la cible, de la focalisation et des boss, et des minuteurs d'attaque de MelloUI (Minimaliste pour Celle du jeu) : Partagée, l'art du jeu, ou une image à elles.", -- draft
-- stale: ["The finish of health and mana bars (flat, smooth, glossy, minimalist) and their colours; the fill under the kit's brackets."] = "La finition des barres de vie et de mana (plate, lisse, brillante, minimaliste) et leurs couleurs ; le remplissage sous les supports du kit.", -- draft
-- stale: ["The fonts and sizes used by the whole interface. Off: the game's own fonts."] = "Les polices et tailles de toute l'interface. Désactivé : les polices du jeu.", -- draft
-- stale: ["The frame round every progress bar: reputation and skills, the professions' ranks, legacy, guild, experience, the tracker's, the tooltip's and the damage meter's. The unit frames, the nameplates, the cast bar, the swing timers and the Personal Display have a border of their own."] = "Le cadre autour de chaque barre de progression : réputation et compétences, rangs des métiers, héritage, guilde, expérience, celles du suivi, de l'encadré d'aide et du compteur de dégâts. Les portraits d'unités, les barres d'info, la barre de sorts, les minuteurs d'attaque et l'Affichage personnel ont leur propre bordure.", -- draft
-- stale: ["The frame round every window: a thin stone rail on the window's edge, or the double rail with gem corners. Windows already opened change after a /reload."] = "Le cadre autour de chaque fenêtre : un fin rail de pierre sur le bord de la fenêtre, ou le double rail aux coins de gemmes. Les fenêtres déjà ouvertes changent après un /reload.", -- draft
-- stale: ["The frame round the Personal Display's bars and its shield column (the bars under your character): the Ornate bracket the unit frames wear (the default), the cast bar's, a thin rim, the Single rail, the Stone rail, the Backdrop or none. The game's own personal resource display, while the Personal Display is off and the unit frames wear their Painted Skin, takes one frame round its bars: a thin rim or one of the library's styles."] = "Le cadre autour des barres de l'Affichage personnel et de sa colonne de bouclier (les barres sous votre personnage) : la monture ornée des portraits d'unités (par défaut), celle de la barre de sorts, un contour fin, le rail simple, le rail de pierre, le fond ou aucun. L'affichage des ressources personnelles du jeu, tant que l'Affichage personnel est désactivé et que les portraits d'unités portent leur habillage peint, reçoit un cadre autour de ses barres : un contour fin ou l'un des styles de la bibliothèque.", -- draft
-- stale: ["The frame round the nameplates' health bars."] = "Le cadre autour des barres de vie des barres d'info.", -- draft
-- stale: ["The frame round the unit frames' health and power bars (player, target, focus, pet, party): the Ornate bracket they wear by default, the cast bar's, a thin rim, the Single rail or the Backdrop."] = "Le cadre autour des barres de vie et de ressource des portraits d'unités (joueur, cible, focalisation, familier, groupe) : la monture ornée qu'ils portent par défaut, celle de la barre de sorts, un contour fin, le rail simple ou le fond.", -- draft
-- stale: ["The frame round your cast bar: the Cast bar bracket with its gem clusters (today's), a thin rim, the Single rail or the Backdrop. A frame laid round the bar leaves it its whole width."] = "Le cadre autour de votre barre de sorts : la monture de la barre de sorts avec ses grappes de gemmes (l'actuelle), un contour fin, le rail simple ou le fond. Un cadre posé autour de la barre lui laisse toute sa largeur.", -- draft
-- stale: ["The game volume slider the sounds follow."] = "Le curseur de volume du jeu que suivent les sons.", -- draft
-- stale: ["The game's chat buttons in their column left of the chat: Friends at the top, Channels, the chat menu (Say, Party, Guild, Yell, whisper and reply, emotes, and the language you speak). While you speak more than one language, the one you speak shows at the right end of the line you type in. Off: the column is hidden."] = "Les boutons de discussion du jeu dans leur colonne à gauche de la discussion : Contacts en haut, Canaux, le menu de discussion (Dire, Groupe, Guilde, Crier, chuchoter et répondre, emotes, et la langue que vous parlez). Si vous parlez plus d'une langue, celle que vous parlez s'affiche au bout droit de la ligne de saisie. Désactivé : la colonne est masquée.", -- draft
