-- stale: ["The game's own objective tracker. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "Le suivi des objectifs du jeu. Toujours : jamais estompé. En combat : estompé hors combat, de retour en combat. Au survol : estompé en permanence, affiché quand vous le survolez.", -- draft
-- stale: ["The game's sparkle on quest items you can loot, kept on through its graphics presets, and golden glints over the ore veins and herbs you walk up to: dim out of reach, bright in reach, grey when your skill is too low. The game settings it needs come back as you had them when it is off."] = "L'étincelle du jeu sur les objets de quête que vous pouvez ramasser, maintenue malgré ses préréglages graphiques, et des reflets dorés sur les filons et les herbes dont vous approchez : pâles hors de portée, vifs à portée, gris si votre compétence est trop basse. Les réglages du jeu nécessaires reviennent comme vous les aviez quand c'est désactivé.", -- draft
-- stale: ["The game's windows and HUD dressed in the painted kit, and the frame of MelloUI's own windows. Off: the game's windows and HUD keep the game's own art; MelloUI's own parts (the Quest Tracker, the widget column, the reminders, the race bar ...) keep MelloUI's look either way, and every feature keeps working. Switching it on also switches Custom Sounds on, and the first time puts in the Edit Mode layout the reskin is drawn for, fitted to your screen. Switching it off leaves Custom Sounds on."] = "Les fenêtres et l'ATH du jeu habillés du kit peint, ainsi que le cadre des fenêtres de MelloUI. Désactivé : les fenêtres et l'ATH du jeu gardent leurs propres graphismes ; les éléments de MelloUI (le suivi des quêtes, la colonne de widgets, les rappels, la barre de course...) gardent l'apparence de MelloUI dans tous les cas, et chaque fonction continue de marcher. L'activer active aussi les Sons personnalisés et, la première fois, installe la disposition du mode Édition pour laquelle l'habillage est dessiné, ajustée à votre écran. Le désactiver laisse les Sons personnalisés activés.", -- draft
-- stale: ["The game's windows and HUD dressed in the painted kit. Off: they keep the game's own art; MelloUI's own parts keep its look, and the features you switch on keep working."] = "Les fenêtres et le HUD du jeu habillés du kit peint. Désactivé : ils gardent l'art du jeu ; les parties de MelloUI gardent son apparence, et les fonctions activées continuent de marcher.", -- draft
