-- stale: ["The heals on their way to a unit shown on its health bar: your heals, other healers' heals and shields. On the player, target and focus frames and their targets; the party, pet and raid frames show the game's own (the raid frames' Display Incoming Heals)."] = "Les soins en route vers une unité, affichés sur sa barre de vie : vos soins, ceux des autres soigneurs et les boucliers. Sur les cadres du joueur, de la cible et de la focalisation et leurs cibles ; les cadres de groupe, de familier et de raid affichent ceux du jeu (Afficher les soins entrants des cadres de raid).", -- draft
