-- stale: ["The numbers of the damage you deal, over the enemies. Game: the game's own numbers, as always. Rise, Beside, Fan or Stack: drawn by MelloUI at each enemy's nameplate in its soft look, the game's numbers switched off meanwhile: crits gold and bigger, spells violet, a dodge or parry as a word, about a second and a half each, only on enemies you or your pet are fighting. Beside starts them at the plate's right end, so the name stays readable. Rise, Beside, Fan and Stack draw your hits while you play solo. In a group, or where the game keeps threat hidden, the game's own numbers show, because only they know whose hit it is. With enemy nameplates off, the game's own numbers show too (the plates are where MelloUI draws)."] = "Les chiffres des dégâts que vous infligez, au-dessus des ennemis. Jeu : les chiffres du jeu, comme toujours. Montée, À côté, Éventail ou Pile : dessinés par MelloUI à la barre d'info de chaque ennemi dans son aspect doux, les chiffres du jeu désactivés pendant ce temps : critiques dorés et plus grands, sorts violets, une esquive ou une parade en mot, environ une seconde et demie chacun, seulement sur les ennemis que vous ou votre familier combattez. À côté les fait partir du bout droit de la barre d'info, pour que le nom reste lisible. Montée, À côté, Éventail et Pile dessinent vos coups quand vous jouez seul. En groupe, ou là où le jeu cache la menace, les chiffres du jeu s'affichent, car eux seuls savent à qui est le coup. Avec les barres d'info ennemies désactivées, les chiffres du jeu s'affichent aussi (MelloUI dessine sur les barres d'info).", -- draft
-- stale: ["The numbers of your damage over the enemies (the game's own setting: drawn by the game in the Game Numbers Font, at Numbers Over Enemies' size)."] = "Les chiffres de vos dégâts au-dessus des ennemis (le réglage du jeu : dessinés par le jeu dans la Police des chiffres du jeu, à la taille de Chiffres au-dessus des ennemis).", -- draft
-- stale: ["The numbers of your healing over the ones you heal (the game's own setting)."] = "Les chiffres de vos soins au-dessus de ceux que vous soignez (le réglage du jeu).", -- draft
-- stale: ["The numbers over the enemies: the game's own (after /reload) and Your Damage's (at once); and the hit numbers on the unit frames' portraits. The game's text around you (Combat Text's Game style) and MelloUI's are drawn in the Interface text face."] = "Les chiffres au-dessus des ennemis : ceux du jeu (après /reload) et ceux de Vos dégâts (aussitôt) ; et les chiffres de coups sur les portraits d'unités. Le texte du jeu autour de vous (style Jeu du Texte de combat) et celui de MelloUI sont dessinés dans la police du Texte de l'interface.", -- draft
-- stale: ["The numbers: cooldown counts, stack counts; and the chat windows while Chat text and Interface text both keep the game's. The value text on the unit frames' bars follows the Interface text, the hit numbers on the portraits the Game Numbers Font."] = "Les chiffres : décomptes des temps de recharge, nombres de piles ; et les fenêtres de discussion tant que Texte de discussion et Texte de l'interface gardent tous deux celle du jeu. Le texte des valeurs sur les barres des portraits d'unités suit le Texte de l'interface, les chiffres de coups sur les portraits la Police des chiffres du jeu.", -- draft
-- stale: ["The order inside each kind: better quality first, by name, the ones you picked up last first, or the highest item level first."] = "L'ordre dans chaque type : meilleure qualité d'abord, par nom, les derniers ramassés d'abord, ou le plus haut niveau d'objet d'abord.", -- draft
-- stale: ["The order of the party's frames: tanks, then healers, then damage; the game's group order; or by name."] = "L'ordre des cadres du groupe : tanks, puis soigneurs, puis dégâts ; l'ordre du groupe du jeu ; ou par nom.", -- draft
-- stale: ["The painted Minimap skin's shape (Oldschool): Round, the map in the painted ring, or Square, the whole square map in the border Square Border picks. Without the painted skin the map is square."] = "La forme de l'habillage peint de la minicarte (Oldschool) : Ronde, la carte dans l'anneau peint, ou Carrée, toute la carte carrée dans la bordure choisie par Bordure carrée. Sans l'habillage peint, la carte est carrée.", -- draft
-- stale: ["The painted kit reskin, area by area, and the interface's features: buffs and debuffs, error messages, cooldowns, unit frames, chat, tooltips, fonts, dark mode and more. The look is chosen on the Look page and on each element's own page."] = "L'habillage peint du kit, zone par zone, et les fonctions de l'interface : améliorations et affaiblissements, messages d'erreur, temps de recharge, portraits d'unités, discussion, encadrés d'aide, polices, mode sombre et plus encore. L'apparence se choisit sur la page Apparence et sur la page de chaque élément.", -- draft
-- stale: ["The painted look and its choices"] = "L'aspect peint et ses choix", -- draft
-- stale: ["The painted look and layout. Features stay off."] = "L'aspect peint et la disposition. Les fonctions restent désactivées.", -- draft
-- stale: ["The painted reskin AND every feature of UI Modifications: Vendor, Error Messages, Cooldown Timers, Nameplate Tweaks, Chat, Tooltip, Fonts, Dark Mode, Bar Textures, Buffs & Debuffs, Unit Frame Tweaks, FPS / Latency, Class Icons, Bar Values, the game windows' skins, hiding the micro menu, the bag bar and the minimap coordinates, and the world text scale. Off: all of them are off, Edit Layout lets go of the game's windows (they go back to the game's own places), Windows Fade In stops, names are shown in full and Class Coloured Names stops. The palette, the UI Shade, Reduce Motion and MelloUI's notices keep working."] = "L'habillage peint ET chaque fonction des Réglages UI : Marchand, Messages d'erreur, Minuteurs de recharge, Réglages des barres d'info, Discussion, Encadrés d'aide, Polices, Mode sombre, Textures des barres, Améliorations et affaiblissements, Réglages des portraits d'unités, IPS / Latence, Icônes de classe, Valeurs des barres, les habillages des fenêtres du jeu, le masquage du micro-menu, de la barre de sacs et des coordonnées de la minicarte, et l'échelle du texte du monde. Désactivé : tout est désactivé, Modifier la disposition lâche les fenêtres du jeu (elles retournent à leurs places), Les fenêtres apparaissent en fondu s'arrête, les noms s'affichent en entier et Noms aux couleurs de classe s'arrête. La palette, l'Ombre de l'interface, Réduire les animations et les avis de MelloUI continuent.", -- draft
-- stale: ["The painted reskin and MelloUI's interface features: Vendor, Error Messages, Nameplate Tweaks, Unit Frame Tweaks, Chat, Tooltip, Fonts, Dark Mode, Bar Textures and FPS / Latency, and hiding the micro menu, bag bar and minimap coordinates. Off: all of them stop, and Edit Layout lets go of the game's windows; the palette, the UI Shade, Reduce Motion and the notices keep working."] = "L'habillage peint et les fonctions d'interface de MelloUI : Vendeur, Messages d'erreur, retouches des barres d'info et des cadres d'unité, Discussion, Encadré d'aide, Polices, Mode sombre, Textures de barres et IPS / latence, plus le masquage du micro-menu, de la barre de sacs et des coordonnées de la minicarte. Désactivé : tout s'arrête et Modifier la disposition lâche les fenêtres du jeu ; la palette, l'ombre de l'interface, Réduire les animations et les notifications continuent.", -- draft
-- stale: ["The painted reskin is switched off; your bars and layout stay as they are"] = "L'habillage peint est désactivé ; vos barres et disposition restent", -- draft
-- stale: ["The painted reskin's colours: its art, and MelloUI's own windows and parts while it dresses. Without it MelloUI wears its modern palette, Gilded Slate. Your choice applies at once."] = "Les couleurs de l'habillage peint : ses graphismes, ainsi que les fenêtres et éléments de MelloUI tant qu'il les habille. Sans lui, MelloUI porte sa palette moderne, Gilded Slate. Votre choix s'applique immédiatement.", -- draft
-- stale: ["The part of the bar a hit took stays lit for a moment, then drains away, so you see how big each hit was."] = "La part de la barre prise par un coup reste allumée un instant, puis s'écoule, pour voir la taille de chaque coup.", -- draft
-- stale: ["The part of the bar a member has lost, in a colour of its own: yours, their class colour, or by health."] = "La part de la barre qu'un membre a perdue, dans une couleur à elle : la vôtre, sa couleur de classe, ou selon la vie.", -- draft
-- stale: ["The party frames, the game's and the raid-style ones. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "Les cadres de groupe, ceux du jeu et ceux de style raid. Toujours : jamais estompé. En combat : estompé hors combat, de retour en combat. Au survol : estompé en permanence, affiché quand vous le survolez.", -- draft
-- stale: ["The player, target, focus, target of target, pet and party frames in MelloUI's look, exactly as the game lays them out: a gold ring round the portrait, a dark level badge, and gold-lined iron borders round the name, health and power; the elite's and boss's golden dragon and the rare's silver one round the target. Off: the game's own frame art. The painted skin's frames keep their own (Oldschool)."] = "Les cadres du joueur, de la cible, de la focalisation, de la cible de la cible, du familier et du groupe à l'apparence de MelloUI, exactement disposés comme le jeu : un anneau doré autour du portrait, un insigne de niveau sombre, et des bordures de fer liserées d'or autour du nom, de la vie et de la ressource ; le dragon doré de l'élite et du boss et le dragon d'argent du rare autour de la cible. Désactivé : l'art de cadre du jeu. Les cadres de l'habillage peint gardent le leur (Oldschool).", -- draft
-- stale: ["The popup dialogs, the colour picker, ready checks and split stack on a parchment sheet, their text in dark ink."] = "Les fenêtres de dialogue, le sélecteur de couleur, les appels et la division de piles sur une feuille de parchemin, leur texte à l'encre sombre.", -- draft
-- stale: ["The power bar's colour with My Colour."] = "La couleur de la barre de ressource avec Ma couleur.", -- draft
-- stale: ["The power bar's colour: the power's own (blue mana, red rage, yellow energy), the member's class colour, or one of yours."] = "La couleur de la barre de ressource : celle de la ressource (mana bleu, rage rouge, énergie jaune), la couleur de classe du membre, ou l'une des vôtres.", -- draft
-- stale: ["The quest description when a quest is offered."] = "La description de la quête quand elle est proposée.", -- draft
-- stale: ["The rage, energy or mana an ability costs stays lit a moment, then drains, so you see the cost."] = "La rage, l'énergie ou le mana que coûte une technique reste allumé un instant, puis s'écoule, pour voir le coût.", -- draft
-- stale: ["The raid frames. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "Les cadres de raid. Toujours : jamais estompé. En combat : estompé hors combat, de retour en combat. Au survol : estompé en permanence, affiché quand vous le survolez.", -- draft
-- stale: ["The rim on every square button: the action bars, the micro menu, the bag bar, your bags, the equipment slots and the spell book's spells."] = "Le contour de chaque bouton carré : les barres d'actions, le micro-menu, la barre des sacs, vos sacs, les emplacements d'équipement et les sorts du grimoire.", -- draft
-- stale: ["The rim on every window's side tabs and the spell book's category tabs, all at the character window's size."] = "Le contour des onglets latéraux de chaque fenêtre et des onglets de catégorie du grimoire, tous à la taille de la fenêtre du personnage.", -- draft
-- stale: ["The rim round every round icon: passive spells, the legacy, guild and group finder windows' rings, the auction house's item, the Services bar's round buttons."] = "Le contour de chaque icône ronde : sorts passifs, anneaux des fenêtres d'héritage, de guilde et de recherche de groupe, l'objet de l'hôtel des ventes, les boutons ronds de la barre des services.", -- draft
-- stale: ["The rim round the icons of the game's Cooldown Manager: the game's own bevel, or one of the border styles the buttons wear."] = "Le contour des icônes du gestionnaire de temps de recharge du jeu : le biseau du jeu, ou l'un des styles de bordure des boutons.", -- draft
-- stale: ["The rim round your buffs and debuffs, the target's and the nameplates' (Buffs & Debuffs): a plain black edge or one of the thin rims the buttons wear. The debuff colour stays round the icon. Only MelloUI's own aura rows wear it (Buffs & Debuffs, off by default): the game's own buff and debuff icons keep their edge, which Dark Mode's Buffs & Debuffs darkens."] = "Le contour de vos améliorations et affaiblissements, de ceux de la cible et des barres d'info (Améliorations et affaiblissements) : un bord noir simple ou l'un des contours fins des boutons. La couleur de l'affaiblissement reste autour de l'icône. Seules les rangées d'auras de MelloUI le portent (Améliorations et affaiblissements, désactivé par défaut) : les icônes du jeu gardent leur bord, que le mode sombre assombrit sous Améliorations et affaiblissements.", -- draft
-- stale: ["The ring round the portraits of the unit frames: the player, target, focus, pet, target of target and party. The gem ring, a ring with four diamond studs, a plain heavy ring, or the winged border the windows wear. An elite, rare or boss shows the ring in its metal with its crest (Elite and Rare Marks)."] = "L'anneau autour des portraits des portraits d'unités : joueur, cible, focalisation, familier, cible de la cible et groupe. L'anneau de gemmes, un anneau à quatre rivets en losange, un anneau épais simple, ou la bordure ailée des fenêtres. Un élite, un rare ou un boss montre l'anneau dans son métal avec son blason (Marques élite et rare).", -- draft
