-- stale: ["The room between two of the raid's frames in a column (or a row). Also on the raid's plate in Edit Layout (right-click it)."] = "L'espace entre deux cadres du raid dans une colonne (ou une rangée). Aussi sur la plaque du raid dans Modifier la disposition (clic droit dessus).", -- draft
