-- stale: ["The round reminders beside your portrait (restock, mail, your buffs, the weapon's poison...). A new reminder does not bring them back: In Combat keeps it faded until a fight, On Mouseover until you point at them. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "Les rappels ronds à côté de votre portrait (réapprovisionnement, courrier, vos améliorations, le poison de l'arme...). Un nouveau rappel ne les fait pas revenir : En combat le garde estompé jusqu'à un combat, Au survol jusqu'à ce que vous les survoliez. Toujours : jamais estompé. En combat : estompé hors combat, de retour en combat. Au survol : estompé en permanence, affiché quand vous le survolez.", -- draft
-- stale: ["The route ends and the waypoint is cleared when you get this close. Not for the route to a tracked quest: that one moves on with the quest."] = "L'itinéraire se termine et le point de passage est effacé quand vous arrivez aussi près. Pas pour l'itinéraire vers une quête suivie : celui-là avance avec la quête.", -- draft
-- stale: ["The same button on the loot window. It frees a slot only when something you are looting is worth more than what it would throw away."] = "Le même bouton sur la fenêtre de butin. Il ne libère un emplacement que si ce que vous ramassez vaut plus que ce qu'il jetterait.", -- draft
-- stale: ["The same glints over a quest object you walk up to. Off by default: the game's own sparkle (Quest Item Sparkles) already marks most of them."] = "Les mêmes reflets sur un objet de quête dont vous approchez. Désactivé par défaut : l'étincelle du jeu (Étincelles des objets de quête) en marque déjà la plupart.", -- draft
-- stale: ["The same glints over the herb you walk up to."] = "Les mêmes reflets sur l'herbe dont vous approchez.", -- draft
-- stale: ["The same marks on the minimap for the objectives near you, and a small mark on its edge with an arrow for the nearest ones just beyond it. Drawn with Route's minimap drawing, so Route has to be on."] = "Les mêmes marques sur la minicarte pour les objectifs proches, et une petite marque sur son bord avec une flèche pour les plus proches juste au-delà. Dessiné avec le tracé de minicarte d'Itinéraire, Itinéraire doit donc être actif.", -- draft
-- stale: ["The same numbers above each party frame. Turns on the game's Show Party Pets to make room."] = "Les mêmes nombres au-dessus de chaque cadre de groupe. Active « Afficher les familiers du groupe » du jeu pour faire de la place.", -- draft
-- stale: ["The same three numbers on top of each party frame. To make room, the game's own Show Party Pets setting is switched on while this is on (the party frames stand a little further apart, and party pets show under them); your own setting comes back when it is off. With raid-style party frames: On Raid-Style Frames."] = "Les mêmes trois chiffres au-dessus de chaque cadre de groupe. Pour faire de la place, le réglage Afficher les familiers du groupe du jeu est activé tant que ceci l'est (les cadres de groupe s'écartent un peu, et les familiers du groupe s'affichent dessous) ; votre propre réglage revient quand ceci est désactivé. Avec des cadres de groupe style raid : Sur les cadres style raid.", -- draft
-- stale: ["The seconds left, past the bar's right end; on the shot bar Hold and Moving there while you aim. Off: the bars alone."] = "Les secondes restantes, après l'extrémité droite de la barre ; sur la barre de tir, Tenir et En mouvement à cet endroit pendant la visée. Désactivé : les barres seules.", -- draft
-- stale: ["The shot bar for a bow, gun, crossbow or thrown weapon while Auto Shot is on: cream, shrinking to the middle while it reloads (you can move), then red, growing from the middle while you aim: stand still, moving holds the shot back."] = "La barre de tir pour un arc, une arme à feu, une arbalète ou une arme de jet tant que Tir automatique est actif : crème, rétrécissant vers le milieu pendant le rechargement (vous pouvez bouger), puis rouge, grandissant depuis le milieu pendant la visée : restez immobile, bouger retient le tir.", -- draft
