-- stale: ["The target's and focus's portrait ring and level circle in gold for an elite, silver for a rare or rare elite and red-bronze for a boss, with a small crest on the ring's top gem: a crown, a silver star, a gold star or a skull. Their target's ring too."] = "L'anneau du portrait et le cercle de niveau de la cible et de la focalisation en or pour un élite, en argent pour un rare ou un élite rare et en bronze rouge pour un boss, avec un petit blason sur la gemme du haut de l'anneau : une couronne, une étoile d'argent, une étoile d'or ou un crâne. L'anneau de leur cible aussi.", -- draft
