-- stale: ["The text in the middle of the screen: MelloUI's notices, the zone text, the red error messages and the floating combat numbers."] = "Le texte au milieu de l'écran : les avis de MelloUI, le texte de zone, les messages d'erreur rouges et les chiffres de combat flottants.", -- draft
-- stale: ["The text that floats over your character in a fight (damage taken, heals, Dodge and Parry, procs, resources gained) in MelloUI's look, in one of three styles, or the game's own."] = "Le texte qui flotte au-dessus de votre personnage en combat (dégâts subis, soins, Esquive et Parade, déclenchements, ressources gagnées) à l'apparence de MelloUI, dans l'un de trois styles, ou celui du jeu.", -- draft
-- stale: ["The text-to-speech voice for female NPCs; recorded lines keep their own voice."] = "La voix de synthèse pour les PNJ féminins ; les lignes enregistrées gardent leur voix.", -- draft
-- stale: ["The text-to-speech voice for male and genderless NPCs; recorded lines keep their own voice. Install more voices in Windows speech settings."] = "La voix de synthèse pour les PNJ masculins et sans genre ; les lignes enregistrées gardent leur voix. Installez d'autres voix dans les paramètres vocaux de Windows.", -- draft
-- stale: ["The things MelloUI does for you: repairs and junk sales at the vendor, the restock list, accepting and handing in quests."] = "Ce que MelloUI fait pour vous : réparations et vente de camelote chez le marchand, la liste de réapprovisionnement, l'acceptation et le rendu des quêtes.", -- draft
-- stale: ["The title bar of every window, at the game's own size: a red ribbon, or a plain band with a rail line under it. The red plate riding the rail goes with the double rail. Windows already opened change after a /reload."] = "La barre de titre de chaque fenêtre, à la taille du jeu : un ruban rouge, ou une bande simple avec une ligne de rail dessous. La plaque rouge sur le rail va avec le double rail. Les fenêtres déjà ouvertes changent après un /reload.", -- draft
-- stale: ["The tooltips on a parchment sheet, their text in dark ink."] = "Les encadrés d'aide sur une feuille de parchemin, leur texte à l'encre sombre.", -- draft
-- stale: ["The tooltips' background: the painted kit (Painted), the kit with a parchment sheet whose text is dark ink (Parchment), a flat near-black box with a dark border in your palette's colours (Dark), or the game's own. Painted and Parchment need the reskin on (Oldschool)."] = "Le fond des encadrés d'aide : le kit peint (Peint), le kit avec une feuille de parchemin au texte d'encre sombre (Parchemin), une boîte plate presque noire à bordure sombre aux couleurs de votre palette (Sombre), ou celui du jeu. Peint et Parchemin nécessitent l'habillage actif (Oldschool).", -- draft
-- stale: ["The tooltips: their backdrop, the unit lines, where they sit, and the quest lines on them."] = "Les encadrés d'aide : leur fond, les lignes d'unité, leur place, et les lignes de quête qu'ils portent.", -- draft
-- stale: ["The tracker as wide on the screen as the minimap (the round map's width, or the square map's frame) and, unless you moved it yourself, right under it: it moves and changes size with the map (the Minimap Kit's Width and Height). Needs the Minimap Kit. Off: the Width below, under the game's tracker's place."] = "Le suivi aussi large à l'écran que la minicarte (la largeur de la carte ronde, ou le cadre de la carte carrée) et, sauf si vous l'avez déplacé vous-même, juste en dessous : il bouge et change de taille avec la carte (Largeur et Hauteur du kit de la minicarte). Nécessite le kit de la minicarte. Désactivé : la Largeur ci-dessous, à la place du suivi du jeu.", -- draft
-- stale: ["The tracker's headers and backdrop in the kit."] = "Les en-têtes et le fond du suivi dans le kit.", -- draft
-- stale: ["The whisper popup on a parchment sheet, its text in dark ink."] = "La fenêtre de chuchotement sur une feuille de parchemin, son texte à l'encre sombre.", -- draft
-- stale: ["The whole map in the window frame."] = "Toute la carte dans le cadre de fenêtre.", -- draft
-- stale: ["The workbench when an item is crafted."] = "L'établi quand un objet est fabriqué.", -- draft
-- stale: ["Three numbers on top of your frame: the sword this fight's damage per second, the hourglass this run's, the cross your healing per second. Live in a fight, the last fight's after it. Move them in Edit Layout (Your Values)."] = "Trois chiffres au-dessus de votre cadre : l'épée les dégâts par seconde de ce combat, le sablier ceux de cette sortie, la croix vos soins par seconde. En direct en combat, ceux du dernier combat ensuite. Déplacez-les dans Modifier la disposition (Vos valeurs).", -- draft
-- stale: ["Titles, headers, dialog names, mail and book text, and the kit's title face on the painted plates; a Font Style puts it back to 100% (its faces bring their own correction). Not the Quest Tracker's title and section headers or Combat Text's notices: they have sizes of their own."] = "Titres, en-têtes, noms des dialogues, texte du courrier et des livres, et la police de titre du kit sur les plaques peintes ; un style de police la remet à 100% (ses polices apportent leur propre correction). Pas le titre et les en-têtes de section du suivi des quêtes ni les avis du Texte de combat : ils ont leurs propres tailles.", -- draft
-- stale: ["Tooltip: a Border choice for the Dark background: Dark, the game's own, none, or a SharedMedia border. SharedMedia backgrounds work for tooltips, the chat and party and raid frames."] = "Infobulle : un choix de bordure pour le fond sombre : sombre, celle du jeu, aucune ou une bordure SharedMedia. Les fonds SharedMedia marchent pour les infobulles, la discussion et les cadres de groupe et de raid.", -- draft
-- stale: ["Tooltips colour guilds, factions, levels and quest objectives. Macro Backup is gone: the game keeps your settings."] = "Les encadrés d'aide colorent guildes, factions, niveaux et objectifs de quête. La Sauvegarde des macros n'existe plus : le jeu garde vos réglages.", -- draft
-- stale: ["UI Shade now covers the Personal Display, with its own switch and the Shade Strength slider."] = "L'ombre de l'interface couvre maintenant l'affichage personnel, avec son propre interrupteur et le curseur de force de l'ombre.", -- draft
-- stale: ["Under 35% health the health bar turns ember."] = "Sous 35% de vie, la barre de vie devient braise.", -- draft
-- stale: ["Unit Frame Bars: Font Size"] = "Barres des portraits d'unités : taille de police", -- draft
-- stale: ["Unit Frame Tweaks"] = "Réglages des portraits d'unités", -- draft
-- stale: ["Unit Frames, Nameplates and Action Bars: each switch now turns off everything MelloUI shows there, the rest keeps working."] = "Cadres d'unité, Barres de nom et Barres d'action : chaque interrupteur désactive désormais tout ce que MelloUI y affiche, le reste continue de fonctionner.", -- draft
-- stale: ["Unit Frames: XP Gain -- the stretch of the experience bar you just gained lights up as a light runs along it."] = "Portraits d'unités : Gain d'expérience -- le tronçon de la barre d'expérience que vous venez de gagner s'illumine pendant qu'une lumière la parcourt.", -- draft
-- stale: ["Use No reskin"] = "Utiliser Sans habillage", -- draft
-- stale: ["What a button shows inside its rim where it has no icon."] = "Ce qu'un bouton montre à l'intérieur de son bord là où il n'a pas d'icône.", -- draft
-- stale: ["What a hit takes from your health stays lit a moment, then drains away."] = "Ce qu'un coup prend à votre vie reste allumé un instant, puis s'écoule.", -- draft
-- stale: ["What an empty bag slot shows inside its rim. Both are chosen with pictures on Windows > Bags. The slots' rim is the Button Border (Oldschool > Borders, every window's)."] = "Ce qu'un emplacement de sac vide montre à l'intérieur de son bord. Les deux se choisissent avec des images dans Fenêtres > Sacs. Le bord des emplacements est la Bordure des boutons (Oldschool > Bordures, celles de chaque fenêtre).", -- draft
-- stale: ["What lies behind the buttons inside the backdrop. All three are chosen with pictures on Oldschool > Frame Art."] = "Ce qui se trouve derrière les boutons à l'intérieur du fond. Les trois se choisissent avec des images dans Oldschool > Art des cadres.", -- draft
-- stale: ["What lies behind the health and power bars, under the fill, the heals coming in and the bars' borders: the painted dark trough, a flat dark, the Bar Texture's finish in the dark, or nothing. Every unit frame: the player, target, focus, pet, target of target and party."] = "Ce qui se trouve derrière les barres de vie et de ressource, sous le remplissage, les soins entrants et les bordures des barres : l'auge sombre peinte, un sombre uni, la finition de la Texture des barres dans le sombre, ou rien. Chaque portrait d'unité : joueur, cible, focalisation, familier, cible de la cible et groupe.", -- draft
-- stale: ["What lies behind the health bar: a flat colour (Background Colour), one of MelloUI's backgrounds (stone, concrete, parchment, the dark gradients...), or none."] = "Ce qui se trouve derrière la barre de vie : une couleur unie (Couleur de fond), l'un des fonds de MelloUI (pierre, béton, parchemin, les dégradés sombres...), ou rien.", -- draft
-- stale: ["What lies behind the player, target and focus frames inside their backdrop."] = "Ce qui se trouve derrière les cadres du joueur, de la cible et de la focalisation à l'intérieur de leur fond.", -- draft
-- stale: ["What the NPC says when you hand in a completed quest."] = "Ce que dit le PNJ quand vous rendez une quête terminée.", -- draft
-- stale: ["What the bag windows show behind the items (Bags by Kind's window too, and the bank): cracked concrete (the window's own), stone, iron plate, parchment, leather or dark."] = "Ce que les fenêtres de sac montrent derrière les objets (la fenêtre de Sacs par type aussi, et la banque) : béton fissuré (celui de la fenêtre), pierre, plaque de fer, parchemin, cuir ou sombre.", -- draft
-- stale: ["What the character window shows behind everything: its own stone, or stone, cracked concrete, iron plate, leather or dark. Parchment is Oldschool > Parchment's Character Window: under the right pane, or over the whole window (on its own stone, whatever this shows). The equipment slots, the progress bars and the side tabs wear the borders of Oldschool > Borders (every window's)."] = "Ce que la fenêtre du personnage montre derrière tout : sa propre pierre, ou pierre, béton fissuré, plaque de fer, cuir ou sombre. Le parchemin est la Fenêtre du personnage d'Oldschool > Parchemin : sous le volet droit, ou sur toute la fenêtre (sur sa propre pierre, quoi que ceci affiche). Les emplacements d'équipement, les barres de progression et les onglets latéraux portent les bordures d'Oldschool > Bordures (celles de chaque fenêtre).", -- draft
-- stale: ["What the crafting page shows behind the recipe list and the recipe: cracked concrete, stone, iron plate, parchment, leather or dark."] = "Ce que la page de fabrication montre derrière la liste des recettes et la recette : béton fissuré, pierre, plaque de fer, parchemin, cuir ou sombre.", -- draft
-- stale: ["What the professions' book page shows behind the profession cards: cracked concrete, stone, iron plate, parchment, leather or dark. The spells' rims wear the Button Border, the rank bars the Progress Bar Border (Oldschool > Borders)."] = "Ce que la page du livre des métiers montre derrière les cartes de métier : béton fissuré, pierre, plaque de fer, parchemin, cuir ou sombre. Les bords des sorts portent la Bordure des boutons, les barres de rang la Bordure des barres de progression (Oldschool > Bordures).", -- draft
-- stale: ["What the race bar races. Auto: healing while your group role is healer, else damage."] = "Ce que mesure la barre de course. Auto : les soins tant que votre rôle de groupe est soigneur, sinon les dégâts.", -- draft
-- stale: ["What the recipe list shows behind its rows: its darker list stone, or one of the other backgrounds. All three are chosen with pictures on Windows > Professions. The reagent slots wear the Button Border, the rank bar the Progress Bar Border, the finished item the Round Border (Oldschool > Borders, every window's)."] = "Ce que la liste des recettes montre derrière ses lignes : sa pierre de liste plus sombre, ou l'un des autres fonds. Les trois se choisissent avec des images dans Fenêtres > Métiers. Les emplacements de composants portent la Bordure des boutons, la barre de rang la Bordure des barres de progression, l'objet fini la Bordure ronde (Oldschool > Bordures, celles de chaque fenêtre).", -- draft
-- stale: ["What to keep in your bags and how many. Each character has its own list; a new one starts with suggestions for its class. Also /restock."] = "Ce qu'il faut garder dans vos sacs et en quelle quantité. Chaque personnage a sa propre liste ; une nouvelle commence avec des suggestions pour sa classe. Aussi /restock.", -- draft
-- stale: ["When an NPC's greeting text was changed but the pack has exactly one recorded greeting for that NPC, play the recording anyway instead of reading the new text aloud. The words will not match what is on screen."] = "Quand le texte de salutation d'un PNJ a changé mais que le pack a exactement une salutation enregistrée pour ce PNJ, joue quand même l'enregistrement au lieu de lire le nouveau texte. Les mots ne correspondront pas à ce qui est à l'écran.", -- draft
-- stale: ["When an action's cooldown runs out, a golden light runs once round its button, so you see it is ready again. Never for the global cooldown."] = "Quand le temps de recharge d'une action se termine, une lumière dorée fait une fois le tour de son bouton, pour voir qu'elle est de nouveau prête. Jamais pour le temps de recharge global.", -- draft
-- stale: ["When an item comes into your bag window or leaves it, the others glide to their new slots instead of jumping there; one that moves to the next row slides in at its start, and a new one fades in. Switching between the Backpack and the Reagent Bag fades the window's items over. Not while you hold an item (its + slots come and go at once), not with Reduce Motion."] = "Quand un objet entre dans votre fenêtre de sacs ou en sort, les autres glissent vers leurs nouveaux emplacements au lieu d'y sauter ; un qui passe à la rangée suivante glisse à son début, et un nouveau apparaît en fondu. Passer du sac à dos au sac de composants fait un fondu sur les objets de la fenêtre. Pas tant que vous tenez un objet (ses emplacements + vont et viennent aussitôt), pas avec Réduire les animations.", -- draft
-- stale: ["When no map pin is set, route to the quest you are tracking (the one with the arrow): to the nearest place for an objective you have not finished yet (a creature to kill, an object to use, where the item drops or is sold, a place to explore), and to its turn-in once it is complete. An objective that needs an item in your bags first (remains to bury, a key for a cage) is routed to where that item comes from until you have it."] = "Sans épingle sur la carte, trace l'itinéraire vers la quête que vous suivez (celle avec la flèche) : vers le lieu le plus proche pour un objectif pas encore fini (une créature à tuer, un objet à utiliser, où l'objet tombe ou se vend, un lieu à explorer), et vers son rendu une fois terminée. Un objectif qui exige d'abord un objet dans vos sacs (des restes à enterrer, une clé pour une cage) est tracé vers l'origine de cet objet tant que vous ne l'avez pas.", -- draft
-- stale: ["When nothing is super-tracked, follow the first quest on the game's watch list instead of showing nothing. That is the game's own order of the quests you watch, not the Quest Tracker's Nearest Quest First order."] = "Quand rien n'est mis en avant, suit la première quête de la liste de suivi du jeu au lieu de ne rien afficher. C'est l'ordre du jeu des quêtes que vous suivez, pas l'ordre Quête la plus proche d'abord du suivi des quêtes.", -- draft
-- stale: ["When one of your professions can learn its next rank at a trainer: Journeyman, Expert or Artisan."] = "Quand l'un de vos métiers peut apprendre son rang suivant chez un maître : Compagnon, Expert ou Artisan.", -- draft
-- stale: ["When something does not fit because your bags are full, the bag window's Empty slot (it shows 0 then) gives one short shake and a red flash; with the bags closed, the backpack button flashes red. Once each time, as the game's own \"Inventory is full.\" line comes. Not with Reduce Motion."] = "Quand quelque chose ne rentre pas parce que vos sacs sont pleins, l'emplacement Vide de la fenêtre de sacs (qui affiche alors 0) tremble brièvement et flashe en rouge ; sacs fermés, le bouton du sac à dos flashe en rouge. Une fois à chaque fois, quand vient la ligne du jeu « Votre inventaire est plein. ». Pas avec Réduire les animations.", -- draft
-- stale: ["When the World Marker comes up for a new destination, a small light flies from your character to the place and lights it: the beam rises and the mark pops in as it lands. It follows the place as you turn the camera; while the place is off the screen it settles into the arrow beside your character. Firefly: a bright point with a short streak. Embers: a smaller glow shedding sparks. Not with Reduce Motion. Part of the World Marker."] = "Quand le Marqueur du monde apparaît pour une nouvelle destination, une petite lumière vole de votre personnage jusqu'au lieu et l'allume : le rayon s'élève et la marque apparaît à son arrivée. Elle suit le lieu quand vous tournez la caméra ; tant que le lieu est hors de l'écran, elle se pose dans la flèche à côté de votre personnage. Luciole : un point vif avec une courte traînée. Braises : une lueur plus petite qui perd des étincelles. Pas avec Réduire les animations. Fait partie du Marqueur du monde.", -- draft
-- stale: ["When you enter a dungeon or raid, list in chat the quests for it you could have picked up but have not."] = "Quand vous entrez dans un donjon ou un raid, liste dans la discussion les quêtes pour lui que vous auriez pu prendre mais n'avez pas prises.", -- draft
-- stale: ["When you gain a level, a light runs along the experience bar and the on-screen notice says your new level and, with the Quest List, how many quests it opened in your zone (their givers pop onto the world map the next time it shows them). With the painted reskin, the number in your player frame's level circle also turns over with a ring of light. Not with Reduce Motion: then only the notice."] = "Quand vous gagnez un niveau, une lumière parcourt la barre d'expérience et l'avis à l'écran annonce votre nouveau niveau et, avec la Liste des quêtes, combien de quêtes il a ouvertes dans votre zone (leurs donneurs apparaissent sur la carte du monde la prochaine fois qu'elle les montre). Avec l'habillage peint, le chiffre dans le cercle de niveau de votre cadre de joueur tourne aussi avec un anneau de lumière. Pas avec Réduire les animations : seulement l'avis.", -- draft
-- stale: ["When you gain experience, the stretch of the experience bar just gained lights up while a light runs along it to the new end. Not with Reduce Motion."] = "Quand vous gagnez de l'expérience, le tronçon de la barre d'expérience tout juste gagné s'illumine tandis qu'une lumière la parcourt jusqu'à la nouvelle fin. Pas avec Réduire les animations.", -- draft
-- stale: ["When you reach a level with new spells at your class trainer. It stays until you have learned them; each visit to your class trainer tells MelloUI when the next ones come, and before your first visit it goes by the levels trainers teach at."] = "Quand vous atteignez un niveau avec de nouveaux sorts chez votre maître de classe. Il reste jusqu'à ce que vous les ayez appris ; chaque visite à votre maître de classe dit à MelloUI quand viennent les suivants, et avant votre première visite il se fie aux niveaux où les maîtres enseignent.", -- draft
-- stale: ["When you tank a group, between pulls: a healer of your group is drinking, so wait before the next pull. It goes when they stop or a fight starts. The game keeps party mana hidden from addons, so it shows their drinking, not their mana."] = "Quand vous tankez un groupe, entre deux attaques : un soigneur de votre groupe boit, attendez donc avant la suivante. Il part quand il s'arrête ou qu'un combat commence. Le jeu cache le mana du groupe aux add-ons, il montre donc qu'il boit, pas son mana.", -- draft
-- stale: ["When your target dodges, parries or is missed, the word flicks off the side of its plate."] = "Quand votre cible esquive, pare ou est ratée, le mot file sur le côté de sa barre d'info.", -- draft
-- stale: ["Where Raid Frame Border goes: on each raid frame, round each raid group, or both. A group's border shows while Edit Mode's Display Border is on for the raid frames."] = "Où va la bordure des fenêtres de raid : sur chaque fenêtre de raid, autour de chaque groupe de raid, ou les deux. La bordure d'un groupe s'affiche tant qu'« Afficher les bordures » du mode Édition est activé pour les fenêtres de raid.", -- draft
-- stale: ["Where the next row of buffs goes: under the first, or over it."] = "Où va la rangée suivante d'améliorations : sous la première, ou au-dessus.", -- draft
-- stale: ["Where the reminder button sits beside your portrait. With the player frame hidden it keeps a place of its own, which you can move in Edit Layout."] = "Où se place le bouton de rappel près de votre portrait. Cadre du joueur masqué, il garde une place à lui, que vous pouvez déplacer dans Modifier la disposition.", -- draft
-- stale: ["Where the text sits on the bar."] = "Où le texte se place sur la barre.", -- draft
-- stale: ["Which"] = "Lesquels", -- draft
-- stale: ["Which debuffs light a frame: every one that can be removed, the ones someone in your group can remove, or only the ones you can remove."] = "Quels affaiblissements allument un cadre : tous ceux qui peuvent être retirés, ceux que quelqu'un de votre groupe peut retirer, ou seulement ceux que vous pouvez retirer.", -- draft
-- stale: ["Which quests the list shows. The dropdown at the top of the list switches this as well."] = "Quelles quêtes la liste affiche. La liste déroulante en haut de la liste change aussi ceci.", -- draft
-- stale: ["Which side of your portrait the reminder button sits on. Without a player frame, move it in Edit Layout."] = "De quel côté de votre portrait se place le bouton de rappel. Sans cadre du joueur, déplacez-le avec Modifier la disposition.", -- draft
-- stale: ["Which way a row of buffs grows from the first one."] = "Dans quel sens une rangée d'améliorations grandit à partir de la première.", -- draft
-- stale: ["Which way the party's frames line up from where you placed them."] = "Dans quel sens les cadres du groupe s'alignent depuis l'endroit où vous les avez placés.", -- draft
-- stale: ["Which way your icons run under the player frame: from the bars' left end rightwards, or from their right end leftwards."] = "Dans quel sens vos icônes courent sous le cadre du joueur : de l'extrémité gauche des barres vers la droite, ou de leur extrémité droite vers la gauche.", -- draft
-- stale: ["Which windows wear the painted kit."] = "Quelles fenêtres portent le kit peint.", -- draft
-- stale: ["While a heal over time of yours runs (Renew, Rejuvenation, Regrowth's), each of its ticks plays a small pulse on the frame: a ring and three motes (Holy), a leaf (Nature), a drop and a ripple (Water), the border's breath (Quiet, and in a raid). Timed from the game's spell data: Renew ticks five times in 15 seconds."] = "Tant qu'un de vos soins sur la durée agit (Rénovation, Récupération, celui de Rétablissement), chacun de ses tics joue une petite pulsation sur le cadre : un anneau et trois particules (Sacré), une feuille (Nature), une goutte et une onde (Eau), le souffle de la bordure (Discret, et en raid). Rythmés d'après les données de sort du jeu : Rénovation fait cinq tics en 15 secondes.", -- draft
-- stale: ["While the bag bar is hidden, show the bag slots under the open bag window so bags can still be equipped and removed. Works with and without the Combine Bags option."] = "Tant que la barre de sacs est masquée, affiche les emplacements de sac sous la fenêtre de sac ouverte pour pouvoir encore équiper et retirer des sacs. Fonctionne avec et sans l'option Combiner les sacs.", -- draft
-- stale: ["While the objective marks are on, the game's own blue quest areas and quest markers on the world map are switched off, through the game's own Quest Objectives setting (the quest buttons in the game's quest tracker go with it). Turning this or the marks off gives the game's setting back as you had it."] = "Tant que les marques d'objectifs sont actives, les zones de quête bleues et les marqueurs de quête du jeu sur la carte du monde sont désactivés, via le réglage Objectifs de quête du jeu (les boutons de quête du suivi du jeu partent avec). Désactiver ceci ou les marques rend le réglage du jeu comme vous l'aviez.", -- draft
-- stale: ["While you are not in a group, your own frame stands where your party's will, with your indicators on it. Move it in Edit Layout. With In A Party set to Party Frames, it is a normal party frame where the game's party frames stand (move those in Edit Mode)."] = "Tant que vous n'êtes pas en groupe, votre propre cadre se place là où sera celui de votre groupe, avec vos indicateurs dessus. Déplacez-le dans Modifier la disposition. Avec En groupe réglé sur Cadres de groupe, c'est un cadre de groupe normal là où sont les cadres de groupe du jeu (déplacez-les dans le mode Édition).", -- draft
-- stale: ["While you are stunned, feared, silenced or locked out of a school, the bars' rim turns red and a line under them runs down its time, its name under it. The game's own banner over your character is off while this is on, and comes back as you had it when it is off."] = "Tant que vous êtes étourdi, apeuré, réduit au silence ou privé d'une école, le bord des barres devient rouge et une ligne dessous décompte son temps, son nom en dessous. La bannière du jeu au-dessus de votre personnage est désactivée tant que ceci est actif, et revient comme vous l'aviez une fois désactivé.", -- draft
-- stale: ["While you hold an action button's key, or press it with the mouse, the whole button lights up in the colour scheme's highlight colour, so you can see which button you are pressing."] = "Tant que vous maintenez la touche d'un bouton d'action, ou le pressez à la souris, tout le bouton s'allume dans la couleur de surbrillance du thème, pour voir quel bouton vous pressez.", -- draft
-- stale: ["While you hold an item, every kind in your bag window shows a + slot: drop the item there and it always goes under that kind (drop it on its own kind's + to put it back). Forget puts every item you placed back under its own kind."] = "Tant que vous tenez un objet, chaque type de votre fenêtre de sacs affiche un emplacement + : déposez-y l'objet et il ira toujours sous ce type (déposez-le sur le + de son propre type pour le remettre). Oublier remet chaque objet placé sous son propre type.", -- draft
-- stale: ["Who draws the text over your character. Game: the game's own, as it always was. Lanes: damage taken falls on your left, healing rises on your right, procs and Dodge / Parry above your head, resources under your feet. Feed: one column over your portrait, the newest on top. Classic: one stream over your head, like the game's, in MelloUI's font and soft shade."] = "Qui dessine le texte au-dessus de votre personnage. Jeu : celui du jeu, comme toujours. Couloirs : les dégâts subis tombent à votre gauche, les soins montent à votre droite, les déclenchements et Esquive / Parade au-dessus de votre tête, les ressources à vos pieds. Fil : une colonne au-dessus de votre portrait, le plus récent en haut. Classique : un flux au-dessus de votre tête, comme celui du jeu, dans la police et l'ombre douce de MelloUI.", -- draft
-- stale: ["Who shows a power bar (mana, rage, energy) under their health."] = "Qui affiche une barre de ressource (mana, rage, énergie) sous sa vie.", -- draft
-- stale: ["Whose big moments play on the frames. Yours: when you use one (Challenging Shout, Shield Wall, Last Stand, Divine Shield, Evasion ...), your own frame in your party or raid frames plays its effect for as long as it lasts (a roar: 2 seconds). Your group's: when someone of your party or raid uses one, their frame plays it -- you see at a glance who just used Shield Wall or Divine Shield, and whose roar just pulled."] = "Quels grands moments jouent sur les cadres. Les vôtres : quand vous en utilisez un (Cri de défi, Mur protecteur, Dernier rempart, Bouclier divin, Évasion ...), votre propre cadre dans vos cadres de groupe ou de raid joue son effet tant qu'il dure (un cri : 2 secondes). Ceux de votre groupe : quand quelqu'un de votre groupe ou raid en utilise un, son cadre le joue -- vous voyez d'un coup d'œil qui vient d'utiliser Mur protecteur ou Bouclier divin, et quel cri vient d'attirer.", -- draft
-- stale: ["Whose nameplate gets the class medallion above the name."] = "Quelles barres d'info reçoivent le médaillon de classe au-dessus du nom.", -- draft
-- stale: ["Window text, buttons, tooltips, the quest log, nameplate names and the names above characters in the world (those after /reload)."] = "Texte des fenêtres, boutons, encadrés d'aide, journal des quêtes, noms des barres d'info et noms au-dessus des personnages dans le monde (ceux-ci après /reload).", -- draft
-- stale: ["Window titles, quest and item names in dialogs, mail and book text, and the kit's title plates and headers while the reskin is on. Enchanted Land unless you choose otherwise. Keep the game's leaves each string in the game's own face: Morpheus where the game uses it, the interface face on the strings that start in it (the Quest Tracker's headers, Combat Text's notices)."] = "Titres des fenêtres, noms de quêtes et d'objets dans les dialogues, texte du courrier et des livres, et les plaques de titre et en-têtes du kit tant que l'habillage est actif. Enchanted Land sauf autre choix. Garder celle du jeu laisse chaque texte dans la police du jeu : Morpheus là où le jeu l'utilise, la police de l'interface sur les textes qui y commencent (les en-têtes du suivi des quêtes, les avis du Texte de combat).", -- draft
-- stale: ["Windows framed in gold, snapped ones sharing one rim; the widget column's rows on gold cards, in motion; new class portraits; the Personal Display in gold and in motion."] = "Fenêtres encadrées d'or, celles accolées partageant un même cadre ; les lignes de la colonne de widgets sur des cartes dorées, en mouvement ; de nouveaux portraits de classe ; l'Affichage personnel en or et en mouvement.", -- draft
-- stale: ["With Heal Effects on (Frame Effects > Heals): the light of a heal you cast gathers at your character's middle instead of on the cast bar, and flies from there to the party or raid frame of the one you heal. It follows the display's place and the camera's zoom."] = "Avec Effets de soin actif (Effets de cadre > Soins) : la lumière d'un soin que vous incantez se rassemble au milieu de votre personnage au lieu de la barre d'incantation, et vole de là jusqu'au cadre de groupe ou de raid de celui que vous soignez. Elle suit la place de l'affichage et le zoom de la caméra.", -- draft
-- stale: ["With a choice of rewards: take the one with the highest item level over what you wear in its slot, among those you can use; when none is better, the one that sells for the most."] = "Avec un choix de récompenses : prend celle dont le niveau d'objet dépasse le plus ce que vous portez à cet emplacement, parmi celles que vous pouvez utiliser ; si aucune n'est meilleure, celle qui se vend le plus cher.", -- draft
-- stale: ["Write these lines in the chat instead of showing them on the screen. They show there even while Chat Notices is off."] = "Écrit ces lignes dans la discussion au lieu de les afficher à l'écran. Elles s'y affichent même si Avis dans la discussion est désactivé.", -- draft
-- stale: ["X / Y"] = "X / Y", -- draft
-- stale: ["You are reminded when a line drops below this share of its amount: at 50 %, a line of 20 water reminds you at 9. At a shop it is bought back up to the full amount. The reminder needs Reminders on; the Restock List marks the low lines either way."] = "Vous êtes rappelé quand une ligne descend sous cette part de sa quantité : à 50 %, une ligne de 20 eaux vous rappelle à 9. Chez un marchand, elle est rachetée jusqu'à la quantité pleine. Le rappel nécessite Rappels actif ; la Liste de réapprovisionnement marque les lignes basses dans tous les cas.", -- draft
-- stale: ["Your UI and bars stay. MelloUI's features switch on."] = "Votre interface et vos barres restent. Les fonctions de MelloUI s'activent.", -- draft
-- stale: ["Your addons' minimap buttons (Questie and the others that put a round button on the minimap's edge) taken off the minimap and gathered into one more group in the Services row, AddOns: click it for a list of them. A click on an addon there is that addon's own (left, right or middle), and pointing at it shows its own tooltip. Only with Button Layout's Groups. Off: the buttons go back on the minimap."] = "Les boutons de minicarte de vos add-ons (Questie et les autres qui posent un bouton rond au bord de la minicarte) retirés de la minicarte et réunis dans un groupe de plus de la rangée Services, Add-ons : cliquez-le pour leur liste. Un clic sur un add-on y est celui de l'add-on (gauche, droit ou milieu), et le survoler affiche son propre encadré d'aide. Seulement avec les Groupes de Disposition des boutons. Désactivé : les boutons retournent sur la minicarte.", -- draft
-- stale: ["Your aura indicators on the frames. Off: the frames show none."] = "Vos indicateurs d'auras sur les cadres. Désactivé : les cadres n'en montrent aucun.", -- draft
-- stale: ["Your bag window's kinds in the order they show, the top first: drag a row to move it. A line draws a line across the window between the kinds over and under it; a group puts the kinds under it, to the next line, under one heading you can fold. Untick a kind and its items go to their own type, or to Other. Add kind makes one of your own: it takes the items you drop on its + slot and the ones its rule matches (an item type, a word in the name, a quality), before the game's kinds. Double-click a name to rename it; a kind's cog opens its settings: its name, Split By Type (a heading for each item type, in its place) and an own kind's rule."] = "Les types de votre fenêtre de sacs dans l'ordre d'affichage, le premier en haut : faites glisser une ligne pour la déplacer. Une ligne trace une ligne à travers la fenêtre entre les types au-dessus et en dessous ; un groupe réunit les types en dessous, jusqu'à la ligne suivante, sous un en-tête repliable. Décochez un type et ses objets vont à leur propre type, ou dans Autre. Ajouter un type en crée un à vous : il prend les objets que vous déposez sur son emplacement + et ceux que sa règle reconnaît (un type d'objet, un mot dans le nom, une qualité), avant les types du jeu. Double-cliquez un nom pour le renommer ; l'engrenage d'un type ouvre ses réglages : son nom, Séparer par type (un en-tête par type d'objet, à sa place) et la règle d'un type personnel.", -- draft
-- stale: ["Your bags in one window of MelloUI's own, sorted by kind: what you picked up lately, gear, quest items, consumables, junk, trade goods and the rest, each under its own heading. The empty slots fold into one slot with their count."] = "Vos sacs dans une fenêtre de MelloUI, triés par type : ce que vous avez ramassé récemment, l'équipement, les objets de quête, les consommables, la camelote, les marchandises et le reste, chacun sous son propre en-tête. Les emplacements vides se replient en un seul avec leur nombre.", -- draft
-- stale: ["Your bags' buttons. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "Les boutons de vos sacs. Toujours : jamais estompé. En combat : estompé hors combat, de retour en combat. Au survol : estompé en permanence, affiché quand vous le survolez.", -- draft
-- stale: ["Your bank in the same kinds as your bags, inside the game's bank window: its items under their headings, the lines and groups of the Kinds list, the empty slots folded into one, a + slot in every kind while you hold an item. Deposit and take out as always (right-click, drag). Off: the game's own grid."] = "Votre banque dans les mêmes types que vos sacs, dans la fenêtre de banque du jeu : ses objets sous leurs en-têtes, les lignes et groupes de la liste Types, les emplacements vides repliés en un, un emplacement + dans chaque type quand vous tenez un objet. Déposez et retirez comme toujours (clic droit, glisser). Désactivé : la grille du jeu.", -- draft
-- stale: ["Your buffs and debuffs"] = "Vos améliorations et affaiblissements", -- draft
-- stale: ["Your buffs and debuffs under your player frame, like the target's. They move with the frame."] = "Vos améliorations et affaiblissements sous votre cadre de joueur, comme ceux de la cible. Ils suivent le cadre.", -- draft
-- stale: ["Your buffs in a line beside the minimap, level with the map's top and growing away from it, your debuffs on the line under them. They follow the minimap when it moves or changes size. Needs the Minimap Kit; off, they stand where the game's buff bar is."] = "Vos améliorations en ligne à côté de la minicarte, à hauteur du haut de la carte et s'en éloignant, vos affaiblissements sur la ligne en dessous. Elles suivent la minicarte quand elle bouge ou change de taille. Nécessite le kit de la minicarte ; désactivé, elles se placent là où est la barre d'améliorations du jeu.", -- draft
-- stale: ["Your buffs line up beside the minimap and follow it. Off: they stand where the game's buff bar is."] = "Vos améliorations s'alignent près de la minicarte et la suivent. Désactivé : elles restent là où est la barre du jeu.", -- draft
-- stale: ["Your buffs, then your debuffs on a row of their own. Right-click a buff to cancel it. Beside the minimap, or where the game's buff bar is: that bar comes back while Edit Mode is open, so it can still be moved, and these follow it."] = "Vos améliorations, puis vos affaiblissements sur leur propre rangée. Clic droit sur une amélioration pour l'annuler. À côté de la minicarte, ou là où est la barre d'améliorations du jeu : cette barre revient tant que le mode Édition est ouvert, pour pouvoir encore la déplacer, et celles-ci la suivent.", -- draft
-- stale: ["Your character"] = "Votre personnage", -- draft
-- stale: ["Your choices from each step"] = "Vos choix de chaque étape", -- draft
-- stale: ["Your current setup is saved as the profile 'Before install' first, so you can go back to it later from the Profiles page. After Install you have 15 seconds to keep the new setup; one reload at the end, only if the fonts need it."] = "Votre configuration actuelle est d'abord enregistrée comme profil « Before install », pour y revenir plus tard depuis la page Profils. Après l'installation, vous avez 15 secondes pour garder la nouvelle configuration ; un rechargement à la fin, seulement si les polices l'exigent.", -- draft
-- stale: ["Your damage over time ticks over the enemies (the game's own setting)."] = "Les tics de vos dégâts sur la durée au-dessus des ennemis (le réglage du jeu).", -- draft
-- stale: ["Your damage per second, run total and healing per second above your player frame."] = "Vos dégâts par seconde, le total de l'expédition et vos soins par seconde au-dessus de votre cadre de joueur.", -- draft
-- stale: ["Your debuffs in a block of their own, with their own place in Edit Layout and their own size and rows. Off: they are the line under your buffs."] = "Vos affaiblissements dans un bloc à part, avec leur place dans l'éditeur de disposition, leur taille et leurs rangées. Désactivé : ils sont la ligne sous vos améliorations.", -- draft
-- stale: ["Your debuffs on enemy nameplates, in place of the game's row. Crowd control stays with the game (and the Nameplates module)."] = "Vos affaiblissements sur les barres d'info ennemies, à la place de la rangée du jeu. Le contrôle des foules reste au jeu (et au module Barres d'info).", -- draft
-- stale: ["Your debuffs, then your buffs and weapon buffs, under your player frame, as the target's are under the target frame: the same icons, spiral and timers. Right-click a buff to cancel it. They move with the player frame. Off, they stand beside the minimap or where the game's buff bar is."] = "Vos affaiblissements, puis vos améliorations et améliorations d'arme, sous votre cadre de joueur, comme celles de la cible sous son cadre : mêmes icônes, spirale et minuteurs. Clic droit sur une amélioration pour l'annuler. Elles bougent avec le cadre du joueur. Désactivé, elles se placent à côté de la minicarte ou là où est la barre d'améliorations du jeu.", -- draft
-- stale: ["Your dodge, parry or block flicks its word off the health bar's end: your Revenge window, on the bars you watch."] = "Votre esquive, parade ou blocage fait filer son mot au bout de la barre de vie : votre fenêtre de Revanche, sur les barres que vous regardez.", -- draft
-- stale: ["Your group's frames show their big moments: a roar's square ripples, a taunt, Shield Wall's steel, Last Stand's heartbeat, an immunity's barrier, an evasion's afterimages -- on your own frame when you use one, on a group mate's when they do."] = "Les cadres de votre groupe montrent leurs grands moments : les ondes carrées d'un cri, une provocation, l'acier de Mur protecteur, le battement de cœur de Dernier rempart, la barrière d'une immunité, les images rémanentes d'une évasion -- sur votre propre cadre quand vous en utilisez une, sur celui d'un équipier quand il le fait.", -- draft
-- stale: ["Your heals on your group as light: a cast heal gathers on your cast bar and flies to the frame of the one you heal; an instant one lands on their frame at once. Each kind lands its own way: heals over time, shields, protection, a heal to full, a resurrection."] = "Vos soins sur votre groupe sous forme de lumière : un soin incanté se rassemble sur votre barre d'incantation et vole jusqu'au cadre de celui que vous soignez ; un soin instantané se pose aussitôt sur son cadre. Chaque type atterrit à sa façon : soins sur la durée, boucliers, protection, soin complet, résurrection.", -- draft
-- stale: ["Your health and power in percent beside their bars, the spell and its seconds on the cast bar, the shield's amount under its column, and what took your control under the bars."] = "Votre vie et votre ressource en pourcentage à côté de leurs barres, le sort et ses secondes sur la barre d'incantation, le montant du bouclier sous sa colonne, et ce qui vous a pris le contrôle sous les barres.", -- draft
-- stale: ["Your health, power and cast bar under your character, as Legion's resource display had them, and a shield column beside your character: it fills when a shield goes up, drains as it takes the hits, turns amber when low and breaks when it is gone. The game's own Personal Resource Display is switched off while this is on, and comes back as you had it when it is off; Hide The Game's Cast Bar (on) hides the game's cast bar too, and Swing On The Rails (on) stands in for Swing Timers. This client cannot tell an addon where your character stands, so the display stays where you put it in Edit Layout (under your character to begin with) and hops when you jump."] = "Votre vie, votre ressource et votre barre d'incantation sous votre personnage, comme l'affichage des ressources de Legion, et une colonne de bouclier à côté de votre personnage : elle se remplit quand un bouclier se lève, se vide à mesure qu'il encaisse, devient ambre quand il est bas et se brise quand il disparaît. L'affichage des ressources personnelles du jeu est désactivé tant que ceci est actif, et revient comme vous l'aviez une fois désactivé ; Masquer la barre d'incantation du jeu (actif) masque aussi la barre d'incantation du jeu, et Coups sur les rails (actif) remplace les Minuteurs d'attaque. Ce client ne peut pas dire à un add-on où se tient votre personnage, l'affichage reste donc là où vous l'avez mis dans Modifier la disposition (sous votre personnage au départ) et sautille quand vous sautez.", -- draft
-- stale: ["Your indicators for the spec you play, and the one you picked: its look, place, size, colour and text. Drag it on the frame above to move it."] = "Vos indicateurs pour la spécialisation que vous jouez, et celui que vous avez choisi : son apparence, sa place, sa taille, sa couleur et son texte. Faites-le glisser sur le cadre ci-dessus pour le déplacer.", -- draft
-- stale: ["Your layout was fitted to this screen."] = "Votre disposition a été ajustée à cet écran.", -- draft
-- stale: ["Your own buffs and debuffs, the game's or MelloUI's rows by the minimap. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "Vos améliorations et affaiblissements, les rangées du jeu ou de MelloUI près de la minicarte. Toujours : jamais estompé. En combat : estompé hors combat, de retour en combat. Au survol : estompé en permanence, affiché quand vous le survolez.", -- draft
-- stale: ["Your own frame. In Combat, it also comes back while your health or mana is below full and when you are dead; On Mouseover, it stays faded until you point at it. Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "Votre propre cadre. En combat, il revient aussi tant que votre vie ou votre mana n'est pas pleine et quand vous êtes mort ; Au survol, il reste estompé jusqu'à ce que vous le survoliez. Toujours : jamais estompé. En combat : estompé hors combat, de retour en combat. Au survol : estompé en permanence, affiché quand vous le survolez.", -- draft
-- stale: ["Your own power bar while you play solo, whatever your role."] = "Votre propre barre de ressource quand vous jouez seul, quel que soit votre rôle.", -- draft
-- stale: ["Your palette, the painted kit and its colours. Nothing changes until you install."] = "Votre palette, le kit peint et ses couleurs. Rien ne change avant l'installation.", -- draft
