-- stale: ["Your pet's frame fades and comes back with the player frame, and also comes back while your pet is hurt. Off: the pet frame always stays."] = "Le cadre de votre familier s'estompe et revient avec le cadre du joueur, et revient aussi quand votre familier est blessé. Désactivé : le cadre du familier reste toujours.", -- draft
-- stale: ["Your shot, melee and off-hand swings"] = "Vos tirs, coups de mêlée et de main gauche", -- draft
-- stale: ["Your swing timer without a bar of its own: in a fight, two sparks run out from the middle of the health bar's top rail to its ends, and your swing lands as they reach them. An off hand's swings run along the bottom of the power bar. Your shots run on the seam between the health and power bars: cream sparks out while you reload, then a red line grows back from the ends while you aim (stand still: moving holds it), and the shot flies as it meets in the middle. A wand's shots run out once, with no aim. While it is on, MelloUI's Swing Timers step aside and the game's own swing timers stay off."] = "Votre minuteur d'attaque sans barre à lui : en combat, deux étincelles partent du milieu du rail supérieur de la barre de vie vers ses extrémités, et votre coup tombe quand elles les atteignent. Les coups d'une main gauche courent le long du bas de la barre de ressource. Vos tirs courent sur la jointure entre les barres de vie et de ressource : des étincelles crème sortent pendant le rechargement, puis une ligne rouge revient depuis les extrémités pendant la visée (restez immobile : bouger la retient), et le tir part quand elle se rejoint au milieu. Les tirs d'une baguette sortent une fois, sans visée. Tant que c'est actif, les Minuteurs d'attaque de MelloUI s'effacent et ceux du jeu restent désactivés.", -- draft
-- stale: ["Your target's cast bar glows hotter as its cast nears the end, and shatters when the cast is interrupted."] = "La barre d'incantation de votre cible chauffe à l'approche de la fin de l'incantation, et se brise quand l'incantation est interrompue.", -- draft
-- stale: ["Your target's debuffs, then its buffs, under the target frame, in place of the game's."] = "Les affaiblissements de votre cible, puis ses améliorations, sous le cadre de la cible, à la place de ceux du jeu.", -- draft
-- stale: ["Your target's frame (and its target's). Always: never faded. In Combat: faded out of combat, back in a fight. On Mouseover: faded all the time, shown while you point at it."] = "Le cadre de votre cible (et celui de sa cible). Toujours : jamais estompé. En combat : estompé hors combat, de retour en combat. Au survol : estompé en permanence, affiché quand vous le survolez.", -- draft
-- stale: ["Your target's health bar flashes a moment when it is hit; a critical hit flashes gold."] = "La barre de vie de votre cible flashe un instant quand elle est touchée ; un coup critique flashe en or.", -- draft
-- stale: ["Your target's nameplate answers the fight: hits flash its bar, the part a hit took drains away, crits glow gold, a dodge or a miss flicks off its edge, an enemy's cast glows hotter towards its end and shatters when you interrupt it, and the killing blow flashes the bar out."] = "La barre d'info de votre cible répond au combat : les coups font flasher sa barre, la part prise par un coup s'écoule, les critiques brillent d'or, une esquive ou un raté file sur son bord, l'incantation d'un ennemi chauffe vers sa fin et se brise quand vous l'interrompez, et le coup fatal fait éclater la barre.", -- draft
-- stale: ["Your unit, party and raid frames, action bars and bag bar are MelloUI's own; health bars show shields and overshields, and members out of range fade."] = "Vos portraits d'unité, de groupe et de raid, vos barres d'action et votre barre de sacs sont ceux de MelloUI ; les barres de vie montrent boucliers et surboucliers, et les membres hors de portée s'estompent.", -- draft
-- stale: ["Your unit, party and raid frames, action bars, experience bars and bag bar are MelloUI's own: action bar settings apply at once."] = "Vos cadres d'unité, de groupe et de raid, vos barres d'action, d'expérience et la barre des sacs sont ceux de MelloUI : les réglages des barres d'action s'appliquent aussitôt.", -- draft
